GimCorpus.put(121,0,[[1,1,"דִּבְרֵי יִרְמְיָהוּ בֶּן חִלְקִיָּהוּ וְגוֹ׳. לֵיתֵי בַּר קַלְקַלְתָּא דְּתַקְנָן עוֹבְדוֹהִי – יִרְמְיָה בָּא מֵרָחָב הַזּוֹנָה (יהושע ב:א), וְלוֹכַח בַּר מְתַקְּנְתָּא דִּמְקַלְקְלָן עוֹבְדוֹהִי – אֵלּוּ יִשְׂרָאֵל שֶׁקִּלְקְלוּ מַעֲשֵׂיהֶן, שֶׁבָּאוּ מִזֶּרַע כָּשֵׁר (פסיקתא רבתי יג,ד):",1,0],[1,2,"אֲשֶׁר הָיָה דְבַר ה׳ אֵלָיו וְגוֹ׳. אֲשֶׁר הִתְחִילָה שְׁכִינָה לִשְׁרוֹת עָלָיו בְּאוֹתוֹ הַזְּמַן:",1,0],[1,3,"וַיְהִי בִּימֵי יְהוֹיָקִים. וַיְהִי נָבִיא כָּל יְמֵי יֹאשִׁיָּהוּ הַנּוֹתָרִים, וִימֵי יְהוֹיָקִים בְּנוֹ וִימֵי צִדְקִיָּהוּ בְּנוֹ, עַד תֹּם עַשְׁתֵּי עֶשְׂרֵה שָׁנָה, הִיא הַשָּׁנָה עַד גְּלוֹת יְרוּשָׁלִַם בַּחֹדֶשׁ הַחֲמִישִׁי:",1,0],[1,5,"בְּטֶרֶם אֶצָּרְךָ בַבֶּטֶן וְגוֹ׳. מִימֵי אָדָם הָרִאשׁוֹן; הֶרְאָהוּ הַקָּדוֹשׁ בָּרוּךְ הוּא לְאָדָם דּוֹר וְדוֹר וּנְבִיאָיו (סדר עולם רבה ל):",1,0],[1,5,"אֶצָּרְךָ. לְשׁוֹן צוּרָה:",2,0],[1,5,"יְדַעְתִּיךָ. קְנִיּוֹשְׁטְ״וִי בְּלַעַ״ז, כְּמוֹ ״לֹא נוֹדַעְתִּי לָהֶם״ (שמות ו:ג):",3,0],[1,5,"הִקְדַּשְׁתִּיךָ. זִמַּנְתִּיךָ לְכָךְ:",4,0],[1,5,"נָבִיא לַגּוֹיִם. לְיִשְׂרָאֵל שֶׁהָיוּ נוֹהֲגִים עַצְמָם כַּגּוֹיִם, כָּךְ נִדְרַשׁ בְּסִפְרֵי: ״נָבִיא מִקִּרְבְּךָ וְגוֹ׳ יָקִים לְךָ״ (דברים יח:טו) וְלֹא לְמַכְחִישֵׁי תּוֹרָה. הָא מָה אֲנִי מְקַיֵּם נָבִיא לַגּוֹיִם נְתַתִּיךָ? בְּנוֹהֲגֵי מִנְהַג גּוֹיִם. וְעוֹד יֵשׁ לִפְתּוֹר: נָבִיא לַגּוֹיִם כְּמוֹ ״עַל הַגּוֹיִם״ (ירמיהו י:כה); לְהַשְׁקוֹתָם כּוֹס תַּרְעֵלָה, לְהִנָּבֵא עֲלֵיהֶם פּוּרְעָנוּת, כְּמָה שֶׁנֶּאֱמַר ״קַח אֶת כּוֹס הַיַּיִן הַחֵמָה הַזֹּאת … וְהִשְׁקִיתָה אֹתוֹ אֶת כׇּל הַגּוֹיִם״ (ירמיהו כה:טו). דָּבָר אַחֵר: בְּטֶרֶם תֵּצֵא מֵרֶחֶם הִקְדַּשְׁתִּיךָ, עָלֶיךָ אָמַרְתִּי לְמֹשֶׁה: ״נָבִיא אָקִים לָהֶם כָּמוֹךָ״ (דברים יח:יח). זֶה הוֹכִיחָם וְזֶה הוֹכִיחָם, זֶה נִתְנַבֵּא אַרְבָּעִים שָׁנָה וְזֶה נִתְנַבֵּא אַרְבָּעִים שָׁנָה:",5,0],[1,6,"אֲהָהּ. לְשׁוֹן יְלָל, קוֹנְפְּלֵיינְ״ט בְּלַעַ״ז:",1,0],[1,6,"כִּי נַעַר אָנֹכִי. אֵינִי כְדַאי לְהוֹכִיחָן. מֹשֶׁה הוֹכִיחָן סָמוּךְ לְמִיתָתוֹ (דברים א), כְּבָר נֶחְשַׁב בְּעֵינֵיהֶם בְּכַמָּה נִסִּים שֶׁעָשָׂה לָהֶם: הוֹצִיאָם מִמִּצְרַיִם (שמות יב:לא-מג), וְקָרַע לָהֶם אֶת הַיָּם (שמות יד:טו-לא), הוֹרִיד אֶת הַמָּן, הֵגִיז אֶת הַשְּׂלָיו (במדבר יא), נָתַן לָהֶם אֶת הַתּוֹרָה (שמות לד), הֶעֱלָה אֶת הַבְּאֵר (במדבר כא:טז-יח); אֲנִי, בִּתְחִלַּת שְׁלִיחוּתִי אֲנִי בָּא לְהוֹכִיחָם?!",2,0],[1,7,"עַל כָּל אֲשֶׁר אֶשְׁלָחֲךָ. אֶל הָעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת:",1,0],[1,7,"וְאֵת כָּל אֲשֶׁר אֲצַוְּךָ. לְיִשְׂרָאֵל תְּדַבֵּר:",2,0],[1,9,"וַיִּשְׁלַח ה׳ אֶת יָדוֹ. כָּל שְׁלִיחוּת שֶׁהוּא אֵצֶל יָד – לְשׁוֹן הוֹשָׁטָה. לָשׁוֹן אַחֵר: כַּתַּרְגּוּם: ״וְשָׁלַח ה׳ יָת פִּתְגָמֵי נְבִיאוּתֵיהּ״:",1,0],[1,10,"הִפְקַדְתִּיךָ. מִנִּיתִיךָ עַל הַגּוֹיִם:",1,0],[1,10,"לנתוש ולנתוץ. דיספציר בְּלַעַ״ז:",2,0],[1,11,"מַקֵּל שָׁקֵד. מַנְדוֹלִי״ר בְּלַעַ״ז, וְיוֹנָתָן תִּרְגֵּם מַקֵּל שָׁקֵד ״מֶלֶךְ דְּמוֹחִי לְאַבְאָשָׁא״:",1,0],[1,12,"הֵיטַבְתָּ לִרְאוֹת. הַשָּׁקֵד הַזֶּה הוּא מְמַהֵר לְהוֹצִיא פֶרַח קֹדֶם לְכָל הָאִילָנוֹת, אַף אֲנִי מְמַהֵר לַעֲשׂוֹת דְּבָרִי. וּמִדְרַשׁ אַגָּדָה (ירושלמי תענית ד, ה): הַשָּׁקֵד הַזֶּה הוּא מִשְּׁעַת חֲנִיטָתוֹ עַד גְּמַר בִּשּׁוּלוֹ עֶשְׂרִים וְאֶחָד יוֹם, כְּמִנְיַן יָמִים שֶׁבֵּין שִׁבְעָה עָשָׂר בְּתַמּוּז שֶׁבּוֹ הָבְקְעָה הָעִיר, לְתִשְׁעָה בְּאָב שֶׁבּוֹ נִשְׂרַף הַבַּיִת:",1,0],[1,13,"סִיר נָפוּחַ. רוֹתֵחַ בּוֹיִילְנְ״ט בְּלַעַ״ז:",1,0],[1,13,"וּפָנָיו. רְתִיחוֹתָיו, אֵשִׁישׁאוֹנְדִי״שׁ בְּלַעַ״ז:",2,0],[1,14,"מִצָּפוֹן תִּפָּתַח הָרָעָה. בָּבֶל לִצְפוֹנָהּ שֶׁל אֶרֶץ יִשְׂרָאֵל הִיא (גיטין ו.):",1,0],[1,16,"וְדִבַּרְתִּי מִשְׁפָּטַי אוֹתָם. אֶתְוַכַּח עִמָּם, עִם יְהוּדָה וִירוּשָׁלִָם:",1,0],[1,17,"תֶּאְזֹר מָתְנֶיךָ. לְשׁוֹן זֵרוּז, כְּאִישׁ חַיִל:",1,0],[1,18,"לְמַלְכֵי יְהוּדָה. כְּנֶגֶד מַלְכֵי יְהוּדָה:",1,0],[1,19,"וְנִלְחֲמוּ אֵלֶיךָ. ״וִיהוֹן דָּיְנִין וּמְגִיחִין לְקָבְלָךְ לְמִסְתַּר יָת פִּתְגָמֵי נְבוּאָתָךְ״:",1,0],[2,2,"זָכַרְתִּי לָךְ. אִם הֱיִיתֶם שָׁבִים אֵלַי, תַּאֲוָתִי לְרַחֵם עֲלֵיכֶם, כִּי זָכַרְתִּי חֶסֶד נְעוּרַיִךְ וְאַהֲבַת כְּלִילַת חֻפָּתֵךְ, שֶׁהִכְלַלְתִּיךְ לְחֻפָּה; וְלָשׁוֹן הַכְנָסָה הוּא. כְּלוּלֹתָיִךְ נוֹצִי״שׁ בְּלַעַ״ז. וּמַה הוּא חֶסֶד נְעוּרַיִךְ? לֶכְתֵּךְ אַחַר שְׁלוּחַי, מֹשֶׁה וְאַהֲרֹן; מֵאֶרֶץ נוֹשָׁבֶת (שמות טז:לה) יְצָאתֶם לַמִּדְבָּר, וְאֵין צֵדָה לַדֶּרֶךְ, כִּי הֶאֱמַנְתֶּם בִּי (מכילתא בא פסחא יד):",1,0],[2,3,"קֹדֶשׁ יִשְׂרָאֵל. כִּתְרוּמָה:",1,0],[2,3,"רֵאשִׁית תְּבוּאָתֹה. כְּרֵאשִׁית קָצִיר לִפְנֵי הָעֹמֶר, שֶׁאָסוּר בַּאֲכִילָה וְהָאוֹכְלוֹ מִתְחַיֵּב, כֵּן כָּל אֹכְלָיו יֶאְשָׁמוּ. כֵּן תַּרְגֵּם יוֹנָתָן:",2,0],[2,6,"וְלֹא אָמְרוּ אַיֵּה ה׳. כִּי נֵלֵךְ אַחֲרֵי אֱלֹהִים אֲחֵרִים:",1,0],[2,6,"עֲרָבָה. פְּלַנוּרָ״א בְּלַעַ״ז:",2,0],[2,6,"וְשׁוּחָה. נְטוּיָה, אִינְפוּשִׁיאָ״ה בְּלַעַ״ז:",3,0],[2,6,"צִיָּה. דִּישְׁגַאטָ״ה בְּלַעַ״ז:",4,0],[2,6,"וְצַלְמָוֶת. לְשׁוֹן חֹשֶׁךְ:",5,0],[2,7,"אֶל אֶרֶץ הַכַּרְמֶל. ״לְאַרְעָא דְיִשְׂרָאֵל דַּהֲוַת מְנַצְּבָא כְּכַרְמְלָא״ (תרגום יונתן; פסיקתא רבתי טו, א), פֵּירֵשׁ נְטוּעָה כְּיַעַר:",1,0],[2,8,"תּוֹפְשֵׂי הַתּוֹרָה. סַנְהֶדְרִין:",1,0],[2,8,"וְהָרֹעִים. הַמְּלָכִים:",2,0],[2,8,"נִבְּאוּ בַבַּעַל. בְּשֵׁם הַבַּעַל:",3,0],[2,9,"עוֹד אָרִיב. טֶרֶם אָבִיא עֲלֵיכֶם רָעָה, אֶתְוַכַּח עִמָּכֶם עוֹד עַל יְדֵי נְבִיאַי, אַף עַל פִּי שֶׁרַבְתִּי עִמָּכֶם כְּבָר יָמִים רַבִּים:",1,0],[2,10,"אִיֵּי כִתִּיִּים. לְאִיֵּי כִתִּיִּים:",1,0],[2,10,"אִיֵּי. אִישְׁלַ״שׁ בְּלַעַ״ז:",2,0],[2,10,"וְקֵדָר שִׁלְחוּ. וְלִקְדָר שִׁלְחוּ לִרְאוֹת מִנְהָגָם:",3,0],[2,10,"וְהִתְבּוֹנְנוּ מְאֹד. וְשִׂימוּ לֵב לְהִסְתַּכֵּל בַּדָּבָר יָפֶה:",4,0],[2,10,"הֵן. כְּמוֹ אִם, אִם הֵמִיר גּוֹי מֵהֶם אֶת אֱלֹהָיו וְאַף עַל פִּי שֶׁהֵמָּה לֹא אֱלֹהִים, וְעַמִּי הֵמִיר אֶת כְּבוֹדוֹ אֲשֶׁר בּוֹ הָיָה נִכְבָּד. וְכִתִּיִּים וְקֵדָרִיִּים יוֹשְׁבֵי אֹהָלִים וְרוֹעֵי מִקְנֶה, וְנוֹסְעִים וְהוֹלְכִים וּמִטַּלְטְלִין מִמִּרְעֶה לְמִרְעֶה וּמִמִּדְבָּר לְמִדְבָּר, וְנוֹשְׂאִים אֶת אֱלֹהֵיהֶם עִמָּהֶם לְמָקוֹם שֶׁחוֹנִים שָׁם, וַאֲנִי נָשָׂאתִי אֶתְכֶם עַד אֲשֶׁר קָבַעְתִּי אֶתְכֶם, וְהִנַּחְתֶּם אוֹתִי, כָּךְ תִּרְגֵּם יוֹנָתָן. וְרַבּוֹתֵינוּ אָמְרוּ (תענית ה:): כִּתִּיִּים עוֹבְדִים לַמַּיִם, וְקֵדָרִיִּים עוֹבְדִים לָאֵשׁ, וְאַף עַל פִּי שֶׁיּוֹדְעִים שֶׁהַמַּיִם מְכַבִּין אֶת הָאֵשׁ, לֹא הִנִּיחוּ אֶת אֱלֹהֵיהֶם:",5,0],[2,11,"בְּלֹא יוֹעִיל. בַּעֲבוֹדָה זָרָה שֶׁאֵין בָּהּ תּוֹעֶלֶת:",1,0],[2,12,"שֹׁמּוּ שָׁמַיִם. לְשׁוֹן תִּמָּהוֹן, כְּמוֹ הִשְׁתּוֹמְמוּ; וְהוּא לְשׁוֹן צִוּוּי, כְּמוֹ ״אִם כֹּה יֹאמְרוּ אֵלֵינוּ דֹּמּוּ״ (שמואל א יד:ט):",1,0],[2,12,"וְשַׂעֲרוּ. לְשׁוֹן סַעַר:",2,0],[2,12,"חָרְבוּ מְאֹד. כְּאִלּוּ אַתֶּם נֶחֱרָבִים עַל בֵּית הַמִּקְדָּשׁ שֶׁעָתִיד לֵיחָרֵב:",3,0],[2,13,"שְׁתַּיִם רָעוֹת. אִם הֵמִירוּ יִרְאָתָם בְּכַיּוֹצֵא בָּהּ, יֵשׁ כָּאן רָעָה אַחַת; וְעַכְשָׁיו שֶׁאוֹתִי עָזְבוּ, שֶׁאֲנִי מְקוֹר מַיִם חַיִּים, לָלֶכֶת אַחֲרֵי הָעֲבוֹדָה הַזָּרָה, שֶׁהֵם כְּבֹארוֹת שֶׁל מַיִם מְכֻנָּסִין וְנִשְׁבָּרִין וְנִסְדָּקִין, וּמֵימֵיהֶם נִבְלָעִים בִּסְדָקֵיהֶם, הֲרֵי שְׁתַּיִם רָעוֹת:",1,0],[2,13,"לַחְצֹב. לַחְפֹּר:",2,0],[2,13,"אֲשֶׁר לֹא יָכִלוּ. טִינְדְרוֹנְ״ט בְּלַעַ״ז אֶת מֵימֵיהֶם; שֶׁהַמַּיִם מְטַשְׁטְשִׁין אֶת שְׂפָתָם וְכוֹתְלֵיהֶם וְהֵם נוֹפְלִין:",3,0],[2,14,"יְלִיד בַּיִת. בֶּן הָאָמָה:",1,0],[2,15,"יִשְׁאֲגוּ. שׁוֹאֲגִים, לְשׁוֹן הֹוֶה:",1,0],[2,15,"כְּפִירִים. מְלָכִים:",2,0],[2,15,"נִצְּתוּ. נִצְּתוּ בָּאֵשׁ:",3,0],[2,16,"גַּם בְּנֵי נֹף וְתַחְפַּנְחֵס. הֵם מִצְרַיִם שֶׁאַתֶּם בּוֹטְחִים עֲלֵיהֶם לְעֶזְרָה:",1,0],[2,16,"יִרְעוּךְ קָדְקֹד. לְשׁוֹן רְצִיצָה, כְּדִמְתַרְגְּמִינָן ״וְרָצוּץ״ (דברים כח:לג): ״וּרְעִיעַ״:",2,0],[2,17,"הֲלֹא זֹאת תַּעֲשֶׂה לָּךְ. הֲלֹא אֶת הָרָעָה וְאֶת הַפּוּרְעָנוּת הַזֹּאת תִּגְרֹם לָךְ הָאַשְׁמָה וְהֶעָוֹן אֲשֶׁר עָזַבְתְּ אֶת ה׳ אֱלֹהַיִךְ:",1,0],[2,17,"בְּעֵת מוֹלִיכֵךְ בַּדָּרֶךְ. שֶׁהָיָה מְלַמֵּד אוֹתְךָ דֶּרֶךְ הַטּוֹבָה וְהַיְשָׁרָה:",2,0],[2,18,"מַה לָּךְ לְדֶרֶךְ מִצְרַיִם. לָמָּה תַּעַזְבִי אוֹתִי וְתִבְטְחִי עַל מִצְרַיִם?",1,0],[2,18,"לִשְׁתּוֹת מֵי שִׁחוֹר. שֶׁטִּבְּעוּ זְכוֹרֵיכֶם בַּנִּילוּס; שִׁחוֹר הוּא נִילוּס, כְּמָה שֶׁנֶּאֱמַר ״מִן הַשִּׁיחוֹר אֲשֶׁר עַל פְּנֵי מִצְרָיִם״ בְּסֵפֶר יְהוֹשֻׁעַ (יהושע יג:ג):",2,0],[2,18,"וּמַה לָּךְ. לִמְרֹד בִּי לְמַעַן תִּגְלִי לְדֶרֶךְ אַשּׁוּר, לְמֵעֵבֶר נְהַר פְּרָת:",3,0],[2,19,"תְּיַסְּרֵךְ רָעָתֵךְ. סוֹף שֶׁרָעָתֵךְ תָּבִיא עָלֶיךָ יִסּוּרִין:",1,0],[2,19,"וּמְשׁוּבוֹתַיִךְ. לְשׁוֹן ״בָּנִים שׁוֹבָבִים״ (ירמיה ג:יד):",2,0],[2,19,"תּוֹכִיחוּךְ. לְשׁוֹן ״מוּסָר״ (ירמיה ל:יד):",3,0],[2,19,"וְלֹא פַחְדָּתִי. פַּחַד שֶׁלִּי לֹא הָיָה בְּלִבֵּךְ לִירָא אוֹתִי:",4,0],[2,20,"שָׁבַרְתִּי עֻלֵּךְ. הָעוֹל שֶׁל עֵץ נוֹפֵל בּוֹ לְשׁוֹן שְׁבִירָה, וְהַמּוֹסְרוֹת, שֶׁהֵן שֶׁל עוֹר, נוֹפֵל בָּהֶן לְשׁוֹן נְתִיקָה:",1,0],[2,20,"מוֹסְרוֹתַיִךְ. הֵם רְצוּעוֹת שֶׁקּוֹשְׁרִין בָּהֶם הָעוֹל:",2,0],[2,20,"וַתֹּאמְרִי לֹא אֶעֱבוֹר. עַל דְּבָרֶיךָ:",3,0],[2,20,"כִּי עַל כָּל גִּבְעָה. אַךְ אַתָּה לֹא שָׁמַרְתָּ הַבְטָחָתְךָ, וְעַל כָּל גִּבְעָה אַתְּ צֹעָה – לְשׁוֹן מִשְׁכָּב וּמַצָּע. כִּי מְשַׁמֵּשׁ לְשׁוֹן אֶלָּא:",4,0],[2,21,"נְטַעְתִּיךְ שׂוֹרֵק. שׂוֹרֵק הוּא זְמוֹרוֹת גֶּפֶן טוֹב, כְּלוֹמַר בְּנֵי אָבוֹת כְּשֵׁרִים וְצַדִּיקִים. וּמִדְרָשׁוֹ: נְטַעְתִּיךְ שׂוֹרֵק, הוֹסַפְתִּי לְךָ עַל שֶׁבַע מִצְווֹת שֶׁל בְּנֵי נֹחַ שֵׁשׁ מֵאוֹת וָשֵׁשׁ, כְּמִנְיַן שׂוֹרֵ״ק:",1,0],[2,21,"סוּרֵי. דִישְׁטוֹרְלָטוֹ״רְשׁ בְּלַעַ״ז:",2,0],[2,21,"גֶּפֶן נָכְרִיָּה. הַצּוֹמַחַת בַּיְּעָרִים:",3,0],[2,22,"בַּנֶּתֶר. מִין אֲדָמָה שֶׁחָפִין וְשָׁפִין בָּהּ אֶת הַבְּגָדִים:",1,0],[2,22,"בּוֹרִית. נִקָּיוֹן, כְּמוֹ ״וּבַר לֵבָב״ (תהלים כד:ד). וְיֵשׁ לוֹעֲזִים בּוֹרִית – שָׁאבוֹ״ן בְּלַעַז:",2,0],[2,22,"נִכְתָּם עֲוֺנֵךְ. ״הָא כְּרוֹשֶׁם כִּתְמָא דְּלָא דָכֵי, כֵּן סַגִּיאוּ חוֹבֵיךְ קֳדָמַי״ (תרגום יונתן):",3,0],[2,22,"כֶּתֶם. טָאקָ״א בְּלַעַ״ז:",4,0],[2,22,"עֲוֺנֵךְ. עַל עֲוֹן הָעֵגֶל נֶאֱמַר, שֶׁהוּא קַיָּם לְעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר ״וּבְיוֹם פָּקְדִי וּפָקַדְתִּי עֲלֵיהֶם״ (שמות לב:לד) – כָּל פְּקִידוֹת הַבָּאוֹת עַל יִשְׂרָאֵל, יִהְיֶה מִקְצָת עֲוֹן הָעֵגֶל בָּהֶם (סנהדרין קב.):",5,0],[2,23,"רְאִי דַרְכֵּךְ בַּגַּיְא. מָה עָשִׂית מוּל בֵּית פְּעוֹר (דברים ג:כט)! וְעוֹדֵ עַתָּה אַתְּ מַחֲזֶקֶת בְּאוֹתוֹ הַדֶּרֶךְ כִּבְכָרָה קַלָּה הַמְשָׂרֶכֶת דְּרָכֶיהָ:",1,0],[2,23,"בִּכְרָה. גְּמַלָּה נְקֵבָה בְּחוּרָה, שֶׁהִיא אוֹהֶבֶת לָנוּעַ. ״בִּכְרֵי מִדְיָן״ (ישעיהו ס:ו) מְתֻרְגָּם: ״הוֹגְנֵי מִדְיָן״, וְהֵם גְּמַלִּים בְּחוּרִים; כְּמוֹ שֶׁמָּצִינוּ בְּסַנְהֶדְרִין (סנהדרין נב.): נְפִישֵׁי גְּמַלֵּי סָבֵי דְּטָעֲינִי מַשְׁכֵּי דְּהוֹגְנֵי:",2,0],[2,23,"מְשָׂרֶכֶת. מַחֲזֶקֶת בְּדַרְכֵי נְעוּרֶיהָ; לְשׁוֹן מַסְרִיךְ (בבא מציעא ו.), סָרִיךְ (גיטין סח:). וְיֵשׁ לְחַבְּרוֹ עִם ״שְׂרוֹךְ נַעַל״ (בראשית יד:כג) – קוֹשֶׁרֶת דַּרְכֵי נַעֲרוּתָהּ בְּלִבָּהּ:",3,0],[2,24,"פֶּרֶה. שַׁלְוָואטִיקְ״וּ בְּלַעַ״ז, וְיֵשׁ לוֹעֲזִין קוּלִיי״ן בְּלַעַ״ז:",1,0],[2,24,"לִמּוּד מִדְבָּר. הַלָּמוּד לִהְיוֹת בַּמִּדְבָּרוֹת; כֵּן אָהַבְתְּ לָנוּעַ:",2,0],[2,24,"שָׁאֲפָה רוּחַ. פּוֹתַחַת אֶת פִּיהָ וְשׁוֹאֶפֶת רוּחַ, וּלְעוֹלָם הוּא חוֹזֵר לִמְקוֹמוֹ (קהלת א:ו):",3,0],[2,24,"תַּאֲנָתָהּ מִי יְשִׁיבֶנָּה. אוֹתָהּ מִדַּת תַּנִּינִים שֶׁיֵּשׁ בָּהּ, כִּי גַּם הַתַּנִּין שׁוֹאֵף רוּחַ, כְּמָה שֶׁנֶּאֱמַר ״שָׁאֲפוּ רוּחַ כַּתַּנִּים״ (ירמיה יד:ו). מִי יְשִׁיבֶנָּה מֵאוֹתָהּ מִדָּה? כֵּן אַתֶּם, מִי יוּכַל לַהֲשִׁיבְכֶם מִדַּרְכְּכֶם הָרָעָה?",4,0],[2,24,"כָּל מְבַקְשֶׁיהָ לֹא יִיעָפוּ. כִּי עַל חִנָּם יִיעָפוּ, שֶׁלֹּא יוּכְלוּ לְהַשִּׂיגָהּ. וּמַה סוֹפָהּ? בְּחָדְשָׁהּ יִמְצָאוּנְהָ. חֹדֶשׁ אֶחָד יֵשׁ בַּשָּׁנָה שֶׁהִיא יְשֵׁנָה כָּל הַחֹדֶשׁ, וְאָז הִיא נִלְכֶּדֶת; אַף אַתֶּם, חֹדֶשׁ אֶחָד (הוּא אָב) הוּכַן לָכֶם כְּבָר מִימוֹת הַמְרַגְּלִים, שֶׁקָּבְעוּ אֲבוֹתֵיכֶם בְּכִיַּת חִנָּם, בּוֹ תִּלָּכְדוּ (סוטה לה.). תַּאֲנָתָהּ. שׁוֹ״ן דְּגְרוֹנְמִינְ״ט בְּלַעַ״ז. וְכֵן תִּרְגֵּם יוֹנָתָן: ״כִּירוּדָא״. דָּבָר אַחֵר: לְשׁוֹן יְלָלָה, כְּמוֹ ״תַּאֲנִיָּה וַאֲנִיָּה״ (יחזקאל כט:ב). לָשׁוֹן אַחֵר: שַׁאקוֹנְטְרִיאָ״ה בְּלַעַ״ז, כְּמוֹ ״תַּאֲנַת שִׁילֹה״ (יהושע טז:ו):",5,0],[2,25,"מִנְעִי רַגְלֵךְ מִיָּחֵף. זוֹ הִיא מִדָּתֵךְ, כְּפֶרֶא הָאוֹהֶבֶת לָנוּעַ. נְבִיאַי אוֹמְרִים לִיךְ: מִנְעִי עַצְמֵךְ מֵעֲבוֹדָה זָרָה שֶׁלֹּא תֵּלְכִי יָחֵף בַּגּוֹלָה, וּמִנְעִי גְּרוֹנֵךְ מִלָּמוּת בַּצָּמָא; וַתֹּאמְרִי עַל דִּבְרֵי הַנְּבִיאִים נוֹאָשׁ. אֵין מִיחוּשׁ, נוֹאַשְׁתִּי בְּדִבְרֵיכֶם. נוֹאָשׁ נוֹקְלִיי״ר בְּלַעַ״ז:",1,0],[2,26,"כִּי יִמָּצֵא. בִּתְחִלָּה כְּשֶׁהוּא נִמְצָא גַּנָּב, וְהוּא הָיָה מֻחְזָק נֶאֱמָן; כָּךְ תִּרְגֵּם יוֹנָתָן:",1,0],[2,27,"וּבְעֵת רָעָתָם יֹאמְרוּ. אֵלַי קוּמָה וְהוֹשִׁיעֵנוּ. וְכֵן תַּרְגּוּם יוֹנָתָן: ״וּבְעִידָּן דְּבִישְׁתָּא אַתְיָא עֲלֵיהוֹן כַּפְרִין בְּטָעוּתְהוֹן וּמוֹדָן קֳדָמַי וְאָמְרִין רַחֵם עֲלָנָא וּפְרוּקְנָא״:",1,0],[2,28,"מִסְפַּר עָרֶיךָ הָיוּ אֱלֹהֶיךָ. בְּכָל עִיר וָעִיר אֱלוֹהַּ אַחֵר:",1,0],[2,29,"לָמָּה תָרִיבוּ. אֵיךְ תָּבֹאוּ לְהִתְוַכֵּחַ בְּרִיב וְלוֹמַר: לֹא חָטָאנוּ?!",1,0],[2,29,"כֻּלְּכֶם פְּשַׁעְתֶּם בִּי. אַף הַצַּדִּיקִים בְּמַשְׁמָע; הַיְינוּ דְּאָמְרֵי אִינְשֵׁי: בַּהֲדֵי הוּצָא, לָקִיא כַּרְבָּא (בבא קמא צב.):",2,0],[2,30,"לַשָּׁוְא הִכֵּיתִי. עַל חִנָּם, כִּי לֹא הוֹעִיל שֶׁיִּקְחוּ מוּסָר:",1,0],[2,30,"אָכְלָה חַרְבְּכֶם. אֶת נְבִיאֵיכֶם, הֲרַגְתֶּם אֶת זְכַרְיָה (דברי הימים ב כד:כא) וִישַׁעְיָה (יבמות מט:):",2,0],[2,31,"רְאוּ דְבַר ה׳. הוֹצִיא לָהֶם צִנְצֶנֶת הַמָּן, אָמַר לָהֶם: רְאוּ כָּאן מַה דְּבַר ה׳ מוֹעִיל (מכילתא בשלח ויסע ה)! הֲמִדְבָּר הָיִיתִי לְיִשְׂרָאֵל. לְשׁוֹן תֵּימָה הוּא, לְכָךְ נְקוּדה מ״ם רָפִי וְה״א בַּחֲטַף פַּתָּח: כְּלוּם נִדְמֶה לַאֲבוֹתֵיכֶם שֶׁהוּא מִדְבָּר כְּשֶׁהָלְכוּ בּוֹ, שֶׁהוֹרַדְתִּי לָהֶם לֶחֶם זֶה דְּבַר יוֹם בְּיוֹמוֹ (שמות טז:ד)?",1,0],[2,31,"מַאְפֵּלְיָה. לְשׁוֹן חֹשֶׁךְ:",2,0],[2,31,"מַדּוּעַ אָמְרוּ עַמִּי רַדְנוּ. נִבְדַּלְנוּ מִמְּךָ, כְּמוֹ הָרוֹדֶה פַּת מִן הַתַּנּוּר (תרומות י,ג). כָּךְ מִדְרַשׁ רַבִּי תַּנְחוּמָא (תנחומא, במדבר ב). וּמְנַחֵם פֵּרֵשׁ רַדְנוּ לְשׁוֹן יְרִידָה, וְעוֹד פָּנִים אֲחֵרִים:",3,0],[2,33,"תֵּיטִיבִי. תְּקַשְּׁטִי עַצְמֵךְ לִקְרַאת נוֹאֲפַיִךְ, כְּמוֹ ״וַתֵּיטֶב רֹאשָׁהּ״ דְּאִיזֶבֶל, בְּפָרָשַׁת יֵהוּא (מלכים ב ט:ל):",1,0],[2,33,"גַּם אֶת הָרָעוֹת לִמַּדְתְּ. חָזַרְתְּ עַל כָּל רוֹעַ דֶּרֶךְ, לִלְמוֹד אֶת הַמְקֻלְקֶלֶת שֶׁבְּכֻלָּם:",2,0],[2,33,"גַּם. לְשׁוֹן אֲפִילוּ. לָכֵן. לְשׁוֹן שְׁבוּעַת אֱמֶת, אַךְ אֶת הַדֶּרֶךְ הָרָעָה שֶׁבְּכָל הַדְּרָכִים לִמַּדְתְּ לְעַצְמֵךְ:",3,0],[2,33,"לִמַּדְתְּ. הִנְהַגְתְּ:",4,0],[2,34,"בַּמַּחְתֶּרֶת מְצָאתִים. לֹא מָצָאתָ אוֹתָם בַּמַּחְתֶּרֶת כְּשֶׁהָרַגְתָּ אוֹתָם:",1,0],[2,34,"מְצָאתִים. כֹּה יֹאמַר לִנְקֵבָה לְשׁוֹן פָּעַלְתְּ, וְהַרְבֵּה יֵשׁ בְּסֵפֶר (יחזקאל טז:נח) אֶת נְשָׂאתִים:",2,0],[2,34,"כִּי עַל כָּל אֵלֶּה. שֶׁהָיוּ מוֹכִיחִים אוֹתְךָ בַּדְּבָרִים הָאֵלֶּה:",3,0],[2,35,"וַתֹּאמְרִי. בְּלִבֵּךְ׃",1,0],[2,35,"כִּי נִקֵּיתִי. אֲשֶׁר זַכָּאָה אֲנִי נַפְשִׁי:",2,0],[2,35,"נִשְׁפָּט אוֹתָךְ. בָּא עִמָּךְ בְּמִשְׁפָּט:",3,0],[2,36,"תֵּזְלִי. לְשׁוֹן זִלְזוּל:",1,0],[2,36,"לְשַׁנּוֹת אֶת דַּרְכֵּךְ. לַעֲזֹב אוֹתִי וְלִסְמֹךְ עַל מִצְרַיִם לְעֶזְרָה, בִּימֵי יְהוֹיָקִים (מלכים ב כד:ז) וְצִדְקִיָּהוּ (ירמיה לז):",2,0],[2,36,"לְשַׁנּוֹת. לְשׁוֹן שִׁנּוּי:",3,0],[2,36,"כַּאֲשֶׁר בֹּשְׁתְּ מֵאַשּׁוּר. שֶׁסָּמַךְ אָחָז עָלָיו, ״וַיָּצַר לוֹ וְלֹא חִזְּקוֹ״ כְּמָה שֶׁנֶּאֱמַר בְּדִבְרֵי הַיָּמִים (דברי הימים ב כח:כ):",4,0],[3,1,"לֵאמֹר הֵן יְשַׁלַּח וְגוֹ׳. יֵשׁ לִי לוֹמַר, שֶׁאֵין עוֹד אַתְּ רְאוּיָה לִי, כִּי כֵן דֶּרֶךְ הַמְּשַׁלֵּחַ אֶת אִשְׁתּוֹ וְהָלְכָה וְגוֹ׳:",1,0],[3,1,"וְאַתְּ זָנִית רֵעִים רַבִּים. עִם אוֹהֲבִים רַבִּים; וְאַף עַל פִּי כֵן, שׁוּבִי אֵלַי:",2,0],[3,1,"וְשׁוּב אֵלַי. כְּמוֹ ״עֲשׂוֹת״, וְלָשׁוּב אֵלַי אֲנִי עוֹסֵק בָּךְ:",3,0],[3,2,"שְׁפָיִים. יִבְלֵי מַיִם:",1,0],[3,2,"לֹא שֻׁגַּלְתְּ. לְשׁוֹן פִּילֶגֶשׁ:",2,0],[3,2,"יָשַׁבְתְּ לָהֶם. לִהְיוֹת נְכוֹנָה לִקְרָאתָם:",3,0],[3,2,"כַּעֲרָבִי. יוֹשֵׁב אֹהָלִים, שֶׁהוּא תָּמִיד מָצוּי בַּחוּץ, בַּמִּדְבָּרוֹת; וְעַל שֵׁם כָּךְ הוּא קָרוּי עֲרָבִי, שֶׁשּׁוֹכֵן בָּעֲרָבָה:",4,0],[3,3,"וּמַלְקוֹשׁ. כְּמָטָר הַיּוֹרֵד בְּנִיסָן (יואל ב:כג) עַל הַמְּלִילוֹת וְעַל הַקַּשִּׁין. וּמַלְקוֹשׁ טְרַדִיוֹ״א בְּלַעַ״ז:",1,0],[3,4,"הֲלוֹא מֵעַתָּה. הַלְוַאי שַׁבְתְּ מֵרָעָתֵךְ וְקָרָאת לִי אָבִי, וְאִם תַּעֲשִׂי כָּךְ, הֲיִנְטֹר לָךְ אֲדוֹנַיִךְ לְעוֹלָם אֵת אֲשֶׁר חָטָאת לוֹ, אִם יִשְׁמֹר לָנֶצַח? לֹא יִשְׁמֹר!",1,0],[3,5,"הִנֵּה דִבַּרְתְּ. בְּפִיךְ: ״לֹא נָבוֹא עוֹד אֵלֶיךָ״ (ירמיה ב:לא), וְאוֹתָהּ הָרָעָה תַּעֲשִׂי וְלֹא תִתְּנִי לֵב לָשׁוּב:",1,0],[3,5,"וַתּוּכָל. וְנִצַּחְתְּ לִמְרוֹד:",2,0],[3,6,"מְשׁוּבָה. נִצַּחַת (ירמיה ח:ה) וּמוּכַחַת בִּימֵי יֹאשִׁיָּהוּ הַמֶּלֶךְ כְּשֶׁצִּוַּנִי לְהַחֲזִיר עֲשֶׂרֶת הַשְּׁבָטִים (מגלה יד:). הֲרָאִיתָ אֲשֶׁר עָשְׂתָה מְשֻׁבָה יִשְׂרָאֵל ״הַשּׁוֹבֵבָה״ (ירמיה לא:כא), אַנְבּוֹזִייָ״ה בְּלַעַ״ז:",1,0],[3,6,"יִשְׂרָאֵל. עֲשֶׂרֶת הַשְּׁבָטִים:",2,0],[3,6,"הוֹלְכָה הִיא. בְּעוֹדָהּ עַל אַדְמָתָהּ, קוֹדֶם שֶׁגָּלְתָה בִּימֵי חִזְקִיָּהוּ עִם הוֹשֵׁעַ בֶּן אֵלָה (מלכים ב יז):",3,0],[3,6,"הוֹלְכָה. הָיְתָה הוֹלֶכֶת עַל כָּל הַר גָּבֹהַּ:",4,0],[3,6,"וַתִּזְנִי שָׁם. לַעֲבוֹדָה זָרָה. וַתִּזְנִי כְּמוֹ וַתִּזֶן: יוֹ״ד יְתֵרָה:",5,0],[3,7,"וָאֹמַר. עַל יְדֵי נְבִיאַי עָמוֹס וְהוֹשֵׁעַ בֶּן בְּאֵרִי וּשְׁאָר נְבִיאִים: אֵלַי תָּשׁוּב:",1,0],[3,7,"וַתֵּרֶא בָּגוֹדָה אֲחוֹתָהּ יְהוּדָה. כָּל זֶה. בֹּגֵדָה קָשָׁה מִמְּשׁוּבָה: יִשְׂרָאֵל, שֶׁהֵם רִאשׁוֹנִים לְקִלְקוּל וְלֹא רָאוּ פֻּרְעָנוּת לִלְמֹד מִמֶּנּוּ וְלָשׁוּב, קְרוּיִין מְשׁוּבָה; יְהוּדָה, שֶׁרָאוּ שֶׁגָּלוּ אֵלּוּ וְלֹא לָקְחוּ מוּסָר, קְרוּיִין בֹּגֵדָה:",2,0],[3,8,"וָאֵרֶא כִּי עַל כָּל אוֹדוֹת וגו׳. נְקֻדּוֹת טַעֲמֵי מִקְרָא זֶה מְלַמְּדִין עַל פֵּרוּשׁוֹ: יִשְׂרָאֵל נָקוּד זָקֵף, מֻבְדָּל מִשִּׁלַּחְתִּיהָ; שִׁלַּחְתִּיהָ נָקוּד זָקֵף גָּדוֹל לְעַצְמוֹ. וְזֶה פֵּרוּשׁוֹ: וָאֵרֶא נִסְתַּכַּלְתִּי בָּהּ לִיפָּרַע מִמֶּנָּה, וְלָמָּה? כִּי עַל כָּל אוֹדוֹת אֲשֶׁר נִאֲפָה מְשׁוּבָה יִשְׂרָאֵל, וּמָה הָיְתָה נִקְמָתִי? שִׁלַּחְתִּיהָ מֵעַל פָּנַי. וְלֹא יָרְאָה בֹּגֵדָה יְהוּדָה שֶׁרָאֲתָה בְּפוּרְעָנוּת שֶׁל שׁוֹמְרוֹן, לָתֵת לִבָּהּ לָשׁוּב:",1,0],[3,9,"וַתִּנְאַף אֶת הָאֶבֶן. ״וְטָעַת עִם פָּלְחֵי אַבְנַיָּא וְאָעֵיָא״, וְיוֹנָתָן תִּרְגֵּם מִקֹּל זְנוּתָהּ לְשׁוֹן קַלּוּת: ״מִדְּקַלִּילָא בְּעֵינָהָא טָעֲוָותָהָא״:",1,0],[3,10,"וְגַם בְּכָל זֹאת. שֶׁרָאוּ בְּקִלְקוּלַת פֻּרְעָנוּת חֲבֵרֵיהֶם:",1,0],[3,10,"כִּי אִם בְּשֶׁקֶר. דּוֹרוֹ שֶׁל יֹאשִׁיָּה מַרְאִין עַצְמָם שֶׁהֵם צַדִּיקִים, וְהֵם רְשָׁעִים הָיוּ. צָרִים צוּרוֹת שֶׁל עֲבוֹדָה זָרָה עַל דַּלְתוֹתֵיהֶם מִבִּפְנִים, חֶצְיָהּ עַל זוֹ וְחֶצְיָהּ עַל זוֹ, וּכְשֶׁהָיוּ מְבַעֲרֵי עֲבוֹדָה זָרָה בּוֹדְקִים, הָיָה הַדֶּלֶת פָּתוּחַ וְלֹא הָיוּ מַכִּירִין בָּהּ:",2,0],[3,11,"צִדְּקָה נַפְשָׁהּ מְשֻׁבָה יִשְׂרָאֵל. נִקְּתָה וּפָטְרָה עַצְמָהּ מִן הַדִּין, שֶׁלֹּא הָיָה לָהּ מִמִּי לִלְמוֹד:",1,0],[3,12,"הָלוֹךְ וְקָרָאתָ וְגוֹ׳. הָלוֹךְ כְּתַרְגּוּמוֹ: ״אֲזִיל״, לְשׁוֹן צִוּוּי; כָּאן צִוָּהוּ לֵילֵךְ וּלְהַחֲזִיר עֲשֶׂרֶת הַשְּׁבָטִים בִּימֵי יֹאשִׁיָּהוּ (מגלה יד:), כְּמוֹ שֶׁאָמַר לְמַעְלָה (פסוק ו), שֶׁבִּימֵי יֹאשִׁיָּהוּ נֶאֶמְרָה לוֹ נְבוּאָה זוֹ; וְחָזְרוּ מִקְצָת מֵהֶן בִּשְׁמוֹנֶה עֶשְׂרֵה לְיֹאשִׁיָּהוּ (דברי הימים ב לה,יז-יט):",1,0],[3,12,"צָפוֹנָה. אֶל הַמְּקוֹמוֹת שֶׁגָּלוּ שָׁם לְאַשּׁוּר:",2,0],[3,12,"פָּנַי. ״רוּגְזִי״, כֵּן תַּרְגֵּם יוֹנָתָן:",3,0],[3,13,"פָּשָׁעַתְּ. מָרַדְתְּ:",1,0],[3,13,"וַתְּפַזְּרִי אֶת דְּרָכַיִךְ. לְשׁוֹן זְנוּת; פִּסּוּק רַגְלַיִם לְמִשְׁכְּבֵי אִשָּׁה:",2,0],[3,14,"שׁוֹבָבִים. אַנְוִוישִׁי״ר בְּלַעַ״ז, שֶׁשּׁוֹבַבְתֶּם דַּרְכְּכֶם מֵרוֹב כֹּל (דברים כח:מז), שֶׁהֱיִיתֶם בְּשַׁלְוָה וְעֹנֶג, כְּמוֹ שֶׁהוּא אוֹמֵר ״הַפּוֹרְטִים עַל פִּי הַנָּבֶל״ (עמוס ו:ה), ״הַשֹּׁתִים בְּמִזְרְקֵי יַיִן״ (עמוס ו:ו):",1,0],[3,14,"כִּי אָנֹכִי בָּעַלְתִּי בָכֶם. וְנִקְרֵאתֶם בִּשְׁמִי, שֶׁאֲנִי אָדוֹן לָכֶם, וְאֵין כְּבוֹדִי לְהַנִּיחַ אֶתְכֶם בְּיַד אוֹיְבִי:",2,0],[3,16,"לֹא יֹאמְרוּ עוֹד אֲרוֹן. כִּי כָל כְּנִיסַתְכֶם תְּהֵא קְדוֹשָׁה, וְאֶשְׁכּוֹן בָּהּ כְּאִלּוּ הוּא אֲרוֹן:",1,0],[3,16,"יִפְקֹדוּ. כְּמוֹ יִזְכְּרוּ:",2,0],[3,16,"וְלֹא יֵעָשֶׂה עוֹד. מַה שֶּׁנַּעֲשָׂה בּוֹ כְּבָר בְּשִׁילֹה, שֶׁהֱבִיאוּהוּ בַּמִּלְחָמָה עִם פְּלִשְׁתִּים, בִּימֵי עֵלִי (שמואל א ד):",3,0],[3,17,"וְנִקְווּ. וְנִקְבְּצוּ, לְשׁוֹן ״מִקְוֵה מַיִם״ (ויקרא יא:לו):",1,0],[3,17,"שְׁרִירוּת. לְשׁוֹן רְאִיָּה, כְּמוֹ ״אֲשׁוּרֶנּוּ״ (במדבר כד, יז):",2,0],[3,18,"יֵלְכוּ בֵית יְהוּדָה עַל בֵּית יִשְׂרָאֵל. עִמָּם יִתְחַבְּרוּ וְיִתְוַסְּפוּ עֲלֵיהֶם לִהְיוֹת מַמְלָכָה אַחַת:",1,0],[3,19,"וְאָנֹכִי אָמַרְתִּי. בְּלִבִּי, וְלָכֵן הִנְחַלְתִּים לַאֲבוֹתֵיכֶם:",1,0],[3,19,"אֵיךְ אֲשִׁיתֵךְ בַּבָּנִים. אֶת, עֲדָתִי וְאֻמָּתִי, בְּתוֹךְ שְׁאָר בָּנִים, לְפִיכָךְ בֵּרַרְתִּי מָנָה יָפָה וְאֶתֶּן לָךְ אֶרֶץ חֶמְדָּה:",2,0],[3,19,"צְבִי צִבְאוֹת גּוֹיִם. צִבְיוֹן כָּל צִבְאוֹת גּוֹיִם (תנחומא, משפטים יז):",3,0],[3,20,"אָכֵן. אֲבָל אַתֶּם לֹא עֲשִׂיתֶם מַחֲשַׁבְתִּי, כִּי אִם כְּמוֹ אִשָּׁה שֶׁבּוֹגְדָה מֵרֵעָהּ עַל שֶׁאֵינוֹ יָכוֹל לְהַסְפִּיק מְזוֹנוֹתֶיהָ, כֵּן בְּגַדְתֶּם בִּי – הַמַּסְפִּיק לָכֶם כָּל טוֹב; כָּךְ מִדְרַשׁ אַגָּדָה (תנחומא, משפטים יז):",1,0],[3,21,"עַל שְׁפָיִים נִשְׁמָע. קָרוֹב הוּא לְהִשָּׁמַע:",1,0],[3,22,"הִנְנוּ אָתָנוּ לָךְ. הַנָּבִיא מְלַמְּדָם לְהִתְוַדּוֹת וְלוֹמַר כֵּן: הִנְנוּ אָתָנוּ לָךְ, אָכֵן לַשֶּׁקֶר וְגוֹ, וְהַבֹּשֶׁת אָכְלָה וְגוֹ׳ נִשְׁכְּבָה בְבָשְׁתֵּנוּ. כָּל זֶה לְשׁוֹן תְּפִלָּה שֶׁהַנָּבִיא מְלַמְּדָם לוֹמַר:",1,0],[3,22,"אָתָנוּ. בָּאנוּ:",2,0],[3,23,"אָכֵן לַשֶּׁקֶר. שָׁמַרְנוּ מִגְּבָעוֹת וְהָמוֹן הָרִים שֶׁעָבַדְנוּ עֲבוֹדָה זָרָה שָׁם (על פי שמואל א כה:כא):",1,0],[3,23,"אָכֵן. בֶּאֱמֶת:",2,0],[3,24,"וְהַבֹּשֶׁת. עֲבוֹדָה זָרָה שֶׁעָסַקְנוּ בָּהּ; כְּמָה דְאַתְּ אָמֵר ״וַיִּנָּזְרוּ לַבֹּשֶׁת״ (הושע ט:י):",1,0],[3,24,"אָכְלָה אֶת יְגִיעַ אֲבוֹתֵינוּ. בַּעֲוֹן עֲבוֹדָתָהּ הָיָה יְגִיעֵנוּ לָבַז:",2,0],[4,1,"אִם תָּשׁוּב יִשְׂרָאֵל. בִּתְשׁוּבָה זוֹ אֵלַי תָּשׁוּב לִכְבוֹדְךָ וּגְדֻלָּתְךָ הָרִאשׁוֹנָה:",1,0],[4,1,"וְאִם תָּסִיר שִׁקּוּצֶיךָ מִפָּנַי. אָז לֹא תָנוּד – לָצֵאת בַּגּוֹלָה:",2,0],[4,2,"וְנִשְׁבַּעְתָּ חַי ה׳ בֶּאֱמֶת. כְּשֶׁתִּשָּׁבַע בִּשְׁמִי תִּשָּׁבַע בֶּאֱמֶת, וְלֹא כַּאֲשֶׁר עַתָּה, שֶׁכָּתוּב בָּכֶם ״אִם חַי ה׳ יֹאמְרוּ אָכֵן לְשֶׁקֶר יִשָּׁבֵעוּ״ (ירמיה ה:ב):",1,0],[4,2,"וְהִתְבָּרְכוּ בוֹ גוֹיִם. אִם תַּעֲשׂוּ כֵּן, אָז יִתְבָּרְכוּ בְּיִשְׂרָאֵל הַגּוֹיִם; כָּל גּוֹי יֹאמַר לִבְנוֹ: תְּהֵא כִּפְלוֹנִי יִשְׂרָאֵל:",2,0],[4,2,"יִתְהַלָּלוּ. יַגִּידוּ שִׁבְחֲכֶם. דָּבָר אַחֵר: יִתְהַלָּלוּ – מִי שֶׁיּוּכַל לְהִדָּבֵק בְּיִשְׂרָאֵל, יִתְפָּאֵר בַּדָּבָר; פורוונטי״ר בְּלַעַ״ז:",3,0],[4,3,"כִּי כֹה אָמַר ה׳ וגו׳ נִירוּ לָכֶם נִיר. – הֱווּ לְמֵדִין מֵעוֹבְדֵי אֲדָמָה, שֶׁנָּרִים אוֹתָהּ בִּימֵי הַקַּיִץ לְהָמִית שָׁרְשֵׁי הָעֲשָׂבִים, שֶׁלֹּא תְּהֵא מַעֲלָה קוֹצִים בְּעֵת הַזֶּרַע בַּחֹרֶף; אַף אַתֶּם הֵטִיבוּ מַעֲשֵׂיכֶם בְּטֶרֶם תָּבֹא עֲלֵיכֶם הָרָעָה, שֶׁלֹּא תְּהֵא תְּפִלַּתְכֶם נִמְאֶסֶת כְּשֶׁתִּצְעֲקוּ:",1,0],[4,3,"וְאַל תִּזְרְעוּ אֶל קוֹצִים. וְאַל תְּהִי צַעֲקַתְכֶם לְפָנַי מִתּוֹךְ הָרֶשַׁע כִּי אִם מִתּוֹךְ תְּשׁוּבָה, שֶׁלֹּא תִהְיוּ דּוֹמִים לְזוֹרֵעַ בְּלֹא נִיר, וְהִיא נֶהְפֶּכֶת לְקוֹצִים; קַרְדוֹנְ״שׁ בְּלַעַ״ז:",2,0],[4,4,"הִמּוֹלוּ לַה׳. בְּטֶרֶם תֵּצֵא חֲמָתִי כָאֵשׁ; זֶהוּ כְּנִיר לִפְנֵי הַזֶּרַע (ירמיה ג:ג):",1,0],[4,5,"וְאִמְרוּ תִּקְעוּ שׁוֹפָר. הַזְהִירוּ אֶת יוֹשְׁבֵי הָאָרֶץ, שֶׁיִּתְקְעוּ בְּשׁוֹפָר לִבְרוֹחַ:",1,0],[4,5,"מַלְאוּ. לְשׁוֹן אֲסִיפָה, וְהַרְבֵּה יֵשׁ בַּמִּקְרָא: ״אֲשֶׁר יִקָּרֵא עָלָיו מְלֹא רֹעִים״ (ישעיהו לא:ד); ״קָרְאוּ אַחֲרֶיךָ מָלֵא״ (ירמיהו יב:ו); ״יַחַד עָלַי יִתְמַלָּאוּן״ (איוב טז:י):",2,0],[4,6,"שְׂאוּ נֵס. לִבְרוֹחַ לְצִיּוֹן:",1,0],[4,6,"הָעִיזוּ. הֵאָסְפוּ, כְּמוֹ ״שְׁלַח הָעֵז״ (שמות ט:יט):",2,0],[4,7,"עָלָה אַרְיֵה. נְבוּכַדְנֶצַּר (מגלה יא.):",1,0],[4,7,"מִסֻּבְּכוֹ. דֶּרֶךְ אַרְיֵה לֵישֵׁב בְּמַאֲרַב סִבְכֵי הַיַּעַר (ישעיה י:לד); אשפיישי״ש בְּלַעַז:",2,0],[4,7,"תִּצֶּינָה. לְשׁוֹן ״צִיָּה״ (ירמיה ב:ו):",3,0],[4,8,"עַל זֹאת. מַה הוּא זֹאת? כִּי לֹא שָׁב וְגוֹ׳. וְאַף עַל פִּי שֶׁדִּבֵּר לְמַעְלָה בִּנְבוּכַדְנֶצַּר עַל הַחֻרְבָּן, כָּאן חָזַר לְדַבֵּר בְּמִיתַת יֹאשִׁיָּהוּ:",1,0],[4,8,"כִּי לֹא שָׁב חֲרוֹן אַף וְגוֹ׳. וְאַף עַל פִּי שֶׁשָּׁב יֹאשִׁיָּהוּ בְּכָל לֵב, נֶאֱמַר בּוֹ (מלכים ב כג:כו) ״לֹא שָׁב ה׳ מֵחֲרוֹן אַפּוֹ עַל כָּל הַכְּעָסִים אֲשֶׁר הִכְעִיסוֹ מְנַשֶּׁה״:",2,0],[4,9,"וְהָיָה בַּיּוֹם הַהוּא. בְּיוֹמוֹ שֶׁל יֹאשִׁיָּהוּ יִתְמְהוּ: לָמָּה עָלְתָה בּוֹ כָּל כָּךְ? וְהֵם אֵין יוֹדְעִין שֶׁאֵין דּוֹרוֹ חוֹזֵר יָפֶה; כְּשֶׁבָּא לְבַעֵר אֶת עֲבוֹדָה זָרָה מֶה הָיוּ לֵיצָנֵי הַדּוֹר עוֹשִׂין? חוֹקְקִין צוּרַת עֲבוֹדָה זָרָה עַל דַּלְתוֹתֵיהֶן, חֶצְיָהּ בְּדֶלֶת זֶה וְחֶצְיָהּ בְּדֶלֶת זֶה; כְּשֶׁהָיָה פּוֹתְחוֹ לֹא הָיְתָה נִכֶּרֶת, וּכְשֶׁהָלַךְ מִשָּׁם סוֹגְרָהּ וְהִיא מִתְחַבֶּרֶת:",1,0],[4,10,"הַשֵּׁא הִשֵּׁאתָ. אַטִינְטַא״ר בְּלַעַ״ז, לְשׁוֹן ״הַנָּחָשׁ הִשִּׁיאַנִי״ (בראשית ג:יג); שֶׁנְּבִיאֵי הַשֶּׁקֶר נִבָּאִים לָכֶם: שָׁלוֹם יִהְיֶה לָכֶם:",1,0],[4,11,"לָעָם הַזֶּה. עַל הָעָם הַזֶּה, כְּשֶׁיִּגְלוּ כֻּלָּם:",1,0],[4,11,"צַח שְׁפָיִים. מְכַבֵּד וּמְטַאטֵא אַף אֶת שְׂדוֹת יִבְלֵי הַמַּיִם, לְשִׁיתָם מִדְבָּר. לָשׁוֹן אַחֵר: צַח לְשׁוֹן ״צָמָא״, דִּמְתַרְגְּמִינָן: ״צְחוּתָא״:",2,0],[4,11,"דֶּרֶךְ בַּת עַמִּי. אוֹתוֹ רוּחַ בָּא. וְגַם לוֹא לִזְרוֹת מוֹץ מִגֹּרֶן, אהבוניי״ר בְּלַעַז, כְּמוֹ ״וְאֶזְרֵם בְּמִזְרֶה״ (ירמיה טו:ז):",3,0],[4,11,"וְלוֹא לְהָבַר. וְלִנְקוֹת תְּבוּאָה הוּא בָּא, כְּלוֹמַר: לֹא לְטוֹבָה כִּי אִם לְרָעָה, לְהַגְלוֹת אֶת אֲנָשִׁים (וְנָשִׁים) טַף וּבְהֵמָה:",4,0],[4,12,"רוּחַ מָלֵא. מֵאֵלֶּה הַפֻּרְעָנוּת יָבוֹא לִי רוּחַ מָלֵא, רוּחַ שָׁלֵם, שֶׁלֹּא אֶחְזוֹר בּוֹ וְלֹא אֶנָּחֵם. רוּחַ טַלְנ״ט בְּלַעַ״ז:",1,0],[4,12,"מִשְׁפָּטִים. לְשׁוֹן וִכּוּחַ:",2,0],[4,13,"וְכַסּוּפָה. אִיקוֹמָאטְרוֹבִילוֹ בְּלַעַ״ז:",1,0],[4,14,"אוֹנֵךְ. חֲמָסֵךְ:",1,0],[4,15,"כִּי קוֹל מַגִּיד מִדָּן. ״אָרֵי קַל נְבִיָּא מִתְנְבָן עֲלֵיהוֹן דְּגָלוֹן עַל דְּפָלְחוּ לָעֲגָלָה דִּבְדָן וּמְבַשְּׂרָן בְּשׁוֹרָן בַּיְּשָׁן יָתוּן עֲלֵיהוֹן עַל דְּאִשְׁתַּעֲבְדוּ לְצַלְמָא דָּקִים מִיכָה בְּטוּרָא דְּבֵית אֶפְרַיִם״. וְאַף עַל פִּי שֶׁכְּבָר גָּלוּ הָעֲגָלִים מִיְּמוֹת סַנְחֵרִב, עֲדַיִן עֲווֹנָם קַיָּם. גְּדוֹלָה הִיא עֲבֵרָה שֶׁשּׁוֹבֶרֶת לְפָנֶיהָ וּלְאַחֲרֶיהָ: לְפָנֶיהָ מִיְּמוֹת אַבְרָהָם שֶׁנֶּאֱמַר ״וְיִרְדֹּף עַד דָּן״ (בראשית יד:יד), כֵּיוָן שֶׁהִגִּיעַ לְדָן תָּשַׁשׁ כֹּחוֹ שֶׁעֲתִידִין בָּנָיו לַעֲבֹד שָׁם עֲבוֹדָה זָרָה; וּלְאַחֲרֶיהָ בְּחֻרְבַּן הַבַּיִת שֶׁנֶּאֱמַר: כִּי קוֹל מַגִּיד מִדָּן:",1,0],[4,15,"וּמַשְׁמִיעַ אָוֶן. אָוֶן שֶׁבֶר:",2,0],[4,16,"נוֹצְרִים. נוֹתְנֵי מָצוֹר עֲלֵיהֶם:",1,0],[4,17,"שָׂדַי. כְּמוֹ שָׂדֶה:",1,0],[4,17,"אוֹתִי מָרָתָה. הִקְנִיטָה; כְּמוֹ ״מַמְרִים הֱיִיתֶם״ (דברים ט:כד) – מַרְגְּזִין:",2,0],[4,18,"עָשׂוֹ אֵלֶּה. לַעֲשׂוֹת אֵלֶּה לָךְ:",1,0],[4,19,"אוֹחִילָה. לְשׁוֹן חִיל וְרֶתֶת:",1,0],[4,19,"קִירוֹת. אַנְטִינָ״שׁ בְּלַעַ״ז:",2,0],[4,19,"שָׁמַעַתְּ נַפְשִׁי. מֵאֲחוֹרֵי הַפַּרְגּוֹד (חגיגה טו.) בָּאַתְנִי בְּשׂוֹרַת קוֹל מִתְּרוּעַת מִלְחָמָה:",3,0],[4,20,"שֶׁבֶר עַל שֶׁבֶר. חָרְבוֹת יְרוּשָׁלַיִם עַל גָּלוּת יְכָנְיָה:",1,0],[4,20,"רֶגַע יְרִיעוֹתָי. רֶגַע שֻׁדְּדוּ יְרִיעוֹתָי:",2,0],[4,21,"עַד מָתַי אֶרְאֶה. הָאֲסִיפוֹת הָאֵלֶּה הַנּוֹשְׂאִים נֵס, לְהִקָּבֵץ לָבֹא לְהִלָּחֵם:",1,0],[4,24,"הִתְקַלְקָלוּ. נִתְּקוּ וְנִזְרְקוּ מִמְּקוֹמָן; וְעִם ״קַלְקַל בַּחִצִּים״ (יחזקאל כא:כו) חִבְּרוֹ מְנַחֵם:",1,0],[4,26,"וְהִנֵּה הַכַּרְמֶל. אֶרֶץ הַנְּטוּעַ כָּל טוֹב כַּכַּרְמֶל נִהְיָה מִדְבָּר. מִדְרַשׁ אַגָּדָה: רָאִיתִי הֶהָרִים אֵלּוּ הָאָבוֹת, וְכָל הַגְּבָעוֹת אֵלּוּ אִמָּהוֹת (ראש השנה יא.), כְּלוֹמַר זְכוּתָן תַּמָּה, אֵין הָאָדָם, זְכוּת מֹשֶׁה שֶׁנֶּאֱמַר בּוֹ עָנִיו מִכָּל הָאָדָם (במדבר יב,ג), וְהִנֵּה הַכַּרְמֶל אֵלִיָּהוּ:",1,0],[4,27,"וְכָלָה לֹא אֶעֱשֶׂה. בְּיוֹשְׁבֶיהָ, כִּי אוֹתִיר פְּלִיטִים שֶׁיֵּלְכוּ בַּגּוֹלָה:",1,0],[4,28,"תֶּאֱבַל. תֶּחֱרַב:",1,0],[4,28,"זַמּוֹתִי. לְשׁוֹן מַחֲשָׁבָה:",2,0],[4,28,"עַל כִּי דִבַּרְתִּי. הַפּוּרְעָנוּת הַזֶּה, וַאֲקַיְּמֶנָּה:",3,0],[4,28,"וְלֹא אָשׁוּב. וְלֹא אֶנָּחֵם, לַחְשֹׁב מַחְשָׁבוֹת טוֹבוֹת עֲלֵיהֶם:",4,0],[4,29,"וְרוֹמֵה. כְּמוֹ ״רָמָה בַיָּם״ (שמות טו:א):",1,0],[4,29,"בָּאוּ בֶעָבִים. בַּיְּעָרוֹת עָבִים, מְקוֹם סִיכּוּךְ קוֹצִים לְהִטָּמֵן:",2,0],[4,29,"וּבַכֵּפִים עָלוּ. ״סֶלַע״ (ירמיה כג:כט) מְתֻרְגָּם ״בְּכִיפַיָּא״:",3,0],[4,30,"כִּי תִלְבְּשִׁי שָׁנִי. לְהִתְנָאוֹת וְלִמְצֹא רַחֲמִים לִפְנֵי הַשּׁוֹדֵד:",1,0],[4,30,"תִּקְרְעִי בַפּוּךְ. לְשׁוֹן קְרִיעָה, שֶׁהַפּוּךְ נִרְאֶה כְּמַרְחִיב קֶרַע הָעַיִן; כָּךְ שָׁמַעְתִּי. וְגַם מְנַחֵם לֹא חָלַק, בְּמַחְבֶּרֶת קֶרַע:",2,0],[4,30,"פּוּךְ. לְשׁוֹן כָּחוֹל (שבת ח,ג):",3,0],[4,30,"עוֹגְבִים. הַמְּשַׂחֲקִים עִם הַנָּשִׁים בְּצִדֵּי מִינֵי נִיאוּף; כְּמוֹ ״וַתַּעְגְּבָה עַל פִּלַגְשֵׁיהֶם״ (יחזקאל כג:כ):",4,0],[4,30,"נַפְשֵׁךְ יְבַקֵּשׁוּ. מְבַקְּשִׁים לְהָרְגֵךְ:",5,0],[4,31,"כְּמַבְכִּירָה. כְּאִשָּׁה הַמְּבַכֶּרֶת תְּחִלַּת לֵידָתָהּ:",1,0],[4,31,"תִּתְיַפֵּחַ. תְּיַלֵּל וְתִצְעַק גְּנִיחוֹת; קונפליינ״ט בְּלַעַ״ז; כְּמוֹ ״וִיפֵחַ חָמָס״ (תהלים כז:יב) – לְשׁוֹן דִּבּוּר:",2,0],[4,31,"אוֹי נָא לִי. כָּךְ אוֹמֶרֶת:",3,0],[5,3,"ה׳ עֵינֶיךָ הֲלוֹא. הֵם בַּעֲלֵי אֱמוּנָה לְהֵיטִיב, וְלָמָּה בָּגְדוּ אֵלֶּה בָּךְ וְאֵין מְבַקְּשִׁין אֱמוּנָה?",1,0],[5,3,"הִכִּיתָה אוֹתָם. וְלֹא נַעֲשׂוּ חוֹלִים עַל הַמַּכָּה, לָשׂוּם עַל לִבָּם לָשׁוּב מֵרָעָתָם:",2,0],[5,3,"קַחַת. כְּמוֹ לָקַחַת:",3,0],[5,4,"וַאֲנִי אָמַרְתִּי. הַנָּבִיא אוֹמֵר כָּךְ. אַךְ דַּלִּים הֵם מֵחָכְמָה, אֵלּוּ שֶׁאֲנִי מְדַבֵּר עִמָּהֶם:",1,0],[5,4,"נוֹאֲלוּ. לְשׁוֹן ״אֱוִיל״ (ירמיה ד:כב), כְּתַרְגּוּמוֹ: ״אִיטְפַּשׁוּ״:",2,0],[5,5,"אֵלְכָה לִי אֶל הַגְּדוֹלִים. הֵם יִשְׁמְעוּ; אַךְ לֹא הוֹעַלְתִּי, וְגַם הֵמָּה יַחְדָּו שָׁבְרוּ עֹל שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא מֵעֲלֵיהֶם:",1,0],[5,6,"אַרְיֵה. מַלְכוּת בָּבֶל:",1,0],[5,6,"זְאֵב. מַלְכוּת מָדַי:",2,0],[5,6,"נָמֵר. מַלְכוּת אַשּׁוּר:",3,0],[5,6,"יִטָּרֵף. בֶּאֱדוֹם (אסתר רבה, פתיחתא ה):",4,0],[5,6,"זְאֵב עֲרָבוֹת. לְשׁוֹן ״עֲרָבָה וְשׁוּחָה״ (ירמיה ב:ו): זְאֵב הַמִּדְבָּר:",5,0],[5,6,"שׁוֹקֵד. מְמַהֵר, וּמְנַחֵם חִבְּרוֹ עִם לְשׁוֹן שְׁמִירָה, כְּמוֹ ״לִשְׁקֹד עַל דַּלְתוֹתַי״ (משלי ח:לד). וְיוֹנָתָן תִּרְגֵּם לְשׁוֹן אֲרִיבָה:",6,0],[5,7,"אֵי לָזֹאת אֶסְלַח לָךְ. בִּתְמִיהָּ: שֶׁמָּא לָזֹאת אֶסְלַח לָךְ?! וּמְנַחֵם פֵּרֵשׁ אֵי כְּמוֹ אַיִן. אֲשֶׁר בָּנַיִךְ עֲזָבוּנִי וָאַשְׂבִּעַ אוֹתָם כָּל טוֹב:",1,0],[5,7,"יִתְגּוֹדָדוּ. יִתְקַבְּצוּ גְדוּדִים:",2,0],[5,8,"סוּסִים מְיֻזָּנִים מַשְׁכִּים הָיוּ. בְּכָל בֹּקֶר הָיוּ. מַשְׁכִּים – לְאוֹר בֹּקֶר בְּהַשְׁכָּמָה:",1,0],[5,8,"יִצְהָלוּ. לָשׁוֹן זֶה נוֹפֵל עַל הַסּוּסִים: ״מִקּוֹל מִצְהֲלוֹת אַבִּירָיו״ (ירמיה ח:טז). לְשׁוֹן צַהֲלָה – אֵישְׁיוּדְמִינְ״ט בְּלַעַ״ז:",2,0],[5,10,"בְשָׁרוֹתֶיהָ. לְשׁוֹן מִישׁוֹר, וּמְנַחֵם חִבְּרוֹ לְשׁוֹן חוֹמָה עִם ״אֲדַלֵּג שׁוּר״ (תהלים יח:ל), אַךְ לֹא יִתָּכְנוּ נְטִישׁוֹתֶיהָ צִי״שׁ בְּלַעַ״ז, שֶׁהֵם שָׁרְשֵׁי כֶּרֶם, לִהְיוֹת נֶחְשָׁבִים עִם הַחוֹמוֹת וְלֹא עִם הַמִּישׁוֹר. וַאֲנִי אוֹמֵר שָׁרוֹתֶיהָ לְשׁוֹן שׁוּרוֹת הַכֶּרֶם. וְיוֹנָתָן תִּרְגֵּם בְּשָׁרוֹתֶיהָ ״בְּקִירוֹהָא״, וּנְטִישׁוֹתֶיהָ ״בְּרָנִיתָהָא״:",1,0],[5,12,"וַיֹּאמְרוּ לֹא הוּא. ״לָא מִן קֳדָמוֹהִי אַתְיָא עֲלָנָא טָבְתָא״ (תרגום יונתן):",1,0],[5,13,"וְהַנְּבִיאִים יִהְיוּ לְרוּחַ. כְּתַרְגּוּמוֹ: ״וְנָבִיֵּי שִׁקְרָא יְהוֹן לְלָמָא״; כְּלוֹמַר: הַנְּבוּאָה שֶׁנִּיבָּאִים לָנוּ נְבִיאֵי שֶׁקֶר בִּשְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, דִּבְרֵיהֶם יֵהָפְכוּ לְהֶבֶל, וְהַדִּבֵּר שֶׁל קְדֻשָּׁה, שֶׁהֵם אוֹמְרִים לָנוּ בְּשֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא, אֵינָן בָּהֶם:",1,0],[5,13,"כֹּה יֵעָשֶׂה לָהֶם. הַנָּבִיא אוֹמֵר לָאוֹמְרִים זֹאת, כֹּה יֵעָשֶׂה לָהֶם, כַּאֲשֶׁר אָמַר ה׳ לִי. וּמָה אָמַר ה׳ לִי? יַעַן דַּבֶּרְכֶם אֶת הַדָּבָר הַזֶּה וְגוֹ׳:",2,0],[5,14,"וַאֲכָלָתַם. וְתֹאכַל אוֹתָם:",1,0],[5,15,"אֵיתָן. תַּקִּיף (מכילתא בשלח ויהי ו):",1,0],[5,15,"גּוֹי מֵעוֹלָם הוּא. מִימֵי קֶדֶם הִתְחִיל לִמְרוֹד בִּי, בְּדוֹר הַפְּלַגָּה בְּאֶרֶץ שִׁנְעָר (בראשית יא:א-ט; פסחים צד.-צד:):",2,0],[5,16,"אַשְׁפָּתוֹ. מְקוֹם נַרְתֵּק הַחִצִּים:",1,0],[5,17,"יְרוֹשֵׁשׁ עָרֵי מִבְצָרֶיךָ וְגוֹ׳. הֲרֵי זֶה מִקְרָא מְסֹרָס: יְרוֹשֵׁשׁ בֶּחָרֶב אֶת עָרֵי מִבְצָרֶיךָ אֲשֶׁר אַתָּה בּוֹטֵחַ בָּהֵנָּה:",1,0],[5,17,"יְרוֹשֵׁשׁ. יְמַסְכֵּן:",2,0],[5,17,"בַּחָרֶב. עַל יְדֵי גְּיָסוֹת, וְכֵן הוּא אוֹמֵר ״וְחֶרֶב לֹא תַעֲבֹר בְּאַרְצְכֶם״ (ויקרא כו:ו):",3,0],[5,22,"הַאוֹתִי לֹא תִירָאוּ. הֲלֹא הַיָּם, שֶׁאֵינוֹ דּוֹאֵג מִפְּנֵי הַפּוּרְעָנוּת וְאֵינוֹ מְצַפֶּה לְקִבּוּל שָׂכָר, יָרֵא מִפָּנַי, וְאֵינוֹ עוֹבֵר הַגְּבוּל אֲשֶׁר שַׂמְתִּי סְבִיבָיו:",1,0],[5,22,"תָּחִילוּ. לְשׁוֹן פַּחַד:",2,0],[5,22,"וַיִּתְגָּעֲשׁוּ. גַּלָּיו, וּמְרוֹמֵם לַעֲבוֹר הַגְּבוּל וְלֹא יוּכָלוּ לַעֲבוֹר:",3,0],[5,22,"וְהָמוּ גַלָּיו. שָׁאוֹן קוֹל גָּדוֹל (ישעיהו יג:ד):",4,0],[5,22,"וְלֹא יַעַבְרֶנְהוּ. הַגַּלִּים לֹא יַעַבְרוּ הַגְּבוּל:",5,0],[5,24,"יוֹרֶה וּמַלְקוֹשׁ. כַּתַּרְגּוּם: ״בְּכִיר וְלָקִישׁ״:",1,0],[5,24,"שְׁבֻעוֹת חֻקּוֹת קָצִיר. שִׁבְעָה שָׁבוּעוֹת, שֶׁחָקַק לָנוּ בָּהֶן שְׁתֵּי חֻקּוֹת קָצִיר: חֹק הָעֹמֶר וְחֹק שְׁתֵּי הַלֶּחֶם (ויקרא רבה כח, ג):",2,0],[5,24,"יִשְׁמָר לָנוּ. שֶׁיְּהֵא הַקָּצִיר בִּזְמַנּוֹ:",3,0],[5,25,"הִטּוּ אֵלֶּה. הִטּוּ הַחֻקּוֹת הָאֵלֶּה מֵעֲלֵיכֶם; שֶׁאֵינָם שׁוֹמְרִים לָכֶם, וְאַתֶּם כָּלִים בָּרָעָב:",1,0],[5,26,"יָשׁוּר. יֶאֱרֹב, וְכֵן ״לְמַעַן שׁוֹרְרָי״ (תהילים ה:ט); לְשׁוֹן ״אֲשׁוּרֶנּוּ וְלֹא קָרוֹב״ (במדבר כד:יז):",1,0],[5,26,"כְּשַׁךְ יְקוּשִׁים. כַּאֲשֶׁר יִשּׁוֹךְ הַיָּקוֹשׁ שֶׁעוֹשִׂין לִלְכּוֹד צְבָיִים בַּיַּעַר, כְּשֶׁרַגְלוֹ בָּא לְתוֹכוֹ, וְהוּא נוֹשְׁכוֹ וּמַחֲזִיקוֹ בְּרַגְלוֹ, וְנִלְכָּד; וְקוֹרִין לוֹ פִּיי״ד בְּלַעַז:",2,0],[5,26,"הִצִּיבוּ מַשְׁחִית. צִינְבִּי״ל בְּלַעַ״ז; כֵּן עוֹשִׂין אוֹרְבִים עַל עִיר אוֹ עַל דֶּרֶךְ:",3,0],[5,26,"הִצִּיבוּ. כְּמוֹ ״מַצַּב פְּלִשְׁתִּים״ (שמואל א יג:כג) (סא״א):",4,0],[5,27,"כִּכְלוּב. הוּא מָקוֹם שֶׁמְּפַטְּמִין בּוֹ עוֹפוֹת; וְכֵן תִּרְגְּמוֹ יוֹנָתָן: ״כְּבֵית פִּיטְמָא״; וּבְלַעַ״ז פְרַנְ״ק:",1,0],[5,28,"עָשְׁתוּ. לְשׁוֹן ״עֶשֶׁת שֵׁן״ (שיר השירים ה:יד), גּוּף עָב; וּבְלַעַז אִישְׁפִּישׁוֹרְ״ט:",1,0],[5,28,"עָבְרוּ דִבְרֵי רָע. אִם בָּאת רָעָה אוֹ עֲבֵירָה לְיָדָם לֹא נָטוּ מִמֶּנָּה, אֶלָּא עָבְרוּ בָהּ וַעֲשָׂאוּהָ:",2,0],[5,28,"לֹא דָנוּ דִּין יָתוֹם. לְמַעַן יַצְלִיחוּ:",3,0],[5,30,"שַׁמָּה. תִּמָּהוֹן:",1,0],[5,30,"וְשַׁעֲרוּרָה. דָּבָר מְגֻנֶּה לַכֹּל. וּמַהוּ דְּבַר הַתִּמָּהוֹן? הַנְּבִיאִים נִבְּאִים שֶׁקֶר וְאוֹמְרִים: הֱווּ גּוֹזְלִין וְאוֹנְסִין, וְהַכֹּהֲנִים שֶׁהֵם שׁוֹפְטֵי הָעָם וְנוֹגְשֵׂיהֶם יִרְדּוּ אֶת הָעָם עַל יְדֵי הַנְּבִיאִים, כְּלוֹמַר: לְאַחֲרֵיהֶם, כְּמוֹ ״וְהַמֶּלֶךְ עוֹבֵר וְכָל הָעָם עוֹבְרִים עַל יָדוֹ״ (שמואל ב טו:יז-כג) (רוֹדֵף) (ס״א דְּדָוִד) אַחֲרָיו, אַף כָּאן עַל יְדֵיהֶם – אַחֲרֵיהֶם, לַעֲשׂוֹת כְּדִבְרֵי הַנְּבִיאִים:",2,0],[6,1,"הָעִזוּ בְּנֵי בִנְיָמִן. לָלֶכֶת לְעָרֵיכֶם, לִשְׁמֹר מִבְצָרֵיכֶם:",1,0],[6,1,"בֵּית הַכֶּרֶם. שֵׁם מָקוֹם הוּא:",2,0],[6,1,"שְׂאוּ מַשְׂאֵת. נֵס, לְהִקָּבֵץ וּלְהִלָּחֵם עַל נַפְשְׁכֶם:",3,0],[6,2,"הַנָּוָה וְהַמְּעֻנָּגָה דָּמִיתִי. הֶחֱרַבְתִּי תִּרְגְּמוֹ יוֹנָתָן; לְשׁוֹן ״וְנָדַמּוּ נְאוֹת הַשָּׁלוֹם״ (ירמיה כה:לז); ״נִדְמְתָה אַשְׁקְלוֹן״ (ירמיה מז:ה):",1,0],[6,3,"רוֹעִים וְעֶדְרֵיהֶם. מָשָׁל הוּא: מְלָכִים וְחֵילוֹתֵיהֶם:",1,0],[6,3,"רָעוּ. אָכְלוּ:",2,0],[6,3,"אֶת יָדוֹ. אֶת מְקוֹמוֹ; סְבִיבָיו:",3,0],[6,4,"קַדְּשׁוּ. זַמְּנוּ:",1,0],[6,4,"אוֹי לָנוּ. לְעֵת פְּנוֹת הַיּוֹם:",2,0],[6,4,"כִּי פָנָה הַיּוֹם. כַּאֲשֶׁר פָּנָה לְעֵת עֶרֶב הִצִּיתוּ הָאוּר בְּבֵית הַמִּקְדָּשׁ (תענית כט.):",3,0],[6,6,"כִּרְתוּ עֵצָה. לֹא מַפִּיק הֵ״א, וְהוּא לְשׁוֹן ׳עֵץ׳, שֶׁאֵין לְשׁוֹן ׳כְּרִיתָה׳ נוֹפֵל עַל הָ״עֵצָה״ (שמואל ב טז:כ). וְעֵצָה הָאָמוּר כָּאן – לְשׁוֹן הַרְבֵּה עֵצִים, כְּמוֹ ״דָּגָה״ (שמות ז:יח) – לְשׁוֹן דָּגִים הַרְבֵּה:",1,0],[6,6,"הָעִיר הָפְקַד. שֶׁבָּאָה פְּקֻדָּתָהּ:",2,0],[6,7,"כְּהָקִיר. לְשׁוֹן מָקוֹר:",1,0],[6,7,"בַּיִר. בְּאֵר:",2,0],[6,7,"כֵּן הֵקֵרָה רָעָתָהּ. כֵּן נוֹבַעַת רָעָתָם; תָּמִיד מוֹסִיפִים וּמְחַדְּשִׁים:",3,0],[6,7,"חֳלִי וּמַכָּה. ״עַל כֵּן אַיְתֵיתִי עֲלָהּ מְרַע וּמְחָא״ (תרגום יונתן):",4,0],[6,8,"הִוָּסְרִי. קַבְּלִי מוּסָר:",1,0],[6,8,"פֶּן תֵּקַע. פֶּן תִּנָּתֵק. הוֹקַע לְשׁוֹן חִבּוּר: ״וְהוֹקַע אוֹתָם״ (במדבר כה:ד), וְיֵשׁ לְשׁוֹן הֲסָרַת הַחִבּוּר, וְהַרְבֵּה תֵּיבוֹת מְשַׁמְּשׁוֹת כֵּן:",2,0],[6,9,"עוֹלֵל. גְּרַפָּאִי״ן בְּלַעַ״ז. לְאַחַר שֶׁבָּצְרוּ הַכֶּרֶם וְנִשְׁאֲרוּ עוֹלֵלוֹת, וְהָעֲנִיִּים בָּאִים וְעוֹלְלִים אוֹתָם, כֵּן יָבוֹזּוּ וְיַחְזְרוּ וְיָבוֹזּוּ:",1,0],[6,9,"הָשֵׁב יָדְךָ. אַתָּה, הַשּׂוֹנֵא, הָשֵׁב יָדְךָ לִשְׁלוֹל שֵׁנִית, כְּבוֹצֵר הַמֵּשִׁיב יָדוֹ עַל סַלְסִלּוֹת – הַמְּסַלְסֵל וּמְחַפֵּשׂ הָעוֹלֵלוֹת. וְכֵן הָיְתָה: מִשֶּׁהִגְלָה אֶת יְהוֹיָקִים וַהֲרָגוֹ וְהִמְלִיךְ אֶת יְכָנְיָה, חָזַר לְסוֹף שְׁלֹשָׁה חֳדָשִׁים וְהִגְלָהוּ, חָזַר לְסוֹף עַשְׁתֵּי עֶשְׂרֵה שָׁנָה וְהִגְלָה אֶת צִדְקִיָּהוּ (מלכים ב כד-כה):",2,0],[6,9,"סַלְסִלּוֹת. רְבִירְקְדוּרְ״שׁ בְּלַעַ״ז, כְּמוֹ ״סַלְסְלֶהָ וּתְרוֹמְמֶךָּ״ (משלי ד:ח) – כָּךְ פֵּרְשׁוֹ דּוּנַשׁ. וּמְנַחֵם פֵּרֵשׁ לְשׁוֹן ״סַל״ (שמות כט:ג); פַּנִירְ״שׁ בְּלַעַ״ז:",3,0],[6,10,"וְאָעִידָה. לְשׁוֹן הַתְרָאָה:",1,0],[6,10,"עֲרֵלָה. אֲטוּמָה, וְכֵן כָּל לְשׁוֹן עֲרֵלָה:",2,0],[6,10,"לְחֶרְפָּה. מְחָרְפִין אוֹתוֹ:",3,0],[6,11,"וְאֶת חֲמַת ה׳ מָלֵאתִי. לִבִּי מָלֵא נְבוּאָה לָבוֹא חֲמַת ה׳ עֲלֵיהֶם:",1,0],[6,11,"הָכִיל. כְּמוֹ ״לְהָכִיל״ (יחזקאל כא:לג), אשופרי״ר בְּלַעַ״ז:",2,0],[6,11,"שְׁפֹךְ עַל עוֹלָל. לִשְׁפֹּךְ עַל הַיּוֹנְקִים:",3,0],[6,11,"בַּחוּץ. בַּשּׁוּק:",4,0],[6,11,"מְלֵא יָמִים. קָרוֹב לַמָּוֶת, וְהוּא יֶתֶר עַל זָקֵן:",5,0],[6,12,"שָׂדוֹת וְנָשִׁים יַחְדָּו. יוּסַבּוּ לַאֲחֵרִים:",1,0],[6,13,"בּוֹצֵעַ בָּצַע. אוֹנֵס מָמוֹן:",1,0],[6,14,"עַל נְקַלָּה. קַל הוּא לִנְבִיאֵי הַשֶּׁקֶר לְהוֹצִיא מִפִּיהֶם וְלוֹמַר שָׁלוֹם יִהְיֶה לָכֶם (ירמיה ד:י), וּבַדָּבָר הַזֶּה מְרַפְּאִין בְּדִבּוּרָם אֶת הַשֶּׁבֶר הֶעָתִיד לָבֹא עֲלֵיהֶן:",1,0],[6,15,"הוֹבִישׁוּ. ״עֲלֵיהוֹן לְמִיבְהַת״ (תרגום יונתן):",1,0],[6,15,"הַכְלִים. כְּמוֹ לְהַכְלִים:",2,0],[6,15,"גַּם בּוֹשׁ לֹא יֵבוֹשׁוּ. אֵינָם מִתְבַּיְּשִׁין מִמַּעֲשֵׂיהֶם הָרָעִים:",3,0],[6,16,"מַרְגּוֹעַ. מְנוּחָה:",1,0],[6,17,"וַהֲקִימֹתִי עֲלֵיכֶם צוֹפִים. הוּא שֶׁמַּעֲמִידִין אֲנָשִׁים עַל הַמִּגְדָּלִים עֵת הַחֵרוּם אִישׁ צוֹפֶה, וְרוֹאֶה: אִם גַּיִס בָּא לָעִיר, תּוֹקֵעַ בַּשּׁוֹפָר וּמַזְהִיר אֶת הָעָם לְהֵחָלֵץ וְלָבֹא עַל הַחוֹמָה; אַף אֲנִי הֶעֱמַדְתִּי נְבִיאִים הַמַּשְׁמִיעִים אֶתְכֶם אֶת הַפֻּרְעָנוּת הַבָּאָה, לְהִזְדָּרֵז וּלְתַקֵּן דַּרְכֵיכֶם שֶׁתְּנַצְּלוּ, וְהוּא כְּשׁוֹפָר תְּקִיעוֹת הַצּוֹפֶה, הַקְשִׁיבוּ לְקוֹל הַשּׁוֹפָר הַזֶּה וְהֵחָלְצוּ:",1,0],[6,17,"וְהַקִימֹתִי. פֵּירוּשׁ: הֶעֱמַדְתִּי לָהֶם כְּבָר; וְכֵן תִּרְגֵּם יוֹנָתָן: ״וַאֲקִימִית״, צוֹפִים גִּיט״שׁ בְּלַעַ״ז:",2,0],[6,18,"אֶת אֲשֶׁר בָּם. אֶת הָרָעָה אֲשֶׁר בְּיָדָם:",1,0],[6,19,"פְּרִי מַחְשְׁבוֹתָם. שְׂכַר מַחְשְׁבוֹתָם:",1,0],[6,19,"וְתוֹרָתִי וַיִּמְאֲסוּ בָהּ. הֲרֵי זֶה דּוּגְמַת ״עָזִּי וְזִמְרָת יָהּ וַיְהִי לִי לִישׁוּעָה״ (שמות טו:ב), שֶׁהָיָה לוֹ לוֹמַר הָיָה לִי לִישׁוּעָה; אַף כָּאן הָיָה לוֹ לוֹמַר וְתוֹרָתִי מָאֲסוּ בָהּ. וְדֶרֶךְ הַמִּקְרָאוֹת לְדַבֵּר כֵּן:",2,0],[6,20,"לָמָּה זֶּה לִי לְבוֹנָה. אֲשֶׁר אַתֶּם מַקְרִיבִים לְפָנַי, אֲשֶׁר מִשְּׁבָא בָּאָה:",1,0],[6,20,"לֹא עָרְבוּ. לֹא נָעֲמוּ:",2,0],[6,23,"יַחֲזִיקוּ. יִקְחוּ, כְּמוֹ ״וַיִּשְׁלַח יָדוֹ וַיַּחֲזֶק בּוֹ״ (שמות ד:ד), וְכֵן ״צָרָה הֶחֱזִיקַתְנוּ״ (ירמיה ו:כד) – אֲחָזַתְנוּ:",1,0],[6,25,"מָגוֹר. יִרְאָה. לָשׁוֹן אַחֵר: לְשׁוֹן אֲסִיפָה, כְּמוֹ ״מְגוּרֵי אֶל חֶרֶב״ (יחזקאל כא:יז); וְכֵן תִּרְגֵּם יוֹנָתָן:",1,0],[6,26,"וְהִתְפַּלְּשִׁי. הִתְגַּלְגְּלִי:",1,0],[6,26,"אֵבֶל יָחִיד. אֵבֶל שֶׁל בֵּן יָחִיד, מִי שֶׁאֵין לוֹ אֶלָּא בֵּן יָחִיד וּמֵת:",2,0],[6,26,"מִסְפַּד תַּמְרוּרִים. לְפִי שֶׁהוּא דָּבוּק נָקוּד מִסְפַּד בְּפַתָּח, וְאֵינוֹ נָקוּד מִסְפֵּד (ירמיה מח:לח) בְּצֵירֵי:",3,0],[6,26,"עָלֵינוּ. כִּבְיָכוֹל, עָלַי וְעָלֶיךָ:",4,0],[6,27,"בָּחוֹן נְתַתִּיךָ. לְיִרְמְיָה נֶאֱמַר: חָזָק נְתַתִּיךָ בְּתוֹכָם. וְתֵדַע וּבָחַנְתָּ אֶת דַּרְכָּם. שֶׁתּוֹכִיחֵם וְהֵם לֹא יִשְׁמְעוּ. בָּחוֹן. לְשׁוֹן חוֹזֶק, כְּמוֹ ״עֹפֶל וָבַחַן״ (ישעיהו לב:יד); ״הֵקִימוּ בְחוּנָיו״ (ישעיהו כג:יג):",1,0],[6,28,"סָרֵי סוֹרְרִים. סָרִים מִן הַדֶּרֶךְ:",1,0],[6,28,"הוֹלְכֵי רָכִיל. בֵּין הַנְּחֹשֶׁת וְהַבַּרְזֶל: מַטִּילֵי אֵיבָה בֵּין שְׁנֵי שָׂרִים שֶׁיֵּשׁ בָּהֶן כֹּחַ לְהִתְגָּרוֹת יַחַד; כָּךְ שָׁמַעְתִּי. וַאֲנִי אוֹמֵר: הוֹלְכֵי רָכִיל הֵם, וַחֲזָקִים כַּנְּחֹשֶׁת וּבַרְזֶל לְהַחֲזִיק כְּזָבֵיהֶם. וְיוֹנָתָן תִּרְגֵּם רָכִיל זֶה לְשׁוֹן נוֹכֵל: ״מְהַלְּכִין בִּנְכִילוּ כְּמָא דְמְעָרֵב נְחָשׁ עִם פַּרְזְלָא״. וְנוֹכֵל הוּא לְשׁוֹן מַחֲשָׁבָה, כְּמוֹ ״וַיִּתְנַכְּלוּ אֹתוֹ לַהֲמִיתוֹ״ (בראשית לז:יח):",2,0],[6,29,"נָחַר מַפּוּחַ. מָשָׁל הוּא: כְּשֶׁצּוֹרְפִים כֶּסֶף נוֹפְחִין בַּמַּפּוּחַ, וְנוֹתְנִין תָּמִיד עוֹפֶרֶת בְּתוֹךְ הַכּוּר וּמוֹעִיל לִצְרוֹף; אֲבָל אַתֶּם, בָּאתִי לִצְרוֹף אֶתְכֶם – הַמַּפּוּחַ נָחַר וְנֶחְרַךְ מִכֹּחַ הָאֵשׁ, וְתַם הָעוֹפֶרֶת כֻּלּוֹ. נָחַר לְשׁוֹן ״חָרָה אַפּוֹ״ (איוב לב:ב) ״וְעַצְמִי חָרָה מִנִּי חֹרֶב״ (איוב ל:ל) אישר״ש בְּלַעַ״ז:",1,0],[6,29,"לַשָּׁוְא. עַל חִנָּם צָרַף הַצּוֹרֵף כִּי לֹא הוֹעִיל:",2,0],[6,29,"וְרָעִים לֹא נִתָּקוּ. מִדַּרְכָּם הָרָעָה; כְּלוֹמַר: יָגְעוּ הַנְּבִיאִים לְהוֹכִיחַ וְלֹא הוֹעִילוּ:",3,0],[6,29,"נִתָּקוּ. פּוֹרְצְטְרַאקִי״ץ בְּלַעַ״ז, (נוסח אחר וְרָעִים כְּמוֹ רְשָׁעִים סא״א):",4,0],[6,30,"כֶּסֶף נִמְאָס. שֶׁאֵינוֹ נִצְרָף בְּשׁוּם יְגִיעָה:",1,0],[7,4,"הֵיכַל ה׳ הֵיכַל ה׳ הֵיכַל ה׳. ״תְּלָת זִמְנִין בְּשַׁתָּא אַתּוּן מִתְחֲזִין קֳדָמוֹהִי״:",1,0],[7,9,"הֲגָנֹב רָצֹחַ וְגוֹ׳. בִּתְמִיהָּ, וְכִי אֵלֶּה תַּעֲשׂוּ וְיוֹעִיל הַהֵיכָל לָכֶם?",1,0],[7,11,"הַמְעָרַת פָּרִיצִים הָיָה. בְּעֵינֵיכֶם הַבַּיִת הַזֶּה? בִּתְמִיהָּ:",1,0],[7,11,"הִנֵּה רָאִיתִי. שֶׁכָּךְ הוּא בְּעֵינֵיכֶם:",2,0],[7,14,"כַּאֲשֶׁר עָשִׂיתִי לְשִׁלוֹ. בִּימֵי עֵלִי (שמואל א ד:יא-יח):",1,0],[7,15,"כַּאֲשֶׁר הִשְׁלַכְתִּי וְגוֹ׳. עֲשֶׂרֶת הַשְּׁבָטִים:",1,0],[7,18,"לַעֲשׂוֹת כַּוָּנִים. דְּפוּס הַכּוֹכָב:",1,0],[7,18,"לִמְלֶכֶת הַשָּׁמַיִם. כּוֹכָב הַגָּדוֹל הָיוּ קוֹרִין מְלֶכֶת הַשָּׁמַיִם, לְשׁוֹן מַלְכָּה; וְכֵן תִּרְגֵּם יוֹנָתָן: ״לְכוֹכֶבֶת שְׁמַיָּא״:",2,0],[7,20,"נִתֶּכֶת. יוֹרֶדֶת וּמַגַּעַת; כְּמוֹ ״וּמָטָר לֹא נִתַּךְ אָרְצָה״ (שמות ט:לג) ״לָא מְטָא״ (תרגום אונקלוס):",1,0],[7,21,"עוֹלוֹתֵיכֶם. שֶׁאַתֶּם מַקְרִיבִים כָּלִיל (ויקרא א:ח-ט), טוֹב לָכֶם שֶׁתּוֹסִיפוּ אוֹתָם עַל שַׁלְמֵיכֶם וְתַקְרִיבוּ אוֹתָם שְׁלָמִים וְתֹאכְלוּ הַבָּשָׂר, שֶׁהֲרֵי אֵינָם מְקֻבָּלוֹת לְפָנַי, וְלָמָּה תַפְסִידוּם?",1,0],[7,22,"בְּיוֹם הוֹצִיאִי אוֹתָם. תְּחִלַּת תְּנַאי לֹא הָיְתָה אֶלָּא ״אִם שָׁמוֹעַ תִּשְׁמְעוּ בְּקוֹלִי וּשְׁמַרְתֶּם אֶת בְּרִיתִי וִהְיִיתֶם לִי סְגֻלָּה״ (שמות יט:ה).",1,0],[7,24,"בִּשְׁרִירוּת לִבָּם. בְּמַרְאֵה לִבָּם; לָשׁוֹן ״אֲשׁוּרֶנּוּ״ (במדבר כד:יז):",1,0],[7,25,"יוֹם הַשְׁכֵּם וְשָׁלוֹחַ. מִדֵּי יוֹם בְּיוֹם הַשְׁכֵּם וְשָׁלוֹחַ:",1,0],[7,29,"גָּזִּי נִזְרֵךְ. תַּלְשִׁי שְׂעָרֵךְ; כְּמוֹ ״וַיָּגָז שַׂלְוִים״ (במדבר יא:לא); ״וַיָּגָז אֶת רֹאשׁוֹ״ (איוב א:כ). לָשׁוֹן אַחֵר: נִזְרֵךְ כִּתְרֵךְ, לְשׁוֹן גְּדֻלָּה; וְכֵן תִּרְגֵּם יוֹנָתָן: ״רַבְרְבִיךְ״, וְכֵן חִבְּרוֹ מְנַחֵם:",1,0],[7,29,"וַיִּטֹּשׁ. וַיַּעֲזֹב:",2,0],[7,31,"בָּמוֹת הַתֹּפֶת. הוּא הַמֹּלֶךְ (מלכים ב כג:י), שֶׁהָיָה שֶׁל נְחֹשֶׁת, וּמַסִּיקִין אוֹתוֹ מִתַּחְתָּיו וְיָדָיו פְּשׁוּטוֹת וְנִסָּקוֹת, וְנוֹתְנִין אֶת הַיֶּלֶד עַל יָדָיו וְהוּא נִכְוֶה וְנוֹהֵם, וְהַכּוֹמְרִים הָיוּ מַקִּישִׁין בְּתוּפִּים שֶׁלֹּא יִשְׁמַע הָאָב קוֹל הַבֵּן וְיִכָּמְרוּ רַחֲמָיו (בראשית מג:ל). תֹּפֶת עַל שֵׁם הַתּוֹף:",1,0],[7,31,"הִנֹּם. עַל שֵׁם נַהֲמַת הַבֵּן (תנחומא בובר, ואתחנן הוספה ב):",2,0],[7,31,"לֹא צִוִּיתִי. בְּמִצְווֹת שֶׁיַּקְרִיבוּ בְּנֵיהֶם לְקָרְבָּן, וְלֹא דִבַּרְתִּי לְאֶחָד מִן הַנְּבִיאִים. וּכְשֶׁדִּבַּרְתִּי לְאַבְרָהָם לִשְׁחוֹט אֶת בְּנוֹ (בראשית כב:ב), לֹא עָלְתָה עַל לִבִּי שֶׁיִּשְׁחוֹט, אֶלָּא לְהוֹדִיעַ צִדְקוֹ:",3,0],[7,33,"וְאֵין מַחֲרִיד. אֶת הָעוֹפוֹת מֵעַל הַפְּגָרִים:",1,0],[8,2,"וּשְׁטָחוּם לַשֶּׁמֶשׁ. וְהַכַּשְׂדִּים יִשְׁכְּנוּ לָצוּר עַל הָעִיר בְּקִבְרֵי הַשָּׂרִים, שֶׁהָיוּ נָאִים כְּפַלָּטִין (סנהדרין צו:):",1,0],[8,2,"לְדֹמֶן. לְזֶבֶל:",2,0],[8,3,"וְנִבְחַר מָוֶת מֵחַיִּים. אַף עַל פִּי שֶׁהֵם רוֹאִים אֶת הַמֵּתִים נְתוּנִין בְּבִזָּיוֹן, צָרַת הַחַיִּים גְּדוֹלָה הֵימֶנָּה, וְיִבְחֲרוּ אֶת הַמָּוֶת:",1,0],[8,4,"הֲיִפְּלוּ וְלֹא יָקוּמוּ. הֲטוֹב לָהֶם שֶׁיַּפִּילוּ אֶת עַצְמָם לִנְפִילָה שֶׁאֵין לָהֶם תְּקוּמָה:",1,0],[8,4,"אִם יָשׁוּב וְלֹא יָשׁוּב. לִכְשֶׁיִּרְצוּ לָשׁוּב מֵרָעָתָם, לֹא יָשׁוּב הַקָּדוֹשׁ בָּרוּךְ הוּא מִגְּזֵרָתוֹ (ספר במדבר מב). דָּבָר אַחֵר: אַף אִם יָשׁוּבוּ בִּתְשׁוּבָה, לֹא תִתְקַיֵּם בְּיָדָם, כִּי יְמַהֲרוּ לָשׁוּב לְרִשְׁעָתָם (ספר במדבר מב); וְכֵן תִּרְגֵּם יוֹנָתָן: ״אִם לְמֵיתַב, גְּלֵי קֳדָמַי דְּלָא יְתוּבוּן״:",2,0],[8,5,"מְשׁוּבָה נִצַּחַת. מְשׁוּבַת עוֹלָם; כְּמוֹ ״נֶצַח״ (ירמיה טו:יח):",1,0],[8,5,"הֶחֱזִיקוּ. אָחֲזוּ:",2,0],[8,5,"בַּתַּרְמִית. בְּמִרְמָה:",3,0],[8,6,"לֹא כֵן. לֹא בַּדִּין, כְּמוֹ ״כֵּן בְּנוֹת צְלָפְחָד״ (במדבר כז:ז):",1,0],[8,6,"כֻּלֹּה שָׁב בִּמְרוּצָתָם. בַּדֶּרֶךְ הָרִאשׁוֹן חוֹטְאִים, וְחוֹזְרִים וְחוֹטְאִים. מְרוּצָתָם – קוֹרְשִׁ״י בְּלַעַ״ז:",2,0],[8,6,"שׁוֹטֵף. אֵישְׁפְּרִידִי״ן בְּלַעַ״ז:",3,0],[8,7,"חֲסִידָה. צִיגוֹנִיאָ״ה בְּלַעַ״ז:",1,0],[8,7,"מוֹעֲדֶיהָ. עֵת עָבְרָם אֶל אִיֵּי הַיָּם מִפְּנֵי הַצִּנָּה, וְעֵת שׁוּבָם:",2,0],[8,7,"שָׁמְרוּ. הִמְתִּינוּ:",3,0],[8,7,"וְתוֹר וְסִיס וְעָגוּר. ״וְשַׁפְנִינָא וְכוּרְכְיָא וּסְנוּנִיתָא״ (תרגום יונתן). כּוּרְכְיָא – גְּרוּאָ״ה בְּלַעַ״ז, סְנוּנִית – אֲרוּנְדִּילָ״א בְּלַעַ״ז:",4,0],[8,8,"אָכֵן הִנֵּה לַשֶּׁקֶר. הִנֵּה חָכְמַתְכֶם לַשֶּׁקֶר בָּכֶם, לְרַפְּאוֹתְכֶם עַל נְקַלָּה:",1,0],[8,8,"עָשָׂה עֵט שֶׁקֶר סוֹפְרִים. נְבִיאֲכֶם:",2,0],[8,9,"הוֹבִישׁוּ חֲכָמִים. כְּמוֹתְכֶם. וּמַהוּ הַבֹּשֶׁת? – הִנֵּה בִדְבַר ה׳ מָאָסוּ וְחָכְמַת מֶה לָהֶם:",1,0],[8,11,"וַיְרַפּוּ. כְּמוֹ ״וַיְרַפְּאוּ״ (ירמיה ו:יד):",1,0],[8,12,"הוֹבִישׁוּ. בֹּשֶׁת וּכְלִימָּה תָּבֹא לָהֶם:",1,0],[8,12,"גַּם בּוֹשׁ לֹא יֵבוֹשׁוּ. אֵינָם מִתְבַּיְּשִׁים בְּמַעֲשֵׂיהֶם הָרָעִים, לָתֵת לֵב לָשׁוּב:",2,0],[8,13,"אָסֹף אֲסִיפֵם. לְשׁוֹן כְּלָיָה, כְּמוֹ ״אָסֹף אָסֵף כֹּל מֵעַל פְּנֵי הָאֲדָמָה״ (צפניה א:ב):",1,0],[8,13,"אֵין עֲנָבִים בַּגֶּפֶן. לֹא יִוָּתֵר דָּבָר:",2,0],[8,13,"וְהֶעָלֶה נָבֵל. לְשׁוֹן כָּמוֹשׁ, פְּלֵיישְׁטִי״שׁ בְּלַעַ״ז; כְּמוֹ ״וּכְנֹבֶלֶת מִתְּאֵנָה״ (ישעיהו לד:ד), ״כָּאֵלָה נוֹבֶלֶת עָלֶיהָ״ (ישעיהו א:ל):",3,0],[8,13,"וָאֶתֵּן לָהֶם יַעַבְרוּם. כָּל זֹאת תִּהְיֶה לָהֶם עַל כִּי נָתַתִּי לָהֶם חֻקִּים וְעָבְרוּ עֲלֵיהֶם:",4,0],[8,14,"וְנִדְּמָה שָׁם. וְנִדּוֹם שָׁם, נֵשֵׁב שָׁם דּוֹמִים וַאֲבֵלִים:",1,0],[8,14,"מֵי רֹאשׁ. ״כָּס דִּלְוָוט בִּישׁ כְּרֵישֵׁי חִיוָן״ (תרגום יונתן); ״רֹאשׁ פְּתָנִים״ (דברים לב:לג) הוּא אֶרֶס שֶׁבְּשִׁנָּיו:",2,0],[8,16,"מִדָּן נִשְׁמַע. ״עַל דְּפַלְחוּ לְעֶגְלָא דִּבְדָן״ (תרגום יונתן; סנהדרין צו.):",1,0],[8,16,"נַחְרַת סוּסָיו. עֲטִישׁוֹת נְחִירָיו:",2,0],[8,16,"מִצְהֲלוֹת אַבִּירָיו. צַהֲלַת מִשְׂחַק סוּסָיו; וּמָצִינוּ בְּמָקוֹם אַחֵר סוּסִים נִקְרָאִים אַבִּירִים: ״מִדַּהֲרוֹת דַּהֲרוֹת אַבִּירָיו״ (שופטים ה:כב), לְשׁוֹן ״סוּס דּוֹהֵר״ (נחום ג:ב). וְיוֹנָתָן תִּרְגֵּם: ״מִקָּל פְּסִיעוֹת גַּבְרוֹהִי״:",3,0],[8,17,"נְחָשִׁים צִפְעֹנִים. לְסוֹף שִׁבְעִים שָׁנָה נַעֲשֶׂה צֶפַע, וְאוֹטֵם אָזְנוֹ שֶׁלֹּא יִשְׁמַע לְקוֹל חֶבֶר הַמְלַחֲשׁוֹ, שֶׁנֶּאֱמַר ״כְּמוֹ פֶתֶן חֵרֵשׁ יַאְטֵם אָזְנוֹ…״ (תהלים נח:ה-ו); הוּא שֶׁנֶּאֱמַר: אֲשֶׁר אֵין לָהֶם לָחַשׁ (ראה שוחר טוב נח:ב):",1,0],[8,18,"מַבְלִיגִיתִי עֲלֵי יָגוֹן. כְּמוֹ הִבְלַגְתִּי, וְשֵׁם דָּבָר הוּא מישאיטינמנ״ץ בְּלַעַ״ז, כְּלוֹמַר אִם אָמַרְתִּי אַבְלִיגָה וְאֶתְאַפֵּק עֲלֵי יָגוֹנִי:",1,0],[8,18,"עָלַי לִבִּי דַוָּי. מִקּוֹל נְבוּאוֹת הַנִּגְלוֹת אֵלַי בְּפֻרְעָנִיּוֹת הַבָּאוֹת:",2,0],[8,19,"הִנֵּה קוֹל שַׁוְעַת בַּת עַמִּי. אֲנִי שׁוֹמֵעַ שֶׁסּוֹפָן לִצְעֹק בְּאֶרֶץ מַרְחַקִּים. וְלָמָּה כָּל זֹאת? הֲלֹא ה׳ בְּצִיּוֹן, וְאִם יָשׁוּבוּ אֵלָיו יִמָּצֵא לָהֶם!",1,0],[8,20,"עָבַר קָצִיר כָּלָה קָיִץ. צִפִּינוּ לְעֶזְרַת מִצְרַיִם וְלֹא בָאָה; אָמַרְנוּ: יַעֲבֹר הַקָּצִיר וְיִהְיוּ פְנוּיִין וְיָבֹאוּ, וְהִנֵּה עָבַר זְמַן הַקָּצִיר בְּאִיָּר, וּזְמַן הַקָּיִץ בְּתַמּוּז, וְלֹא בָאוּ (בבא מציעא קו:):",1,0],[8,21,"קָדַרְתִּי. לְשׁוֹן שַׁחֲרוּת וְאֹפֶל:",1,0],[8,21,"שַׁמָּה. תִּמָּהוֹן:",2,0],[8,21,"הֶחֱזִקָתְנִי. אֲחָזַתְנִי:",3,0],[8,22,"הַצֳּרִי אֵין בְּגִלְעָד. שֶׁהַצֳּרִי בָּא מִשָּׁם, כְּמוֹ שֶׁנֶּאֱמַר ״עֲלִי גִלְעָד וּקְחִי צֳרִי״ (ירמיה מו:יא); כְּלוֹמַר: וְכִי לֹא הָיוּ לָהֶם אֲנָשִׁים צַדִּיקִים מִמִּי לִלְמֹד, וְיֵיטִיבוּ דַרְכֵיהֶם?",1,0],[8,22,"אֲרֻכַת. רְפוּאַת אִינְפְּלַשְׁטְרָ״א בְּלַעַ״ז:",2,0],[9,1,"עֲצֶרֶת בֹּגְדִים. כְּנֵסִיּוֹת בּוֹגְדִים:",1,0],[9,2,"וַיַּדְרְכוּ. לָשׁוֹן זֶה נוֹפֵל בְּהַזְמָנַת הַקֶּשֶׁת לִירוֹת חֵץ; וְקֶשֶׁת הִיא אַרְבַּלִישְׁטְ״א בְּלַעַ״ז, וּבָרַגְלַיִם דּוֹרְכִין אוֹתָהּ, לְכָךְ קוֹרֵא אוֹתָהּ דְּרִיכָה. וְהַנָּבִיא הִמְשִׁיל לְשׁוֹנָם לְקֶשֶׁת שֶׁקֶר, שֶׁדָּרְכוּ לְשׁוֹנָם קֶשֶׁת בְּשֶׁקֶר:",1,0],[9,2,"מֵרָעָה אֶל רָעָה. מֵעֲבֵירָה אֶל עֲבֵירָה:",2,0],[9,3,"עָקוֹב יַעֲקֹב. אָרוֹב יֶאֱרֹב:",1,0],[9,4,"הַעֲוֵה נִלְאוּ. יָגְעוּ וְטָרְחוּ לְעַוֵּת אֶת דַּרְכָּם:",1,0],[9,4,"הַעֲוֵה. כְּמוֹ ״הַכְבֵּד אֶת לִבּוֹ״ (שמות ח:יא): לְהַעֲווֹת:",2,0],[9,5,"שִׁבְתְּךָ בְּתוֹךְ מִרְמָה. כְּשֶׁהֵן יוֹשְׁבִים, חוֹשְׁבִין מַחְשְׁבוֹת מִרְמָה; וּבְמִרְמָה הֶחְלִיפוּ יִרְאָתִי וּמֵאֲנוּ דַעַת אוֹתִי:",1,0],[9,5,"בְּמִרְמָה. בִּשְׁבִיל הַמִּרְמָה:",2,0],[9,6,"הִנְנִי צוֹרְפָם. בְּיִסּוּרִין:",1,0],[9,6,"מִפְּנֵי בַת עַמִּי. ״מִן קֳדָם חוֹבֵי כְּנִישְׁתָּא דְיִשְׂרָאֵל״ (תרגום יונתן):",2,0],[9,7,"חֵץ שָׁחוּט לְשׁוֹנָם. מָשׁוּךְ; כְּמוֹ ״זָהָב שָׁחוּט״ (מלכים א י:טז), וְכֵן ״וְשַׁחֲטָה שִׁטִּים״ (הושע ה:ב) טְרֵיי״ט בְּלַעַ״ז. לִישְׁנָא אַחֲרִינָא: לְשׁוֹן שְׁחִיטָה מַמָּשׁ, טְרַאנְקָא״ט בְּלַעַ״ז; וְכֵן חִבְּרוֹ מְנַחֵם, וְכֵן תִּרְגֵּם יוֹנָתָן: ״כְּגִיר דִּי מַחְרִיף״:",1,0],[9,7,"וּבְקִרְבּוֹ. תִּרְגֵּם יוֹנָתָן: ״וּבְמָעוֹהִי״:",2,0],[9,9,"עַל הֶהָרִים. עַל חֻרְבַּן הֶהָרִים:",1,0],[9,9,"וְעַל נְאוֹת מִדְבָּר. נְוֵה רוֹעִים שֶׁבַּמִּדְבָּרוֹת. נְאוֹת לְשׁוֹן ״נָוֶה״, וְכֵן ״נְאוֹת אֱלֹהִים״ (תהלים פג:יג), וְכֵן ״לְבֵיתְךָ נָאֲוָה קֹדֶשׁ״ (תהלים צג:ה):",2,0],[9,9,"נִצְּתוּ. לְשׁוֹן ״צִיָּה״ (ירמיה ב:ו), וְכֵן ״נִצְּתָה״ (ירמיה ט:יא):",3,0],[9,9,"נָדְדוּ הָלָכוּ. סוֹפָן לֵילֵךְ. חֲמִשִּׁים וּשְׁתַּיִם שָׁנָה לֹא עָבַר אִישׁ בִּיהוּדָה; מִגָּלוּת צִדְקִיָּהוּ עַד פְּקִידַת כּוֹרֶשׁ מֶלֶךְ פָּרַס חֲמִשִּׁים וּשְׁתַּיִם שָׁנָה הָיוּ, וְרֶמֶז לַדָּבָר: עַד בְּהֵמָה. חֶשְׁבּוֹנָהּ בְּגִימַטְרִיָּא חֲמִשִּׁים וּשְׁתַּיִם; וְהַחֶשְׁבּוֹן מְכֻוָּן בְּמַסֶּכֶת מְגִלָּה (ראה יומא נד.):",4,0],[9,10,"לְגַלִּים. ״דְּגוֹרִין״ (תרגום יונתן):",1,0],[9,11,"מִי הָאִישׁ הֶחָכָם. שֶׁיָּבִין זֹאת, וּמִי הַנָּבִיא אֲשֶׁר דִּבֶּר פִּי ה׳ אֵלָיו:",1,0],[9,11,"וְיַגִּידָהּ. וּמִי יַגִּיד עַל מָה אָבְדָה הָאָרֶץ וּבָא כָּל הַפֻּרְעָנוּת הַזֶּה:",2,0],[9,14,"לַעֲנָה. עֵשֶׂב מַר:",1,0],[9,14,"מֵי רֹאשׁ. אֶרֶס נָחָשׁ:",2,0],[9,18,"כִּי הִשְׁלִיכוּ מִשְׁכְּנוֹתֵינוּ. אֶת שׁוֹכְנֵיהֶם. וְיֵשׁ עוֹד לוֹמַר: כִּי הִשְׁלִיכוּ הָאוֹיְבִים אֶת מִשְׁכְּנוֹתֵינוּ לָאָרֶץ:",1,0],[9,20,"לְהַכְרִית עוֹלָל מִחוּץ. מִן הַשּׁוּק; כְּמוֹ ״וְחוּצוֹת תָּשִׂים לְךָ בְדַמֶּשֶׂק״ (מלכים א כ:לד):",1,0],[9,22,"אַל יִתְהַלֵּל חָכָם. אַל תִּתְהַלְּלוּ לוֹמַר: ״חֲכָמִים אֲנַחְנוּ״ (ירמיה ח:ח); הִנֵּה בִּדְבָרַי מְאַסְתֶּם וְחָכְמַת מַה לָכֶם (ירמיה ח:ט); אִם הִשְׂכַּלְתֶּם וִידַעְתֶּם אוֹתִי, אָז תִּתְהַלְּלוּ בְּחָכְמַתְכֶם:",1,0],[9,23,"השכל. כמו ״הַכְבֵּד״ (שמות ח:יא) (אגטליינ״ט בלע״ז):",1,0],[9,24,"עַל כָּל מוּל בְּעָרְלָה. עַל כָּל מוּל שֶׁיֵּשׁ לוֹ עָרְלָה, אֲפִלּוּ עָרְלַת לֵב (בראשית רבה מו, ה):",1,0],[9,25,"עַל מִצְרַיִם וְגוֹ׳. שְׁכֵינֵי אֶרֶץ יִשְׂרָאֵל הָיוּ, וְלָקוּ אַחֲרֶיהָ בְּסָמוּךְ לָהּ, כְּמוֹ שֶׁכָּתוּב בִּיחֶזְקֵאל (יחזקאל כט:ב-יב); וּמְפֹרָשׁ בְּסֵדֶר עוֹלָם (סדר עולם רבה כו):",1,0],[9,25,"קְצוּצֵי פֵאָה. לְשׁוֹן קָצֶה: הַמּוּקְצִין בִּפְאַת מִדְבָּר:",2,0],[10,2,"אֶל דֶּרֶךְ הַגּוֹיִם אַל תִּלְמָדוּ. וְאָז מֵאוֹתוֹת הַשָּׁמַיִם אַל תֵּחָתּוּ – מֵחַמָּה לוֹקָה וּמִמְּאוֹרוֹת לוֹקִין:",1,0],[10,3,"חָרָשׁ. אֻמָּן:",1,0],[10,3,"מַעֲצָד. דּוֹלְדוֹיִירָ״א בְּלַעַ״ז:",2,0],[10,4,"מַסְמְרוֹת. קְלוֹיִ״שׁ בְּלַעַ״ז:",1,0],[10,4,"וּמַקָּבוֹת. קוֹרְנָס, מַרְטִי״ל בְּלַעַ״ז:",2,0],[10,4,"יָפִיק. יִכְרַע בִּרְכָּיו, לְשׁוֹן ״פּוּקָה״ (שמואל א כה:לא) ״וּפִיק בִּרְכַּיִם״ (נחום ב:יא):",3,0],[10,5,"כְּתֹמֶר מִקְשָׁה. מַקִּישׁ אוֹתוֹ בְּקוּרְנָס עַד שֶׁזּוֹקֵף לוֹ קוֹמָה כְּדֶקֶל:",1,0],[10,5,"אַל תִּירְאוּ מֵהֶם. אִם תִּפְרְשׁוּ מֵהֶם, כִּי לֹא יָרֵעוּ לָכֶם:",2,0],[10,5,"וְגַם הֵיטֵיב אֵין אוֹתָם. אִם תַּעַבְדוּם. הֵיטֵיב כְּמוֹ ״לְהֵיטִיב״ (ירמיה לב:מא):",3,0],[10,7,"לְךָ יָאָתָה. לְךָ נָאֶה:",1,0],[10,8,"וּבְאַחַת יִבְעֲרוּ. הַגּוֹיִים. וּמָה הִיא הָאַחַת מוּסַר הֲבָלִים שֶׁל עֵץ שֶׁלָּהֶם וְיִתְיַסְּרוּ עָלָיו. יִבְעֲרוּ לְשׁוֹן שְׁטוּת, וְכֵן וְיִכְסָלוּ:",1,0],[10,9,"מְרֻקָּע. מְרֻדָּד:",1,0],[10,10,"וַה׳ אֱלֹהִים אֱמֶת. לָמָּה? כִּי הוּא אֱלֹהִים חַיִּים וּמֶלֶךְ עוֹלָם, לְכָךְ יָכוֹל לְאַמֵּת דְּבָרָיו. אֲבָל בָּשָׂר וָדָם – אוֹמֵר לַעֲשׂוֹת, וּמֵת אוֹ תָּשַׁשׁ כֹּחוֹ אוֹ יוֹרֵד מִנְּכָסָיו, וְאֵין בְּיָדוֹ לְקַיֵּם (פסיקתא רבתי יד):",1,0],[10,11,"כִּדְנָה תֵאמְרוּן. אִגֶּרֶת הִיא שֶׁשָּׁלַח יִרְמְיָה לִיכָנְיָה וְגָלוּתוֹ בַּגּוֹלָה, לְהָשִׁיב לַכַּשְׂדִּים אֲרָמִית תְּשׁוּבָה, אִם אוֹמְרִין לָהֶם לַעֲבוֹד לַעֲבוֹדָה זָרָה (תנחומא, שופטים יב):",1,0],[10,12,"נָטָה. טינדי״ש בְּלַעַ״ז:",1,0],[10,13,"לְקוֹל תִּתּוֹ. בְּעֵת בֹּא קוֹל שֶׁהוּא נוֹתֵן הֲמוֹן מַיִם בַּשָּׁמַיִם:",1,0],[10,13,"נְשִׂאִים. עֲנָנִים:",2,0],[10,13,"בְּרָקִים. פְלַנְדוֹרִי״שׁ בְּלַעַ״ז:",3,0],[10,14,"נִבְעַר. לְשׁוֹן ״אִישׁ בַּעַר״ (תהילים צב:ז), וְכֵן נִבְעֲרוּ הָרוֹעִים:",1,0],[10,14,"נִסְכּוֹ. לְשׁוֹן ״מַסֵּכָה״ (שמות לב:ד):",2,0],[10,15,"בְּעֵת פְּקֻדָּתָם. כְּשֶׁאֶפְקֹד עֲלֵיהֶם:",1,0],[10,17,"אִסְפִּי מֵאֶרֶץ כִּנְעָתֵךְ. הַחְבִּיאוּ, וְכֵן תִּרְגֵּם יוֹנָתָן: ״כְּנוֹשִׁי מֵאַרְעָא סְחוֹרְתִּיךְ״, כְּמוֹ ״כְּנַעַן בְּיָדוֹ מֹאזְנֵי מִרְמָה״ (הושע יב:ח); וּמְנַחֵם פֵּרֵשׁ כִּנְעָתֵךְ – לְשׁוֹן הַכְנָעָה וְשִׁפְלוּת, וְאִסְפִּי – לְשׁוֹן שְׁחִיָּה: שְׁחִי וְהַשְׁפִּילִי יוֹתֵר מִשִּׁפְלוּת אֶרֶץ אֶת הַכְנָעָתֵךְ, אַתְּ, יְרוּשָׁלַיִם, הַיּוֹשֶׁבֶת עַתָּה בַּמָּצוֹר:",1,0],[10,18,"קוֹלֵעַ. כְּזֶה שֶׁהוּא זוֹרֵק אֶבֶן בַּקֶּלַע:",1,0],[10,18,"לְמַעַן. אֲשֶׁר יִמְצְאוּ שְׂכַר פְּעֻלָּתָם:",2,0],[10,19,"נַחְלָה. לְשׁוֹן חוֹלִי:",1,0],[10,19,"וְאֶשָּׂאֶנּוּ. תִּרְגֵּם יוֹנָתָן: ״וַאֲסוֹבְרַנִיהּ״; אֲשׁוֹפְרִיר״לוֹי בְּלַעַ״ז:",2,0],[10,20,"יְצָאוּנִי. יָצְאוּ מִמֶּנִּי; יְרוּשָׁלַיִם אוֹמֶרֶת כֵּן:",1,0],[10,21,"הָרֹעִים. הַמְּלָכִים:",1,0],[10,21,"לֹא הִשְׂכִּילוּ. לֹא הִצְלִיחוּ בְּמַלְכוּתָם; כְּמוֹ ״בְּכָל אֲשֶׁר יִפְנֶה יַשְׂכִּיל״ (משלי יז:ח, שמואל א יד:מז):",2,0],[10,21,"מַרְעִיתָם. צֹאן מַרְעִיתָם:",3,0],[10,23,"לֹא לָאָדָם דַּרְכּוֹ. כִּי יֵצֶר הָרַע שֶׁבָּרָאתָ בּוֹ מַטֵּהוּ מִן הַדֶּרֶךְ. דָּבָר אַחֵר: יָדַעְתִּי ה׳ כִּי לֹא לָאָדָם דַּרְכּוֹ, אֵין בְּיַד כָּל אָדָם כֹּחַ לְהַצְלִיחַ דַּרְכּוֹ, וְאִם לֹא עַל פִּיךָ, אֵין כֹּחַ בְּיַד אוֹיֵב לְהַחֲרִיב בֵּיתֶךָ:",1,0],[10,24,"אַךְ בְּמִשְׁפָּט. בְּיִסּוּרִין:",1,0],[10,24,"בְּמִשְׁפָּט. יוּשְׁטִיצָ״א בְּלַעַ״ז:",2,0],[10,24,"אַךְ בְּמִשְׁפָּט. תִּרְגֵּם יוֹנָתָן: ״בְּרַם בְּדִין חֲשׁוּךְ״:",3,0],[10,24,"אַל בְּאַפְּךָ. פֶּן תְּהֵא כְלָיָה:",4,0],[10,25,"אָכְלוּ. דְוֹורִירוֹ״נְט בְּלַעַ״ז, וְכֵן וַאֲכָלֻהוּ:",1,0],[11,5,"אָמֵן ה׳. שֶׁיְּהֵא אָרוּר:",1,0],[11,7,"הָעֵד הַעִדֹתִי. לְשׁוֹן הַתְרָאָה:",1,0],[11,8,"וָאָבִיא עֲלֵיהֶם אֶת כָּל דִּבְרֵי הַבְּרִית. הָאָלוֹת הָאֲמוּרוֹת בַּבְּרִית עַל הַדְּבָרִים אֲשֶׁר צִוִּיתִי לַעֲשׂוֹת וְלֹא עָשׂוּ:",1,0],[11,12,"עָרֵי יְהוּדָה. מֵעָרֵי יְהוּדָה:",1,0],[11,14,"רִנָּה וּתְפִלָּה. ״בְּבָעוּ וּבְצָלוּ״ (תרגום יונתן):",1,0],[11,15,"מָה לִידִידִי בְּבֵיתִי. מָה לְעַם סְגֻלָּתִי לָבֹא עוֹד בְּבֵיתִי:",1,0],[11,15,"עֲשׂוֹתָהּ הַמְזִמָּתָה. לַעֲשׂוֹת הִיא מְזִמַּת עֲצַת חֲטָאִים שֶׁלָּהּ:",2,0],[11,15,"הָרַבִּים. שֶׁבָּהֶם:",3,0],[11,15,"וּבְשַׂר קֹדֶשׁ יַעַבְרוּ מֵעָלָיִךְ. אַף הַמִּילָה בִּטְּלוּ מִבְּשָׂרָם, שֶׁעַל יָדָהּ הָיוּ מְקֻדָּשִׁים לִי (מנחות נג:):",4,0],[11,15,"כִּי רָעָתֵכִי אָז תַּעֲלֹזִי. כְּשֶׁאַתֶּם עוֹבְרִים עֲבֵרָה אַתֶּם שְׂמֵחִים:",5,0],[11,16,"לְקוֹל הֲמוּלָּה. לְשׁוֹן שָׁאוֹן עַם רַב שֶׁיָּבֹא עֲלֵיהֶם:",1,0],[11,16,"וְרָעוּ דָּלִיּוֹתָיו. וְרִצְּצוּ אֶת עֲנָפָיו:",2,0],[11,18,"וַה׳ הוֹדִיעַנִי. כָּךְ אָמַר הַנָּבִיא: הַקָּדוֹשׁ בָּרוּךְ הוּא הוֹדִיעַנִי אֶת פּוּרְעָנוּתָם:",1,0],[11,19,"וַאֲנִי כְּכֶבֶשׂ אַלּוּף. אֲשֶׁר יוּבַל לִטְבוֹחַ:",1,0],[11,19,"יוּבַל. לְפִי שֶׁאֲנִי מוֹדִיעָם הָרָעָה, הֵם אוֹמְרִים לְהָרְגֵנִי:",2,0],[11,19,"כְּכֶבֶשׂ אַלּוּף. דּוּנָשׁ וִיהוּדָה בֶּן קוּרִישׁ פֵּתְרוּהוּ: כְּכֶבֶשׂ וּפָר אֲשֶׁר יוּבַל לִטְבוֹחַ. וְאַלּוּף כְּמוֹ ״שְׁגַר אֲלָפֶיךָ״ (דברים כח:ד). וְאַף עַל פִּי שֶׁלֹּא נֶאֱמַר וְאַלּוּף, יֵשׁ לָנוּ כַּיּוֹצֵא בוֹ: ״שֶׁמֶשׁ יָרֵחַ עָמַד זְבֻלָה״ (חבקוק ג:יא); ״כְּסוּס עָגוּר כֵּן אֲצַפְצֵף״ (ישעיהו לח:יד). וּמְנַחֵם פֵּתֵר כֶּבֶשׂ אַלּוּף – כֶּבֶשׂ גָּדוֹל (עיין בתהלים נח בפירוש רש״י); וְיוֹנָתָן מְסַיְּעוֹ, שֶׁתִּרְגֵּם: ״כְּאִימַר בְּחִיר״:",3,0],[11,19,"נַשְׁחִיתָהּ עֵץ בְּלַחְמוֹ. ״נִרְמֵי סְמָא דְּמָוְתָא בְּמִכְלֵיהּ״ (תרגום יונתן):",4,0],[11,20,"אֶרְאֶה נִקְמָתְךָ מֵהֶם. אֶת אַנְשֵׁי עֲנָתוֹת הָיָה מְקַלֵּל:",1,0],[11,23,"אֶל אַנְשֵׁי עֲנָתוֹת. כְּמוֹ עַל אַנְשֵׁי עֲנָתוֹת:",1,0],[12,1,"צַדִּיק אַתָּה ה׳ כִּי אָרִיב אֵלֶיךָ. כְּשֶׁאֶתְוַכֵּחַ עִמְּךָ, יָדַעְתִּי כִּי תִצְדַּק בִּדְבָרֶיךָ, אַךְ חָפֵץ אֲנִי לְדַבֵּר מִשְׁפָּטִים אוֹתָךְ, לְהוֹדִיעֵנִי דַּרְכֶּךָ (שמות לג:יג):",1,0],[12,1,"מַדּוּעַ דֶּרֶךְ רְשָׁעִים צָלֵחָה. שֶׁנָּתַתָּ גְּדֻלָּה לִנְבוּכַדְנֶצַּר הָרָשָׁע וְתַצְלִיחֵהוּ לְהַחֲרִיב בֵּיתֶךָ. דָּבָר אַחֵר: עַל אַנְשֵׁי עֲנָתוֹת הָיָה צוֹעֵק וְקוֹרֵא תִּגָּר (ירמיה יא:כא):",2,0],[12,1,"שָׁלוּ. לְשׁוֹן ״שַׁלְוָה״ (תהלים קכב:ז):",3,0],[12,3,"וְאַתָּה ה׳ יְדַעְתָּנִי. גַּם עַל אַנְשֵׁי עֲנָתוֹת הָעוֹמְדִים עָלַי עָזְרֵנִי, כִּי אַתָּה יְדַעְתָּנִי:",1,0],[12,3,"הַתִּיקֵם כְּצֹאן לְטִבְחָה. נַתְּקֵם מִן הַחַיִּים לָמוּת, דִּישְׁטָאקָאלוּ״שׁ בְּלַעַ״ז, כְּמוֹ ״עַד הַתִּיקְנוּ אוֹתָם מִן הָעִיר״ (יהושע ח:ו):",2,0],[12,3,"וְהַקְדִּישֵׁם. הַזְמִינֵם:",3,0],[12,4,"עַד מָתַי תֶּאֱבַל הָאָרֶץ וְעֵשֶׂב כָּל הַשָּׂדֶה יִיבָשׁ. עַד כָּאן דִּבְרֵי הַנָּבִיא, וְרוּחַ הַקֹּדֶשׁ מְשִׁיבָתוֹ: מֵרָעַת יֹשְׁבֵי בָהּ סָפְתָה בְהֵמוֹת וָעוֹף:",1,0],[12,4,"תֶּאֱבַל. תֶּחֱרַב:",2,0],[12,4,"סָפְתָה. פוֹנִיד״א בְּלַעַ״ז:",3,0],[12,4,"כִּי אָמְרוּ. יוֹשְׁבֵי הָאָרֶץ הַזֹּאת:",4,0],[12,4,"לֹא יִרְאֶה אֶת אַחֲרִיתֵנוּ. אֵין גָּלוּי לְפָנָיו מַה יִהְיֶה בְּסוֹפֵינוּ:",5,0],[12,5,"כִּי אֶת רַגְלִים רַצְתָּה וַיַּלְאוּךָ. קְרוֹבֶיךָ, הַכֹּהֲנִים כְּמוֹתְךָ, וְאַנְשֵׁי עִירְךָ בָּאִים לְהָרְגֶךָ. אֶת רַגְלִים. עִם רַגְלִים, פִּיאוֹנִיד״ש בְּלַעַז:",1,0],[12,5,"וְאֵיךְ תְּתַחֲרֶה אֶת הַסּוּסִים. לָרוּץ אֶת הַסּוּסִים; כְּלוֹמַר: וּמָה קְרוֹבֶיךָ הַכֹּהֲנִים בָּאִים לְהָרְגְךָ, כָּל שֶׁכֵּן שֶׁיָּקוּמוּ לְהוֹרְגְךָ שָׂרֵי יְהוּדָה; וְזֶהוּ קִצְפִּי עֲלֵיהֶם, וְזוֹ הִיא הַצְלָחַת הָאוֹיֵב. וְכֵן תִּרְגֵּם יוֹנָתָן: ״דְּנָא תְּיוּבְתָּא וְגוֹ׳״. וּמִדְרַשׁ רַבּוֹתֵינוּ (סנהדרין צו.): אִם עַל שְׂכַר שָׁלֹשׁ פְּסִיעוֹת שֶׁרָץ נְבוּכַדְנֶצַּר לִכְבוֹדִי בִּימֵי מְרֹדַךְ בַּלְאֲדָן אַתָּה תָּמֵהַּ, שֶׁהִרְבֵּיתִי גְדֻלָּתוֹ כָּל כָּךְ, מָה תִּתְמַהּ עוֹד כְּשֶׁתִּרְאֶה שִׁלּוּם שָׂכָר שֶׁאֲשַׁלֵּם לַצַּדִּיקִים שֶׁרָצוּ לְפָנַי כַּסּוּסִים!",2,0],[12,5,"תְּתַחֲרֶה. אַאֲטִיר״שׁ בְּלַעַ״ז:",3,0],[12,5,"וּבְאֶרֶץ שָׁלוֹם. אֲשֶׁר אַתָּה בּוֹטֵחַ שָׁם הִלְאוּךָ:",4,0],[12,5,"וְאֵיךְ תַּעֲשֶׂה בִּגְאוֹן. שָׂרֵי יְהוּדָה. וּגְאוֹן הַיַּרְדֵּן מָשָׁל הוּא, לְפִי שֶׁהוּא מְקוֹם אֲרָיוֹת וּנְמֵרִים, וְכֵן לִמְּדָנוּ יוֹנָתָן בְּהַרְבֵּה מְקוֹמוֹת; וְכָאן תִּרְגֵּם: ״וְאַכְדֵּין אַתְּ מְדַמֵּי לְקָבֵל חֵיוַת בָּרָא דִּי בְּרוּם יַרְדְּנָא״, וְהִנֵּה ״כְּאַרְיֵה יַעֲלֶה מִגְּאוֹן הַיַּרְדֵּן״ (ירמיה מט:יט; נ:מד) תִּרְגֵּם יוֹנָתָן בִּשְׁתֵּי מְקוֹמוֹת: ״כְּאַרְיֵה דְּסָלִיק מֵרוּם יַרְדְּנָא״:",5,0],[12,6,"קָרְאוּ אַחֲרֶיךָ מָלֵא. קְבוּצַת אֲנָשִׁים:",1,0],[12,7,"יְדִידוּת נַפְשִׁי. עַם סְגֻלָּתִי:",1,0],[12,8,"נָתְנָה עָלַי בְּקוֹלָהּ. עָלְתָה לְפָנַי צַעֲקַת חֲמָסֶיהָ:",1,0],[12,9,"הָעַיִט צָבוּעַ. הַה״א תָּמוּהַּ, לְכָךְ הוּא נָקוּד פַּתָּ״ח: הֲכִי הֵם עוֹף צָבוּעַ, מְגֹאָל בְּדָם, שֶׁשְּׁאָר הָעוֹפוֹת נֶאֱסָפִים עָלָיו? דָּבָר אַחֵר: הָעַיִט צָבוּעַ עוֹף אֶחָד שֶׁהוּא צָבוּעַ וְכָל הָעוֹפוֹת נֶאֱסָפִים עָלָיו לְאוֹכְלוֹ שֶׁשּׂוֹנְאִים אוֹתוֹ:",1,0],[12,9,"הָעַיִט סָבִיב עָלֶיהָ. שֶׁמָּא עוֹף שָׁמַיִם הֵם אֵלּוּ הַחַיָּלוֹת, הַגְּדוּדִים הַקַּלִּים אֲשֶׁר סְבִיבֶיהָ?!",2,0],[12,9,"הֵתָיוּ. בֹּאוּ:",3,0],[12,10,"רוֹעִים רַבִּים. רָאשֵׁי גְיָסוֹת שֶׁל חֵיל נְבוּכַדְנֶצַּר, כְּמוֹ שֶׁנֶּאֱמַר לְמַעְלָה ״אֵלֶיהָ יָבֹאוּ רוֹעִים וְעֶדְרֵיהֶם״ (ירמיה ו:ג):",1,0],[12,10,"בֹּסְסוּ. לְשׁוֹן ״מִרְמָס״ (ישעיה י:ו); וְכֵן ״וְהָיוּ כַגִּבּוֹרִים בּוֹסִים בְּטִיט חוּצוֹת״ (זכריה י:ה):",2,0],[12,10,"חֶלְקַת. קַנְפַנְיָ״א בְּלַעַ״ז:",3,0],[12,11,"אָבְלָה עָלַי. לְפָנַי:",1,0],[12,13,"זָרְעוּ חִטִּים וְקֹצִים קָצָרוּ. הִתְפַּלְלוּ וְלֹא נִתְקַבְּלָה תְּפִלָּתָם. לָמָּה? לְפִי שֶׁלֹּא נָרוּ לָהֶם נִיר תְּשׁוּבָה וּמַעֲשִׂים טוֹבִים, לְכָךְ זָרְעוּ אֶל קוֹצִים (ירמיה ד:ג). סֵפֶר שֶׁנָּקוּד בּוֹ זִרְעוּ, בְּחִירִ״ק הַזַּיִ״ן, שִׁבּוּשׁ הוּא:",1,0],[12,13,"נֶחְלוּ. לְשׁוֹן חוֹלִי, נֶחְלוּ בְּמַכְאוֹבָם וְצָעֲקָתָם לְפָנַי, וְלֹא יוֹעִלוּ:",2,0],[12,13,"מִתְּבוּאֹתֵיכֶם. מִמַּעֲשֵׂיכֶם:",3,0],[12,14,"שְׁכֵנַי הָרָעִים. מִצְרַיִם, עַמּוֹן וּמוֹאָב וְצוֹר וְצִידוֹן, שֶׁהָיוּ שְׁכֵנֵי אֶרֶץ יִשְׂרָאֵל וּמַזִּיקִין אוֹתָם:",1,0],[12,15,"אָשׁוּב וְרִחַמְתִּים. כֻּלָּן לָקוּ סָמוּךְ לְחֻרְבַּן הַבַּיִת, וּבְכֻלָּם נֶאֱמַר ״וְשַׁבְתִּי אֶת שְׁבוּת״ בְּסֵפֶר זֶה (ירמיה כט:יד; ל:ג, יח; לא:כב; לג:ז, יא, כו; מח:מז; מט:ו, לט):",1,0],[12,16,"אִם לָמוֹד יִלְמְדוּ. אִם יַאֲמִינוּ בַּה׳:",1,0],[12,16,"וְנִבְנוּ. לְשׁוֹן בִּנְיָן:",2,0],[13,1,"אֵזוֹר. פּוֹרְצִינְ״ט בְּלַעַ״ז:",1,0],[13,1,"וּבַמַּיִם לֹא תְבִיאֵהוּ. לְכַבְּסוֹ כְּשֶׁיְּהֵא מָלֵא זֵיעָה, כְּדֵי שֶׁיְּמַהֵר לֵירָקֵב:",2,0],[13,7,"לֹא יִצְלַח לַכֹּל. אֵינוֹ רָאוּי לִכְלוּם:",1,0],[13,10,"וִיהִי כָּאֵזוֹר הַזֶּה. גְּאוֹנָם יִהְיֶה כָּאֵזוֹר הַזֶּה הַנִּרְקָב:",1,0],[13,12,"נֵבֶל. כְּלִי חֶרֶס הוּא, וְעָשׂוּי לְהַכְנִיס בּוֹ יָיִן:",1,0],[13,14,"וְנִפַּצְתִּים אִישׁ אֶל אָחִיו. אַכֶּה זֶה עַל זֶה, עַד שֶׁיִּשָּׁבְרוּ חֲתִיכוֹת דַּקּוֹת; כְּמוֹ ״כִּכְלִי יוֹצֵר תְּנַפְּצֵם״ (תהלים ב:ט); ״וְנִפֵּץ אֶת עֹלָלַיִךְ״ (תהלים קלז:ט); וְכֵן כָּל נִפּוּץ שֶׁבַּמִּקְרָא:",1,0],[13,14,"וְהָאָבוֹת וְהַבָּנִים. אֲנַפֵּץ זֶה אֵצֶל זֶה:",2,0],[13,16,"יִתְנַגְּפוּ. יִכָּשְׁלוּ, אצופי״ר בְּלַעַ״ז:",1,0],[13,16,"הָרֵי נָשֶׁף. הָרֵי חֹשֶׁךְ, בְּלֶכְתָּם בַּגּוֹלָה:",2,0],[13,16,"וְשִׁית לַעֲרָפֶל. כְּמוֹ וְלָשִׁית אֶת הָאוֹר לַעֲרָפֶל:",3,0],[13,17,"מִפְּנֵי גֵוָה. מִפְּנֵי גְדוּלָּה שֶׁלָּכֶם שֶׁתִּתְבַּטֵּל. דָּבָר אַחֵר, מִפְּנֵי גַּאֲוָתָהּ שֶׁל מַלְכוּת שָׁמַיִם שֶׁתִּנָּתֵן לֶאֱלִילִים שֶׁל כַּשְׂדִּים (חגיגה ה:):",1,0],[13,18,"לַמֶּלֶךְ וְלַגְּבִירָה. יְהוֹיָכִין וְאִמּוֹ:",1,0],[13,18,"יָרַד מַרְאֲשׁוֹתֵיכֶם. וּושְׁטְרִי קָאיִ״ץ בְּלַעַ״ז, עֲלִיַּתְכֶם; כְּמוֹ שֶׁנֶּאֱמַר ״וַיֵּצֵא אֵלָיו יְהוֹיָכִין הוּא וְאִמּוֹ וַעֲבָדָיו״ (מלכים ב כד:יב), וְכֻלָּם הוֹלִיכָם בַּגּוֹלָה:",2,0],[13,19,"עָרֵי הַנֶּגֶב סֻגְּרוּ. לִפְנֵי הַבָּאִין עֲלֵיהֶם מִן הַצָּפוֹן; עָרֵי אֶרֶץ יִשְׂרָאֵל סְגוּרוֹת מֵאֵימַת נְבוּכַדְנֶצַּר:",1,0],[13,19,"הׇגְלָת שְׁלוֹמִים. לֹא יִלָּחֵם יְהוֹיָכִין, כִּי לְשָׁלוֹם יֵצֵא וְיַגְלֵהוּ (מלכים ב כד:יב). לָשׁוֹן אַחֵר: שְׁלוֹמִים גרדונאמינ״ץ בְּלַעַז, כְּלוֹמַר: תַּשְׁלוּם עֲוֹנָם; וְכֵן תִּרְגֵּם יוֹנָתָן: ״אִיתְקַבְּלוּ תּוֹשְׁלַמַת חוֹבֵיהוֹן״:",2,0],[13,20,"שְׂאוּ עֵינֵיכֶם וּרְאוּ. אֶת הַבָּאִים עֲלֵיכֶם מִצָּפוֹן:",1,0],[13,20,"אַיֵּה הָעֵדֶר נִתַּן לָךְ. אַחַר שֶׁיִּגְלוּ, יֹאמַר לִירוּשָׁלַיִם כֵּן:",2,0],[13,21,"מַה תֹּאמְרִי כִּי יִפְקֹד. הַקָּדוֹשׁ בָּרוּךְ הוּא עָלַיִךְ:",1,0],[13,21,"לִמַּדְתְּ אוֹתָם עָלַיִךְ אַלֻּפִים לְרֹאשׁ. שְׁלַחְתֶּם אֲלֵיהֶם מַלְאָכִים לַכַּשְׂדִּיִּים לְהָבִיא מִשָּׁם אֱלִילִים שֶׁלָּהֶם לְעָבְדָם, כְּמוֹ שֶׁנֶּאֱמַר בִּיחֶזְקֵאל (יחזקאל כג:טז) ״וַתַּעְגְּבָה עֲלֵיהֶם לְמַרְאֵה עֵינֶיהָ וַתִּשְׁלַח מַלְאָכִים אֲלֵיהֶם כַּשְׂדִּימָה״. דָּבָר אַחֵר: לִמַּדְתְּ אוֹתָם עָלַיִךְ אַלֻּפִים – חִזְקִיָּהוּ שֶׁהֶרְאָה לִשְׁלוּחֵי מְרֹדַךְ בַּלְאֲדָן אֶת כָּל בֵּית נְכָאתָה (ישעיהו לט:ב):",2,0],[13,22,"שׁוּלַיִךְ. שִׁפּוּלֵי הַבְּגָדִים, טִי״שׁ אוֹרְלָ״שׁ בְּלַעַ״ז; כְּשֶׁמַּפְשִׁיטִין אֶת הָאִשָּׁה דֶּרֶךְ בִּזָּיוֹן, מְהַפְּכִין חֲלוּקָהּ מִלְּמַטָּה לְמַעְלָה:",1,0],[13,22,"נֶחְמְסוּ עֲקֵבָיִךְ. נִגְזְרוּ דְּרָכַיִךְ. נֶחְמְסוּ כְּמוֹ ״וַיַּחְמֹס כַּגַּן שֻׂכּוֹ״ (איכה ב:ו):",2,0],[13,22,"עֲקֵבָיִךְ. טְרַצִי״שׁ בְּלַעַ״ז; פָּסְקוּ עוֹבְרֵי דְרָכִים:",3,0],[13,23,"כּוּשִׁי. שֵׁם אָדָם שָׁחוֹר, וְקוֹרִין מָאוֹר בְּלַעַ״ז:",1,0],[13,23,"וְנָמֵר. לִיאַפַּרְ״ט בְּלַעַ״ז:",2,0],[13,23,"חֲבַרְבֻּרֹתָיו. הַנָּמֵר מְנֻמָּר הוּא, וְהֵם הַחֲבַרְבֻּרוֹת, טָק״שׁ בְּלַעַ״ז; וְאִי אֶפְשָׁר שֶׁיֵּהָפְכוּ:",3,0],[13,23,"הָרֵעַ. כְּמוֹ ״לְהָרֵעַ״ (תהלים לז:ח):",4,0],[13,25,"מְנָת מִדַּיִךְ. חֵלֶק מִדּוֹתַיִךְ, מִדָּה כְּנֶגֶד מִדָּה:",1,0],[13,26,"חָשַׂפְתִּי שׁוּלַיִךְ. גִּלִּיתִי שִׁפּוּלֵי בְגָדַיִךְ, לְהָפְכָם עַל פָּנָיִךְ:",1,0],[13,27,"מִצְהֲלוֹתַיִךְ. כְּצַהֲלַת סוּסִים נוֹאֲפִים (ירמיה ה:ח):",1,0],[13,27,"אַחֲרֵי מָתַי. תִּטְהֲרִי עֹד:",2,0],[14,1,"דִּבְרֵי הַבַּצָּרוֹת. שֶׁיָּבִיא עֲלֵיהֶם רָעָב. וּמְנַחֵם חִבְּרוֹ לְשׁוֹן מִבְצָר, כְּמוֹ ״וּמִבְצַר מִשְׂגַּב חוֹמוֹתֶיךָ״ (ישעיהו כה:יב):",1,0],[14,2,"וּשְׁעָרֶיהָ. עָרֶיהָ:",1,0],[14,2,"וְצִוְחַת יְרוּשָׁלִַם. צַעֲקַת יְרוּשָׁלַיִם, כְּמוֹ ״מֵרֹאשׁ הָרִים יִצְוָחוּ״ (ישעיה מב:יא):",2,0],[14,3,"עַל גֵּבִים. בּוֹרוֹת שֶׁהַמַּיִם מִתְכַּנְּסִים בָּהֶם:",1,0],[14,3,"שָׁבוּ כְלֵיהֶם רֵיקָם. שֶׁלֹּא יָרַד מָטָר:",2,0],[14,3,"וְחָפוּ. לְשׁוֹן כִּסּוּי:",3,0],[14,4,"אִכָּרִים. בּוֹבִיֵּיר״שׁ בְּלַעַ״ז:",1,0],[14,5,"יָלְדָה וְעָזוֹב. אֶת וְלָדָהּ, לְבַקֵּשׁ לָהּ מִרְעֶה:",1,0],[14,6,"עַל שְׁפָיִים. יִבְלֵי מַיִם, רִיבֵיירְ״שׁ בְּלַעַ״ז:",1,0],[14,7,"עָנוּ בָנוּ. הֵעִידוּ בָּנוּ:",1,0],[14,7,"עֲשֵׂה לְמַעַן שְׁמֶךָ. עֲשֵׂה מַה שֶּׁתַּעֲשֶׂה עִמָּנוּ לְמַעַן שֵׁם גָּדוֹל שֶׁיֵּצֵא לְךָ, שֶׁאַתָּה מוֹשֵׁל בַּכֹּל, וַאֲנַחְנוּ עַמְּךָ וְצֹאן מַרְעִיתֶךָ (תהלים עט:יג), וְלֹא נָאֶה שֶׁתִּתֵּן שֵׁם נִצְחוֹנְךָ לָאֱלִילִים. וּמִדְרַשׁ אַגָּדָה יֵשׁ (ירושלמי תענית ב:ו סה,ד): לְמַעַן שְׁמֶךָ וְכוּ׳:",2,0],[14,8,"מִקְוֵה. תּוֹחֶלֶת:",1,0],[14,9,"נִדְהָם. רַקְרוּ״ץ בְּלַעַ״ז, מוֹשֵׁךְ יָדוֹ מִן הַמִּלְחָמָה; וְיֵשׁ אוֹמְרִים: רַקְרִיאַנְ״ץ בְּלַעַ״ז:",1,0],[14,9,"וְשִׁמְךָ עָלֵינוּ נִקְרָא. לְפִיכָךְ אֵין כְּבוֹדְךָ בְּכָךְ:",2,0],[14,9,"תַּנִּחֵנוּ. פֵּירוּשׁוֹ כְּמוֹ ״תַּעַזְבֵנוּ״ (איכה ה:כ):",3,0],[14,10,"כֵּן אָהֲבוּ לָנוּעַ. כֵּן, כְּמָה שֶׁגָּזַרְתִּי עֲלֵיהֶם גּוֹלָה בְּמִצְרַיִם וּבָבֶל, אָהֲבוּ שָׁם לִהְיוֹת גּוֹלִים, לַעֲבֹד אֱלִילֵיהֶם הָרְחוֹקוֹת:",1,0],[14,14,"וֶאֱלִיל. לְשׁוֹן אַל, דָּבָר שֶׁאֵינוֹ:",1,0],[14,17,"נַחְלָה מְאֹד. לְשׁוֹן ״חֳלִי״ (ירמיה ו:ז):",1,0],[14,18,"סָחֲרוּ. סָבְבוּ לְבַקֵּשׁ הַצָּלָה:",1,0],[14,18,"אֶל אֶרֶץ וְלֹא יָדָעוּ. אֶל אֶרֶץ אַחֶרֶת, וְלֹא הָיוּ יוֹדְעִין בָּהּ עַד הֵנָּה:",2,0],[14,19,"אִם בְּצִיּוֹן גָּעֲלָה נַפְשֶׁךָ. עַל מְנָת שֶׁלֹּא לָשׁוּב עָלֶיהָ? כִּי אִם דַּעְתְּךָ לָשׁוּב, מַדּוּעַ הִכִּיתָ בְּאֵין מַרְפֵּא? (פסיקתא רבתי לא)",1,0],[14,21,"לְמַעַן שִׁמְךָ. שֶׁנִּקְרֵאתָ ״רַחוּם״ (שמות לד:ו):",1,0],[14,21,"כִּסֵּא כְבוֹדֶךָ. בֵּית הַמִּקְדָּשׁ (פסחים ה.), וּמִדְרַשׁ אַגָּדָה (תנחומא, במדבר כב): יִשְׂרָאֵל הַחֲקוּקִים בְּכִסֵּא כְבוֹדֶךָ:",2,0],[14,22,"וְאִם הַשָּׁמַיִם יִתְּנוּ רְבִיבִים. מֵאֲלֵיהֶם, אִם לֹא עַל פִּיךָ? בִּתְמִיהָּ. כָּל תְּמִיהָה הַכְּפוּלָה, הָרִאשׁוֹנָה בְּה״א וְהַשְּׁנִיָּה בְּאִם, כְּגוֹן: ״הַבְּמַחֲנִים אִם בְּמִבְצָרִים״ (במדבר יג:יט); ״הֲטוֹבָה הִיא אִם רָעָה״ (במדבר יג:יט); ״הֲמָאוֹס מָאַסְתָּ אִם בְּצִיּוֹן גָּעֲלָה נַפְשֶׁךָ״ (ירמיהו יד:יט). אַף כָּאן: הֲיֵשׁ בְּהַבְלֵי הַגּוֹיִם… וְאִם הַשָּׁמַיִם:",1,0],[15,1,"מֹשֶׁה וּשְׁמוּאֵל. שְׁנֵיהֶם נִזְקְקוּ לְבַקֵּשׁ רַחֲמִים עַל יִשְׂרָאֵל, וּמִתְּחִלָּה הֶחֱזִירוּם לְמוּטָב, וְאַחַר כָּךְ הִתְפַּלְלוּ עֲלֵיהֶם; וְלֹא עָלָה בְלִבָּם לְהָשִׁיב אַפִּי עַד שֶׁהֶחֱזִירוּם לְמוּטָב. מֹשֶׁה אָמַר: ״שִׂימוּ אִישׁ חַרְבּוֹ וְגוֹ׳״ (שמות לב:כז), ״וַיִּזֶר עַל פְּנֵי הַמַּיִם וְגוֹ׳״ (שמות לב:כ), וְאַחַר כָּךְ ״אֶעֱלֶה אֶל ה׳ אוּלַי אֲכַפְּרָה״ (שמות לב:ל); שְׁמוּאֵל בַּמִּצְפָּה: ״וַיָּסִירוּ בְנֵי יִשְׂרָאֵל אֶת הַבְּעָלִים וְגוֹ׳״ (שמואל א ז:ד), וְאַחַר כָּךְ ״קִבְצוּ אֶת יִשְׂרָאֵל הַמִּצְפָּתָה וְאֶתְפַּלֵּל עֲלֵיכֶם״ (שמואל א ז:ה). אַתָּה אֵינְךָ יָכוֹל לַהֲשִׁיבָם אֵלַי, לְכָךְ אַל תִּתְפַּלֵּל עֲלֵיהֶם (ירמיה ז:טז):",1,0],[15,1,"נַפְשִׁי. רְצוֹנִי:",2,0],[15,2,"אֲשֶׁר לַמָּוֶת וְגוֹ׳. כָּל הַמְאֻחָר בַּפָּסוּק קָשֶׁה מֵחֲבֵירוֹ. חֶרֶב קָשֶׁה מִמָּוֶת, מִיתַת חֶרֶב מְנֻוֶּלֶת וּמִיתָה עַל מִטָּתוֹ אֵינָהּ מְנֻוֶּלֶת, וְכֵן הוּא אוֹמֵר (תהלים קטז:טו) ״יָקָר בְּעֵינֵי ה׳ הַמָּוְתָה לַחֲסִידָיו״. רָעָב קָשֶׁה מֵחֶרֶב, שֶׁזֶּה מִצְטַעֵר וְזֶה אֵינוֹ מִצְטַעֵר, וְכֵן הוּא אוֹמֵר ״טוֹבִים הָיוּ חַלְלֵי חֶרֶב מֵחַלְלֵי רָעָב״ (איכה ד:ט). שְׁבִי כֻּלְּהוּ אִיתַנְהוּ בְּגַוֵּהּ (בבא בתרא ח:):",1,0],[15,3,"וּפָקַדְתִּי. לְשׁוֹן מִנּוּי וּפְקִידוּת:",1,0],[15,3,"לִסְחֹב. לִגְרֹר, וְכֵן ״אִם לֹא יִסְחָבוּם״ (ירמיה מט:כ):",2,0],[15,4,"לְזַעֲוָה. מִגִּזְרַת ״לֹא קָם וְלֹא זָע״ (אסתר ה:ט); וּכְמוֹהוּ גַּאֲוָה מִגִּזְרַת ״גֵּא מְאֹד״ (ישעיה טז:ו):",1,0],[15,4,"לְכָל מַמְלְכוֹת הָאָרֶץ. כָּל הַשּׁוֹמֵעַ רָעָה שֶׁבָּאָה עֲלֵיהֶם, יָזוּעַ:",2,0],[15,5,"יָנוּד. יְקוֹנֵן:",1,0],[15,5,"וּמִי יָסוּר. אֵלֶיךָ, לִנְטוֹת מִדַּרְכּוֹ אֵלַיִךְ, לִשְׁאֹל לָךְ לְשָׁלוֹם:",2,0],[15,6,"נִלְאֵיתִי הִנָּחֵם. כַּמָּה פְּעָמִים חָשַׁבְתִּי לְהַשְׁחִית וְנִחַמְתִּי עַל הָרָעָה; עַתָּה נִלְאֵיתִי הִנָּחֵם. הִנָּחֵם – רְפוֹרְפִינְשְׁ״ר בְּלַעַ״ז:",1,0],[15,7,"בַּמִּזְרֶה. נָפָה שֶׁקּוֹרִין וו״ן בְּלַעַ״ז, כָּזֶה שֶׁהוּא זוֹרֶה שְׂעוֹרִין; שֶׁלֹּא יְהוּ כֻּלָּן גּוֹלִין לְמָקוֹם אֶחָד:",1,0],[15,8,"עָצְמוּ לִי. רַבּוּ לְפָנַי אַלְמְנוֹתָו:",1,0],[15,8,"עַל אֵם. עַל יְרוּשָׁלַיִם שֶׁהָיְתָה עִיר וָאֵם בְּיִשְׂרָאֵל (שמואל ב כ:יט):",2,0],[15,8,"בַּצׇּהֳרָיִם. הַכֹּל יְהֵא גָּלוּי לְפָנָיו, כָּל גִּנְזֵי מַטְמוֹנָם:",3,0],[15,8,"הִפַּלְתִּי עָלֶיהָ פִּתְאֹם עִיר. הִשְׁכַּנְתִּי עֲלֵיהֶם פִּתְאֹם גְּיָסוֹת שֶׁל עִיר וּבֶהָלוֹת רַבּוֹת. וְיֵשׁ פּוֹתְרִים עִיר – לְשׁוֹן שׂוֹנֵא, כְּמוֹ ״וַיְהִי עָרֶיךָ״ (שמואל א כח:טז); ״וּפִשְׁרֵיהּ לְעָרָךְ״ (דניאל ד:טז):",4,0],[15,9,"אֻמְלְלָה יוֹלֶדֶת הַשִּׁבְעָה. שׁוֹמְרוֹן וּכְנֵסִיָּה שֶׁל עֲשֶׂרֶת שְׁבָטִים, שֶׁעָמְדוּ מֵהֶם שֶׁבַע מִשְׁפָּחוֹת (גיטין פח.), כְּבָר אֻמְלְלָה וְגָלְתָה:",1,0],[15,9,"וּשְׁאֵרִיתָם. אֵלּוּ יְהוּדָה וּקְצָת בִּנְיָמִין שֶׁנִּשְׁתַּיְּרוּ בְּיִשְׂרָאֵל, לַחֶרֶב אֶתֵּן. אֵלּוּ הֵן שֶׁבַע מִשְׁפָּחוֹת: יָרָבְעָם בֶּן נְבָט וּבֵיתוֹ, בַּעְשָׁא וּבֵיתוֹ, עָמְרִי וּבֵיתוֹ, יֵהוּא וּבֵיתוֹ, מְנַחֵם וּבֵיתוֹ, פֶּקַח וּבֵיתוֹ, הוֹשֵׁעַ וּבֵיתוֹ:",2,0],[15,9,"נָפְחָה נַפְשָׁהּ. לְשׁוֹן דָּאֲבָה נַפְשָׁהּ, מְתַרְגְּמִינָן ״וְדַאֲבוֹן נֶפֶשׁ״ (דברים כח:סה) ״וּמַפְּחָן נְפָשׁ״:",3,0],[15,9,"בְּעוֹד יוֹמָם. בְּלֹא זְמַנָּם מִהֲרוּ לִיפּוֹל. כָּךְ נִדְרַשׁ בְּמַסֶּכֶת גִּיטִּין (גיטין פח.). וּבְמִדְרַשׁ רַבִּי תַּנְחוּמָא (תנחומא, בובר ויצא יד) דָּרְשׁוּ כְּלַפֵּי יְרוּשָׁלַיִם, וּמוֹנֶה שִׁבְעָה רְשָׁעִים: יְהוֹרָם, יְהוֹאָשׁ, אָחָז, מְנַשֶּׁה, אָמוֹן, יְהוֹיָקִים, צִדְקִיָּהוּ. אַךְ יֵשׁ לִמְנוֹת עוֹד: רְחַבְעָם, אֲבִיָּה, אֲמַצְיָה, אֲחַזְיָה:",4,0],[15,9,"וְחָפֵרָה. לְשׁוֹן בּוֹשֶׁת:",5,0],[15,10,"אוֹי לִי אִמִּי. יִרְמְיָה הָיָה מִתְאוֹנֵן עַל עַצְמוֹ, שֶׁהָיוּ שׂוֹנְאִין אוֹתוֹ בְּנֵי עִירוֹ עַל דִּבְרֵי תוֹכְחוֹתָיו:",1,0],[15,10,"וְאִישׁ מָדוֹן. אִישׁ מְרִיבָה, כְּמוֹ ״לֹא יָדוֹן רוּחִי״ (בראשית ו:ג):",2,0],[15,10,"לֹא נָשִׁיתִי. כְּמוֹ ״לֹא תִהְיֶה לוֹ כְּנֹשֶׁה״ (שמות כב:כד):",3,0],[15,10,"כֻּלֹּה מְקַלְלַוְנִי. אֵינִי רָב עִמָּהֶם עַל עִסְקֵי מָמוֹן שֶׁיֵּשׁ לִי עֲלֵיהֶם וְלֹא לָהֶם עָלַי, וַהֲרֵי כָּל הָעָם מְקַלְלַנִי:",4,0],[15,11,"שֵׁרִיתִיךָ. הִשְׁאַרְתִּיךָ, לְשׁוֹן ״שְׁאֵרִית״ (בראשית מה:ז). וְכֵן פִּתְרוֹ מְנַחֵם. אֲבָל דּוֹנָשׁ פָּתַר אוֹתוֹ לְשׁוֹן הַתָּרָה, וְשֵׁרִיתִיךָ כְּמוֹ ״מְשָׁרֵי קִטְרִין״ (דניאל ה:יב). וּפִתְרוֹן שֵׁרִיתִיךָ כֵּן הוּא, שֶׁנֶּאֱמַר ״הִנֵּה פְתַחְתִּיךָ הַיּוֹם מִן הָאֲזִקִּים״ (ירמיה מ:ד); כְּלוֹמַר: בַּיּוֹם אֲשֶׁר הֵקִים ה׳ אֶת דְּבָרוֹ נֶאֱמַר לוֹ: ״וְעַתָּה הִנֵּה פְתַחְתִּיךָ הַיּוֹם מִן הָאֲזִקִּים אֲשֶׁר עַל יָדֶיךָ, אִם טוֹב בְּעֵינֶיךָ לָבוֹא אִתִּי בָבֶלָה״ (ירמיה מ:ד). וְגַם יִשְׂרָאֵל בִּקְּשׁוּ מִמֶּנּוּ שֶׁיִּתְפַּלֵּל בִּשְׁבִילָם, כַּאֲשֶׁר נֶאֱמַר לוֹ: ״הִתְפַּלֵּל בַּעֲדֵנוּ אֶל ה׳ אֱלֹהֵינוּ… כִּי נִשְׁאַרְנוּ מְעַט מֵהַרְבֵּה״ (ירמיה מב:ב):",1,0],[15,11,"אִם לֹא. לְשׁוֹן שְׁבוּעָה:",2,0],[15,11,"הִפְגַּעְתִּי בְךָ בְּעֵת רָעָה. אֶת הָאוֹיֵב, כְּשֶׁתָּבֹא עֲלֵיהֶם הָרָעָה, יִפְגְּעוּ בְךָ שֶׁתְּבַקֵּשׁ רַחֲמִים עֲלֵיהֶם; כְּגוֹן צִדְקִיָּה, אָמַר לוֹ: ״דְּרָשׁ נָא בַּעֲדֵנוּ אֶת ה׳ וְגוֹ׳״ (ירמיה כא:ב). דָּבָר אַחֵר: נְבוּזַרְאֲדָן יְבַקֵּשׁ מֵאִתְּךָ: ״אִם טוֹב בְּעֵינֶיךָ לָבֹא אִתִּי בָּבֶלָה״ (ירמיה מ:ד):",3,0],[15,12,"הֲיָרֹעַ בַּרְזֶל בַּרְזֶל מִצָּפוֹן. אוֹמֵר אֲנִי: בַּרְזֶל הַבָּא מִצָּפוֹן קָשֶׁה מִשְּׁאָר בַּרְזֶל. וְכֵן פִּתְרוֹנוֹ: הֵם נִמְשְׁלוּ לְבַרְזֶל: ״הוֹלְכֵי רָכִיל נְחֹשֶׁת וּבַרְזֶל״ (ירמיה ו:כח), וּבְיִרְמְיָה נֶאֱמַר: ״נְתַתִּיךָ לְעַמּוּד בַּרְזֶל וּלְחוֹמַת נְחֹשֶׁת״ (ירמיה א:יח) – וְשֶׁלּוֹ חָזָק מִשֶּׁלָּהֶם, כִּי נְבוּכַדְנֶצַּר מִצָּפוֹן יָבֹא כִּדְבָרָיו עֲלֵיהֶם:",1,0],[15,12,"הֲיָרֹעַ. הֲיְרוֹצֵץ בַּרְזֶל שֶׁלָּהֶם אֶת שֶׁלְּךָ? דָּבָר אַחֵר: הֲיְרוֹצֵץ פַּרְעֹה הַבָּא בְּעֶזְרַתְכֶם, שֶׁהוּא קָשֶׁה כְּבַרְזֶל, אֶת נְבוּכַדְנֶצַּר, שֶׁהוּא בַּרְזֶל הַבָּא מִצָּפוֹן וּנְחֹשֶׁת? וְתַרְגּוּם יוֹנָתָן נוֹטֶה לְצַד זֶה:",2,0],[15,13,"חֵילְךָ. לְשׁוֹן מָמוֹן (ראה דברים ח:יז):",1,0],[15,13,"וְאוֹצְרוֹתֶיךָ. לְיִשְׂרָאֵל הוּא אוֹמֵר:",2,0],[15,13,"וּבְכָל חַטֹּאותֶיךָ. וּלְמַעַן כָּל חַטֹּאותֶיךָ תְּהִי זֹאת לָךְ:",3,0],[15,13,"וּבְכָל גְּבוּלֶיךָ. אֲשֶׁר הֶעֱמַדְתָּ אֱלִילִים בְּכֻלָּן:",4,0],[15,15,"אַל לְאֶרֶךְ אַפְּךָ תִּקָּחֵנִי. תַּרְגּוּם יוֹנָתָן: ״לָא תִּתֵּן אַרְכָּא לְעוֹלְבָנִי״ – אַל תִּקַּח אֶת רִיבִי לְהַנִּיחוֹ לְאֹרֶךְ אַפְּךָ, אֶלָּא מַהֵר וְהִנָּקֶם לִי:",1,0],[15,15,"שְׂאֵתִי. כְּמוֹ סָבַלְתִּי:",2,0],[15,15,"עָלֶיךָ. בִּשְׁבִילְךָ:",3,0],[15,16,"נִמְצְאוּ דְבָרֶיךָ וָאֹכְלֵם. לְתַאֲוָה מִתְּחִלָּה, וְהָיוּ לְשָׂשׂוֹן, כִּי דִּמִּיתִי שֶׁיִּשְׁמְעוּ אֵלַי עַתָּה:",1,0],[15,17,"מִפְּנֵי יָדְךָ. מִפְּנֵי נְבוּאָה הַבָּאָה לִי מֵאִתְּךָ:",1,0],[15,17,"יָשַׁבְתִּי. יְחִידִי וּמִשְׁתּוֹמֵם בַּאֲבֵילוּת, כִּי נְבוּאַת זַעַם מִלֵּאתָנִי, בְּחֻרְבַּן בֵּיתֶךָ:",2,0],[15,18,"אֲנוּשָׁה. חוֹלָה; כְּמוֹ ״וַיֵּאָנַשׁ״ (שמואל ב יב:טו) – וַיֶּחֱלֶה; בִּבְנָהּ שֶׁל בַּת שֶׁבַע:",1,0],[15,18,"הָיוֹ תִהְיֶה לִי. אַתָּה הוֹוֶה לִי כְּמוֹ אַכְזָב. כְּאָדָם שֶׁמִּבְטָחוֹ נִפְסָק מִמֶּנּוּ, שֶׁאַתָּה מַנִּיחֵנִי לְהִצְטַעֵר בְּיָדָם. אַכְזָב מָקוֹר פּוֹסֵק, פייליינ״ץ בְּלַעַז:",2,0],[15,18,"מַיִם לֹא נֶאֱמָנוּ. לִסְמֹךְ עֲלֵיהֶם:",3,0],[15,19,"לָכֵן. בַּעֲבוּר שֶׁאֲנִי סוֹבֵל הַצָּרוֹת הָאֵלֶּה:",1,0],[15,19,"כֹּה אָמַר ה׳. לִי:",2,0],[15,19,"אִם תָּשׁוּב. אַתָּה יִשְׂרָאֵל עַל יְדֵי וַאֲשִׁיבְךָ אֲנִי אֵלָיו, אָמַר לִי: לְפָנַי תַּעֲמֹד:",3,0],[15,19,"וְאִם תּוֹצִיא יָקָר מִזּוֹלֵל. אִם תּוֹצִיא אָדָם הָגוּן מֵאָדָם רָשָׁע, שֶׁתַּחֲזִירֶנּוּ לְמוּטָב:",4,0],[15,19,"כְּפִי תִהְיֶה. שֶׁאֲנִי גּוֹזֵר גְּזֵירָה וְאַתָּה מְבַטְּלָהּ (בבא מציעא פה.):",5,0],[15,19,"יָשׁוּבוּ הֵמָּה אֵלֶיךָ וְאַתָּה לֹא תָשׁוּב אֲלֵיהֶם. ״יְתוּבוּן אִינּוּן לְפִתְגָּמָךְ וְאַתְּ לָא תְּתוּב לְמִטְעֵי בַּתְרֵיהוֹן״ (תרגום יונתן):",6,0],[16,5,"בֵּית מַרְזֵחַ. מִשְׁתֶּה; בְּסִפְרֵי בְּפָרָשַׁת בֵּית פְּעוֹר(ספרי פיסקא קלא) רָאִיתִי: חָזְרוּ לַעֲשׂוֹת לָהֶם מַרְזֵיחִין; אֲבָל רַבּוֹתֵינוּ פֵּרְשׁוּ (כתובות סט:) מַרְזֵחַ – אֵבֶל:",1,0],[16,5,"תָּנֹד. תְּקוֹנֵן:",2,0],[16,5,"כִּי אָסַפְתִּי אֶת שְׁלוֹמִי וגו׳. כְּשֶׁהָיָה אַבְרָהָם אֲבִיהֶם עוֹשֶׂה צְדָקָה וּמִשְׁפָּט (בראשית יח:יט), נָתַתִּי לְזַרְעוֹ חֶסֶד וְרַחֲמִים: ״וְשָׁמַר ה׳ אֱלֹהֶיךָ לְךָ וגו׳״ (דברים ז:יב), ״וְנָתַן לְךָ רַחֲמִים״ (דברים יג:יח). הֵם הָפְכוּ לַלַּעֲנָה מִשְׁפָּט וּצְדָקָה לָאָרֶץ הִנִּיחוּ (עמוס ה:ז), אַף אֲנִי חָזַרְתִּי וְאָסַפְתִּי אֵלַי אֶת חַסְדִּי וְאֶת רַחֲמִי:",3,0],[16,5,"אָסַפְתִּי. אטואי״ש בְּלַעַ״ז, כְּמוֹ ״אָסַף אֱלֹהִים אֶת חֶרְפָּתִי״ (בראשית ל:כג):",4,0],[16,6,"וּמֵתוּ גְדוֹלִים וּקְטַנִּים. וְאַחַר שֶׁהַכֹּל מֵתִים, מַה לְּךָ לִסְפּוֹד?",1,0],[16,6,"וְלֹא יִתְגֹּדַד וְלֹא יִקָּרֵחַ לָהֶם. דֶּרֶךְ הָאֲבֵלִים לְהִתְגּוֹדֵד וְלִשְׂרֹט בְּשָׂרָם וְלִקְרוֹחַ קָרְחָה בְּרֹאשָׁם; וּמִכָּל מָקוֹם, לְיִשְׂרָאֵל אָסוּר (ויקרא יט:כח; דברים יד:א), וְלֹא הִזְכִּירוֹ כָּאן אֶלָּא לְדוּגְמַת אֵבֶל:",2,0],[16,7,"וְלֹא יִפְרְסוּ. לְשׁוֹן שְׁבִירָה, כְּמוֹ ״מְנֵא מְנֵא תְּקֵל וּפַרְסִין״ (דניאל ה:כה); שֶׁמַּבְרִין אֶת הָאֲבֵלִים בָּרְחָבָה וּפוֹרְסִין לָהֶם בִּרְכַּת הַמּוֹצִיא. ״כִּי הוּא יְבָרֵךְ הַזֶּבַח״ (שמואל א ט:יג) – תִּרְגֵּם יוֹנָתָן: ״אֲרֵי הוּא פָּרִיס עַל מְזוֹנָא״:",1,0],[16,7,"וְלֹא יַשְׁקוּ אוֹתָם וְגוֹ׳. הֲרֵי טַעַם לָמָּה שֶׁאָמַרְתִּי: אַל תֵּלֵךְ לִסְפּוֹד:",2,0],[16,8,"וּבֵית מִשְׁתֶּה. אֲשֶׁר אָמַרְתִּי לְךָ לְמַעְלָה לֹא תָבוֹא, זֶה הַטַּעַם: הִנְנִי מַשְׁבִּית מִן הַמָּקוֹם הַזֶּה וְגוֹ׳:",1,0],[16,13,"וַעֲבַדְתֶּם שָׁם אֶת אֱלֹהִים אֲחֵרִים. תִּרְגֵּם יוֹנָתָן: ״וְתִפְלְחוּן תַּמָּן לְעַמְמַיָּא פָּלְחֵי טָעֲוָותָא״:",1,0],[16,14,"לָכֵן. לְשׁוֹן שְׁבוּעָה, אַף עַל פִּי שֶׁבְּגַדְתֶּם בִּי, שְׁבוּעָה הִיא בְּיָדִי שֶׁאֶגְאוֹל אֶתְכֶם:",1,0],[16,14,"וְלֹא יֵאָמֵר עוֹד וגו׳. רַבּוֹתֵינוּ דָּרְשׁוּ (ברכות יב:) לֹא שֶׁתֵּעָקֵר יְצִיאַת מִצְרַיִם מִמְּקוֹמָהּ, אֶלָּא גְּאֻלָּה אַחֲרוֹנָה עִקָּר וִיצִיאַת מִצְרַיִם טָפֵל לָהּ:",2,0],[16,16,"וְדִיגוּם. מָה הַדַּיָּג שׁוֹלְהוּ מִתּוֹךְ מְקוֹם גִּדּוּלוֹ, אַף אֵלּוּ יִלְכְּדוּ אוֹתָם בְּתוֹךְ הָעִיר; וּמָה עִסְקוֹ שֶׁל דָּג, מִשֶּׁנִּלְכַּד הוּא מֵת, כָּךְ אָבִיא עֲלֵיהֶם הוֹרְגִים; וְאַחֲרֵי כֵן אֶשְׁלַח צַיָּדִים לַנִּשְׁאָרִים וְלַבּוֹרְחִים מִן הַחֶרֶב עַל הַהָרִים וְהַגְּבָעוֹת, וְצָדוּם – לְהַגְלוֹתָם בַּשֶּׁבִי:",1,0],[16,18,"מִשְׁנֵה עֲוֺנָם. אֶת שֶׁשָּׁנוּ עַל עֲוֹנָם לַעֲשׂוֹת עֲוֹנוֹת אֲבוֹתֵיהֶם; וְיוֹנָתָן תִּרְגֵּם כֵּן: ״וַאֲשִׁלֵּים לְתִנְיָינִין כְּקַדְמָאִין עַל חַד תְּרֵין״:",1,0],[16,19,"ה׳ עֻזִּי וּמָעֻזִּי וּמְנוּסִי. אַנְטִיפוֹיְימַאנְ״ט בְּלַעַ״ז, וּמְנַחֵם חִבְּרוֹ לְשׁוֹן פֶּלֶא, כְּמוֹ ״נָתַתָּ לִּירֵאֶיךָ נֵּס לְהִתְנוֹסֵס״ (תהלים ס:ו), וְכֵן ״ה׳ נִסִּי״ (שמות יז:טו). וְדוֹנָשׁ פָּתַר אוֹתוֹ לְשׁוֹן מָנוֹס מַמָּשׁ:",1,0],[16,19,"אֵלֶיךָ גּוֹיִם יָבֹאוּ. סוֹף הָאֻמּוֹת לָשׁוּב אֵלֶיךָ וּלְעָבְדְּךָ שְׁכֶם אֶחָד (צפניה ג:ט); וְעַמְּךָ, אֵיךְ עָשׂוּ לָהֶם אֱלֹהִים וְהֵמָּה לֹא אֱלֹהִים?!",2,0],[16,19,"מֵאַפְסֵי. כְּמוֹ ״מִקְּצֵה״ (ירמיה יב:יב):",3,0],[16,19,"נָחֲלוּ. לְשׁוֹן נַחֲלָה:",4,0],[16,19,"מוֹעִיל. לְשׁוֹן תּוֹעֶלֶת:",5,0],[16,21,"כִּי שְׁמִי ה׳. כְּמַשְׁמָעוֹ: מוֹשֵׁל וְשַׁלִּיט לְקַיֵּם גְּזֵרָתִי (ויקרא רבה כד, א):",1,0],[17,1,"בְּעֵט בַּרְזֶל. מָשָׁל הוּא, כְּלוֹמַר: חֲקוּקָה בְּשִׁקּוּעַ וְאֵין נוֹחָה לִמְחוֹק. וּמִדְרַשׁ אַגָּדָה בְּעֵט בַּרְזֶל בְּצִפֹּרֶן שָׁמִיר עַל יְדֵי יִרְמְיָה שֶׁנִּקְרָא עַמּוּד בַּרְזֶל, וְעַל יְדֵי יְחֶזְקֵאל שֶׁנֶּאֱמַר לוֹ״ כַּשָּׁמִיר חָזָק מִצּוּר נָתַתִּי מִצְחֶךָ״ (יחזקאל ג:ט):",1,0],[17,1,"חֲרוּשָׁה. חֲקוּקָה, כְּזֶה שֶׁהוּא חוֹרֵשׁ בָּעֹמֶק:",2,0],[17,1,"עַל לוּחַ לִבָּם. שֶׁאֵינָם שׁוֹכְחִין עֲבוֹדָה זָרָה שֶׁלָּהֶם:",3,0],[17,2,"כִּזְכֹּר בְּנֵיהֶם מִזְבְּחוֹתָם. כִּזְכִירַת בְּנֵיהֶם כֵּן הָיְתָה לָהֶם זְכִירַת מִזְבְּחוֹתָם; כְּאָדָם שֶׁיֵּשׁ לוֹ גִּעְגּוּעִין עַל בְּנוֹ (סנהדרין סג:):",1,0],[17,2,"וַאֲשֵׁרֵיהֶם. אֲשֶׁר עַל עֵץ רַעֲנָן. עַל עֵץ – כְּמוֹ אֵצֶל, וְכֵן תִּרְגֵּם יוֹנָתָן: ״תְּחוֹת כָּל אִילָן עֲבוּף״:",2,0],[17,3,"הֲרָרִי בַּשָּׂדֶה. יְרוּשָׁלַיִם הַיּוֹשֶׁבֶת בָּהָר הַמִּישׁוֹר (ירמיה כא:יג), כָּל סְבִיב הָעִיר מִישׁוֹר, שָׂדֶה. וְלָשׁוֹן הֲרָרִי – כְּמוֹ ״עֲרָבִי״ (ישעיה יג:כ), עַל שֵׁם שֶׁיּוֹשֵׁב בָּעֲרָבָה; מוֹנְטִינְיֵיר״שׁ בְּלַעַ״ז, יוֹשְׁבֵי הָהָר (ספרים ארחים יוֹשֶׁבֶת הָהָר):",1,0],[17,3,"חֵילְךָ. כְּמוֹ מָמוֹנְךָ (ראה דברים ח:יז):",2,0],[17,3,"בָּמוֹתֶיךָ בְּחַטָּאת. בָּמוֹתֶיךָ עֲשׂוּיוֹת בְּחֵטְא לְשֵׁם עֲבוֹדָה זָרָה בְּכָל גְּבוּלֶיךָ:",3,0],[17,4,"וְשָׁמַטְתָּה. עַל כָּרְחֲךָ תִּשְׁמַט אַרְצְךָ אֶת אֲשֶׁר לֹא שָׁבְתָה בְּשַׁבְּתוֹתֵיכֶם (ויקרא כו:לה), שֶׁאָמַרְתִּי לָכֶם ״וְשָׁבְתָה הָאָרֶץ״ (ויקרא כה:ב):",1,0],[17,4,"וּבְךָ. אֶנָּקֵם מֵחֲמַת נַחֲלָתְךָ אֲשֶׁר נָתַתִּי לָךְ שֶׁלֹּא עָשִׂיתָ רְצוֹנִי לְהַשְׁמִיטָהּ, דָּבָר אַחֵר: וּבְךָ מִנַּחֲלָתְךָ – וּבְךָ אֶנָּקֵם מִנַּחֲלָתְךָ, שֶׁאַגְלֶה אוֹתְךָ מִמֶּנָּה:",2,0],[17,4,"כִּי אֵשׁ קְדַחְתֶּם בְּאַפִּי. יְקַדְתֶּם בִּנְחִירַי:",3,0],[17,5,"אֲשֶׁר יִבְטַח בָּאָדָם. בַּחֲרִישׁוֹ וּקְצִירוֹ, לוֹמַר: אֶזְרַע בַּשְּׁבִיעִית וְאֹכַל:",1,0],[17,5,"זְרוֹעוֹ. כְּמוֹ עֶזְרוֹ, וְכֵן תִּרְגֵּם יוֹנָתָן: ״רוּחְצָנֵיהּ״:",2,0],[17,5,"וּמִן ה׳ יָסוּר לִבּוֹ. שֶׁהִבְטִיחוֹ: ״וְצִוִּיתִי אֶת בִּרְכָתִי לָכֶם״ (ויקרא כה:כא). כָּךְ שָׁמַעְתִּי:",3,0],[17,6,"כְּעַרְעָר. כְּעֵץ יְחִידִי; לְשׁוֹן ״עֲרִירִי״ (בראשית טו:ב). וְיֵשׁ אוֹמֵר: דְּגַאשְׁטִי״הּ בְּלַעַ״ז. וּמְנַחֵם פֵּירֵשׁ: שֵׁם עֵץ מֵעֲצֵי הַיַּעַר וְעַרְעָר שְׁמוֹ; וְכֵן פֵּירֵשׁ ״כְּעַרְעָר בַּמִּדְבָּר״ (ירמיה מח:ו): עֵץ אֶחָד מֵעֲצֵי הַיַּעַר:",1,0],[17,6,"בָּעֲרָבָה. לְשׁוֹן מִישׁוֹר:",2,0],[17,6,"חֲרֵרִים. יֹבֶשׁ, כְּמוֹ ״חָרָה מִנִּי חֹרֶב״ (איוב ל:ל):",3,0],[17,6,"אֶרֶץ מְלֵחָה. אֶרֶץ שֶׁהִיא מְלֵחָה וְלֹא תְהֵא מְיֻשֶּׁבֶת:",4,0],[17,8,"וְלֹא יִרְאֶה. הָעֵץ כִּי יָבֹא חֹם:",1,0],[17,8,"בַּצֹּרֶת. לְשׁוֹן רָעָב פאמצ״א בְּלַעַ״ז,.לָשׁוֹן אַחֵר: בַּצֹּרֶת לְשׁוֹן מִבְצָר, וְכֵן חִבְּרוֹ מְנַחֵם:",2,0],[17,8,"לֹא יִדְאָג. לֹא יִפְחַד:",3,0],[17,9,"עָקֹב הַלֵּב. מָלֵא תּוֹאֲנָה וַעֲקֻבָּה מִכֹּל רָעָה:",1,0],[17,9,"וְאָנוּשׁ. לְשׁוֹן חֹלִי, וְחָלְיוֹ הוּא זֶה:",2,0],[17,9,"מִי יֵדָעֶנּוּ. הוּא סָבוּר: מִי יֵדָעֶנּוּ. אֲנִי ה׳ חוֹקְרוֹ:",3,0],[17,11,"קוֹרֵא דָגַר. קוּקוּ״וּ גְלוּנְצְנְ״ט בְּלַעַ״ז:",1,0],[17,11,"וְלֹא יָלָד. הַקּוֹרֵא הַזֶּה מוֹשֵׁךְ אַחֲרָיו אֶפְרוֹחִים שֶׁלֹּא יָלָד. דָּגַר. צִפְצוּף שֶׁמְּצַפְצֵף הָעוֹף בְּקוֹלוֹ לִמְשׁוֹךְ אֶפְרוֹחִין אַחֲרָיו, וְאֵלּוּ שֶׁהַקּוֹרֵא דָּגַר לֹא יֵלְכוּ אַחֲרָיו מִשֶּׁיִּגְדְּלוּ שֶׁאֵינָם מִינוֹ, כָּךְ עֹשֶׂה עֹשֶׁר וְלֹא בְמִשְׁפָּט:",2,0],[17,11,"יִהְיֶה נָבָל. ״מִתְקְרֵי רְשִׁיעָא״ (תרגום יונתן):",3,0],[17,12,"כִּסֵּא כָבוֹד וגו׳. לְפִי שֶׁבָּא לוֹמַר כָּל עֹזְבֶיךָ יֵבֹשׁוּ, מַתְחִיל בְּקִלּוּסוֹ שֶׁל מָקוֹם וּמְדַבֵּר לְפָנָיו: אַתָּה, שֶׁכִּסֵּא כָבוֹד וּמָרוֹם מֵרֵאשִׁית בְּרִיאַת עוֹלָם וּמְכֻוָּן כְּנֶגֶד מִקְדָּשֵׁנוּ:",1,0],[17,13,"מִקְוֵה יִשְׂרָאֵל. ה׳ יוֹשֵׁב עָלָיו, לְפִיכָךְ כָּל עֹזְבֶיךָ יֵבֹשׁוּ:",1,0],[17,13,"וְסוּרַי בָּאָרֶץ יִכָּתֵבוּ. אוֹתָם שֶׁסָּרִים מִדְּבָרַי, שֶׁאֵינָם שׁוֹמְעִים שְׁלִיחוּתִי, בְּקִבְרוֹת תַּחְתִּיּוֹת אֶרֶץ יִכָּתֵבוּ:",2,0],[17,14,"כִּי תְהִלָּתִי אָתָּה. בְּךָ אֲנִי מִתְהַלֵּל וּמִתְפָּאֵר לוֹמַר שֶׁאַתָּה מוֹשִׁיעִי:",1,0],[17,14,"תְּהִלָּתִי. וונטנצ״א בְּלַעַ״ז:",2,0],[17,15,"אַיֵּה דְּבַר ה׳. הַפּוּרְעָנִיּוֹת שֶׁאַתָּה מִתְנַבֵּא:",1,0],[17,16,"וַאֲנִי לֹא אַצְתִּי. לֹא מִהַרְתִּי לְזָרֶזְךָ לַהֲבִיאָם, מִהְיוֹת רֹעֶה טוֹב מְחַזֵּר אַחֲרֶיךָ לְבַקֵּשׁ עֲלֵיהֶם רַחֲמִים:",1,0],[17,16,"וְיוֹם אָנוּשׁ. חֹלִי שֶׁל פֻּרְעָנוּת לֹא הִתְאַוֵּיתִי. וְיוֹנָתָן תִּרְגֵּם: ״וַאֲנָא לָא עַנְבִּית עַל מֵימְרָךְ מִלְּהִתְנַבָּאָה עֲלֵיהוֹן לַאֲתָבוּתְהוֹן לְדַחַלְתָּךְ״. וּלְפִי הַתַּרְגּוּם יִהְיֶה אַצְתִּי – לְשׁוֹן עִכּוּב, כְּלוֹמַר: לֹא עִכַּבְתִּי מִלּוֹמַר לָהֶם שְׁלִיחוּתֶיךָ וּלְהָשִׁיבָם אֵלֶיךָ, אִם הָיוּ שׁוֹמְעִים אֵלַי:",2,0],[17,16,"מוֹצָא שְׂפָתַי נֹכַח פָּנֶיךָ הָיָה. לְהָשִׁיב אֶת חֲמָתְךָ מֵהֶם:",3,0],[17,17,"אַל תִּהְיֵה לִי לִמְחִתָּה. אַל יְהִי שְׁלִיחוּתְךָ לִמְחִתָּה:",1,0],[17,18,"יֵבֹשׁוּ רֹדְפַי. אַנְשֵׁי עֲנָתוֹת לְבַדָּם:",1,0],[17,23,"וְלֹא שָׁמְעוּ. אֲבוֹתֵיכֶם לְמַה שֶּׁצִּוִּיתִים:",1,0],[17,27,"וּבֹא. כְּמוֹ וְלָבֹא:",1,0],[18,3,"עַל הָאׇבְנָיִם. ״עַל סַדְנָא״ (תרגום יונתן). פורמ״ש בְּלַעַ״ז:",1,0],[18,4,"אֲשֶׁר הוּא עוֹשֶׂה בַּחֹמֶר. אֲשֶׁר הוּא עוֹשֶׂה מִן הַחֹמֶר נִשְׁחַת בְּיַד הַיּוֹצֵר, בְּעוֹדוֹ לַח; וּמִקְרָא מְסֹרָס הוּא:",1,0],[18,8,"מֵרָעָתוֹ אֲשֶׁר דִּבַּרְתִּי עָלָיו. מֵעֲבֵירוֹת שֶׁבְּיָדוֹ, אֲשֶׁר בִּשְׁבִילוֹ דִּבַּרְתִּי עָלָיו ״לִנְתוֹשׁ וְלִנְתוֹץ״ (ירמיה א:י), אִירְפוֹרְקִ״י בְּלַעַ״ז:",1,0],[18,8,"וְנִחַמְתִּי. וְחָשַׁבְתִּי מַחֲשָׁבָה אַחֶרֶת:",2,0],[18,12,"וְאָמְרוּ נוֹאָשׁ. וְיָדַעְתִּי שֶׁהֵם יֹאמְרוּ לְךָ עַל דְּבָרֶיךָ, שֶׁאֵין חוֹשְׁשִׁין לָהֶם:",1,0],[18,13,"שַׁעֲרֻרִת. דְּבָר גְּנַאי:",1,0],[18,14,"הֲיַעֲזֹב מִצּוּר שָׂדַי שֶׁלֶג לְבָנוֹן. הֲיַעֲזֹב אָדָם הַצָּרִיךְ לִשְׁתּוֹת מַיִם הַנּוֹזְלִים מִצּוּר שֶׁבַּשָּׂדוֹת, הַבָּאִים מִשֶּׁלֶג הַלְּבָנוֹן שֶׁהוּא נָקִי?!",1,0],[18,14,"אִם יִנָּתְשׁוּ מַיִם זָרִים. אוֹ אִם יַעַזְבוּ מַיִם חַיִּים נוֹבְעִים, שֶׁהֵם זָרִים עַד הֵנָּה מִכָּל אָדָם, וְהֵם קָרִים. זָרִים הֵם נוֹבְעִים, וְזֶה יוֹכִיחַ: ״אֲנִי קַרְתִּי וְשָׁתִיתִי מַיִם זָרִים״ (מלכים ב יט:כד). וּמְנַחֵם חִבְּרוֹ זָרִים עִם ״לֹא זֹרוּ וְלֹא חֻבָּשׁוּ״ (ישעיהו א:ו) – לְשׁוֹן מֵימֵי תְרוּפָה. וְנָתַן טַעַם לִדְבָרָיו וְאָמַר, כִּי אִם בִּקֵּשׁ לְדַבֵּר בִּלְשׁוֹן זֶרֶם, הָיָה מַכְפִּיל אֶת הַמֵּ״ם וְהָיָה מוֹסִיף יוֹ״ד מֵ״ם, וְהָיָה אוֹמֵר זְרוּמִים, לְרַבּוֹת הַמַּיִם וְלִהְיוֹתָם זְרָמִים:",2,0],[18,14,"שָׂדַי. כְּמוֹ שָׂדֶה:",3,0],[18,14,"קָרִים. פְּרִיוְודָ״שׁ בְּלַעַ״ז:",4,0],[18,14,"נוֹזְלִים. קוֹרַאנְ״ץ בְּלַעַ״ז. וְעוֹד יֵשׁ לְפָתְרוֹ: אִם יִנָּתְשׁוּ לִהְיוֹת מַיִם זָרִים נִמְאָסִים, הַמַּיִם שֶׁהֵם קָרִים נוֹזְלִים:",5,0],[18,14,"(זָרִים לְלָשׁוֹן רִאשׁוֹן הוּא לְשׁוֹן זֶרֶם; לְלָשׁוֹן שֵׁנִי הוּא לָשׁוֹן זָרוֹת, כְּלוֹמַר מַיִם מְאוּסִים):",6,0],[18,15,"כִּי. כֵּן עָשׂוּ עַמִּי אֲשֶׁר שְׁכֵחֻנִי וְלַשָּׁוְא יְקַטֵּרוּ:",1,0],[18,15,"שְׁבִילֵי עוֹלָם. שְׁבִילִים הַמְתֻקָּנִים אָמְרוּ שֶׁהֵם מִכְשׁוֹל, כְּדֵי לָלֶכֶת דֶּרֶךְ לֹא סְלוּלָה לֹא כְבוּשָׁה:",2,0],[18,16,"שְׁרִיקוֹת. הָעוֹבֵר עַל חֳרָבוֹת שֶׁרָאָה כְּבָר בְּבִנְיָנָם, טוֹבִים, רָגִיל לִשְׁרֹק:",1,0],[18,16,"יִשּׁוֹם. יִתְמַהּ:",2,0],[18,17,"עֹרֶף וְלֹא פָנִים. כְּשֶׁיִּבְרְחוּ מִפְּנֵי הָאוֹיֵב:",1,0],[18,17,"אֶרְאֵם. וְלֹא אוֹשִׁיעֵם:",2,0],[18,18,"וַיֹּאמְרוּ לְכוּ וְגוֹ׳. יִרְמְיָה הָיָה קוֹבֵל עַל אַנְשֵׁי עֲנָתוֹת וְאוֹמֵר שֶׁאוֹמְרִים כֵּן:",1,0],[18,18,"תּוֹרָה מִכֹּהֵן. שֶׁעַל הַכֹּהֲנִים לְהוֹרוֹת תּוֹרָה, שֶׁנֶּאֱמַר ״יוֹרוּ מִשְׁפָּטֶיךָ לְיַעֲקֹב״ (דברים לג:י):",2,0],[18,18,"וְדָבָר מִנָּבִיא. דִּבְרֵי נְבוּאָה:",3,0],[18,18,"וְנַכֵּהוּ בַלָּשׁוֹן. ״וּנְסַהֲדִינֵיהּ סַהֲדוּתָא דְּשִׁקְרָא״ (תרגום יונתן):",4,0],[18,21,"וְהַגִּרֵם. (הוֹרִידֵם עַל יְדֵי חֶרֶב) לְשׁוֹן ״עֵינִי נִגְּרָה״ (איכה ג:מט), ״כַּמַּיִם הַמּוּגָרִים״ (מיכה א:ד):",1,0],[18,21,"עַל יְדֵי חֶרֶב. עַל יְדֵי גְּיָסוֹת:",2,0],[18,21,"וְאַנְשֵׁיהֶם. שֶׁל הָאַלְמָנוֹת, יִהְיוּ הֲרֻגֵי מַלְאַךְ הַמָּוֶת:",3,0],[18,22,"כִּי כָרוּ שׁוּחָה. שֶׁחֲשָׁדוּהוּ מֵאֵשֶׁת אִישׁ, שֶׁנֶּאֱמַר ״כִּי שׁוּחָה עֲמֻקָּה זוֹנָה״ (משלי כג:כז):",1,0],[18,23,"אַל תֶּמְחִי. אַל תְּהִי מְחוּיָה. וּלְפִי שֶׁהוּא לְשׁוֹן נְקֵבָה נָתַן בּוֹ יוֹ״ד, וְאַף הִיא יְתֵרָה, כְּיוֹ״ד שֶׁל ״וַתִּזְנִי בָם״ (יחזקאל טז:יז):",1,0],[19,1,"בַּקְבּוּק. צְלוֹחִית:",1,0],[19,1,"יוֹצֵר חָרֶשׂ. כְּלוֹמַר: שֶׁל יוֹצֵר, שֶׁהוּא שֶׁל חָרֶשׂ:",2,0],[19,1,"וּמִזִּקְנֵי הָעָם. הָלוֹךְ עִמָּךְ; וּמִזִּקְנֵי הָעָם מוּסָב עַל הָלוֹךְ :וּמִזִּקְנֵי הָעָם עִמָּךְ:",3,0],[19,2,"שַׁעַר הַחַרְסִית. שַׁעַר הָאַשְׁפּוֹת (נחמיה ב:יג), שֶׁשָּׁם זוֹרְקִין חֲרָסִים הַנִּשְׁבָּרִים; וְכֵן תִּרְגְּמוֹ יוֹנָתָן: ״תְּרַע קִילְקִלְתָּא״:",1,0],[19,3,"תִּצַּלְנָה. טִינְטִינִי״ר בְּלַעַ״ז; לְשׁוֹן ״מְצִלְתַּיִם״ (נחמיה יב:כז); ״בְּצִלְצְלֵי שָׁמַע״ (תהלים קנ:ה):",1,0],[19,4,"וַיְנַכְּרוּ. עֲשָׂאוּהוּ נָכְרִי לְפָנַי:",1,0],[19,7,"וּבַקּוֹתִי. וְרוֹקַנְתִּי, לְשׁוֹן ״בּוּקָה וּמְבוּקָה״ (נחום ב:יא). וְעַל שֵׁם בַּקְבּוּק שֶׁהוּא מְדַבֵּר בּוֹ, לָקַח לְשׁוֹנוֹ כֵּן:",1,0],[19,9,"וּבְמָצוֹק. לְשׁוֹן צָרָה, כְּמוֹ ״צוּקָה״ (ישעיה ל:ו):",1,0],[19,11,"(אֲשֶׁר לֹא יוּכַל לְהֵרָפֵה. אַהָעָם קָאֵי, אֲבָל הָעִיר אֶעֱשֶׂה כְּתֹפֶת וַאֲטַהֵר לֶעָתִיד):",1,0],[19,12,"הָעִיר הַזֹּאת כְּתֹפֶת. כֻּלָּהּ מְלֵאָה הֲרוּגִים, כְּמוֹ הַתֹּפֶת שֶׁהוֹרְגִין שָׁם אֶת הַיְלָדִים לַמֹּלֶךְ (מלכים ב כג:י):",1,0],[20,2,"הַמַּהְפֶּכֶת. שֵׁם מְקוֹם הָאֲסוּרִים, וְיוֹנָתָן תִּרְגֵּם: ״לְכִיפְתָּא״, אַרְוְלוֹ״ר בְּלַעַ״ז:",1,0],[20,3,"מָגוֹר. יִרְאָה:",1,0],[20,3,"לֹא פַשְׁחוּר קָרָא ה׳ שְׁמֶךָ וגו׳. לֹא נִקְרָא שִׁמְךָ פַּשְׁחוּר אֶלָּא בִּשְׁבִיל דָּבָר זֶה. כְּלוֹמַר פָּשַׁח שָׁחוֹר כְּמוֹ אִילָן שֶׁנִּפְשַׁח (משנה שביעית ד, ו), וְכֵן ״וַיְפַשְּׁחֵנִי״ (איכה ג, יא), וְכֵן אָמַר לוֹ לֹא פַשְׁחוּר קָרָא שְׁמֶךָ שֶׁלְּשׁוֹן פַּשְׁחוּר מַשְׁמַע אָדָם גָּדוֹל וּבֶן חוֹרִין, פָּשׁ חוּר, אֶלָּא לְכָךְ נִקְרָא שִׁמְךָ פַּשְׁחוּר – פָּשַׁח שָׁחוֹר. דָּבָר אַחֵר: פָּשׁ סְחוֹר, רַבִּים סְבִיבוֹתֶיךָ לַהֲרֹג, וְלַלָּשׁוֹן זֶה מָגוֹר הוּא לְשׁוֹן אֲסִיפָה, כְּמוֹ ״מְגוּרֵי אֶל חָרֶב״ (יחזקאל כא:יז):",2,0],[20,5,"חֹסֶן. מָמוֹן:",1,0],[20,7,"פִּתִּיתַנִי. לָלֶכֶת בִּשְׁלִיחוּתְךָ:",1,0],[20,7,"חֲזַקְתַּנִי. הִכְבַּדְתָּ עָלַי יָדְךָ הַחֲזָקָה, לָלֶכֶת עַל כָּרְחִי:",2,0],[20,7,"וַתּוּכָל. וְנִצַּחְתָּ:",3,0],[20,7,"כֻּלֹּה. כָּל הָעָם לֹעֵג לִי:",4,0],[20,8,"מִדֵּי אֲדַבֵּר. בְּכָל עֵת שֶׁאֲדַבֵּר אֲלֵיהֶם, אֲנִי צָרִיךְ לִזְעֹק וּלְהָרִים קוֹל; וְאֵינִי קוֹרֵא אֲלֵיהֶם טוֹבָה כִּי אִם נְבוּאוֹת חָמָס וָשֹׁד:",1,0],[20,8,"כִּי הָיָה דְבַר ה׳ לִי. לְפִיכָךְ דִּבְּרוּ לִי חֶרְפָּה, שֶׁהֵם מְחָרְפִים אוֹתִי:",2,0],[20,8,"וּלְקֶלֶס. וּלְדִבּוּר, כְּמוֹ ״וְקַלָּסָה״ (יחזקאל כב:ד):",3,0],[20,9,"וְאָמַרְתִּי לֹא אֶזְכְּרֶנּוּ. וְאִם אָמַר לִי לִבִּי שֶׁלֹּא לֵילֵךְ בִּשְׁלִיחוּתוֹ עוֹד:",1,0],[20,9,"וְהָיָה בְלִבִּי. הַנְּבוּאָה כְּאֵשׁ בֹּעֶרֶת, וְעַל כָּרְחִי אֲנִי צָרִיךְ לֵילֵךְ:",2,0],[20,9,"עָצוּר בְּעַצְמוֹתָי. וְכָנוּס בְּעַצְמוֹתַי הָאֵשׁ:",3,0],[20,9,"כַּלְכֵּל. לִסְבּוֹל הָאֵשׁ:",4,0],[20,10,"כִּי שָׁמַעְתִּי. אֲנִי אָמַרְתִּי שֶׁלֹּא אֶזְכְּרֶנּוּ לְפִי שֶׁשָּׁמַעְתִּי דִּבַּת רַבִּים, אֵלּוּ שֶׁמִּתְלַחֲשִׁים עָלַי:",1,0],[20,10,"מָגוֹר. לְשׁוֹן אֲסִיפָה, וְכֵן תִּרְגֵּם יוֹנָתָן:",2,0],[20,10,"הַגִּידוּ. עָלָיו עֵדוּת שֶׁקֶר:",3,0],[20,10,"וְנַגִּידֶנּוּ. וְנָעִידֶנּוּ. וּמְנַחֵם פֵּירֵשׁ הַגִּידוּ וְנַגִּידֶנּוּ כְּמוֹ ״לֹא תִתְגּוֹדְדוּ״ (דברים יד:א), וְכֵן חִבֵּר ״לְחֵלֶק יַגִּיד רֵעִים״ (איוב יז:ה) לְשׁוֹן הַשְׁחָתָה, כְּמוֹ ״גֹּדּוּ אִילָנָא״ (דניאל ד:יא). וְדוּנָשׁ פָּתַר אוֹתוֹ לְשׁוֹן הַגָּדָה מַמָּשׁ, וְכֹה פִּתְרוֹנוֹ: הַגִּידוּ עָלָיו דִּבְרֵי שֶׁקֶר וְנַגִּידֶנּוּ לַמֶּלֶךְ. וְיֵשׁ לָנוּ כְּמוֹ נַגִּידֶנּוּ דְּבָרִים רַבִּים בַּמִּקְרָא, אֲשֶׁר לֹא יִכּוֹן פִּתְרוֹנוֹ כִּי אִם עַד אֲשֶׁר יְחַלְּקוּן לִשְׁתֵּי תֵיבוֹת אוֹ לְשָׁלֹשׁ, כְּמוֹ ״וְלֹא יָכְלוּ דַּבְּרוֹ לְשָׁלוֹם״ (בראשית לז:ד); ״בָּנַי יְצָאֻנִי״ (ירמיה י:כ):",4,0],[20,10,"שׁוֹמְרֵי צַלְעִי. מְצַפִּים שִׁבְרִי:",5,0],[20,10,"אוּלַי יְפֻתֶּה. לִשְׁמֹעַ לָנוּ וְלִטְעוֹת אַחֲרֵינוּ:",6,0],[20,11,"כִּי לֹא הִשְׂכִּילוּ. לֹא הִצְלִיחוּ בַּעֲצָתָם:",1,0],[20,14,"אָרוּר הַיּוֹם אֲשֶׁר יֻלַּדְתִּי בּוֹ. פוא״י אינייניר״ט בְּלַעַ״ז, הִיא שְׁעַת הֵרָיוֹן. וְעַל יְדֵי אֹנֶס שִׁמֵּשׁ חִלְקִיָּהוּ אָבִיו מִטָּתוֹ בַּיּוֹם, שֶׁהָיָה בּוֹרֵחַ מִפְּנֵי מְנַשֶּׁה שֶׁהָיָה הוֹרֵג אֶת הַנְּבִיאִים; וְשִׁמֵּשׁ מִטָּתוֹ וּבָרַח (בראשית רבה סד, ה):",1,0],[20,15,"שַׂמֵּחַ. מ״ם דְּגוּשָׁה, שֶׁהוּא לְשׁוֹן תְּשַׂמַּח אֲחֵרִים; שֶׁשִּׂמַּח אֶת אָבִיו בִּבְשׂוֹרָתוֹ:",1,0],[20,16,"כֶּעָרִים אֲשֶׁר הָפַךְ. סְדוֹם וַעֲמוֹרָה (בראשית יט:כד-כה):",1,0],[20,16,"וְלֹא נִחָם. מִשֶּׁגָּזַר עֲלֵיהֶם חוּרְבָּן, לֹא חָשַׁב מַחֲשָׁבָה אַחֶרֶת לְבַטֵּל גְּזֵרָתוֹ (בראשית יח:כ-לב):",2,0],[20,17,"אֲשֶׁר לֹא מוֹתְתַנִי מַלְאַךְ הַמָּוֶת מֵרָחֶם. וַהֲרֵי זֶה מִן הַמִּקְרָאוֹת קִצְרֵי דִּבּוּר:",1,0],[20,17,"הֲרַת עוֹלָם. הֵרָיוֹן שֶׁל עוֹלָמִית:",2,0],[20,18,"עָמָל וְיָגוֹן. חֻרְבַּן בֵּית הַמִּקְדָּשׁ:",1,0],[21,4,"הִנְנִי מֵסֵב אֶת כְּלֵי הַמִּלְחָמָה. יֵשׁ בָּכֶם הַיּוֹדְעִים לְהַשְׁבִּיעַ אֶת הַשָּׂרִים שֶׁל מַעְלָה הַמְמֻנִּים עַל הַפֻּרְעָנִיּוֹת, לְהַצִּיל אִישׁ אִישׁ מִן הָרָעָה שֶׁהוּא מְמֻנֶּה עָלֶיהָ, וּבְכָךְ אַתֶּם בּוֹטְחִים; הִנְנִי מֵסֵב אֶת הַשְּׂרָרָה שֶׁל זֶה לָזֶה, וְלֹא תֵדְעוּ עַל מִי תַּשְׁבִּיעוּ:",1,0],[21,4,"וְאָסַפְתִּי אוֹתָם. כְּלֵי מִלְחָמָה אֶל תּוֹךְ הָעִיר הַזֹּאת, שֶׁאַשְׁחִית אֶתְכֶם בְּדֶבֶר עַל יְדֵי מַלְאַךְ הַמָּוֶת, שֶׁהוּא מִן הַשָּׂרִים הָעֶלְיוֹנִים; וְכֵן מְפֹרָשׁ בָּעִנְיָן: בְּדֶבֶר גָּדוֹל יָמוּתוּ:",2,0],[21,9,"וְהָיְתָה לוֹ נַפְשׁוֹ לְשָׁלָל. כְּאָדָם הַשּׁוֹלֵל שָׁלָל וְחוֹטְפוֹ וְהוֹלֵךְ לוֹ, כֵּן תִּהְיֶה לוֹ נַפְשׁוֹ שְׁלוּלָה מִן הַמִּיתָה, מִן הַהוֹרְגִים:",1,0],[21,10,"פָּנַי. כְּתַרְגּוּמוֹ: ״רוּגְזִי״:",1,0],[21,12,"מִיַּד עוֹשֵׁק. טַעֲמוֹ לְמַטָּה, שֶׁאֵינוֹ שֵׁם דָּבָר אֶלָּא שֵׁם הַגַּזְלָן הָעוֹשֵׁק אֶת אֲחֵרִים:",1,0],[21,12,"וְאֵין מְכַבֶּה. שֶׁלֹּא יִמָּלֵט לָכֶם שָׂרִיד:",2,0],[21,13,"יוֹשֶׁבֶת הָעֵמֶק. יְרוּשָׁלַיִם הִיא בְּתוֹךְ עֵמֶק. דָּבָר אַחֵר: שֶׁהֶעֱמִיק הַקָּדוֹשׁ בָּרוּךְ הוּא עֵצָה עָלֶיךָ לְהַחֲרִיבֶךָ:",1,0],[21,13,"צוּר הַמִּישׁוֹר. הַר שֶׁכָּל סְבִיבָיו מִישׁוֹר:",2,0],[21,13,"מִי יֵחַת עָלֵינוּ. מִי יַחֲנֶה עָלֵינוּ, כְּמוֹ ״כִּי שָׁם אֲרָם נְחִתִּים״ (מלכים ב ו:ט):",3,0],[22,3,"אַל תּוֹנוּ. זוֹ אוֹנָאַת דְּבָרִים (תורת כהנים בהר פרשתא ג, ד):",1,0],[22,6,"גִּלְעָד אַתָּה לִי וגו׳. ״אִלּוּ אַתְּ חֲבִיב קֳדָמַי כְּבֵית מַקְדְּשָׁא דְּרָם בְּרֵישׁ טוּרַיָּא, אִם לֹא אֲשַׁוִּינָךְ מִדְבְּרָא״ (תרגום יונתן):",1,0],[22,6,"גִּלְעָד אַתָּה. הַמִּקְדָּשׁ (מכילתא בשלח עמלק ב), שֶׁמִּמֶּנּוּ צֳרִי וּרְפוּאָה לְכָל הָעוֹלָם (פסיקתא רבתי לג):",2,0],[22,7,"וְקִדַּשְׁתִּי. וְזִמַּנְתִּי:",1,0],[22,7,"וְכָרְתוּ מִבְחַר אֲרָזֶיךָ. לְפִי שֶׁדִּמָּהוּ לַלְּבָנוֹן, נוֹפֵל כָּאן הַלָּשׁוֹן הַזֶּה:",2,0],[22,10,"אַל תִּבְכּוּ לַמֵּת. לִיהוֹיָקִים, שֶׁיָּמוּת לִפְנֵי הַשַּׁעַר כְּשֶׁיִּסְחָבוּהוּ לְהַגְלוֹתוֹ (ירמיה כב:יט):",1,0],[22,10,"בְּכוּ לַהֹלֵךְ. לִיהוֹיָכִין וְלִצִדְקִיָּהוּ. אֱמוֹר מֵעַתָּה: חֲבִיבָה מִיתָתוֹ שֶׁל יְהוֹיָקִים, שֶׁנֶּאֱמַר בּוֹ ״וְנִבְלָתוֹ תִּהְיֶה מֻשְׁלֶכֶת לַחֹרֶב בַּיּוֹם וְלַקֶּרַח בַּלָּיְלָה״ (ירמיה לו:ל), מֵחַיָּיו שֶׁל יְהוֹיָכִין, שֶׁנֶּאֱמַר בּוֹ ״וַאֲרֻחָתוֹ אֲרֻחַת תָּמִיד וְגוֹ׳״ (ירמיה נב:לד):",2,0],[22,11,"אֶל שַׁלּוּם. הוּא צִדְקִיָּהוּ, וְכָךְ נִקְרָא ״וְהָרְבִיעִי שַׁלּוּם״ (דברי הימים א ג:טו). וְקְרָאוֹ רְבִיעִי לַמַּלְכוּת בִּבְנֵי יֹאשִׁיָּהוּ, שֶׁבַּתְּחִלָּה מָלַךְ יְהוֹאָחָז וְאַחַר כָּךְ יְהוֹיָקִים וְאַחֲרָיו יְהוֹיָכִין וְאַחֲרָיו צִדְקִיָּהוּ (מלכים ב כג-כה; הוריות יא:):",1,0],[22,11,"אֲשֶׁר יָצָא. וְאַף עַל פִּי שֶׁלֹּא יָצָא עֲדַיִן, מִתְנַבֵּא עָלָיו כְּאִלּוּ יָצָא:",2,0],[22,13,"הוֹי בּוֹנֶה בֵיתוֹ. עַל יְהוֹיָקִים הוּא אוֹמֵר, שֶׁהוּא הָיָה רָשָׁע. וְסוֹף הָעִנְיָן מוֹכִיחַ: לָכֵן כֹּה אָמַר ה׳ אֶל יְהוֹיָקִים וְגוֹ׳:",1,0],[22,14,"בֵּית מִדּוֹת. בַּיִת גָּדוֹל, כְּמוֹ ״אַנְשֵׁי מִדּוֹת״ (במדבר יג:לב) שֶׁיֵּשׁ בָּהֶן מַה לִמְדֹּד:",1,0],[22,14,"וְקָרַע לוֹ. וְהִרְחִיב לוֹ. אֲחֵרִים הִגִּיהוּ וְקָרַע לוֹ וּפָתַח לוֹ, וְכֵן ״וַתִּקְרְעִי בַּפּוּךְ״ (ירמיה ד:ל), ״קָרַעְתָּ שָׁמַיִם יָרַדְתָּ״ (ישעיהו סג:יט) – כֻּלָּן לְשׁוֹן פְּתִיחָה:",2,0],[22,14,"וְסָפוּן בָּאָרֶז. מְסַכֵּךְ הַגַּג בַּאֲרָזִים:",3,0],[22,14,"וּמָשׁוֹחַ בַּשָּׁשַׁר. ״וּמְצֻיָּר בְּסַמְמָנִים״, תִּרְגֵּם יוֹנָתָן. בַּשָּׁשַׁר צֶבַע הוּא מִמִּין הַצִּיּוּרִים. לָשׁוֹן אַחֵר: וּמָשׁוֹחַ בַּשָּׁשַׁר כְּמוֹ חוּט הַמִּשְׁחָה (כלים יז,יג) אֵיינַאנְ״ט אַנְשִׁינוֹפְלָ״א בְּלַעַז:",4,0],[22,15,"הֲתִמְלֹךְ. הַתַּאֲרִיךְ יָמִים עַל שֶׁאַתָּה מְתַחֲרֶה לְהַכְבִּיד עַל מֶמְשַׁלְתְּךָ לְהוֹדִיעַ שֶׁאַתָּה מֶלֶךְ?!",1,0],[22,15,"אָבִיךָ. יֹאשִׁיָּהוּ, שֶׁהִתְנַהֵג בַּעֲנָוָה, הֲלוֹא אָכַל וְשָׁתָה וְרָאָה טוֹב כָּל יְמֵי חַיָּיו:",2,0],[22,17,"עַל בִּצְעֶךָ. לִגְזֹל מָמוֹן:",1,0],[22,17,"הַמְּרוּצָה. רִצּוּץ דַּלִּים; וְעֹשֶׁק יוֹכִיחַ עָלָיו, כִּי עָשׁוּק וְרָצוּץ תָּמִיד סְמוּכִין בִּלְשׁוֹן מִקְרָא (דברים כח:לג; עמוס ד:א), וְכֵן ״אֶת מִי עָשַׁקְתִּי וְאֶת מִי רַצּוֹתִי״ (שמואל א יב:ג):",2,0],[22,18,"וְהוֹי הֹדֹה. הוֹי עַל תִּפְאַרְתּוֹ:",1,0],[22,19,"קְבוּרַת חֲמוֹר יִקָּבֵר. ״כְּמָה דִמְשַׁגְּרִין יָת נִבְלַת חֲמָרָא כֵּן יְשַׁגְּרוּן יָת נְבִילְתֵיהּ״ (תרגום יונתן). יְשַׁגְּרוּן – יִסְחֲבוּן:",1,0],[22,20,"עֲלִי הַלְּבָנוֹן וּצְעָקִי. ״סַקִי לְבֵית מַקְדְּשָׁא וְצַוְּחִי״ (תרגום יונתן):",1,0],[22,20,"וּבַבָּשָׁן תְּנִי קוֹלֵךְ. עַל הַבָּשָׁן שֶׁיֶּחֱרַב. וְיוֹנָתָן תִּרְגֵּם: ״וּבְתַרְעֵי טוּר בֵּיתָא״; וְאֵינִי יוֹדֵעַ לְפָרֵשׁ הָאֵיךְ נוֹפֵל לְשׁוֹן בָּשָׁן בְּשַׁעֲרֵי הַר הַבַּיִת, אִם לֹא בִּשְׁבִיל הַדְּלָתוֹת שֶׁעוֹשִׂין מֵאַלּוֹנֵי הַבָּשָׁן, וְהוּא שֵׁם מָקוֹם. אוֹ לְשׁוֹן בָּשָׁן – מְקוֹם בִּקְעָה רְחָבָה, כֵּן הֶקֵּף הַר הַבַּיִת מִגְרָשׁ רֶוַח לְבֵית הַמִּקְדָּשׁ:",2,0],[22,20,"וְצַעֲקִי מֵעֲבָרִים. ״וְצַוְּחִי עַל מְגִיזָתָא״ (תרגום יונתן), וְהֵם לְשׁוֹן מָקוֹם:",3,0],[22,21,"בְּשַׁלְוֺתַיִךְ. כְּשֶׁהָיִיתָ בְּשַׁלְוָה:",1,0],[22,22,"כָּל רֹעַיִךְ. כָּל מְלָכַיִךְ:",1,0],[22,22,"תִּרְעֶה רוּחַ. רוּחַ קָדִים תְּרוֹצְצֵם:",2,0],[22,23,"מְקֻנַּנְתְּ בָּאֲרָזִים. שֶׁשַּׂמְתְּ קִנֵּךְ בְּמִגְדְּלוֹת בָּתֵּי אֲרָזִים, לִבְנוֹת בָּתֵּי מִדּוֹת:",1,0],[22,23,"מַה נֵּחַנְתְּ. מַה מָּצָאת חֵן בִּשְׁבִיל גֹּבַהּ מִגְדָּלַיִךְ בְּעֵינֵי שׁוֹדְדַיִךְ, בְּבֹא לָךְ חֲבָלִים שֶׁל לֵידָה. וּמְנַחֵם פָּתַר נֵּחַנְתְּ לְשׁוֹן חֲנִיָּה; אֲבָל דּוּנַשׁ פָּתַר אוֹתוֹ לְשׁוֹן חֵן:",2,0],[22,24,"חוֹתָם עַל יַד יְמִינִי. חָקוּק וְחָתוּם בְּתוֹךְ בְּשַׂר זְרוֹעִי:",1,0],[22,24,"אֶתְּקֶנְךָּ. אֶנְתְּקֶךָ, לְשׁוֹן ״הַתִּיקֵם כַּצֹּאן לְטִבְחָה״ (ירמיה יב:ג); ״עַד הִתִּיקוּנוֹ אוֹתָם״ (יהושע ח:ו); וְהַנּוּ״ן יְתֵרָה בּוֹ. וּמִדְרַשׁ אַגָּדָה (פסיקתא דרב כהנא כד:יא): בִּמְקוֹם שֶׁנִּתַּק – נִתְקַן; שֶׁעָשָׂה תְּשׁוּבָה בְּבָבֶל, וְנִשְׁאַל הַקָּדוֹשׁ בָּרוּךְ הוּא עַל שֶׁנִּשְׁבַּע כִּתְבוּ אֶת הָאִישׁ הַזֶּה עֲרִירִי, וְנוֹלַד לוֹ זְרֻבָּבֶל בְּבָבֶל, וְנֶאֱמַר לוֹ עַל פִּי הַנָּבִיא: ״בַּיּוֹם הַהוּא אֶקָּחֲךָ זְרֻבָּבֶל בֶּן שְׁאַלְתִּיאֵל עַבְדִּי וְשַׂמְתִּיךָ כַּחוֹתָם״ (חגי ב:כג); כְּלַפֵּי שֶׁאָמַר לְאָבִיו: אִם יִהְיֶה חוֹתָם עַל יַד יְמִינִי, אֶנְתְּקֶנּוּ:",2,0],[22,26,"וְהֵטַלְתִּי. לְשׁוֹן הַשְׁלָכָה:",1,0],[22,27,"מְנַשְּׂאִים אֶת נַפְשָׁם. לְשׁוֹן תַּנְחוּמִים; שֶׁנַּפְשָׁם מִתְנַשְּׂאָה לְהִתְנַחֵם וְלוֹמַר: עוֹד נָשׁוּב לְאַרְצֵנוּ:",1,0],[22,28,"הַעֶצֶב נִבְזֶה. תְּמִיהָּ הוּא: שֶׁמָּא צוּרָה נִשְׁבָּר וְנִבְזֶה הָאִישׁ הַזֶּה שֶׁהֻשְׁלַךְ מֵעַל פָּנַי כְּמִי שֶׁאֵין חֵפֶץ בּוֹ?!",1,0],[22,28,"נָפוּץ. נִשְׁבָּר, כְּמוֹ ״כִּכְלִי יוֹצֵר תְּנַפְּצֵם״ (תהלים ב:ט). וַאֲחֵרִים הִגִּיהוּ הַעֶצֶב כְּמוֹ הָעֲצַבִּים, ״מְעַצְּבִין אֶת הַקָּטָן״ בְּמַסֶּכֶת שַׁבָּת (קמז.), כְּלוֹמַר: הַאַתָּה נִבְזֶה וְנָפוּץ בְּעֵינֶיךָ כְּעוֹלֵל קָטָן שֶׁמְּעַצְּבִין אוֹתוֹ? מילויילי״ר בְּלַעַז. אֵין זֶה כְּדַי:",2,0],[22,28,"הוּטְלוּ. הֻשְׁלְכוּ, לְשׁוֹן הַשְׁלָכָה שֶׁאֵין לָהּ תְּקוּמָה, כְּמוֹ ״כִּי יִפֹּל לֹא יוּטָל״ (תהלים לז:כד):",3,0],[22,29,"אֶרֶץ אֶרֶץ אָרֶץ. מֵאַרְצוֹ גָּלָה אֶל אֶרֶץ אַחֶרֶת, וְאַתְּ, אֶרֶץ יִשְׂרָאֵל, שִׁמְעִי דְּבַר ה׳. דָּבָר אַחֵר: אֶרֶץ אֶרֶץ, אֶרֶץ שֶׁהוּא אֶרֶץ שֶׁבָּאֲרָצוֹת, שֶׁהָיְתָה חֲשׁוּבָה שֶׁבְּכֻלָּן. דָּבָר אַחֵר (בבא בתרא לח.): אֶרֶץ יִשְׂרָאֵל שָׁלֹשׁ אֲרָצוֹת הָיוּ בָּהּ: יְהוּדָה וְעֵבֶר הַיַּרְדֵּן וְהַגָּלִיל:",1,0],[22,30,"גֶּבֶר. אֲשֶׁר לֹא יִצְלַח בְּיָמָיו כִּתְבוּהוּ:",1,0],[23,1,"הוֹי רוֹעִים. מַלְכֵי יְהוּדָה:",1,0],[23,2,"לֹא פְקַדְתֶּם אוֹתָם. לֹא נִזְהַרְתֶּם לְשָׁמְרָם:",1,0],[23,4,"וְלֹא יִפָּקֵדוּ. וְלֹא יֶחְסְרוּ, לָשׁוֹן ״וְלֹא נִפְקַד מִמֶּנּוּ אִישׁ״ (במדבר לא:מט):",1,0],[23,5,"וְהִשְׂכִּיל. וְיַצְלִיחַ:",1,0],[23,6,"ה׳ צִדְקֵנוּ. ה׳ מַצְדִּיק אוֹתָנוּ בְּיָמָיו שֶׁל זֶה:",1,0],[23,9,"לַנְּבִיאִים נִשְׁבַּר לִבִּי בְקִרְבִּי. לְדִבְרֵי הַנְּבִיאִים, הָאוֹמְרִים שָׁלוֹם יִהְיֶה לָכֶם, נִשְׁבַּר לִבִּי. רָחֲפוּ – הוֹלְכִים וְנָעִים, כְּכַנְפֵי צִפּוֹר הַמְרַחֵף עַל קִנּוֹ; טְרַנְבְּלִיר״ט בְּלַעַז:",1,0],[23,9,"מִפְּנֵי ה׳. שֶׁאֲנִי שׁוֹמֵעַ מִמֶּנּוּ גְּזֵרָה רָעָה זֹאת:",2,0],[23,10,"מִפְּנֵי אָלָה. שְׁבוּעַת שֶׁקֶר:",1,0],[23,10,"אָבְלָה. חֲרֵבָה:",2,0],[23,10,"מְרוּצָתָם. קוֹרְשָׁ״א בְּלַעַ״ז, וְיוֹנָתָן תִּרְגֵּם לְשׁוֹן רָצוֹן:",3,0],[23,10,"לֹא כֵן. לֹא בַדִּין:",4,0],[23,11,"גַּם נָבִיא גַּם כֹּהֵן. אֲפִילּוּ אֵלּוּ, שֶׁהַכֹּל לְמֵדִין מֵהֶם:",1,0],[23,11,"גַּם בְּבֵיתִי מָצָאתִי רָעָתָם. שֶׁהֶעֱמִידוּ דְּמוּת בַּהֵיכָל:",2,0],[23,12,"כַּחֲלַקְלַקּוֹת. אֶרֶץ חֲלָקָה, שֶׁהָרֶגֶל מַחְלֶקֶת בָּהּ וְהָאָדָם נוֹפֵל:",1,0],[23,12,"כַּחֲלַקְלַקּוֹת בָּאֲפֵלָה. כִּשָּׁלוֹן עַל כִּשָּׁלוֹן: חֲלַקְלַקּוֹת בָּאוֹר יֵשׁ כִּשָּׁלוֹן, אֲפֵלָה בְּלֹא חֲלַקְלַקּוֹת יֵשׁ כִּשָּׁלוֹן:",2,0],[23,13,"וּבִנְבִיאֵי שֹׁמְרוֹן רָאִיתִי תִפְלָה. קֹדֶם שֶׁגָּלוּ:",1,0],[23,14,"וּבִנְבִיאֵי יְרוּשָׁלִַם. אֲנִי רוֹאֶה עַתָּה שַׁעֲרוּרָה, דָּבָר מְגֻנֶּה:",1,0],[23,14,"וְחִזְּקוּ יְדֵי מְרֵעִים. אוֹמְרִים לָרְשָׁעִים: שָׁלוֹם יִהְיֶה לָכֶם:",2,0],[23,14,"לְבִלְתִּי שָׁבוּ. שֶׁלֹּא יָשׁוּבוּ הַמְּרֵעִים אִישׁ מֵרָעָתוֹ:",3,0],[23,17,"וְכֹל הוֹלֵךְ בִּשְׁרִירוּת לִבּוֹ וְגוֹ׳. וּלְכָל הוֹלֵךְ בִּשְׁרִירוּת לִבּוֹ וְגוֹ׳:",1,0],[23,18,"מִי עָמַד בְּסוֹד ה׳. וְיִשְׁמַע אֶת הַנִּגְזָר מִלְּפָנָיו? אוֹתוֹ שֶׁהִקְשִׁיב דְּבַר תּוֹרָתוֹ וְיִשְׁמַע לְמִצְוֹתָיו, וְלֹא הָרְשָׁעִים הָאֵלֶּה! שְׁמִיעָה הָרִאשׁוֹנָה שֶׁבַּמִּקְרָא זֶה – שְׁמִיעָה מַמָּשׁ; שְׁמִיעָה הָאַחֲרוֹנָה – קַבָּלָה:",1,0],[23,19,"מִתְחוֹלֵל. מִשְׁתַּכֵּן, מְחַזֵּר לִשְׁכּוֹן; וְעַל רֹאשׁ רְשָׁעִים יִשְׁכּוֹן:",1,0],[23,20,"מְזִמּוֹת. לְשׁוֹן מַחֲשָׁבָה:",1,0],[23,22,"וְאִם עָמְדוּ בְּסוֹדִי וְיַשְׁמִיעוּ דְבָרַי וגו׳. הָיָה לָהֶם לְהַשְׁמִיעַ דְּבָרַי וְתוֹרָתִי אֶת עַמִּי, וְלֹא לְהַטְעוֹתָם בָּהּ מֵעָלַי:",1,0],[23,23,"הַאֱלֹהֵי מִקָּרֹב. שֶׁאֵינִי רוֹאֶה אֶלָּא בְּסָמוּךְ לִי, וְאֵין בִּי כֹּחַ לִשְׁפּוֹט אֶת הַתַּחְתּוֹנִים שֶׁהֵם רְחוֹקִים מִמֶּנִּי, וְאֵינִי יוֹדֵעַ בְּמַעֲשֵׂיהֶם?!",1,0],[23,24,"אִם יִסָּתֵר אִישׁ. זֶהוּ כֶּפֶל תְּמִיהָה הַאֱלֹהֵי מִקָּרֹב, כְּדֶרֶךְ כָּל תְּמִיהוֹת הַכְּפוּלוֹת:",1,0],[23,26,"עַד מָתַי. יִנָּבְאוּ שֶׁקֶר? וְכִי יֵשׁ בְּלִבָּם שֶׁל הַנְּבִיאִים הַלָּלוּ, הַנִּבְּאִים שָׁקֶר, לְקַיֵּם מַחְשְׁבוֹתָם שֶׁהֵם חוֹשְׁבִים לְהַשְׁכִּיחַ אֶת עַמִּי שְׁמִי וְגוֹ׳?!",1,0],[23,26,"תַּרְמִית. לְשׁוֹן מִרְמָה:",2,0],[23,28,"יְסַפֵּר חֲלוֹם. יְסַפְּרֶנּוּ לְשׁוֹן הֲבַאי כִּשְׁאָר חֲלוֹמוֹת, וְלֹא יְחַזְּקֶנּוּ בְּדִבְרֵי נְבוּאָה:",1,0],[23,28,"מַה לַתֶּבֶן אֶת הַבָּר. מַה עִנְיַן שֶׁקֶר אֵצֶל אֱמֶת?",2,0],[23,28,"אֶת הַבָּר. עִם הַבָּר:",3,0],[23,29,"הֲלֹא כֹה דְבָרִי כָּאֵשׁ. לֹא הָיָה לָהֶם לִטְעוֹת וּלְדַמּוֹת חֲלוֹמוֹת לוֹמַר שֶׁהֵם נְבוּאָה, כִּי דְּבַר נְבוּאָה כְּשֶׁבָּאָה בְּפִי הַנָּבִיא בִּגְבוּרָה הִיא בָאָה בּוֹ כְּאֵשׁ בּוֹעֶרֶת, כָּעִנְיָן שֶׁנֶּאֱמַר ״וַתְּהִי בְלִבִּי כְּאֵשׁ בֹּעֶרֶת״ (ירמיה כ:ט), וְאוֹמֵר ״וְיַד ה׳ עָלַי חֲזָקָה״ (יחזקאל ג:יד):",1,0],[23,29,"וּכְפַטִּישׁ. פִּי״ק בְּלַעַ״ז, וְיֵשׁ אוֹמֵר מַרְטִיי״ל בְּלַעַ״ז:",2,0],[23,30,"מְגַנְּבֵי דְבָרַי אִישׁ מֵאֵת רֵעֵהוּ. אִישׁ מֵאֵת רֵעֵהוּ יֵשׁ לָהֶם מְרַגְּלִים אֵצֶל נְבִיאֵי הָאֱמֶת, וְשׁוֹמְעִין סִגְנוֹן שֶׁלָּהֶם שֶׁהֵם מִתְנַבְּאִים בּוֹ, וְאוֹמְרִין נְבוּאַת שֶׁקֶר בְּאוֹתוֹ לָשׁוֹן, כְּמוֹ שֶׁעָשָׂה חֲנַנְיָה בֶּן עַזּוּר: שָׁמַע אֶת יִרְמְיָה מִתְנַבֵּא בַּשּׁוּק הָעֶלְיוֹן ״הִנְנִי שׁוֹבֵר אֶת קֶשֶׁת עֵילָם״ (ירמיה מט:לה), וְהוּא נִיבָּא בַּשּׁוּק הַתַּחְתּוֹן ״שָׁבַרְתִּי אֶת עוֹל מֶלֶךְ בָּבֶל״ (ירמיה כח:ב), כְּמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ בְּסַנְהֶדְרִין (פט.):",1,0],[23,31,"הַלּוֹקְחִים לְשׁוֹנָם. הַמְּלַמְּדִים לְשׁוֹנָם לוֹמַר שִׁקְרֵיהֶם בְּלָשׁוֹן נְאֻם ה׳, כִּנְבִיאֵי הָאֱמֶת, לְמַעַן יַאֲמִינוּ בָם:",1,0],[23,32,"וּבְפַחֲזוּתָם. לְשׁוֹן תִּמָּהוֹן, אִישְׁטוֹרְדִיזוֹ״ן בְּלַעַ״ז:",1,0],[23,33,"מַה מַשָּׂא ה׳. לְשׁוֹן שְׂחוֹק, לְפִי שֶׁנְּבוּאָתוֹ לָהֶם לְמַשָּׂא:",1,0],[23,33,"וְאָמַרְתָּ אֲלֵיהֶם אֶת מַה מַשָּׂא וְנָטַשְׁתִּי וגו׳. אוֹמְרִים לָכֶם מָה הַמַּשָּׂא, אַתֶּם לְמַשָּׂא לְהַקָּדוֹשׁ בָּרוּךְ הוּא, וְהוּא אָמַר שֶׁיִּטּוֹשׁ וְיַשְׁלִיךְ אֶתְכֶם מֵעַל זְרוֹעוֹתָיו מִשָּׁמַיִם אֶרֶץ (איכה ב:א), כָּךְ שָׁמַעְתִּי:",2,0],[23,33,"וְנָטַשְׁתִּי. וְעָזַבְתִּי:",3,0],[23,36,"כִּי הַמַּשָּׂא יִהְיֶה לְאִישׁ דְּבָרוֹ. אַף עַל פִּי שֶׁאַתֶּם מְהַפְּכִין אֶת הַמַּשָּׂא לִגְנַאי, מַשָּׂא דְּבַר ה׳ לְאִישׁ דְּבָרוֹ וּלְאִישׁ עֲצָתוֹ הוּא מְגַלֵּהוּ (ישעיהו מ:יג), וְאַתֶּם מְהַפְּכִין אוֹתוֹ לִלְשׁוֹן מַשָּׂאוֹי. זוֹ לֹא שָׁמַעְתִּי כֵּן, וְהִיא עִקָּר; אֲבָל כָּךְ שָׁמַעְתִּי: כִּי הַמַּשָּׂאוֹי יִהְיֶה מַשָּׂאוֹי שֶׁל פֻּרְעָנוּת לְמִי שֶׁאוֹמְרוֹ, הַשּׁוֹאֵל מַה מַּשָּׂא. עִנְיָן אַחֵר: מַשָּׂא ה׳. לְשׁוֹן נְבוּאָה הוּא; וְהָיָה הַנָּבִיא הַשֶּׁקֶר שׁוֹאֵל לַנָּבִיא הָאֱמֶת לֵאמֹר לוֹ אֶת דְּבַר הַקָּדוֹשׁ בָּרוּךְ הוּא בְּלָשׁוֹן שֶׁבָּא הַסִּיגְנוֹן אֵלָיו, וְהַסִּיגְנוֹן לֹא הָיָה מְפָרֵשׁ הַדִּבּוּר כָּל כָּךְ, וְהָיָה נְבִיא הַשֶּׁקֶר מְהַפֵּךְ אֶת הַפֵּרוּשׁ לְצַד אַחֵר, וְהָיָה מְדַבֵּר בְּדוּגְמַת נְבִיא הָאֱמֶת כְּדֵי שֶׁיַּאֲמִינוּ בּוֹ; וְכֵן עָשָׂה חֲנַנְיָה בֶּן עַזּוּר. לָכֵן הוּא אוֹמֵר: אַל תִּשְׁאֲלוּ מַשָּׂא ה׳ – אֶת לְשׁוֹן הַסִּיגְנוֹן, אֶלָּא מַה דִּבֵּר וּמַה עָנָה – אֶת פֵּרוּשׁ הַדָּבָר; שַׁאֲלוּ לַנָּבִיא הָאֱמֶת לֵאמֹר לָהֶם מַה הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹמֵר וּלְהֵיכָן נוֹטִין אֶת דְּבָרָיו:",1,0],[23,36,"כִּי הַמַּשָּׂא יִהְיֶה לְאִישׁ דְּבָרוֹ. סִיגְנוֹן סְתָם; הַקָּדוֹשׁ בָּרוּךְ הוּא אֲמָרוֹ סְתָם לְאִישׁ עֲצָתוֹ, שֶׁאֵינוֹ חָשׁוּד לְהוֹפְכוֹ, וְאַתֶּם שׁוֹאֲלִים אוֹתוֹ כְּדֵי לְהוֹפְכוֹ. וַהֲפַכְתֶּם אֶת דִּבְרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְזֶהוּ שֶׁאָמַר לְמַעְלָה מִגַּנְּבֵי דְבָרַי אִישׁ מֵאֵת רֵעֵהוּ, גַּם זֶה לָשׁוֹן מְיֻתָּר:",2,0],[23,37,"כֹּה תֹאמַר אֶל הַנָּבִיא. כְּשֶׁאַתֶּם בָּאִים לִשְׁאֹל דְּבָרַי מֵאֵת הַנָּבִיא:",1,0],[23,39,"וְנָשִׁיתִי. לְשׁוֹן ״גִּיד הַנָּשֶׁה״ (בראשית לב:לג), וְלָשׁוֹן ״נָשְׁתָה גְבוּרָתָם״ (ירמיה נא:ל); קוֹפֵץ וּמְטַלְטֵל מִמָּקוֹם לְמָקוֹם:",1,0],[24,1,"דּוּדָאֵי. קְדֵרוֹת:",1,0],[24,1,"מוּעָדִים. מוּכָנִים:",2,0],[24,1,"הֶחָרָשׁ וְהַמַּסְגֵּר. תַּלְמִידֵי חֲכָמִים שֶׁגָּלוּ עִם יְכָנְיָה (סדר עולם רבה כה), וּכְבָר פֵּירַשְׁתִּיו בְּסֵפֶר מְלָכִים (מלכים ב כד:טז) הֶחָרָשׁ וְהַמַּסְגֵּר לימייטראה ליפורטי״ר בְּלַעַז. לָשׁוֹן אַחֵר: הֶחָרָשׁ וְהַמַּסְגֵּר – הֶחָרָשׁ לְשׁוֹן חֶרֶשׁ, הַמַּסְגֵּר לְשׁוֹן סָגוּר, כְּלוֹמַר: חֲכָמִים גְּדוֹלִים בַּתּוֹרָה, שֶׁכְּשֶׁהָיָה אֶחָד מֵהֶם מְדַבֵּר, הַכֹּל שׁוֹתְקִים. מַסְגֵּר שֶׁהָיוּ סוֹגְרִים וְאֵין פּוֹתֵחַ (ישעיה כב:כב; סנהדרין לח.):",3,0],[24,2,"כִּתְאֵנֵי הַבַּכֻּרוֹת. שֶׁבִּשְּׁלוּ כָּל צָרְכָּן בִּתְחִלַּת בִּכּוּרֵי תְאֵנִים, שֶׁהֵם חֲבִיבוֹת עַל מוֹצְאֵיהֶם בְּרֵאשִׁיתָם (ישעיה כח:ד):",1,0],[24,5,"כֵּן אַכִּיר אֶת גָּלוּת וגו׳. הֲרֵי זֶה מִקְרָא מְסֹרָס: כֵּן אַכִּיר לְטוֹבָה אֶת גָּלוּת יְהוּדָה שֶׁהִגְלֵיתִי כְּבָר, יְכָנְיָה וְגָלוּתוֹ:",1,0],[24,6,"אֶתּוֹשׁ. לְשׁוֹן עֲקִירָה:",1,0],[24,9,"לְזַעֲוָה לְרָעָה לְכָל מַמְלְכוֹת הָאָרֶץ. שֶׁיִּשְׁמְעוּ הָרָעָה הַבָּאָה עֲלֵיהֶם וְיָזוּעוּ:",1,0],[24,9,"וְלִשְׁנִינָה. שֶׁיִּשְׁנְנוּ וִידַבְּרוּ הַכֹּל בְּפֻרְעָנוּתָם:",2,0],[25,1,"בַּשָּׁנָה הָרְבִיעִית. שָׁנָה שֶׁנִּתְחַתֵּם גְּזַר דִּינָם שֶׁיִּגְלוּ וְשֶׁיִּשְׁתּוּ כּוֹס הַחֵמָה, כְּמוֹ שֶׁאָמוּר בָּעִנְיָן: קַח אֶת כּוֹס וְגוֹ׳. וְקוֹדֶם גְּזַר דִּין אָמַר לַנָּבִיא לְהוֹכִיחָם, אוּלַי יָשׁוּבוּ וְלֹא יִתְחַתֵּם גְּזַר דִּינָם:",1,0],[25,3,"שָׁלֹשׁ וְעֶשְׂרִים. יֹאשִׁיָּהוּ מָלַךְ שְׁלֹשִׁים וְאַחַת (מלכים ב כב:א), צֵא מֵהֶם שְׁתֵּים עֶשְׂרֵה שָׁנָה, נִשְׁאֲרוּ תְּשַׁע עֶשְׂרֵה, וְאַרְבַּע שֶׁל בְּנוֹ (ירמיה א:ג), הֲרֵי שָׁלֹשׁ וְעֶשְׂרִים:",1,0],[25,3,"אַשְׁכֵּים וְדַבֵּר. לְשׁוֹן הוֹוֶה: הָיִיתִי מַשְׁכִּים וּמְדַבֵּר תָּמִיד:",2,0],[25,10,"קוֹל רֵחַיִם. סִימָן הוּא לִסְעוּדַת בְּרִית מִילָה, עַל שֵׁם שֶׁטּוֹחֲנִין וְשׁוֹחֲקִין לָהּ סַמְמָנִין לִרְפוּאָה:",1,0],[25,10,"אוֹר נֵר. סִימַן מִשְׁתֶּה. כָּךְ שָׁנִינוּ בְּסַנְהֶדְרִין (סנהדרין לב:):",2,0],[25,13,"אֶת כָּל הַכָּתוּב. עַל בָּבֶל:",1,0],[25,13,"בַּסֵּפֶר הַזֶּה. בְּסוֹפוֹ:",2,0],[25,14,"כִּי עָבְדוּ בָם. כְּמוֹ כִּי יַעַבְדוּ בָם, בִּבְנֵי בָבֶל:",1,0],[25,14,"גַּם הֵמָּה גּוֹיִם רַבִּים. מָדַי וּפָרָס:",2,0],[25,15,"כּוֹס הַיַּיִן הַחֵמָה. נְבוּאַת הַפֻּרְעָנוּת:",1,0],[25,15,"וְהִשְׁקִיתָה אוֹתוֹ. הִנָּבֵא לָהֶם שֶׁלֹּא תָשׁוּב עוֹד בְּשׁוּם תְּשׁוּבָה:",2,0],[25,16,"וְהִתְגֹּעֲשׁוּ. ״וְיִשְׁתַּגְּעוּן״ (תרגום יונתן):",1,0],[25,16,"וְהִתְהוֹלָלוּ. לְשׁוֹן ״הוֹלֵלוּת״ (קהלת י:יג), יִשְׁתַּטּוּ:",2,0],[25,18,"כַּיּוֹם הַזֶּה. כַּאֲשֶׁר הֵם הַיּוֹם; לְאַחַר הַחֻרְבָּן כָּתַב יִרְמְיָה סִפְרוֹ:",1,0],[25,20,"וְאֵת כָּל הָעֶרֶב. ״כָּל סוּמְכְוָתָא״ (תרגום יונתן) אֲשֶׁר עֲרֻבַּת פַּרְעֹה וּמִשְׁעַנְתּוֹ עֲלֵיהֶם לְעֶזְרָה. הָעֶרֶב גרנטיא״ה בְּלַעַ״ז:",1,0],[25,22,"וְאֵת מַלְכֵי הָאִי. כָּל אֵלּוּ שֶׁמָּנָה עַד כָּאן, שְׁכֵינֵי אֶרֶץ יִשְׂרָאֵל הֵם:",1,0],[25,23,"קְצוּצֵי פֵאָה. הַמּוּקְצִים בִּקְצֵה אוֹתָהּ הָרוּחַ:",1,0],[25,24,"מַלְכֵי עֲרָב. עֲרַבְיָא (כתובות סז.):",1,0],[25,24,"וְאֵת כָּל מַלְכֵי הָעֶרֶב. ״סוּמְכְוָותָא״ שֶׁל עַרְבִיִּים:",2,0],[25,26,"שֵׁשַׁךְ. הוּא בָּבֶל בְּא״ת ב״ש (תנחומא, קרח יב):",1,0],[25,27,"וּקְיוּ. כְּאָדָם שֶׁשּׁוֹתֶה יוֹתֵר מִדַּאי, שֶׁמֵּקִיא:",1,0],[25,27,"הַחֶרֶב. הַתִּגָּר שֶׁל הַמִּלְחָמָה:",2,0],[25,29,"מֵחֵל. מַתְחִיל:",1,0],[25,30,"עַל נָוֵהוּ. מִתְאַבֵּל עַל חֻרְבַּן בֵּיתוֹ:",1,0],[25,30,"הֵידָד. לָשׁוֹן הוּא שֶׁצּוֹעֲקִין עוֹשֵׂי מְלָאכָה כְּבֵדָה בְּקוֹל רָם, לְזָרֵז זֶה אֶת זֶה לְהִתְחַזֵּק, וְדוֹרְכֵי גִּתּוֹת רְגִילִין בָּהּ:",2,0],[25,30,"יַעֲנֶה. כָּל לְשׁוֹן עֲנִיָּה צְעָקַת קוֹל רָם הִיא:",3,0],[25,31,"נִשְׁפָּט. מִתְוַכֵּחַ בַּדִּין:",1,0],[25,32,"מִגּוֹי אֶל גּוֹי. שֶׁאֲנִי מְסַכְסְכָן זֶה בָּזֶה:",1,0],[25,32,"מִיַּרְכְּתֵי. כְּתַרְגּוּמוֹ: ״מִסְּיָפֵי״:",2,0],[25,34,"הֵילִילוּ. לְשׁוֹן ״יְלָלָה״ (צפניה א:י):",1,0],[25,34,"וְהִתְפַּלְּשׁוּ. הִתְגַּלְגְּלוּ בֶּעָפָר, וֹוטְרְלִי״ר בְּלַעַ״ז:",2,0],[25,34,"וּתְפוֹצוֹתִיכֶם. הֲרֵי זֶה מִקְרָא קָצָר, כְּלוֹמַר: וּתְפוּצוֹתֵיכֶם תִּקְרַבְנָה לָבֹא:",3,0],[25,34,"כִּכְלִי חֶמְדָּה. כְּלוֹמַר: אִם תֹּאמְרוּ חֲשׁוּבִים אֲנַחְנוּ, הַרְבֵּה יֵשׁ כְּלֵי חֶמְדָּה שֶׁל זְכוּכִית, נוֹפְלִים וּמִשְׁתַּבְּרִים וְאוֹבְדִים:",4,0],[25,37,"וְנָדַמּוּ. לְשׁוֹן חֻרְבָּה, לְשׁוֹן ״הֲדִמָּנוּ״, ״וְנִדְּמָה שָׁם״ (ירמיה ח:יד):",1,0],[25,38,"עָזַב כַּכְּפִיר וְגוֹ׳. ״גָּלָה מַלְכָּא מִכַּרְכֵּיהּ״ (תרגום יונתן), כַּכְּפִיר הָעוֹזֵב אֶת סֻכּוֹ:",1,0],[25,38,"הַיּוֹנָה. מִשְׁתַּכֶּרֶת בְּיַיִן, כֵּן תִּרְגֵּם יוֹנָתָן. דָּבָר אַחֵר: לְשׁוֹן אוֹנָאָה:",2,0],[26,1,"בְּרֵאשִׁית מַמְלְכוּת. פָּרָשָׁה זוֹ תַּחְתּוֹנָה קָדְמָה לָעֶלְיוֹנָה אַרְבַּע שָׁנִים (ירמיה כה:א):",1,0],[26,10,"וַיִּשְׁמְעוּ שָׂרֵי יְהוּדָה. שֶׁתָּפְשׂוּ נְבִיאֵי הַשֶּׁקֶר וְהַכֹּהֲנִים אֶת יִרְמְיָה:",1,0],[26,10,"בְּפֶתַח שַׁעַר ה׳ הֶחָדָשׁ. אֲחֵרִים הִגִּיהוּ: כְּשֶׁגָּלָה יְהוֹיָכִין וְקְצָת כְּלֵי בֵּית אֱלֹהֵינוּ עִמּוֹ, שָׁבְרוּ חֵילוֹ שֶׁל נְבוּכַדְנֶצַּר שַׁעַר הַמִּזְרָחִי, וְחָזַר צִדְקִיָּהוּ וְתִקְּנוֹ וְחִדְּשׁוֹ; לְכָךְ נִקְרָא חָדָשׁ:",2,0],[26,18,"מִיכָה הַמּוֹרַשְׁתִּי. ״דְּמִן מָרֵישָׁא״ (תרגום יונתן):",1,0],[26,18,"עִיִּים. גַּלִּים:",2,0],[26,19,"וַיְחַל. לְשׁוֹן תְּפִלָּה:",1,0],[26,19,"וַאֲנַחְנוּ עֹשִׂים רָעָה גְדוֹלָה. אִם נַהֲרֹג אוֹתוֹ:",2,0],[26,20,"וְגַם אִישׁ הָיָה מִתְנַבֵּא. מִי שֶׁאָמַר זוֹ לֹא אָמַר זוֹ; עַד כָּאן דִּבְרֵי צַדִּיקִים, וְעָמְדוּ רְשָׁעִים שֶׁהָיוּ שָׁם וְאָמְרוּ: גַּם אִישׁ מִתְנַבֵּא וְגוֹ׳, כְּשֵׁם שֶׁאוּרִיָּה נֶהֱרַג, יֵהָרֵג יִרְמְיָה; כָּךְ מְפֹרָשׁ בְּסִפְרֵי (ספרי במדבר פיסקא פח):",1,0],[27,1,"בְּרֵאשִׁית מַמְלֶכֶת יְהוֹיָקִם. שָׁלֹשׁ שָׁנִים לִפְנֵי שֶׁמָּלַךְ נְבוּכַדְנֶצַּר (ירמיה כה:א), נִתְנַבֵּא עָלָיו שֶׁיִּמְלֹךְ:",1,0],[27,2,"מוֹסֵרוֹת. הֵם רְצוּעוֹת הָעוֹל, שֶׁקּוֹרִין קוֹיוּנְגְמְ״שׁ:",1,0],[27,3,"וְשִׁלַּחְתָּם אֶל מֶלֶךְ אֱדוֹם. בִּימֵי צִדְקִיָּהוּ בַּשָּׁנָה הָרְבִיעִית לְמָלְכוֹ (ירמיה כח:א); שֶׁעָשָׂהוּ נְבוּכַדְנֶצַּר שַׁלִּיט עַל חֲמִשָּׁה מְלָכִים:",1,0],[27,3,"מֶלֶךְ אֱדוֹם וּמֶלֶךְ מוֹאָב וּמֶלֶךְ בְּנֵי עַמּוֹן וְגוֹ׳. אֵלּוּ חֲמִשָּׁה מְלָכִים נָתַן נְבוּכַדְנֶצַּר תַּחַת יָדוֹ שֶׁל צִדְקִיָּהוּ (איכה רבה ב, יד). חֲמֵשׁ עֶשְׂרֵה שָׁנָה הָיוּ עַל צַוָּארוֹ, מִשָּׁנָה אַחַת לִיהוֹיָקִים עַד הַשָּׁנָה הָרְבִיעִית לְצִדְקִיָּהוּ, שֶׁשְּׁבָרָם הֵימֶנּוּ חֲנַנְיָה בֶּן עַזּוּר (ירמיה כח:י):",2,0],[27,6,"עַבְדִּי. שֶׁיַּעֲשֶׂה רְצוֹנִי לִפָּרַע מִשּׂוֹנְאַי:",1,0],[27,7,"וְאֶת בְּנוֹ. אֱוִיל מְרֹדַךְ:",1,0],[27,7,"וְאֶת בֶּן בְּנוֹ. בֵּלְשַׁאצַּר:",2,0],[27,7,"עַד בֹּא עֵת אַרְצוֹ. שֶׁיָּבֹאוּ דָּרְיָוֶשׁ הַמָּדִי וְכוֹרֶשׁ וְיַהַרְגוּ אֶת בֵּלְשַׁאצַּר:",3,0],[27,12,"וְאֶל צִדְקִיָּה מֶלֶךְ יְהוּדָה דִּבַּרְתִּי וְגוֹ׳. כָּל זֶה אָמַר יִרְמְיָהוּ אֶל שְׁלוּחֵי הַמְּלָכִים:",1,0],[27,16,"הִנֵּה כְלֵי בֵית ה׳. שֶׁגָּלוּ עִם יְכָנְיָה (להלן כ):",1,0],[27,19,"הַמְּכוֹנוֹת. תִּרְגֵּם יוֹנָתָן: ״בְּסִיסַיָּא״, כְּמוֹ ״אֶת הַכִּיּוֹר וְאֶת כַּנּוֹ״ (שמות לה:טז):",1,0],[27,20,"בַּגְלוֹתוֹ. כְּמוֹ בְּהַגְלוֹתוֹ:",1,0],[27,20,"חֹרֵי. כְּמוֹ ״שָׂרֵי״ (ירמיה כד:א):",2,0],[27,22,"עַד יוֹם פָּקְדִי אוֹתָם. בִּימֵי כּוֹרֶשׁ, כְּמוֹ שֶׁמְפוֹרָשׁ בְּסֵפֶר עֶזְרָא (עזרא א:ז-יא):",1,0],[28,1,"וַיְהִי בַּשָּׁנָה הַהִיא. כְּשֶׁהִגִּיעַ אוֹתוֹ הַזְּמַן שֶׁהִשְׁלִיט נְבוּכַדְנֶצַּר אֶת צִדְקִיָּהוּ עַל חֲמֵשֶׁת מְלָכִים, שֶׁהָיָה יִרְמְיָה אוֹמֵר שְׁלִיחוּתוֹ וּמְשַׁלֵּחַ הַמּוֹסֵרוֹת וְהַמּוֹטוֹת אֶל הַמְּלָכִים בְּיַד מַלְאָכֵיהֶם (ירמיה כז:ב-ג):",1,0],[28,1,"בְּרֵאשִׁית מַמְלֶכֶת צִדְקִיָּה. בִּתְחִלָּה שֶׁהִשְׁלִיטוֹ עַל חֲמֵשֶׁת הַמְּלָכִים, וְאִי אֶפְשָׁר לוֹמַר בִּתְחִלַּת מַלְכוּתוֹ, שֶׁהֲרֵי נֶאֱמַר בַּשָּׁנָה הָרְבִיעִית. אוֹתָהּ שָׁנָה יָרַד לְהַקְבִּיל אֶת פְּנֵי נְבוּכַדְנֶצַּר בְּבָבֶל, וְשָׂרָיָה שַׂר הַמְּנוּחָה עִמּוֹ, וּכְמוֹ שֶׁנֶּאֱמַר בְּסוֹף הַסֵּפֶר (ירמיה נא:נט), וְהִשְׁלִיטוֹ עַל הַמְּלָכִים:",2,0],[28,1,"אָמַר אֵלַי וגו׳. אָמְרוּ רַבּוֹתֵינוּ (סדר עולם רבה כה): מִי הִטְעָה אֶת חֲנַנְיָה? שָׁמַע שֶׁהָיָה יִרְמְיָה מִתְנַבֵּא בַּשּׁוּק הָעֶלְיוֹן: ״הִנְנִי שֹׁבֵר אֶת קֶשֶׁת עֵילָם״ (ירמיה מט:לה), וּנְבוּאָה זוֹ בְּסוֹף הַסֵּפֶר נֶאֶמְרָה, בְּרֵאשִׁית מַמְלֶכֶת צִדְקִיָּה, כְּמוֹ שֶׁמְּפֹרָשׁ שָׁם (ירמיה מט:לד); וּלְפִי שֶׁעֵילָם סְמוּכָה לְבָבֶל, עָמַד הוּא בַּשּׁוּק הַתַּחְתּוֹן וְדָרַשׁ וְדָן קַל וָחֹמֶר: וּמָה עֵילָם, שֶׁלֹּא בָּאָה אֶלָּא לַעֲזֹר אֶת הַכַּשְׂדִּים וְכוּ׳; כְּמָה שֶׁהִיא בְּסַנְהֶדְרִין (פט.):",3,0],[28,6,"יַעֲשֶׂה. פַאצָ״א בְּלַעַ״ז:",1,0],[28,6,"יקם. לְשׁוֹן תְּפִלָּה (של״ש שטי״ן אלו ע״ד והביא״ו לבית הכל״א לא סדר״ן הר״ב המחב״ר) (אָמֵן כֵּן יַעֲשֶׂה וְגוֹ׳. בַּעֲלֵי אַגָּדָה אוֹמְרִים: כָּךְ אָמַר לוֹ הַלְוַאי וְיִתְקַיְּמוּ דְּבָרֶיךָ אֲנִי מִשְׁתַּכֵּר וְאַתָּה נִפְסַד, אֲנִי כֹּהֵן וְאוֹכֵל קָדְשֵׁי שָׁמַיִם אִם יַעֲמֹד הַבַּיִת בְּבִנְיָנוֹ, וְאַתָּה גִּבְעוֹנִי כְּדָכָתִיב כָּאן) אֲשֶׁר מִגִּבְעוֹן, וְתִהְיֶה לִי עֶבֶד חוֹטֵב עֵצִים וְשׁוֹאֵב מַיִם (וּמוֹרֵה צֶדֶק שֶׁלֹּא פֵּרֵשׁ נָקִיט לֵהּ טַעַם רַבּוֹתֵינוּ, שֶׁלָּמְדוּ מִכָּאן: כָּל הַמַּחֲנִיף לָרָשָׁע סוֹף נוֹפֵל בְּיָדוֹ אוֹ בְּיַד בְּנוֹ אוֹ בְּיַד בֶּן בְּנוֹ, שֶׁכֵּן יִרְאִיָּיה בֶּן שֶׁלֶמְיָה בֶּן חֲנַנְיָה תָּפְשׂוּ לְבַסּוֹף וְהֵבִיאוּ לְבֵית הַכֶּלֶא):",2,0],[28,7,"אַךְ שְׁמַע נָא וְגוֹ׳. עַד הַנָּבִיא אֲשֶׁר יִנָּבֵא לְשָׁלוֹם, אָמַר: אֲנִי מִתְנַבֵּא פּוּרְעָנִיּוֹת; אִם לֹא יָבֹא, אֵינִי שַׁקְרָן, הַקָּדוֹשׁ בָּרוּךְ הוּא ״נִחָם עַל הָרָעָה״ (יואל ב:יג), אֲבָל הַנָּבִיא אֲשֶׁר יִנָּבֵא לְשָׁלוֹם, בְּבֹא דְּבַר הַנָּבִיא יִוָּדַע וְגוֹ׳, אֲבָל אִם לֹא יָבֹא דְּבָרוֹ – שַׁקְרָן הוּא, שֶׁנֶּאֱמַר: ״לֹא אִישׁ אֵל וִיכַזֵּב וְגוֹ׳״ (במדבר כג:יט). כָּךְ דָּרַשׁ רַבִּי תַּנְחוּמָא (תנחומא, וירא יג):",1,0],[28,14,"אֶת חַיַּת הַשָּׂדֶה נָתַתִּי לוֹ. שֶׁרָכַב עַל אֲרִי וְקָשַׁר תַּנִּין בְּרֹאשׁוֹ (שבת קמט:):",1,0],[28,16,"הַשָּׁנָה אַתָּה מֵת. וּבַשָּׁנָה הַבָּאָה תִּקָּבֵר:",1,0],[28,17,"בַּשָּׁנָה הַהִיא בַּחֹדֶשׁ הַשְּׁבִיעִי. וַהֲלֹא אֵין חֹדֶשׁ שְׁבִיעִי מִן הַשָּׁנָה? אֶלָּא מֵת עֶרֶב רֹאשׁ הַשָּׁנָה, וְצִוָּה לְבָנָיו שֶׁיִּקְבְּרוּהוּ לְאַחַר רֹאשׁ הַשָּׁנָה וְלֹא קֹדֶם, וְיַעֲלִימוּ אֶת מִיתָתוֹ אוֹתוֹ הַיּוֹם, כְּדֵי לַעֲשׂוֹת נְבוּאַת יִרְמְיָה שֶׁקֶר (ירושלמי סנהדרין יא,ה):",1,0],[29,2,"וְהַגְּבִירָה. אֵם הַמֶּלֶךְ (מלכים א טו:יג):",1,0],[29,8,"יַשִּׁיאוּ. לְשׁוֹן הֲסָתָה, כְּמוֹ ״הַנָּחָשׁ הִשִּׁיאַנִי״ (בראשית ג:יג):",1,0],[29,12,"וּקְרָאתֶם אֹתִי וְהֲלַכְתֶּם. בִּדְרָכַי; וַהֲרֵי זֶה מִקְרָא קָצָר:",1,0],[29,16,"אֶל הַמֶּלֶךְ. צִדְקִיָּהוּ, אֲשֶׁר לֹא גָּלָה:",1,0],[29,17,"כַּתְּאֵנִים הַשֹּׁעָרִים. לְשׁוֹן ״שַׁעֲרוּרִיָּה״ (הושע ו:י):",1,0],[29,18,"וּלְחֶרְפָּה. שֶׁיְּחָרְפוּ אוֹתָם, דִּישְׁטְרוּוִי״ר בְּלַעַ״ז; וְכֵן כָּל חֶרְפָּה שֶׁבַּמִּקְרָא:",1,0],[29,22,"אֲשֶׁר קָלָם. לְשׁוֹן ״קָלוּי בָּאֵשׁ״ (ויקרא ב:יד):",1,0],[29,23,"וַיְנַאֲפוּ אֶת נְשֵׁי רֵעֵיהֶם. כְּמוֹ שֶׁמְּפֹרָשׁ בְּסַנְהֶדְרִין (סנהדרין צג.): כֹּה אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: שִׁכְבִי עִם חֲבֵרִי:",1,0],[29,23,"וָעֵד. לְשׁוֹן עֵדוּת:",2,0],[29,24,"הַנֶּחֱלָמִי. שֵׁם מָקוֹם:",1,0],[29,26,"נְתָנְךָ כֹהֵן. אֶל צְפַנְיָה כָּתַב כֵּן (ירמיה כא:א):",1,0],[29,26,"פְּקִידִים. מְמֻנִּים:",2,0],[29,26,"מַהְפֶּכֶת. כִּיפָּה:",3,0],[29,26,"הַצִּינוֹק. סַדָּן, צִיפְ״שׁ בְּלַעַ״ז:",4,0],[29,28,"כִּי עַל כֵּן שָׁלַח. כִּי יֵשׁ לְךָ לִגְעֹר בּוֹ עַל אֲשֶׁר שָׁלַח אֵלֵינוּ בָּבֶל לֵאמֹר אֲרֻכָּה הִיא גָּלוּתְכֶם שָׁם:",1,0],[29,28,"עַל כֵּן. כְּמוֹ עַל אֲשֶׁר:",2,0],[30,3,"כִּי הִנֵּה יָמִים בָּאִים. וְלֹא תֹאמַר לָמָּה אֶכְתְּבֶנּוּ כִּי יֹאבְדוּ כֻּלָּם וְאֵין קוֹרֵא בּוֹ וְאֵין זוֹכְרוֹ עוֹד כִּי הִנֵּה יָמִים בָּאִים וְגוֹ׳:",1,0],[30,5,"קוֹל חֲרָדָה שָׁמָעְנוּ. יֵשׁ פּוֹתְרִין עַל שְׁמוּעַת בָּבֶל שֶׁהָיוּ חֲרֵדִים מִמֶּנָּה אוֹתָם שֶׁגָּלוּ שָׁם, וּמִדְרַשׁ אַגָּדָה עַל מִלְחֶמֶת גּוֹג וּמָגוֹג:",1,0],[30,6,"אִם יוֹלֵד זָכָר. אִם דֶּרֶךְ לִזְכָרִים לָלֶדֶת שֶׁיֹּאחֲזוּם חֲבָלִים כַּיּוֹלֵדָה:",1,0],[30,6,"חֲלָצָיו. כְּמוֹ מָתְנָיו:",2,0],[30,7,"הַיּוֹם הַהוּא. יוֹם הֲרִיגַת בֵּלְשַׁאצַּר וּמַפֶּלֶת בָּבֶל, עִנְיָן אַחֵר יוֹם מַפֶּלֶת גּוֹג:",1,0],[30,8,"אֶשְׁבֹּר עֻלּוֹ. יָסוּר עוֹל הָאֻמּוֹת מֵעַל יִשְׂרָאֵל:",1,0],[30,10,"וְאַתָּה אַל תִּירָא. מִכָּל הָרָעוֹת אֲשֶׁר תִּרְאֶה בָּאָה עַל בָּבֶל אֲשֶׁר אַתָּה בְתוֹכָהּ:",1,0],[30,10,"וְשַׁאֲנַן. כְּמוֹ וְשָׁקַט:",2,0],[30,11,"וְיִסַּרְתִּיךָ לַמִּשְׁפָּט. בְּדִין חָסוּךְ:",1,0],[30,11,"וְנַקֵּה לֹא אֲנַקֶּךָ. לְשׁוֹן טִיאוּט, הַשְׁמֵד:",2,0],[30,12,"אָנוּשׁ לְשִׁבְרֵךְ נַחְלָה. שִׁבְרֵךְ אנפר״ש בְּלַעַ״ז:",1,0],[30,13,"לְמָזוֹר. רְפוּאָה, אֵין אָדָם סָבוּר שֶׁתְּהֵא לָךְ תְּשׁוּעָה:",1,0],[30,13,"תְּעָלָה. רְפוּאָה, לְשׁוֹן הוֹעִיל:",2,0],[30,14,"מוּסַר אַכְזָרִי. יִסּוּרֵי אַכְזָרִיּוּת. הַמּוּסַר אַכְזָרִי הוּא:",1,0],[30,16,"לָכֵן. שְׁבוּעָה:",1,0],[30,16,"שֹׁאסַיִךְ לִמְשִׁסָּה. לְשׁוֹן בִּיזָּה, וְכֵן תִּרְגֵּם יוֹנָתָן: ״וִיהוֹן עָדַיִךְ לַעֲדִי״:",2,0],[30,17,"אֲרֻכָה. רְפוּאָה:",1,0],[30,18,"וְאַרְמוֹן. הַמִּקְדָּשׁ:",1,0],[30,19,"וְהִכְבַּדְתִּים. שֶׁיִּהְיוּ עַם כָּבֵד:",1,0],[30,19,"וְלֹא יִצְעָרוּ. כְּמוֹ יִמְעָטוּ:",2,0],[30,21,"אַדִּירוֹ. שַׂר שֶׁלּוֹ:",1,0],[30,21,"עָרַב אֶת לִבּוֹ. לְשׁוֹן עֵרָבוֹן, פרוויל״א הטינ״א בְּלַעַ״ז:",2,0],[30,21,"לָגֶשֶׁת אֵלַי. לַמִּלְחָמָה, לִמְחוֹת בְּיָדִי:",3,0],[30,23,"מִתְגּוֹרֵר. חוֹנֶה וְדָר, לְשׁוֹן ״אֶרֶץ מְגוּרֵי״ (בראשית לז:א). וְדוּגְמָתוֹ ״וְסַעַר מִתְחוֹלֵל״ (ירמיה כג:יט) הָאָמוּר בַּמִּקְרָא הָאַחֵר, הוּא זֶה, שֶׁשְּׁנֵיהֶם לְשׁוֹן חֲנִיָּה:",1,0],[30,23,"עַל רֹאשׁ רְשָׁעִים. עַל רֹאשׁ הַגּוֹיִים:",2,0],[31,2,"מָצָא חֵן. בְּעֵינֵי דּוֹר הַמִּדְבָּר:",1,0],[31,2,"שְׂרִידֵי חָרֶב. מִצְרַיִם וְהָעֲמָלֵקִי וְהַכְּנַעֲנִי:",2,0],[31,2,"הָלוֹךְ לְהַרְגִּיעוֹ יִשְׂרָאֵל. בְּהוֹלִיכָם לִנְחוֹל אֶרֶץ מַרְגּוֹעָם:",3,0],[31,3,"מֵרָחוֹק. בִּזְכוּת אָבוֹת (בראשית יז:ז):",1,0],[31,3,"נִרְאָה לִי. אֲנִי הַנָּבִיא, וְאָמַר לִי לֵאמֹר לִכְנֶסֶת יִשְׂרָאֵל אַהֲבַת עוֹלָם אֲהַבְתִּיךְ:",2,0],[31,4,"עוֹד אֶבְנֵךְ וְנִבְנֵית. בִּנְיָנִים שְׁנַיִם הָיוּ לָךְ עַל יְדֵי אָדָם, לְכָךְ חָרְבוּ. עוֹד אֶבְנֵךְ אֲנִי בְּעַצְמִי בִּנְיָן שְׁלִישִׁי, וְנִבְנֵית לְעוֹלָם. תַּעְדִּי תִּתְקַשְּׁטִי:",1,0],[31,5,"וְחִלֵּלוּ. בַּשָּׁנָה הָרְבִיעִית יְחַלְּלוּ אֶת פִּרְיָם לִפְדּוֹתוֹ בְּכֶסֶף (ויקרא יט:כד):",1,0],[31,6,"נוֹצְרִים. צוֹפִים בְּרָאשֵׁי מִגְדָּלִים גְּבוֹהִים לְהַכְרִיז קוֹל נִשְׁמָע לְמֵרָחוֹק. לָשׁוֹן אַחֵר: נוֹצְרִים כְּמוֹ ״נֹצֵר חֶסֶד לָאֲלָפִים״ (שמות לד:ז), לְשׁוֹן שְׁמִירָה. כְּלוֹמַר, יֶשׁ יוֹם שֶׁיִּקְרְאוּ אוֹתָם שֶׁשָּׁמְרוּ הַתּוֹרָה וְיֹאמְרוּ קוּמוּ. וְכֵן תִּרְגֵּם יוֹנָתָן: ״אֲרֵי אִית אֲרִיכוּת יוֹמַיָּא וְסַגִּי טוּבָא דְּעָתִיד לְמֵיתֵי לְצַדִּיקַיָּא דְּנַטְרוּ אוֹרַיְתִי מִלְּקַדְמִין״:",1,0],[31,7,"וְצַהֲלוּ בְּרֹאשׁ הַגּוֹיִם. בְּמִגְדָּלוֹת גְּבוֹהִים כְּדֵי שֶׁיִּשְׁמְעוּ לְמֵרָחוֹק:",1,0],[31,8,"בָּם עִוֵּר וּפִסֵּחַ. אֲפִילּוּ הַנִּכְשָׁלִים שֶׁבָּהֶם לֹא אֶמְאַס:",1,0],[31,9,"בִּבְכִי יָבֹאוּ. עַל יְדֵי תְּפִלָּה וּתְשׁוּבָה:",1,0],[31,10,"מְזָרֵה. אֶסְפְּרֵיינְ״שׁ בְּלַעַ״ז:",1,0],[31,12,"וְנָהֲרוּ. יֵאָסְפוּ כְּמוֹ נָהָר:",1,0],[31,14,"דָּשֶׁן. שָׁמֵן:",1,0],[31,15,"קוֹל בְּרָמָה נִשְׁמָע. ״קָלָא בְּרוּם עָלְמָא אִישְׁתְּמַע, קָל בֵּית יִשְׂרָאֵל דְּבָכְיָן עַל יִרְמְיָה נְבִיָּיא כַּד שְׁלַח יָתֵיהּ נְבוּזַרְאֲדָן מֵרָמָתָא״. לָשׁוּב מֵאַחַר הַגּוֹלִים אֶל גְּדַלְיָה בֶּן אֲחִיקָם, כְּמוֹ שֶׁאָמַר בְּסֵפֶר זֶה (ירמיה מ:א):",1,0],[31,15,"רָחֵל מְבַכָּה עַל בָּנֶיהָ. מִדְרַשׁ אַגָּדָה אָמַר שֶׁהָלְכוּ אָבוֹת וְאִמָּהוֹת לְפַיֵּס אֶת הַהַקָּדוֹשׁ בָּרוּךְ הוּא עַל שֶׁהֶעֱמִיד מְנַשֶּׁה דְּמוּת בַּהֵיכָל, וְלֹא נִתְפַּיֵּס. נִכְנְסָה רָחֵל, אָמְרָה לְפָנָיו: רִבּוֹנוֹ שֶׁל עוֹלָם רַחֲמֵי מִי מְרֻבִּים רַחֲמֶיךָ אוֹ רַחֲמֵי בָּשׂר וָדָם, הֱוֵי אוֹמֵר רַחֲמֶיךָ מְרֻבִּים. וַהֲלֹא אֲנִי הִכְנַסְתִּי צָרָתִי בְּתוֹךְ בֵּיתִי, שֶׁכָּל עֲבוֹדָה שֶׁעָבַד יַעֲקֹב אֶת אָבִי לֹא עָבַד אֶלָּא בִּשְׁבִילִי; כְּשֶׁבָּאתִי לִיכָּנֵס לַחֻפָּה הִכְנִיסוּ אֶת אֲחוֹתִי, וְלֹא דַי שֶׁשָּׁתַקְתִּי אֶלָּא שֶׁמָּסַרְתִּי לָהּ סִימָנִי. אַף אַתָּה, אִם הִכְנִיסוּ בָנֶיךָ צָרָתְךָ בְּבֵיתְךָ, שְׁתוֹק לָהֶם. אָמַר לָהּ: יָפֶה לִמַּדְתְּ סַנֵּגוֹרְיָא, יֵשׁ שָׂכָר לִפְעֻלָּתֵךְ וּלְצִדְקָתֵךְ שֶׁמָּסַרְתְּ סִימָנֵךְ לַאֲחוֹתֵךְ:",2,0],[31,18,"מִתְנוֹדֵד. קוֹמְפְּלֵיְינְ״ט בְּלַעַ״ז, לְשׁוֹן ״מִי יָנוּד לָךְ״ (ירמיה טו:ה):",1,0],[31,18,"יִסַּרְתַּנִי. בְּיִסּוּרִין אַתָּה הַקָּדוֹשׁ בָּרוּךְ הוּא:",2,0],[31,18,"כְּעֵגֶל לֹא לוּמָּד. פוּשָׁאגוּיֵילוֹנִ״י בְּלַעַ״ז, לְשׁוֹן ״מַלְמַד הַבָּקָר״ (שופטים ג:לא). הָיִיתִי בַּתְּחִלָּה, לְכָךְ חָטָאתִי לְךָ:",3,0],[31,19,"נִחַמְתִּי. אֲנִי מִתְחָרֵט עַל תּוֹעֲבוֹתַי:",1,0],[31,19,"הִוָּדְעִי. שֶׁהִתְבּוֹנַנְתִּי בְּעַצְמִי שֶׁמָּעַלְתִּי, אפרינו״יי בְּלַעַ״ז:",2,0],[31,19,"חֶרְפַּת נְעוּרָי. שֶׁיְּכוֹלִים אוֹיְבַי לְחָרְפֵנִי עַל חַטֹּאת נְעוּרָי:",3,0],[31,20,"הֲבֵן יַקִּיר לִי אֶפְרַיִם. הֵן דִּבְרֵי שְׁכִינָה, כְּלוֹמַר הוּא מִתְנוֹדֵד וַאֲנִי לִבִּי נֶהְפַּךְ עָלַי לְרַחֵם, שֶׁמָּא בְּנִי יַקִּירִי הוּא, כְּמוֹ שֶׁאֵין לוֹ אֶלָּא בֵּן אֶחָד שֶׁהוּא עוֹשֶׂה לוֹ כָּל רְצוֹנוֹ. שַׁעֲשׁוּעִים אישבניימני״ץ בְּלַעַ״ז:",1,0],[31,20,"מִדֵּי דַבְּרִי בּוֹ. בְּכָל עֵת שֶׁאֲנִי מְדַבֵּר בּוֹ. וּמִדְרַשׁ וַיִּקְרָא רַבָּה (ויקרא רבה ב,ג): דַּי דִּבּוּרִי שֶׁנָּתַתִּי בּוֹ, שֶׁלִּמַּדְתִּיו תּוֹרָתִי, לְרַחֵם עָלָיו:",2,0],[31,21,"הַצִּיבִי לָךְ צִיֻּנִים. סִימָנִים בְּדַרְכֵי אֲבוֹתַיִךְ הַטּוֹבִים:",1,0],[31,21,"תַּמְרוּרִים. תְּמָרִים קְטַנִּים נְטוּעִים לְסִימָן בַּדֶּרֶךְ. וּפְשׁוּטוֹ שֶׁל מִקְרָא, עֲשִׂי סִימָנִים לָדַעַת הַדֶּרֶךְ שֶׁהָלַכְתְּ בָּהּ מֵאֶרֶץ יִשְׂרָאֵל לְבָבֶל, שֶׁתַּחְזִירִי בְּאוֹתוֹ דֶּרֶךְ. כְּלוֹמַר, כִּי וַדַּאי תָּשׁוּבִי מִשָּׁם:",2,0],[31,21,"דֶּרֶךְ הָלָכְתְּ. הָלַכְתִּי כְּתִיב, וְכָל מָקוֹם שֶׁהָלַכְתְּ הָלַכְתִּי אֲנִי עִמָּךְ. וְיוֹנָתָן תִּרְגֵּם שִׂימִי לָךְ תַּמְרוּרִים ״הִתְפַּלֵּל בְּמָרַר נַפְשֵׁךְ״ (וּמְנַחֵם פֵּרֵשׁ תַּמְרוּרִין עִנְיַן מוֹעֵל, וְכֵן פֵּרֵשׁ ״וְתִימֲרוֹת עָשָׁן״ (יואל ג:ג) סא״א):",3,0],[31,22,"תִּתְחַמָּקִין. תִּסְתְּרִי מִמֶּנִּי, שֶׁאַתְּ בּוֹשָׁה לָשׁוּב אֱלֵי מִפְּנֵי דַּרְכֵּךְ. הִנֵּה חֲדָשָׁה נִבְרֵאת בָּאָרֶץ, שֶׁהַנְּקֵבָה תַּחֲזֹר אַחַר הַזָּכָר לְבַקְּשׁוֹ שֶׁיִּשָּׂאֶנָּה, לְשׁוֹן ״וַאֲסוֹבְבָהּ בָּעִיר אֲבַקְּשָׁהּ וְגוֹ׳״ (שִׁיר הַשִּׁירִים ג:ב); וּמִשּׁוּם רַבִּי יְהוּדָה הַדַּרְשָׁן שָׁמַעְתִּי: נְקֵבָה תְּסוֹבֵב לִהְיוֹת גָּבֶר, אֲנִי נְתַתִּיךְ כְּבַת הַנּוֹטֶלֶת עִשּׂוּר נְכָסִים שִׁבְעָה אֻמּוֹת מִשִּׁבְעִים, סוֹף שֶׁתִּטְּלִי הַכֹּל כְּבֶן זָכָר שֶׁהוּא יוֹרֵשׁ הַכֹּל:",1,0],[31,26,"עַל זֹאת הֱקִיצוֹתִי. כָּךְ אָמַר יִרְמְיָה, כָּל מַה שֶּׁהָיִיתִי יָשֵׁן וְנִרְדָּם בִּנְבוּאַת פֻּרְעָנוּת, בַּנְּבוּאָה הַזֹּאת הֱקִיצוֹתִי מִתַּרְדֵּמָתִי:",1,0],[31,26,"עָרְבָה. נְעֵמָה:",2,0],[31,27,"זֶרַע אָדָם וְזֶרַע בְּהֵמָה. הַטּוֹבִים וְהַסְּכָלִים שֶׁבָּהֶם, אֲנִי אֶזְרָעֵם כֻּלָּם לִהְיוֹת זֶרַע שֶׁלִּי. זֶרַע אָדָם וְזֶרַע בְּהֵמָה תִּרְגֵּם יוֹנָתָן: ״אֲקִימִינוּן כִּבְנֵי אֱנָשָׁא וְאַצְלְחִינוּן כִּבְעִירָא״, שֶׁאֵין עֲוֹנוֹתֶיהָ נִפְקָדִין עָלֶיהָ:",1,0],[31,29,"בֹּסֶר. פְּרִי שֶׁלֹּא נִגְמַר, וְהוּא מַקְהֶה אֶת הַשִּׁנַּיִם:",1,0],[31,29,"וְשִׁנֵּי בָנִים תִּקְהֶינָה. הַבָּנִים יִלְקוּ בַּעֲוֹן אָבוֹת:",2,0],[31,35,"לְאוֹר. אֵיאַקְלַארְזִי״ר בְּלַעַ״ז, וְכֵן תִּרְגֵּם יוֹנָתָן ״לְאַנְהָרָא״:",1,0],[31,35,"רוֹגַע הַיָּם. מְנִידוֹ וּמַרְתִּיחוֹ וְנַעֲשֶׂה קְמָטִים קְמָטִים, כְּמוֹ ״עוֹרִי רָגַע״ (איוב ז:ה):",2,0],[31,36,"יָמֻשׁוּ. כְּמוֹ ״לֹא יָמִישׁ״ (שמות יג:כב):",1,0],[31,37,"אִם יִמַּדּוּ שָׁמַיִם. כַּמָּה גָּבְהָם:",1,0],[31,37,"גַּם אֲנִי אֶמְאַס. בְּיִשְׂרָאֵל, כְּלוֹמַר כְּשֵׁם שֶׁהֵם לֹא יִמַּדּוּ וְלֹא יֵחָקְרוּ, כָּךְ יִשְׂרָאֵל לֹא יִמָּאֲסוּ בְּכָל אֲשֶׁר חָטְאוּ:",2,0],[31,40,"הָעֵמֶק הַפְּגָרִים. עֵמֶק שֶׁנָּפְלוּ שָׁם פִּגְרֵי מַחֲנֵה סַנְחֵרִיב (מלכים ב יט:לה; ישעיה לז:לו):",1,0],[31,40,"וְהַדֶּשֶׁן. מְקוֹם שֶׁפֶךְ הַדֶּשֶׁן שֶׁהָיָה חוּץ לִירוּשָׁלַיִם, יוֹסִיפוּ עַל הָעִיר וְיַכְנִיסוּ כָּל זֶה לְתוֹךְ חוֹמוֹתֶיהָ. וּנְבוּאָה זוֹ עֲתִידָה לָבֹא:",2,0],[31,40,"הַשְּׁדֵמוֹת. קַנְפַנְיָ״א בְּלַעַ״ז:",3,0],[32,2,"צָרִים. לְשׁוֹן ״מָצוֹר״ (דברים כ:יט):",1,0],[32,2,"בַּחֲצַר הַמַּטָּרָה. לְשׁוֹן בֵּית הַמִּשְׁמָר:",2,0],[32,5,"עַד פָּקְדִי אֹתוֹ. פְּקֻדַּת כָּל הָאָדָם הִיא הַמִּיתָה (במדבר טז:כט):",1,0],[32,6,"וַיֹּאמֶר יִרְמְיָהוּ וגו׳. לֹא לְצִדְקִיָּהוּ אָמַר כֵּן, אֶלָּא פֵּירֵשׁ הַכָּתוּב לָמָּה כְּלָאוֹ, וְחוֹזֵר לְדִבּוּרוֹ הָרִאשׁוֹן לְפָרֵשׁ מַה הַדָּבָר אֲשֶׁר הָיָה אֶל יִרְמְיָהוּ:",1,0],[32,7,"בָּא אֵלֶיךָ. עַל פִּי הַדִּבּוּר:",1,0],[32,11,"אֶת סֵפֶר הַמִּקְנָה. שְׁטַר הַמְּכִירָה:",1,0],[32,11,"אֶת הֶחָתוּם וְגוֹ׳. עִם חֲתִימָתוֹ, כְּשֶׁהוּא חָתוּם כְּדָת וְחֹק:",2,0],[32,11,"וְאֶת הַגָּלוּי. שֶׁהוּחְזַק בְּבֵית דִּין עַל פִּי עֵדָיו, וְכָתְבוּ וְחָתְמוּ הַדַּיָּנִין אַשְׁרְתָּא דְדַיָּנֵי, הוּא קִיּוּם הַשְּׁטָרוֹת (כתובות כא:), לַעֲשׂוֹת הַדָּבָר גָּלוּי וּמְפֻרְסָם, פֶּן יָמוּתוּ הָעֵדִים. וְרַבּוֹתֵינוּ פֵּרְשׁוּ לְעִנְיַן גֵּט פָּשׁוּט וּמְקֻשָּׁר בְּבָבָא בַּתְרָא (קס.-קס:):",3,0],[32,12,"לְעֵינֵי חֲנַמְאֵל דּוֹדִי. וְעַד עַכְשָׁו קְרָאוֹ בֶּן דּוֹדִי, שֶׁמָּא שְׁנַיִם הָיוּ, וְאִם אֵין זֹאת לֹא יָדַעְתִּי מַהוּ. וְיֵשׁ נוֹטִים לוֹמַר דּוֹדוֹ וּבֶן דּוֹדוֹ הָיָה חֲנַמְאֵל לְיִרְמְיָה, כְּגוֹן רְאוּבֵן נָשָׂא אֶת בַּת שִׁמְעוֹן אָחִיו וְיָלְדָה לוֹ נְמוּאֵל, וּכְבָר הוֹלִיד שִׁמְעוֹן יָמִין, הֲרֵי יָמִין דּוֹדוֹ לִנְמוּאֵל, שֶׁבֶּן אֲחִי אִמּוֹ הוּא וְגַם בֶּן דּוֹדוֹ, שֶׁהוּא בֶּן שִׁמְעוֹן אֲחִי אָבִיו שֶׁל נְמוּאֵל. וְאֵינָהּ הִיא הַמִּדָּה, שֶׁלֹּא מָצִינוּ בְּכָל הַמִּקְרָא אָח הָאֵם קָרוּי דּוֹד:",1,0],[32,14,"כֹּה אָמַר וְגוֹ׳. אַל תֹּאמַר: לְחִנָּם אֲנִי מַצְנִיעָם, שֶׁהֲרֵי הַכֹּל גּוֹלִים:",1,0],[32,15,"כִּי כֹה אָמַר ה׳. סוֹפָן לִקְנוֹת בָּתִּים:",1,0],[32,17,"לֹא יִפָּלֵא. לֹא יִכָּחֵד; וְיוֹדֵעַ אַתָּה שֶׁסּוֹפֵנוּ לִגְלוֹת, וְלָמָּה אָמַרְתָּ לִי לִקְנוֹת שָׂדֶה?",1,0],[32,18,"וּמְשַׁלֵּם עֲוֺן אָבוֹת אֶל חֵיק. הַדּוֹר הַזֶּה, הַהוֹלְכִים אַחֲרֵי אֲבוֹתֵיהֶם בְּדֶרֶךְ הָרָעָה:",1,0],[32,18,"הַגָּדוֹל הַגִּבּוֹר. וְלֹא אָמַר וְהַנּוֹרָא, אָמַר: עוֹבְדֵי אֱלִילִים מְרַקְּדִין בְּהֵיכָלוֹ, אַיֵּה נוֹרְאוֹתָיו? בְּמַסֶּכֶת יוֹמָא (יומא סט:):",2,0],[32,20,"וּבָאָדָם. בִּשְׁאָר אֲנָשִׁים. דָּבָר אַחֵר: אוֹתוֹת שֶׁהָיוּ שְׁקוּלִין לְיִשְׂרָאֵל וּלְמִצְרַיִם, כֵּיצַד? ״וַיְהִי הֶעָנָן וְהַחֹשֶׁךְ וַיָּאֶר הַלַּיְלָה״ (שמות יד:כ) – אוֹתוֹ מַזָּל שֶׁשִּׁמֵּשׁ חֹשֶׁךְ לְמִצְרַיִם, שִׁמֵּשׁ אוֹר לְיִשְׂרָאֵל; מִדְרַשׁ אַגָּדָה:",1,0],[32,23,"וַתַּקְרֵא אוֹתָם. הִקְרֵיתָ אוֹתָם; לְשׁוֹן ״מִקְרֶה״ (שמואל א ו:ט):",1,0],[32,24,"וַאֲשֶׁר דִּבַּרְתָּ. רָעָה עָלֶיהָ, הָיָה וּבָא:",1,0],[32,25,"וְהָעִיר נִתְּנָה. וְלָמָּה לִי שָׂדֶה?",1,0],[32,27,"הֲמִמֶּנִּי יִפָּלֵא. וְכִי הָעֲתִידוֹת עֲלוּמוֹת מִמֶּנִּי?",1,0],[32,31,"לְמִן הַיּוֹם אֲשֶׁר בָּנוּ אוֹתָהּ. בְּיוֹם שֶׁהוּסַד הַבַּיִת, נָשָׂא שְׁלֹמֹה אֶת בַּת פַּרְעֹה (ויקרא רבה יב, ה):",1,0],[32,33,"וְלַמֵּד אוֹתָם. לְשׁוֹן פָּעוּל, אפרננ״ט בְּלַעַ״ז:",1,0],[32,37,"הִנְנִי מְקַבְּצָם. בְּרַחֲמִים, מִכָּל אֲשֶׁר הִדַּחְתִּים שָׁם בְּאַפִּי:",1,0],[33,1,"עָצוּר. בְּבֵית הַכֶּלֶא:",1,0],[33,2,"כֹּה אָמַר ה׳ עֹשָׂהּ. הָעוֹשֶׂה זֹאת:",1,0],[33,3,"קְרָא אֵלַי וְאֶעֱנֶךָּ. לְהוֹדִיעֲךָ הָעֲתִידוֹת:",1,0],[33,3,"וּבְצוּרוֹת. שְׁמוּרוֹת בְּלִבִּי לַעֲשׂוֹתָם:",2,0],[33,4,"הַנְּתֻצִים אֶל הַסֹּלְלוֹת. לַעֲשׂוֹת מֵהֶם סֹלְלוֹת, תִּלִּים שֶׁצְּבוּרִים לְמַעְלָה, אֲשֶׁר בּוֹנִים בְּנֵי הָעִיר לַעֲלוֹת אֶל הַסֹּלְלוֹת, לְהִלָּחֵם מֵעֲלֵיהֶם אֶל הַכַּשְׂדִּים:",1,0],[33,4,"וְאֶל הֶחָרֶב. ״לְתַקְּפָא שׁוּרָא מִן קֳדָם דְּקָטְלִין בְּחַרְבָּא״ (תרגום יונתן):",2,0],[33,5,"וּלְמַלְּאָם אֶת פִּגְרֵי הָאָדָם. וְאֶת הַבָּתִּים אֲשֶׁר נָתְצוּ עוֹשִׂים קְבָרוֹת לַפְּגָרִים שֶׁנֶּהֱרָגִים בְּתוֹךְ הָעִיר:",1,0],[33,5,"וַאֲשֶׁר הִסְתַּרְתִּי וְגוֹ׳. כֹּה אָמַר ה׳ הִנְנִי מַעֲלֶה לָהּ וְגוֹ׳:",2,0],[33,6,"עֲתֶרֶת שָׁלוֹם. בִּרְכַּת שָׁלוֹם; שֶׁלוּ״ד בְּלַעַ״ז:",1,0],[33,12,"נְוֵה רוֹעִים. מְדוֹר רוֹעִים:",1,0],[33,13,"עוֹד תַּעֲבֹרְנָה הַצֹּאן וגו׳. יֵצְאוּ וְיָבֹאוּ יִשְׂרָאֵל עַל יְדֵי מַנְהִיג הוֹלֵךְ בְּרֹאשָׁם (מיכה ב:יג):",1,0],[33,17,"לֹא יִכָּרֵת. כְּרִיתוּת עוֹלָם, אֶלָּא אִם יִפְסוֹק, סוֹפוֹ לַחֲזוֹר:",1,0],[33,18,"כָּל הַיָּמִים. לֹא יִכָּרֵת לָהֶם זֶרַע הָרָאוּי לְהַעֲלוֹת עוֹלָה וּלְהַקְטִיר מִנְחָה:",1,0],[33,20,"אִם תָּפֵרוּ אֶת בְּרִיתִי הַיּוֹם. אִם תּוּכְלוּ לְהָפֵר אֶת בְּרִיתִי אֲשֶׁר כָּרַתִּי אֶת הַיּוֹם וְאֶת הַלַּיְלָה לִהְיוֹתָם בְּעִתָּם, אֲשֶׁר כָּרַתִּי לְנֹחַ וּבָנָיו ״וְיוֹם וָלַיְלָה לֹא יִשְׁבֹּתוּ״ (בראשית ח:כב):",1,0],[33,24,"שְׁתֵּי הַמִּשְׁפָּחוֹת. הַמַּלְכוּת וְהַכְּהֻנָּה (תנחומא, לך כ):",1,0],[33,24,"וְאֶת עַמִּי יִנְאָצוּן. וּבַדְּבָרִים הָאֵלֶּה הֵם גּוֹרְמִים לְעַמִּי לְנָאֵץ מִהְיוֹת גּוֹי לִי:",2,0],[33,24,"לִפְנֵיהֶם. לִפְנֵי דִּבְרֵיהֶם אֵלֶּה, שֶׁמְּלַמְּדִין אוֹתָןלוֹמַר: לֹא יָשׁוּב הַקָּדוֹשׁ בָּרוּךְ הוּא מֵחֲרוֹנוֹ עוֹד, וְלֹא תוֹעִיל לָכֶם תְּשׁוּבָה:",3,0],[33,25,"אִם לֹא בְרִיתִי וְגוֹ׳. אִי אֶפְשָׁר שֶׁלֹּא יִתְקַיֵּם הַבְּרִית שֶׁכָּרַתִּי לְיוֹם וָלַיְלָה לִהְיוֹת בְּעִתָּם, וְאִי אֶפְשָׁר לְחֻקּוֹת שָׁמַיִם וָאָרֶץ לִיבָּטֵל כְּאִלּוּ לֹא שַׂמְתִּים, ״גַּם זֶרַע יַעֲקֹב וְגוֹ׳״ (ירמיהו לג:כו). וְרַבּוֹתֵינוּ דְּרָשׁוּהוּ (נדרים לב.) לְעִנְיַן בְּרִית הַתּוֹרָה, לִלְמֹד מִכָּאן שֶׁבִּשְׁבִיל הַתּוֹרָה נִבְרְאוּ שָׁמַיִם וָאָרֶץ; אַךְ אֵין הַמִּדְרָשׁ מְיֻשָּׁב עַל סֵדֶר הַמִּקְרָאוֹת:",1,0],[34,5,"בְּשָׁלוֹם תָּמוּת. אָמְרוּ רַבּוֹתֵינוּ (מועד קטן כח:), שֶׁמֵּת נְבוּכַדְנֶצַּר בְּיָמָיו. שֶׁכָּל יְמֵי נְבוּכַדְנֶצַּר לֹא יָצְאוּ אֲסִירָיו מֵאֲסִירֵיהֶם, וּכְשֶׁמֵּת נְבוּכַדְנֶצַּר יָצָא צִדְקִיָּהוּ מִבֵּית הָאֲסוּרִים, וּלְמָחֳרָת מֵת וְקָבְרוּהוּ בְּכָבוֹד:",1,0],[34,5,"וּבְמִשְׂרְפוֹת אֲבוֹתֶיךָ. כָּךְ הָיָה דַּרְכָּם, לִשְׂרֹף עַל הַמְּלָכִים מִטָּתָן וּכְלֵי תַשְׁמִישָׁן (דברי הימים ב טז:יד; עבודה זרה יא.):",2,0],[34,8,"אַחֲרֵי כְּרוֹת הַמֶּלֶךְ. בַּשָּׁנָה הַשְּׁבִיעִית לְמָלְכוֹ. כָּךְ שָׁנִינוּ בְּסֵדֶר עוֹלָם (סדר עולם רבה כו): ״וַיְהִי בַּשָּׁנָה הַשְּׁבִיעִית… בָּאוּ אֲנָשִׁים מִזִּקְנֵי יְהוּדָה לִדְרֹשׁ אֶת ה׳״ (יחזקאל כ:א). אָמְרוּ לִיחֶזְקֵאל: עֶבֶד כֹּהֵן שֶׁמְּכָרוֹ רַבּוֹ, מַהוּ שֶׁיֹּאכַל בִּתְרוּמָה? כְּלוֹמַר, לְפִי שֶׁהָיוּ רוֹצִין לוֹמַר: לֹא נֶעֱנַשׁ עַל הַמִּצְוֹת, עַל שֶׁהֶחֱזִירוּ אֶת הָעֲבָדִים:",1,0],[34,17,"הִנְנִי קֹרֵא לָכֶם דְּרוֹר. מֵאִתִּי, שֶׁאֵינִי אָדוֹן לָכֶם לְהַצִּיל, וְתִהְיוּ הֶפְקֵר אֶל הַחֶרֶב וְאֶל הָרָעָב:",1,0],[34,18,"הָעֵגֶל אֲשֶׁר כָּרְתוּ לִשְׁנַיִם. כְּשֶׁחָזְרוּ וְכָבְשׁוּם, כָּרְתוּ כֻּלָּם בְּרִית לִמְרוֹד בַּמָּקוֹם, וְכָרְתוּ הָעֵגֶל לִשְׁנַיִם וְעָבְרוּ בֵּין בְּתָרָיו, לִמְרוֹד בּוֹ. וְהִיא הָיְתָה בְּרִית חֲזָקָה וּגְמוּרָה, לֵאמֹר: כָּכָה יִבָּתֵר וְיֵחָלֵק הָעוֹבֵר עָלֶיהָ (בראשית טו:ט-יז):",1,0],[34,21,"הָעוֹלִים מֵעֲלֵיכֶם. מִפְּנֵי חֵיל פַּרְעֹה שֶׁיָּצָא מִמִּצְרַיִם, כְּמוֹ שֶׁמְּפֹרָשׁ בְּסֵפֶר זֶה (ירמיה לז:ה):",1,0],[34,22,"הִנְנִי מְצַוֶּה. וְשָׁב חֵיל פַּרְעֹה לְאַרְצוֹ, וְהַכַּשְׂדִּים יָשׁוּבוּ עֲלֵיכֶם (ירמיה לז:ה-ח):",1,0],[35,2,"אֶל בֵּית הָרֵכָבִים. בְּנֵי יוֹנָדָב בֶּן רֵכָב (ירמיה לה:ו), וּמִבְּנֵי יִתְרוֹ הָיוּ (מכילתא יתרו עמלק ב):",1,0],[35,4,"אִישׁ הָאֱלֹהִים. ״נָבִיא דַּה׳״ (תרגום יונתן):",1,0],[35,4,"שׁוֹמֵר הַסַּף. ״אֲמַרְכְּלָא״ (תרגום יונתן), טְרֵשׁוֹרִי״ר בְּלַעַ״ז:",2,0],[35,7,"בָּאֳהָלִים תֵּשְׁבוּ. בַּמִּדְבָּרִיּוֹת. אֲשֶׁר אַתֶּם גָּרִים שָׁם. לֹא הָיָה לָהֶם חֵלֶק בָּאָרֶץ, שֶׁבְּנֵי גֵרִים הָיוּ (ספרי במדבר עח):",1,0],[35,11,"וַיְהִי בַּעֲלוֹת נְבוּכַדְרֶאצַּר. עַל כָּרְחֵנוּ בָּאנוּ הָעִיר, לְכָךְ עַכְשָׁיו אָנוּ יוֹשְׁבִים בַּבָּתִּים:",1,0],[36,5,"עָצוּר. בְּבֵית הַכֶּלֶא:",1,0],[36,10,"פֶּתַח שַׁעַר בֵּית ה׳ הֶחָדָשׁ. הוּא שַׁעַר הַמִּזְרָחִי, כֵּן תִּרְגֵּם יוֹנָתָן:",1,0],[36,16,"הַגֵּיד נַגִּיד לַמֶּלֶךְ. אוּלַי יִשְׁמַע:",1,0],[36,20,"חָצֵרָה. אֶל הֶחָצֵר. כָּל תֵּיבָה שֶׁצְּרִיכָה לָמֶ״ד בִּתְחִלָּתָהּ, הִטִּיל לָהּ הֵ״א בְּסוֹפָהּ (יבמות יג:):",1,0],[36,22,"וְאֶת הָאָח. פֵּרְשׁוּ רַבּוֹתֵינוּ (שבת כ.): עֵצִים; עַל שֵׁם שֶׁנִּדְלָקִים בְּאַחְוָה (כְּלוֹמַר שֶׁנִּדְלָקִים זֶה מִזֶּה כְּאַחִים שֶׁמְּהַנִּים זֶה לָזֶה סא״א). וּלְפִי פְשׁוּטוֹ מַשְׁמַע שֶׁהוּא כְּלִי שֶׁמְּבַעֲרִין עָלָיו אוּר לִפְנֵי הַשָּׂרִים:",1,0],[36,23,"שָׁלֹשׁ דְּלָתוֹת. רַבּוֹתֵינוּ אָמְרוּ (מועד קטן כו.): מְגִלַּת קִינוֹת הָיְתָה, קָרְאוּ לְפָנָיו ״אֵיכָה״, ״בָּכֹה תִבְכֶּה״, ״גָּלְתָה יְהוּדָה״, ״דַּרְכֵי צִיּוֹן אֲבֵלוֹת״ (איכה א:א-ד) – בְּכָל זֶה לֹא חָשׁ, אָמַר: אֲנִי מֶלֶךְ עַל הַנּוֹתָרִים; כֵּיוָן שֶׁקָּרָא ״הָיוּ צָרֶיהָ לְרֹאשׁ״ (איכה א:ה), אָמַר: מֵעַכְשָׁיו אֵינִי מֶלֶךְ; מִיָּד וַיִּקְרָעֶהָ בְּתַעַר הַסֹּפֵר:",1,0],[36,23,"יִקְרָעֶהָ. כְּמוֹ קְרָעָהּ:",2,0],[36,25,"הִפְגִּיעוּ. הִתְחַנְּנוּ:",1,0],[36,32,"דְּבָרִים רַבִּים כָּהֵמָּה. מִתְּחִלָּה הָיוּ שָׁלֹשׁ אַלְפָא בֵּיתִין: ״אֵיכָה יָשְׁבָה״ (איכה א:א), ״אֵיכָה יָעִיב״ (איכה ב:א), ״אֵיכָה יוּעַם״ (איכה ד:א), וְהוֹסִיף עָלֶיהָ ״אֲנִי הַגֶּבֶר״ (איכה ג:א), שֶׁכָּל אוֹת מְשֻׁלֶּשֶׁת בָּהּ (איכה רבה ג:א):",1,0],[37,1,"וַיִּמְלֹךְ מֶלֶךְ. לְפִי שֶׁמֵּעַתָּה בָּא לְסַפֵּר וְלוֹמַר שֶׁנִּתְקַיְּמוּ הַפּוּרְעָנִיּוֹת שֶׁנִּבָּא עַד הֵנָּה, הִתְחִיל לוֹמַר כֵּן: וּבְבֹא עֵת הַפְּקֻדָּה, שֶׁקָּרְבוּ הַיָּמִים לְהִתְקַיֵּם הַדְּבָרִים, וַיִּמְלֹךְ מֶלֶךְ אַחֵר עַל יְהוּדָה תַּחַת כָּנְיָהוּ בֶּן יְהוֹיָקִים וְגוֹ׳:",1,0],[37,4,"וְיִרְמְיָהוּ בָּא וְיֹצֵא בְּתוֹךְ הָעָם. כְּשֶׁמָּלַךְ צִדְקִיָּהוּ, צִוָּה וְהוֹצִיאוּהוּ מִבֵּית הַכֶּלֶא שֶׁכְּלָאוֹ יְהוֹיָקִים. שֶׁצִּדְקִיָּה הָיָה צַדִּיק וְדוֹרוֹ רְשָׁעִים, וִיהוֹיָקִים הָיָה רָשָׁע וְדוֹרוֹ צַדִּיקִים (סנהדרין קג.):",1,0],[37,5,"וְחֵיל פַּרְעֹה יָצָא מִמִּצְרָיִם. לְעֶזְרָה לִיהוּדָה:",1,0],[37,7,"שָׁב לְאַרְצוֹ מִצְרָיִם. בִּסְפִינוֹת הָיוּ בָאִים, וְרָמַז הַקָּדוֹשׁ בָּרוּךְ הוּא לַיָּם, וְהֵצִיף עָלָיו כְּמוֹ נוֹדוֹת וְאוֹבוֹת (כְּלוֹמַר נְפוּחוֹת) דּוֹמוֹת לְעוֹרוֹת בְּנֵי אָדָם. אָמְרוּ זֶה לָזֶה: מַה זֹּאת? אָמְרוּ: אֵלּוּ אֲבוֹתֵינוּ, שֶׁטִּבְּעוּם אֲבוֹתֵיהֶם שֶׁל אֵלּוּ שֶׁאָנוּ הוֹלְכִים לְעֶזְרָתָם בַּיָּם. מִיָּד שָׁבוּ לְאַרְצָם (איכה רבה ד, כ):",1,0],[37,12,"לַחֲלִק מִשָּׁם בְּתוֹךְ הָעָם. ״לְפַלְגָא אַחֲסַנְתָּא דִילֵיהּ בְּגוֹ עַמָּא״ (תרגום יונתן). וּבְעוֹד הַכַּשְׂדִּים צָרִים עָלֶיהָ לֹא הָיָה יוֹצֵא מִמֶּנָּה, שֶׁמִּתְפַּלֵּל עַל הָעִיר שֶׁלֹּא תִלָּכֵד:",1,0],[37,13,"וְשָׁם בַּעַל פְּקִדֻת. מְמֻנֶּה לִשְׁמֹר שֶׁלֹּא יֵצֵא אִישׁ מִן הָעִיר לְהַשְׁלִים אֶל הַכַּשְׂדִּים:",1,0],[37,13,"בֶּן שֶׁלֶמְיָה בֶּן חֲנַנְיָה. הוּא חֲנַנְיָה בֶּן עַזּוּר (ירמיה כח:א). בֶּן בְּנוֹ הָיָה זֶה, וּלְכָךְ יִחֲסוֹ הַכָּתוּב, לְלַמֵּד שֶׁכָּל הַמַּחֲנִיף לָרָשָׁע סוֹף נוֹפֵל בְּיָדוֹ (סוטה מא:) אוֹ בְּיַד בְּנוֹ אוֹ בְּיַד בֶּן בְּנוֹ; וְיִרְמְיָה הֶחֱנִיף לוֹ, שֶׁאָמַר לוֹ: ״אָמֵן יָקֵם ה׳ אֶת דְּבָרֶיךָ״ (ירמיה כח:ו). וּמִדְרַשׁ אַגָּדָה: שֶׁצִּוָּה חֲנַנְיָה אֶת בְּנוֹ: רְאֵה שֶׁאֲנִי מֵת עַל יְדֵי יִרְמְיָה, וְהֶעֱמִידַנִי שַׁקְרָן בִּנְבוּאָתִי; אִם תּוּכַל לְהַכְשִׁילוֹ, הַכְשִׁילֵהוּ. וּבְנוֹ צִוָּה גַּם הוּא לְבָנָיו כָּךְ, וּכְשֶׁהִגִּיעַ שָׁעָה, הִכְשִׁילוֹ:",2,0],[37,16,"וְאֶל הַחֲנֻיּוֹת. תִּרְגֵּם יוֹנָתָן: ״לְגַיו מִן חֲנָוָאתָא״; חֲנֻיּוֹת הָיוּ לִפְנֵי אוֹתוֹ בֵּית הַכֶּלֶא:",1,0],[37,21,"מֵחוּץ הָאֹפִים. מִשּׁוּק נַחְתּוֹמִים, כְּמוֹ ״וְחֻצוֹת תָּשִׂים לְךָ בְדַמֶּשֶׂק״ (מלכים א כ:לד):",1,0],[38,2,"וְהָיְתָה לוֹ נַפְשׁוֹ לְשָׁלָל. וְהָיוּ לוֹ חַיָּיו הַצָּלָה, כְּאִלּוּ שָׁלַל נַפְשׁוֹ; כְּאָדָם הַשּׁוֹלֵל שָׁלָל וּמִשְׂתַּכֵּר, כָּךְ יִשְׂתַּכֵּר זֶה נַפְשׁוֹ:",1,0],[38,4,"עַל כֵּן הוּא מְרַפֵּא. אֶלַאקְנְ״ץ בְּלַעַ״ז, לְשׁוֹן רִפְיוֹן:",1,0],[38,5,"יוּכַל. כְּמוֹ יָכוֹל, עַל אֲשֶׁר הוּא מְרַפֵּא אֶת וְגוֹ׳:",1,0],[38,6,"הַבּוֹר מַלְכִּיָּהוּ. שֶׁל מַלְכִּיָּהוּ:",1,0],[38,7,"עֶבֶד מֶלֶךְ. בָּרוּךְ בֶּן נֵרִיָּה:",1,0],[38,7,"הַכּוּשִׁי. צִדְקִיָּהוּ: מָה כּוּשִׁי מְשֻׁנֶּה בְּעוֹרוֹ, אַף צִדְקִיָּהוּ מְשֻׁנֶּה בְּצִדְקוֹ מִכָּל דּוֹרוֹ (מועד קטן טז:). וְיֵשׁ מִדְרָשׁ דּוֹרֵשׁ הַכּוּשִׁי עַל בָּרוּךְ (ספרי במדבר צט):",2,0],[38,7,"אִישׁ סָרִיס. גֶּבֶר רַב:",3,0],[38,9,"וַיָּמָת תַּחְתָּיו וגו׳. אִלּוּ הִנִּיחוּ אוֹתוֹ בִּמְקוֹמוֹ הָיָה מֵת מֵאֵלָיו בָּרָעָב, וְהֵם הֵרֵעוּ לְקָרֵב מִיתָתוֹ:",1,0],[38,10,"שְׁלֹשִׁים אֲנָשִׁים. מִתּוֹךְ שֶׁכֹּחָן תַּשׁ בָּרָעָב, נִצְרְכוּ כֻּלָּן:",1,0],[38,11,"בְּלוֹיֵי סְחָבוֹת. בְּלוּאֵי בְגָדִים הַנִּסְחָבִים:",1,0],[38,12,"וְהַמְּלָחִים. לְשׁוֹן רִקָּבוֹן, כְּמוֹ ״כֶּעָשָׁן נִמְלָחוּ״ (ישעיה נא:ו):",1,0],[38,12,"תַּחַת אַצִּלוֹת יָדֶיךָ. שֶׁלֹּא יַזִּיקוּךָ הַחֲבָלִים:",2,0],[38,12,"אַצִּילוֹת. אֵיישִׁילָ״שׁ בְּלַעַ״ז:",3,0],[38,14,"מָבוֹא הַשְּׁלִישִׁי. לֹא יָדַעְתִּי הֵיכָן הוּא. וְשֶׁמָּא בְּעֶזְרַת יִשְׂרָאֵל הִיא, לוֹמַר שֶׁהַחֵיל וְעֶזְרַת נָשִׁים לְפָנֶיהָ (משנה סכה ה,ד):",1,0],[38,19,"דּוֹאֵג. יָרֵא:",1,0],[38,19,"פֶּן יִתְּנוּ אוֹתִי. הַכַּשְׂדִּים בְּיַד הַיְּהוּדִים, לוֹמַר: מַלְכְּכֶם יְהִי עַבְדְּכֶם עַל שֶׁקְּדַמְתֶּם לְהַשְׁלִים עִמָּנוּ:",2,0],[38,19,"וְהִתְעַלְּלוּ בִי. הַיְּהוּדִים. אִיגְבְּרוֹנְ״ט בְּלַעַ״ז:",3,0],[38,22,"אַנְשֵׁי שְׁלוֹמֶךָ. נְבִיאֵי הַשֶּׁקֶר, שֶׁאָמְרוּ לְךָ: לֹא תִלָּכֵד:",1,0],[38,22,"בַּבֹּץ. טִיט, לְשׁוֹן ״הֲיִגְאֶה גֹּמֶא בְּלֹא בִצָּה״ (איוב ח:יא):",2,0],[38,23,"וְאֶת הָעִיר הַזֹּאת תִּשְׂרֹף בָּאֵשׁ. הֲרֵי אַתָּה כְּאִלּוּ שׂוֹרְפָהּ בְּיָדַיִם, שֶׁאַתָּה גּוֹרֵם לָהּ:",1,0],[39,3,"וַיָּבֹאוּ כָּל שָׂרֵי מֶלֶךְ בָּבֶל וַיֵּשְׁבוּ בְּשַׁעַר הַתָּוֶךְ וְגוֹ׳. מַגִּיד שֶׁנִּתְקַיְּמָה כָּאן נְבוּאָה עֶלְיוֹנָה: ״וּבָאוּ וְנָתְנוּ אִישׁ כִּסְאוֹ פֶּתַח שַׁעֲרֵי יְרוּשָׁלִַם וְגוֹ׳״ (ירמיה א:טו):",1,0],[39,3,"בְּשַׁעַר הַתָּוֶךְ. ״בְּתַרְעָא מְצִיעָתָא״ (תרגום יונתן); שַׁעַר הָעֲזָרָה, שַׁעַר נִיקָנוֹר הַמִּזְרָחִי, וְהוּא בֵּין שַׁעַר עֶזְרַת נָשִׁים וּבֵין שַׁעַר הַהֵיכָל. וְרַבּוֹתֵינוּ אָמְרוּ שַׁעַר הַתָּוֶךְ שַׁעַר שֶׁמְּחַתְּכִין בּוֹ הֲלָכוֹת, עֲלֵיהֶם הוּא אוֹמֵר ״מְקוֹם הַמִּשְׁפָּט שָׁמָּה הָרֶשַׁע״ (קהלת ג:טז):",2,0],[39,4,"דֶּרֶךְ גַּן הַמֶּלֶךְ. מְעָרָה הָיְתָה לוֹ מִבֵּיתוֹ עַד עַרְבוֹת יְרֵחוֹ, וַיֵּצְאוּ לֵילֵךְ דֶּרֶךְ הַמְּעָרָה (פסיקתא רבתי כו); מָה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא, לְקַיֵּם ״וּפָרַשְׂתִּי אֶת רִשְׁתִּי עָלָיו״ (יחזקאל יב:יג)? זִמֵּן צְבִי לִפְנֵי הַכַּשְׂדִּים מְהַלֵּךְ עַל גַּג הַמְּעָרָה חוּץ לָעִיר, וְרָצוּ אַחֲרָיו לְתָפְשׂוֹ וְהוּא רָץ עַד פֶּתַח הַמְּעָרָה, וְרָאוּ אֶת צִדְקִיָּהוּ יוֹצֵא מִן הַמְּעָרָה:",1,0],[39,5,"וַיְדַבֵּר אִתּוֹ מִשְׁפָּטִים. לָמָּה עָבַרְתָּ עַל הַשְּׁבוּעָה?!",1,0],[39,6,"וְאֵת כָּל חוֹרֵי יְהוּדָה. אֵלּוּ הַסַּנְהֶדְרִין, עַל שֶׁהִתִּירוּ לוֹ אֶת שְׁבוּעָתוֹ (תנחומא, ואתחנן א). הַחֵטְא הָיָה בְּעֵינֵי הָאֱלֹהִים שֶׁהִתִּירוּ הַשְּׁבוּעָה:",1,0],[39,8,"וְאֶת בֵּית הָעָם. בָּתֵּי כְנֵסִיּוֹת (שבת לב.):",1,0],[39,10,"כְּרָמִים וִיגֵבִים. שָׂדוֹת לְעָבְדָם. כָּל יְגִיבָה לְשׁוֹן חֲפִירָה, אַפּוֹשִׁי״ץ בְּלַעַ״ז:",1,0],[39,13,"רַבֵּי. כְּמוֹ שָׂרֵי:",1,0],[39,14,"אֶל גְּדַלְיָהוּ בֶן אֲחִיקָם. שֶׁנָּפַל אֶל הַכַּשְׂדִּים עַל פִּי יִרְמְיָה, וּכְשֶׁנִּלְכְּדָה הָעִיר מִנָּהוּ שַׁלִּיט בַּנִּשְׁאָרִים שָׁם:",1,0],[39,16,"וְהָיוּ לְפָנֶיךָ בַּיּוֹם הַהוּא. וְהָיוּ הַדְּבָרִים לְפָנֶיךָ, שֶׁתִּרְאֶה אוֹתָם מִתְקַיְּמִים:",1,0],[39,17,"בְּיַד הָאֲנָשִׁים. בְּיַד הַכַּשְׂדִּים:",1,0],[40,1,"הַדָּבָר אֲשֶׁר הָיָה. מַה שֶׁנֶּאֱמַר בְּסוֹף הָעִנְיָן: ״וַיְהִי מִקֵּץ עֲשֶׂרֶת יָמִים וַיְהִי דְבַר ה׳ וְגוֹ׳״ (ירמיה מב:ז), אֶלָּא שֶׁכָּתַב תְּחִלָּה עַל מָה נֶאֱמַר לוֹ. וּמִדְרַשׁ אַגָּדָה בְּאֵיכָה רַבָּתִי (איכה רבה פתיחתא לד): מַה הָיָה הַדָּבָר? – וְשׁוּבָה אֶל גְּדַלְיָהוּ. אָמַר לוֹ: אוֹ אַתְּ נָחִית עִמְּהוֹן וַאֲנָא מְסוֹבֵר הָכָא, אוֹ אַתְּ סוֹבֵר הָכָא וַאֲנָא נָחִית עִמְּהוֹן; אָמַר: אִין אֲנָא נָחִית עִמְּהוֹן, מָה אֲנָא מְהַנֵּי לְהוֹן? אֶלָּא יֵיחוֹת בָּרְיֵיהוֹן עִמְּהוֹן, דְּסַגִּין הוּא מְהַנֵּי לְהוֹן:",1,0],[40,1,"מִן הָרָמָה. שֶׁהָיָה גּוֹלֶה מֵעַצְמוֹ עִמָּהֶן; הָיָה רוֹאֶה כַּת שְׁלוּלִים בְּקוֹלָרִין, הָיָה מַכְנִיס צַוָּארוֹ בֵּינֵיהֶם, וְכוּ׳; כִּדְאִיתָא בִּפְסִיקְתָּא (פסיקתא דרב כהנא יג, ט) דְּאַפְטַרְתָּא ״דִּבְרֵי יִרְמְיָהוּ״ (ירמיה א:א). שֶׁאִי אֶפְשָׁר לוֹמַר שֶׁנְּתָנוֹ נְבוּזַרְאֲדָן בָּאזִקִּים, שֶׁהֲרֵי צִוָּה נְבוּכַדְנֶצַּר: ״אַל תַּעַשׂ לוֹ מְאוּמָה רָע״ (ירמיה לט:יב):",2,0],[40,1,"בָּאזִקִּים. בְּזִיאוֹ״שׁ בְּלַעַ״ז:",3,0],[40,2,"ה׳ אֱלֹהֶיךָ דִּבֶּר וְגוֹ׳. לָמָּה אַתָּה מִצְטַעֵר עֲלֵיהֶם? וַהֲלֹא אַתָּה נִבֵּאתָ לָהֶם וְלֹא שָׁמְעוּ; כִּדְאִיתָא בַּפְּסִיקְתָּא (פסיקתא דרב כהנא יג, ט):",1,0],[40,4,"פִתַּחְתִּיךָ. לְשׁוֹן ״וַיְפַתַּח הַגְּמַלִּים״ (בראשית כד:לב), וְכַן תִּרְגֵּם יוֹנָתָן: ״וּכְעַן הָא שָׁרִיתָךְ״. וּמְנַחֵם פָּתַר כֻּלָּם לְשׁוֹן פְּתִיחָה מַמָּשׁ:",1,0],[40,5,"וְעוֹדֶנּוּ לֹא יָשׁוּב. בְּכָל זֹאת לֹא הָיָה חָפֵץ לָשׁוּב; אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: וְשֻׁבָה אֶל גְּדַלְיָה, אֲשֶׁר הֻפְקַד עַל הָעֲנִיִּים הַנִּשְׁאָרִים; גַּם הֵם צְרִיכִין לְךָ, כִּשְׁאָר הַגּוֹלִים:",1,0],[40,5,"אֲרוּחָה וּמַשְׂאֵת. ״מַתְּנָן וּנְבִזְבְּזָן״ (תרגום יונתן):",2,0],[40,10,"וְקַיִץ. דְּבֵלָה:",1,0],[41,1,"וְרַבֵּי הַמֶּלֶךְ. וְשָׂרֵי הַמֶּלֶךְ. נִתְקַנְּאוּ בּוֹ שֶׁנָּטַל גְּדֻלָּה:",1,0],[41,5,"לְהָבִיא בֵּית ה׳. כְּשֶׁנָּסְעוּ מִבֵּיתָם לֹא הָיוּ יוֹדְעִים בְּחֻרְבַּן הַבַּיִת, וּבַדֶּרֶךְ שָׁמְעוּ וְקָרְעוּ בִּגְדֵיהֶם וְגִלְּחוּ זְקָנָם (מועד קטן כו.):",1,0],[41,5,"וּמִתְגּוֹדְדִים. לְשׁוֹן שְׂרִיטָה:",2,0],[41,9,"אֲשֶׁר הִכָּה בְּיַד גְּדַלְיָהוּ. מִתּוֹךְ שֶׁהָיָה לוֹ לָחוּשׁ לַעֲצַת יוֹחָנָן בֶּן קָרֵחַ וְלֹא חָשׁ (ירמיה מ:יג-טז), הֶעֱלָה עָלָיו כְּאִלּוּ נֶהֶרְגוּ עַל יָדוֹ (נדה סא.):",1,0],[41,12,"אֶל מַיִם רַבִּים. ״עַל בְּרֵכַת מַיִּין סַגִּיאִין״ (תרגום יונתן):",1,0],[41,17,"בְּגֵרוּת כִּמְהָם. ״בְּגֵרוּת דִּיהַב דָּוִד לְכִמְהָם בַּר בַּרְזִלַּי גִּלְעָדָאָה״ (תרגום יונתן), כְּשֶׁשָּׁב מִמִּלְחֶמֶת אַבְשָׁלוֹם, כְּמוֹ שֶׁנֶּאֱמַר בְּסֵפֶר שְׁמוּאֵל ״אִתִּי יַעֲבֹר כִּמְהָם וְגוֹ׳״ (שמואל ב יט:לט):",1,0],[42,14,"וְקוֹל שׁוֹפָר. שֶׁתּוֹקְעִין הַצּוֹפִים לְהַזְהִיר אֶת הָעָם:",1,0],[43,9,"וּטְמַנְתָּם בַּמֶּלֶט. מ״ם זוֹ יְסוֹד נוֹפֵל הִיא בַּתֵּיבָה, כְּמוֹ מָקוֹם, מַעֲמָד, מַעֲשֶׂה; וִיסוֹדוֹ לָט, כְּמוֹ ״וַיָּלֶט פָּנָיו״ (מלכים א יט:יג): לְאַט אוֹתָהּ בְּתוֹךְ הַטִּיט בַּמַּלְבֵּן. בַּמֶּלֶט אַנְוְלוֹפְמַנְטוֹ בְּלַעַ״ז:",1,0],[43,10,"שַׁפְרִירוֹ. אָהֳלוֹ, וְדֻגְמָתוֹ: ״בְּרוּחוֹ שָׁמַיִם שִׁפְרָה״ (איוב כו:יג):",1,0],[43,12,"וְעָטָה אֶת אֶרֶץ מִצְרַיִם. יִכְרוֹךְ כָּל שְׁלָלָהּ וְיֵצֵא, כַּאֲשֶׁר יִכְרוֹךְ וְיִגְלוֹל הָרֹעֶה אֶת בִּגְדּוֹ וְיַשְׁלִיכוֹ מֵעַל כְּתֵפָיו כְּשֶׁהוּא מוֹלִיךְ צֹאנוֹ לְפָנָיו:",1,0],[43,13,"אֶת מַצְּבוֹת בֵּית שֶׁמֶשׁ. מִזְבְּחוֹת שֶׁעָשׂוּ שָׁם אוֹתָם שֶׁנִּתְגַּיְּרוּ בִּימֵי חִזְקִיָּהוּ, שְׁבוּיֵי סַנְחֵרִיב שֶׁהוֹלִיךְ מִכּוּשׁ וּמִמִּצְרַיִם לִפְנֵי יְרוּשָׁלַיִם בְּיוֹם מַפַּלְתּוֹ; כְּמוֹ שֶׁאָמַר (ישעיהו יט:יח): ״בַּיּוֹם הַהוּא יִהְיוּ חָמֵשׁ עָרִים בְּאֶרֶץ מִצְרַיִם מְדַבְּרוֹת שְׂפַת כְּנַעַן וְנִשְׁבָּעוֹת לַה׳ צְבָאוֹת עִיר הַהֶרֶס יֵאָמֵר לְאַחַת״, וְתִרְגֵּם יוֹנָתָן: ״עִיר קַרְתָּא בֵּית שֶׁמֶשׁ דַּעֲתִידָא לְמֵיחֲרַב יִתְאַמַּר דְּהִיא חֲדָא מִנְּהוֹן״:",1,0],[44,10,"לֹא דֻכְּאוּ. לִבָּם מֵרָעָתָם:",1,0],[44,14,"כִּי אִם פְּלֵטִים. יִרְמְיָה וּבָרוּךְ חָזְרוּ לְשָׁם, שֶׁהִגְלָה נְבוּכַדְנֶאצַּר כְּשֶׁנִּתְּנָה אֶרֶץ מִצְרַיִם בְּיָדוֹ בְּעֶשְׂרִים וְשֶׁבַע לְמָלְכוֹ (יחזקאל כט:יז-כ). כָּךְ שְׁנוּיָה בְּסֵדֶר עוֹלָם (סדר עולם רבה כו):",1,0],[44,19,"הֲמִבַּלְעֲדֵי אֲנָשֵׁינוּ. שֶׁלֹּא מִדַּעְתָּם:",1,0],[44,19,"כַּוָּנִים לְהַעֲצִיבָהּ. דְּפוּסִים כִּדְמוּת עֲצַבִּים (עֲצַבִּים דְּמוּת עַלְמָה כְּמוֹ לְעֵיל כב):",2,0],[44,22,"וְלֹא יוּכַל ה׳ עוֹד לָשֵׂאת. כְּמוֹ וְלֹא יָכוֹל:",1,0],[44,30,"פַּרְעֹה חָפְרַע. ״פַּרְעֹה תְּבִירָא״ (תרגום יונתן); וְחִי״ת זוֹ מְשַׁמֶּשֶׁת בִּמְקוֹם הֵ״א:",1,0],[45,3,"וּמְנוּחָה לֹא מָצָאתִי. לֹא שָׁרְתָה עָלַי שְׁכִינָה לְהִנָּבֵא; כְּמוֹ ״וַתָּנַח עֲלֵיהֶם הָרוּחַ״ (במדבר יא:כו). מָה נִשְׁתַּנֵּיתִי מִתַּלְמִידֵי הַנְּבִיאִים: יְהוֹשֻׁעַ שִׁמֵּשׁ אֶת מֹשֶׁה – נָחָה עָלָיו רוּחַ הַקֹּדֶשׁ; אֱלִישָׁע שִׁמֵּשׁ אֶת אֵלִיָּהוּ – נָחָה עָלָיו רוּחַ הַקֹּדֶשׁ; אֲנִי – מָה נִשְׁתַּנֵּיתִי? (מכילתא בא פסחא א)",1,0],[45,4,"וְאֶת כָּל הָאָרֶץ. הִיא הַנִּדּוֹנֶת בִּנְתִישָׁה וַהֲרִיסָה זוֹ:",1,0],[45,5,"תְּבַקֵּשׁ לְךָ גְדֹלוֹת. נְבוּאוֹת, כְּמוֹ ״סַפְּרָה נָא לִי אֵת כָּל הַגְּדֹלוֹת וְגוֹ׳״ (מלכים ב ח:ד), ״קְרָא אֵלַי וְאַגִּידָה לְךָ גְּדֹלוֹת וְגוֹ׳״ (ירמיה לג:ג). אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: אִם אֵין כֶּרֶם אֵין סְיָג, וְאִם אֵין צֹאן אֵין רוֹעֶה; אֵינִי נִגְלֶה עַל הַנְּבִיאִים אֶלָּא בִּזְכוּתָם שֶׁל יִשְׂרָאֵל. כָּךְ שְׁנוּיָה בַּמְּכִילְתָּא בִּתְחִלָּתָהּ (מכילתא בא פסחא א):",1,0],[46,3,"מָגֵן. שֶׁל עוֹר הוּא, וְהוּא שָׁלוּק; וּכְשֶׁיּוֹצֵא לַמִּלְחָמָה מוֹשְׁחוֹ בְּשֶׁמֶן:",1,0],[46,3,"צִנָּה. שֶׁל עֵץ, דְּמוּת תְּרִיסִין שֶׁלָּנוּ:",2,0],[46,4,"מִרְקוּ הָרְמָחִים. כְּמוֹ ״וּמֹרַק וְשֻׁטַּף״ (ויקרא ו:כא); פורביר בְּלַעַ״ז:",1,0],[46,5,"הֵמָּה חַתִּים. מִצְרַיִם:",1,0],[46,5,"וְלֹא הִפְנוּ. עוֹד לַעֲמוֹד בַּמִּלְחָמָה, לֹא הָיָה לָהֶם פְּנַאי:",2,0],[46,7,"כַּיְאֹר יַעֲלֶה. שֶׁהָיָה רָגִיל לְהַעֲלוֹת גְּיָסוֹת סְבִיבָיו כְּמוֹ נָהָר, לִשְׁטֹף סְבִיבָיו:",1,0],[46,7,"יִתְגָּעֲשׁוּ מֵימָיו. ״דְּמִטָּרְפִין מוֹהִי״ (תרגום יונתן):",2,0],[46,8,"כַּיְאוֹר יַעֲלֶה. הָיָה רָגִיל לַעֲלוֹת:",1,0],[46,8,"אוֹבִידָה. כְּמוֹ אֲאַבֵּד:",2,0],[46,9,"וְהִתְהוֹלְלוּ. לְשׁוֹן סִכְלוּת:",1,0],[46,10,"וְרָוְתָה. לְשׁוֹן שֹׂבַע. לָשׁוֹן אַחֵר: לְשׁוֹן שִׁכָּרוֹן, כְּמוֹ ״שֵׁכָר״ (במדבר ו:ג) דִּמְתַרְגְּמִינָן: ״מְרַוֵי״ (תרגום אונקלוס):",1,0],[46,10,"בְּאֶרֶץ צָפוֹן. שֶׁהָלַךְ פַּרְעֹה עַל נְבוּכַדְנֶצַּר בְּכַרְכְּמִישׁ, וְגַם נָפַל וְנֶהֶרְגוּ גִּבּוֹרָיו (ירמיה מו:ב-ו), וְהוּא בָּרַח מִן הַמִּלְחָמָה:",2,0],[46,12,"גִּבּוֹר בְּגִבּוֹר כָּשָׁלוּ. כְּשֶׁהָיוּ בּוֹרְחִים הָיוּ נִכְשָׁלִים וְנִתְקָלִים זֶה בָּזֶה:",1,0],[46,13,"לָבוֹא נְבוּכַדְרֶאצַּר. זוֹ מַכָּה שְׁנִיָּה, שֶׁהֶחֱרִיב נְבוּכַדְנֶצַּר אֶת מִצְרַיִם בִּשְׁנַת עֶשְׂרִים וְשֶׁבַע לְמָלְכוֹ (יחזקאל כט:יז), כְּמוֹ שֶׁשָּׁנִינוּ בְּסֵדֶר עוֹלָם (סדר עולם רבה כו):",1,0],[46,14,"הִתְיַצֵּב וְהָכֵן לָךְ. כְּנֶגֶד הַמִּלְחָמָה, וְהָכֵן וְאַתְקִין:",1,0],[46,15,"נִסְחַף. נִשְׁטְפוּ וְהֶחֱלִיקוּ גִבּוֹרֶיךָ, כְּמוֹ ״מָטָר סֹחֵף״ (משלי כח:ג), נִסְתַּחֲפָה שָׂדֵהוּ בִּלְשׁוֹן מִשְׁנָה (כתבות ז,ח). וּמְנַחֵם חִבְּרוֹ לְשׁוֹן כִּלָּיוֹן, וְכֵן חִבֵּר ״מָטָר סֹחֵף״. וְדוֹנָשׁ פָּתַר ״מָטָר סֹחֵף״ כְּמוֹ מָטָר סוֹעֵף, כְּמוֹ ״מְסָעֵף פֻּארָה בְּמַעֲרָצָה״ (ישעיהו י:לג):",1,0],[46,16,"הִרְבָּה כּוֹשֵׁל. הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהֲדָפוֹ, וְהִרְבָּה לוֹ מִכְשׁוֹל:",1,0],[46,16,"גַּם נָפַל. נִתְקַבְּצוּ אִישׁ אֶל רֵעֵהוּ לֵאמֹר נָקוּמָה וְנָשׁוּבָה אֶל עַמֵּנוּ, מִמָּקוֹם שֶׁיָּצָאנוּ מִשָּׁם לְהִלָּחֵם:",2,0],[46,16,"חֶרֶב הַיּוֹנָה. ״חַרְבָּא דְּסָנְאָה דְּהִיא כְּחַמְרָא מְרַוְיָא״ (תרגום יונתן); הַיּוֹנָה לְשׁוֹן יַיִן. לָשׁוֹן אַחֵר: לְשׁוֹן אוֹנָאָה:",3,0],[46,17,"קָרְאוּ שָׁם. בַּמִּלְחָמָה הִכְרִיזוּ מָשָׁל שֶׁל חֶרְפָּה:",1,0],[46,17,"פַּרְעֹה מֶלֶךְ מִצְרַיִם שָׁאוֹן. שֶׁהָיָה מַגְבִּיהַּ קוֹל שָׁאוֹנוֹ תְּשׁוּאוֹת, לְהִתְהַלֵּל בְּחֵילוֹתָיו:",2,0],[46,17,"הֶעֱבִיר הַמּוֹעֵד. שֶׁיִּעֵד הַיּוֹם מִלְחָמָה קָבוּעַ לָצֵאת וּלְהִלָּחֵם וְלֹא יָצָא, וְעָבַר יוֹם זְמַן הַמּוֹעֵד (מועד קטן טז.):",3,0],[46,18,"כִּי כְתָבוֹר בֶּהָרִים. כִּי כַּאֲשֶׁר דְּבַר אֱמֶת הוּא שֶׁתָּבוֹר קָבוּעַ בֶּהָרִים וְהַר הַכַּרְמֶל עַל הַיָּם, כֵּן בֶּאֱמֶת יָבוֹא הַדָּבָר הַזֶּה עַל מִצְרַיִם (מכילתא יתרו בחדש ה):",1,0],[46,19,"כְּלֵי גוֹלָה. אָדָם יוֹצֵא לַדֶּרֶךְ, מְתַקֵּן לוֹ חֵמֶת וּמְקַדָּה שֶׁל חֶרֶס לִשְׁתּוֹת בָּהּ:",1,0],[46,19,"וְנִצְּתָה. לְשׁוֹן ״צִיָּה״ (ישעיה מא:יח):",2,0],[46,20,"עֶגְלָה יְפֵה־פִיָּה. ״מַלְכוּתָא יָאיָיא״ (תרגום יונתן):",1,0],[46,20,"קֶרֶץ. ״עַמְּמִין קְטוּלִין״ (תרגום יונתן); קֶרֶץ לְשׁוֹן חִתּוּךְ, וְכֵן ״מֵחֹמֶר קֹרַצְתִּי״ (איוב לג:ו):",2,0],[46,20,"מִצָּפוֹן. מִבָּבֶל:",3,0],[46,21,"שְׂכִירֶיהָ. שָׂרֶיהָ, כְּמוֹ ״בְּתַעַר הַשְּׂכִירָה״ (ישעיה ז:כ):",1,0],[46,21,"מַרְבֵּק. קוֹפְלָ״א בְּלַעַ״ז:",2,0],[46,21,"הִפְנוּ. פָּנוּ עֹרֶף לְבַקֵּשׁ לָנוּס:",3,0],[46,22,"קוֹלָהּ כַּנָּחָשׁ יֵלֵךְ. הֲרֵי הַנָּחָשׁ בָּא לְלַמֵּד עַל מִצְרַיִם וְנִמְצָא לָמֵד: לָמַדְנוּ מִכָּאן, שֶׁכְּשֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לַנָּחָשׁ ״עַל גְּחֹנְךָ תֵלֵךְ״ (בראשית ג:יד), וְקִטֵּעַ אֶת רַגְלָיו וְהָלַךְ קוֹלוֹ בְּסוֹף הָעוֹלָם; כָּךְ שְׁנוּיָה בִּשְׁלֹשִׁים וּשְׁתַּיִם מִדּוֹת דְּרַבִּי אֱלִיעֶזֶר בְּנוֹ שֶׁל רַבִּי יוֹסֵי הַגְּלִילִי (מידה יב):",1,0],[46,22,"כִּי בְחַיִל יֵלֵכוּ. אֵלֶיהָ:",2,0],[46,23,"כָּרְתוּ יַעְרָהּ. כֹּחַ יֵשׁ בָּהֶן לִכְרוֹת כָּל יַעְרָהּ:",1,0],[46,23,"כִּי לֹא יֵחָקֵר. מִסְפַּר צְבָאָם:",2,0],[46,25,"אֶל אָמוֹן. עַל אָמוֹן, עַל הַשַּׂר אָמוֹן. יֵשׁ שֶׁהוּא לְשׁוֹן גְּדֻלָּה, כְּמוֹ ״הֲתֵיטְבִי מִנֹּא אָמוֹן״ (נחום ג:ח):",1,0],[46,25,"מִנֹּא. אֲלֶכְּסַנְדְּרִיָּה רַבְּתָא (פסיקתא רבתי לג), לָאשִׁינְיוֹרִיאָ״ה דְּלִישַׁנְדְּרָ״א בְּלַעַ״ז:",2,0],[46,26,"וְאַחֲרֵי כֵן. מִקֵּץ אַרְבָּעִים שָׁנָה, כְּמוֹ שֶׁאָמַר יְחֶזְקֵאל (יחזקאל כט:יג):",1,0],[46,27,"וְאַתָּה אַל תִּירָא. צַדִּיקִים שֶׁבְּתוֹךְ מִצְרַיִם, שֶׁגָּלוּ שָׁם עַל כָּרְחָם:",1,0],[46,28,"לַמִּשְׁפָּט. ״בְּדִין חָסוּךְ״ (תרגום יונתן), מְעַט מְעַט:",1,0],[46,28,"וְנַקֵּה. לְשׁוֹן טִיאוּט וְהַשְׁמֵד; וְכֵן תִּרְגְּמוֹ יוֹנָתָן לְשׁוֹן כְּלָיָה:",2,0],[47,1,"אֶל פְּלִשְׁתִּים. עַל פְּלִשְׁתִּים:",1,0],[47,1,"בְּטֶרֶם יַכֶּה פַרְעֹה אֶת עַזָּה. כְּשֶׁהָיָה נְבוּכַדְנֶצַּר צָר עַל יְרוּשָׁלַיִם בַּשָּׁנָה הָעֲשִׂירִית לְצִדְקִיָּהוּ, יָצָא חֵיל פַּרְעֹה מִמִּצְרַיִם וַיַּעֲלוּ הַכַּשְׂדִּים מֵעַל יְרוּשָׁלַיִם (ירמיה לז:ה); שָׁמַע פַּרְעֹה, וְשָׁטַף אֶת עַזָּה וְשָׁב לְאַרְצוֹ. בְּסֵדֶר עוֹלָם (פרק כו):",2,0],[47,3,"שַׁעֲטַת. אֵין לוֹ דִּמְיוֹן; וְיוֹנָתָן תִּרְגְּמוֹ: ״מִפְּסוֹעִית״:",1,0],[47,3,"מֵרַעַשׁ לְרִכְבּוֹ. מֵרַעַשׁ אֲשֶׁר לְרִכְבּוֹ:",2,0],[47,3,"גַּלְגִּלָּיו. אוֹפַנֵּי מַרְכְּבוֹתָיו:",3,0],[47,3,"לֹא הִפְנוּ אָבוֹת אֶל בָּנִים. לְהַצִּילָם:",4,0],[47,4,"לְהַכְרִית לְצוֹר וּלְצִידוֹן. פְּלִשְׁתִּים הָיוּ עוֹזְרִים אוֹתָם מֵאוֹיְבֵיהֶם:",1,0],[47,4,"אִי כַפְתּוֹר. אִיזְלָ״שׁ בְּלַעַ״ז:",2,0],[47,5,"נִדְמְתָה. נֶחְרְבָה:",1,0],[47,5,"תִּתְגּוֹדָדִי. תְּשָׂרְטִי בְּאֵבֶל וּבְבֶכִי:",2,0],[47,6,"חֶרֶב לַה׳. שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מֵבִיא לָעוֹלָם:",1,0],[47,6,"הֵרָגְעִי. לְשׁוֹן ״מַרְגּוֹעַ״ (ירמיה ו:טז):",2,0],[48,1,"הַמִּשְׂגָּב. שֵׁם מָקוֹם:",1,0],[48,2,"חֶשְׁבּוֹן. וּמַדְמֵן – שֵׁם מָקוֹם. וּלְפִי שְׁמוֹתָם הוּא מַזְכִּיר פֻּרְעָנוּתָם:",1,0],[48,2,"תִדֹּמִּי. תֶּחֱרָבִי:",2,0],[48,4,"צְעִירֶיהָ. ״שָׁלְטוֹנְהָא״ (תרגום יונתן) הַצְּעִירִים מִן הַמְּלָכִים:",1,0],[48,5,"מַעֲלֵה הַלּוּחִית. שֵׁם מָקוֹם הוּא מַעֲלוֹת הַר:",1,0],[48,6,"כַּעֲרוֹעֵר. מִגְדַּל עֲרוֹעֵר עָשׂוּי בַּמִּדְבָּר, וְאֵין סְבִיבָיו יִשּׁוּב כִּי אִם שׁוֹכְנֵי אֹהָלִים. וּמִגְדָּל הָעוֹמֵד בְּאֵין יִשּׁוּב נִרְאֶה כְּחוּרְבָה; כֵּן תִּרְגֵּם יוֹנָתָן. וּמְנַחֵם פֵּרֵשׁ כַּעֲרוֹעֵר – שֵׁם עֵץ מֵעֲצֵי הַיַּעַר:",1,0],[48,9,"תְּנוּ צִיץ לְמוֹאָב. תְּנוּ כָנָף לְמוֹאָב. כָּל דְּבָר תְּלַאי הַתּוֹלֶה וּבוֹלֵט מִן הָאָדָם וּמִן הַבְּהֵמָה קָרוּי צִיץ, כְּמוֹ ״וְהָיָה לָכֶם לְצִיצִת״ (במדבר טו:לט), ״וַיִּקָּחֵנִי בְּצִיצִת רֹאשִׁי״ (יחזקאל ח:ג):",1,0],[48,9,"כִּי נָצֹא תֵּצֵא. כִּי בִּמְעוֹפָהּ וְחִפָּזוֹן תֵּצְאוּ בַּגּוֹלָה. וְיִהְיֶה נֵצֵא מִגְּזֵרַת נִצָּהּ, כֵּן חָבְרוּ מְנַחֵם, וְכֵן ״כִּי נָצוּ גַּם נָעוּ״ (איכה ד:טו), וְיוֹנָתָן תִּרְגֵּם ״אַעֲדוֹ כִּתְרָא מִמּוֹאָב״, תְּנוּ לַאֲחֵרִים צִיץ הַנֵּזֶר אֲשֶׁר לְמוֹאָב:",2,0],[48,10,"מְלֶאכֶת ה׳. מְלֶאכֶת הַשְׁחָתַת מוֹאָב, שֶׁהִיא שְׁלִיחוּתוֹ שֶׁל מָקוֹם:",1,0],[48,11,"לֹא נָמָר. לֹא נֶחְלַף:",1,0],[48,12,"צוֹעִים. מְרִיקִים, וְכֵן ״מִהַר צֹעֶה לְהִפָּתֵחַ״ (ישעיהו נא:יד) – הוּא הִלּוּךְ הַמֵּעַיִם בְּשִׁלְשׁוּל:",1,0],[48,12,"וְנִבְלֵיהֶם. חֲבִיּוֹתֵיהֶם שֶׁל מוֹאָבִים:",2,0],[48,12,"יְנַפֵּצוּ. יְשַׁבְּרוּ, כְּמוֹ ״אֵיכָה נֶחְשְׁבוּ לְנִבְלֵי חֶרֶשׂ״ (איכה ד:ב); ״כָּל נֵבֶל יִמָּלֵא יָיִן״ (ירמיה יג:יב):",3,0],[48,13,"מִכְּמוֹשׁ. אֲשֶׁר בָּטַח בּוֹ:",1,0],[48,13,"מִבֵּית אֵל. עֵגֶל הַזָּהָב (מלכים א יב:לב):",2,0],[48,17,"נֻדוּ לוֹ. לְשׁוֹן קִינָה, כְּמוֹ ״אַל תָּנֻדוּ לוֹ״ (ירמיה כב:י):",1,0],[48,19,"שַׁאֲלִי נָס וְנִמְלָטָה. שַׁאֲלִי מִן הַנָּסִים וְהַנִּמְלָטִים מִמּוֹאָב מַה נִּהְיָתָה אִם נִמְלַט כְּלוּם מֵהַשְׁחִית:",1,0],[48,21,"וּמִשְׁפָּט בָּא. וּפוּרְעָנוּת בָּא:",1,0],[48,26,"הַשְׁכִּירוּהוּ. הַשְׁקוּהוּ תַּרְעֵלָה (ישעיהו נא:יז) עַד שֶׁיִּשְׁתַּכֵּר:",1,0],[48,26,"גַּם הוּא. כְּמוֹ שֶׁהָיָה שְׂחוֹק לוֹ:",2,0],[48,27,"תִּתְנוֹדָד. הָיִיתָ מֵנִיד בְּרֹאשְׁךָ וּמִתְלוֹצֵץ עַל חֻרְבָּנוֹ. לָשׁוֹן אַחֵר: כִּי מִדֵּי דְבָרֶיךָ בּוֹ – שֶׁהָיִיתָ מִתְרוֹנֵן עַל חָרְבָּנוֹ, אַתָּה תִּתְנוֹדָד – לָצֵאת בַּגּוֹלָה. וְכֵן תִּרְגֵּם יוֹנָתָן: ״עַל דְּאַסְגִּיתוֹן עֲלֵיהוֹן פִּתְגָּמִין בְּכֵן תִּיטַלְטְלוּן״:",1,0],[48,28,"בְּעֶבְרֵי פִי פָחַת. מָקוֹם שֶׁהַמַּיִם כּוֹרִין תַּחַת גִּדּוּדֵי שְׂפַת הַנַּחַל הַגְּבוֹהִים, וּכְשֶׁהַנַּחַל מִתְמַעֵט נִמְצֵאת הַגּוּמָא רֵיקָנִית, וְהַיּוֹנָה מְקַנֶּנֶת בְּאַחַת מֵעֶבְרֵי הַגּוּמָא, וּכְשֶׁנַּחַל רַבָּה שׁוֹטֵף אֶת הַקֵּן וְהִיא נוֹדֶדֶת מִשָּׁם; כָּךְ שָׁמַעְתִּי. וְיוֹנָתָן לֹא תִרְגֵּם כֵּן: ״וְהֲוָה כְּיוֹנָא דְּשַׁבְקָא פּוּם שׁוּבְכָהּ וְנָחֲתָא וְשָׁרְיָא בְּאַרְעִית גּוּבָא״:",1,0],[48,30,"עֶבְרָתוֹ וְלֹא כֵן. שִׂנְאָתוֹ לְיִשְׂרָאֵל לֹא בֶּאֱמֶת וְלֹא בְמִשְׁפָּט:",1,0],[48,30,"בַּדָּיו. גִּבּוֹרָיו:",2,0],[48,30,"לֹא כֵן עָשׂוּ. לֹא כַּגְּמוּל הֵשִׁיבוּ לְזֶרַע אַבְרָהָם, שֶׁנִּלְחַם עִם הַמְּלָכִים וְהִצִּיל אֶת לוֹט אֲבִיהֶם (בראשית יד:יד-טז):",3,0],[48,31,"קִיר חֶרֶשׂ. עִיר מֵאֶרֶץ מוֹאָב:",1,0],[48,31,"יֶהְגֶּה. גּוֹנֵחַ כְּיוֹנִים הוֹגִים:",2,0],[48,32,"מִבְּכִי יַעְזֵר אֶבְכֶּה לָּךְ. כְּשֶׁנֶּאֶמְרָה נְבוּאָה זוֹ כְּבָר חָרְבָה יַעְזֵר, וְהִיא סְמוּכָה לְמוֹאָב:",1,0],[48,32,"אֶבְכֶּה לָּךְ. אֶבְכֶּה בִּשְׁבִילֵךְ דּוּגְמַת אוֹתוֹ בֶּכִי, כִּי גַם אַתְּ תֶּחֱרְבִי כְּמוֹהוּ:",2,0],[48,32,"הַגֶּפֶן שִׂבְמָה. אֶרֶץ כְּרָמִים הָיְתָה:",3,0],[48,32,"נְטִישֹׁתַיִךְ. לְפִי שֶׁדִּמָּה אוֹתָהּ לְגֶפֶן, דִּמָּה אֶת גִּבּוֹרֶיהָ לִנְטִישׁוֹת הַגֶּפֶן:",4,0],[48,32,"עָבְרוּ יָם. הָלְכוּ בַּגּוֹלָה:",5,0],[48,32,"קֵיצֵךְ. לְשׁוֹן ״קַיִץ״ (שמואל ב טז:א) – תְּאֵנִים; וְ״קִצֵּךְ״ (ירמיה נא:יג), שֶׁהִיא לְשׁוֹן קֵץ – אֵין בּוֹ יוֹ״ד וְהַצָּדִ״י דְּגוּשָׁה:",6,0],[48,33,"וְנֶאֶסְפָה. וְכָלְתָה, שֶׁלֹּא תֵרָאֶה:",1,0],[48,33,"לֹא יִדְרֹךְ. עֲנָבִים בְּקוֹל עֲנוֹת הֵידָד, בְּשִׂמְחָה, כַּאֲשֶׁר הָיוּ עוֹשִׂים:",2,0],[48,33,"הֵידָד לֹא הֵידָד. שֶׁהֵידָד יִצְעֲקוּ לֹא יְהִי הֵידָד הָרִאשׁוֹן, כִּי אִם הֵידָד שֶׁל מְנוּסַת חֶרֶב:",3,0],[48,34,"עֶגְלַת שְׁלִשִׁיָּה. מְדִינָה גַּבְרְתָּנִית:",1,0],[48,36,"עַל כֵּן יִתְרַת עָשָׂה. עַל אֲשֶׁר גַּאֲוָה עָשָׂה, לְכָךְ אָבָדוּ:",1,0],[48,37,"גְּדֻדוֹת. שְׂרִיטוֹת:",1,0],[48,39,"אֵיךְ חַתָּה הֵילִילוּ. הֵילִילוּ עָלֶיהָ וְאִמְרוּ אֵיךְ חַתָּה:",1,0],[48,40,"כַּנֶּשֶׁר יִדְאֶה. הָאוֹיֵב אֶל מוֹאָב:",1,0],[48,40,"יִדְאֶה. יָעוּף:",2,0],[48,41,"הַקְּרִיּוֹת. שֵׁם הָעִיר:",1,0],[48,43,"פַּחַד וָפַחַת. אֵלּוּ שְׁנֵי דְבָרִים קָשִׁים זֶה אֵצֶל זֶה, שֶׁהַפַּחַד גּוֹרֵם לוֹ לָנוּס, וְהַפַּחַת מוּכָן לִיפּוֹל בּוֹ:",1,0],[48,43,"פַּחַת. פוֹשָׁ״א בְּלַעַ״ז:",2,0],[48,45,"בְּצֵל חֶשְׁבּוֹן. שֶׁהִיא גְבוֹהָה וְיֵשׁ לָהּ צֵל:",1,0],[48,45,"עָמְדוּ. הַנָּסִים לָנוּחַ בַּצֵּל, אֲשֶׁר לֹא הָיָה בָּהֶן עוֹד כֹּחַ לָנוּס:",2,0],[48,45,"מִבֵּן סִיחוֹן. מֵעִיר סִיחוֹן, כְּמוֹ ״בֶּן רְאוּבֵן״ בִּיהוֹשֻׁעַ (יהושע טו:ו):",3,0],[48,45,"וְקָדְקֹד. אַטְרִיפִירְצְדָ״א בְּלַעַ״ז, וּמְנַחֵם חִבְּרוֹ לְשׁוֹן מָקוֹר, וְיוֹנָתָן תִּרְגֵּם: ״וִיקִירֵי״, לְשׁוֹן יְקָר:",4,0],[48,45,"בְּנֵי שָׁאוֹן. אוֹתָם שֶׁהָיוּ מַגְבִּיהִים קוֹל תִּפְאָרֶת:",5,0],[49,1,"הֲבָנִים אֵין לְיִשְׂרָאֵל. בֵּי״ת רָפָה וְהֵ״א חֲטַף פַּתָּח, שֶׁהוּא לְשׁוֹן תְּמִיהָה:",1,0],[49,1,"מַלְכָּם. עֲבוֹדַת כּוֹכָבִים שֶׁל בְּנֵי עַמּוֹן מַלְכָּם שְׁמָהּ, שֶׁנֶּאֱמַר: ״וּלְמִלְכֹּם תּוֹעֲבַת בְּנֵי עַמּוֹן״ (מלכים ב כג:יג):",2,0],[49,3,"כִּי שֻׁדְּדָה עַי. הַסְּמוּכָה לָהּ, וּמֵאֶרֶץ עַמּוֹן הִיא:",1,0],[49,3,"בְּנוֹת רַבָּה. רַבַּת בְּנֵי עַמּוֹן:",2,0],[49,3,"וְהִתְשׁוֹטַטְנָה בַּגְּדֵרוֹת. תִּרְגְּמוֹ יוֹנָתָן: ״וְאִתְהַמְּמוֹן בְּסִיעָן״ – הִתְגּוֹדְדוּ בַּחֲיָלוֹת; פָּתַר וְהִתְשׁוֹטַטְנָה – לְשׁוֹן חֲיָלוֹת מְשׁוֹטְטִים, וּגְדֵרוֹת – לְשׁוֹן ״גִּדְרוֹת צֹאן״ (במדבר לב:טז) הַמְּלֵאִים עֲדָרִים. וְיֵשׁ לִפְתֹּר: וְהִתְשׁוֹטַטְנָה – וְהִתְעוֹלַלְנָה בְּזֶבֶל גִּדְרוֹת צֹאן, לְשׁוֹן בִּזָּיוֹן; ״וַיִּבֶז עֵשָׂו״ (בראשית כה:לד): ״וְשָׁט עֵשָׂו״ (תרגום אונקלוס):",3,0],[49,4,"תִּתְהַלְלִי. תִּתְפָּאֲרִי, וַונְטִי״ר בְּלַעַ״ז:",1,0],[49,4,"בָּעֲמָקִים. שֶׁאַרְצֵךְ אֶרֶץ עֲמָקִים וְאֵין עֲצִירַת גְּשָׁמִים קָשָׁה לָהּ, שֶׁאֵין חַמָּה שׁוֹלֶטֶת בָּהּ:",2,0],[49,4,"זָב עִמְקֵךְ. מַכַּת רֹב גְּשָׁמִים בָּאָה, עַד שֶׁזָּבוּ הַמַּיִם בָּעֵמֶק וְשָׁטְפוּ שָׁרְשֵׁי הַתְּבוּאָה; כָּךְ פֵּרְשׁוֹ מְנַחֵם:",3,0],[49,5,"אִישׁ לְפָנָיו. כָּל אֲשֶׁר יוּכַל לְמַהֵר וְלָנוּס:",1,0],[49,5,"לַנֹּדֵד. לְשׁוֹן ״נָע וָנָד״ (בראשית ד:יב):",2,0],[49,7,"בְּתֵימָן. אֱדוֹם בִּדְרוֹמָהּ שֶׁל אֶרֶץ יִשְׂרָאֵל הִיא, כְּמָה שֶׁנֶּאֱמַר ״וְהָיָה לָכֶם פְּאַת נֶגֶב מִמִּדְבַּר צִן עַל יְדֵי אֱדוֹם״ (במדבר לד:ג):",1,0],[49,7,"מִבָּנִים. מִדּוֹר זֶה:",2,0],[49,7,"נִסְרְחָה. ״אִתְקַלְקְלַת״ (תרגום יונתן):",3,0],[49,8,"הָפְנוּ. הִתְבַּעֲרוּ מִן הַמָּקוֹם הַזֶּה, לְשׁוֹן ״וּפִנּוּ אֶת הַבַּיִת״ (ויקרא יד:לו):",1,0],[49,8,"הֶעְמִיקוּ לָשֶׁבֶת. לְהֵחָבֵא בְּעִמְקֵי מִסְתָּרִים. נֻסוּ הָפְנוּ הֶעְמִיקוּ. כֻּלָּם לְשׁוֹן צִוּוּי הֵם:",2,0],[49,9,"אִם בּוֹצְרִים בָּאוּ לָךְ חָשַׂפְתִּי אֶת וְגוֹ׳ שְׁמוּעָה שָׁמַעְתִּי וְגוֹ׳. כָּל כְּעֵין דּוּגְמָא זוֹ נִבָּא עוֹבַדְיָה עַל אֱדוֹם (עובדיה א:א-ה), וּלְפִי שֶׁסִּיגְנוֹן אֶחָד עוֹלֶה לְכַמָּה נְבִיאִים וְאֵין שְׁנֵי נְבִיאִים מִתְנַבְּאִים בְּסִיגְנוֹן אֶחָד (סנהדרין פט.), בְּמִקְצָת הַדְּבָרִים מִשְׁתַּנִּין:",1,0],[49,9,"לֹא יַשְׁאִירוּ עוֹלֵלוֹת. בִּתְמִיהָּ: וְהַשּׁוֹדְדִים שֶׁבָּאוּ עָלֶיךָ, לֹא הִשְׁאִירוּ לְךָ כְּלוּם!",2,0],[49,10,"חָשַׂפְתִּי. גִּלֵּיתִי, כְּמוֹ ״מַחְשֹׂף הַלָּבָן״ (בראשית ל:לז). וְאַתָּה הִסְגַּרְתָּ שְׂרִידֵי יִשְׂרָאֵל לְמַעַן לֹא יִשָּׁאֵר מֵהֶם אִישׁ; כְּמָה שֶׁנֶּאֱמַר ״אַל תַּסְגֵּר שְׂרִידָיו״ (עובדיה א:יד):",1,0],[49,10,"וְנֶחְבָּה לֹא יוּכָל. וִיבַקֵּשׁ לְהֵחָבֵא וְלֹא יוּכָל:",2,0],[49,11,"עָזְבָה יְתֹמֶיךָ. שֶׁיִּתַּמְתָּ בְּיִשְׂרָאֵל:",1,0],[49,12,"אֲשֶׁר אֵין מִשְׁפָּטָם לִשְׁתּוֹת. שֶׁלֹּא הָיוּ אַחִים לָהֶם, וְאִם הֵרֵעוּ לָהֶם, אֵין לָהֶם מִשְׁפַּט מָוֶת כְּמוֹתְךָ:",1,0],[49,13,"לְחֶרְפָּה וְלִקְלָלָה תִּהְיֶה בָצְרָה. בָּצְרָה מֵעָרֵי מוֹאָב, אֶלָּא מִפְּנֵי הָעִנְיָן שֶׁנֶּאֱמַר ״יוֹבָב בֶּן זֶרַח מִבָּצְרָה״ (בראשית לו:לג), הִיא לוֹקָה עִמּוֹ:",1,0],[49,15,"קָטֹן נְתַתִּיךָ. שֶׁאֵין בָּהֶם מֶלֶךְ בֶּן מֶלֶךְ; לֹא הָיָה דַּרְכָּם בְּרוֹמִי לְהַעֲמִיד מֶלֶךְ בֶּן מֶלֶךְ (עבודה זרה י.):",1,0],[49,16,"תִּפְלַצְתְּךָ. לְשׁוֹן בֶּהָלָה; שֶׁהָיִיתָ מְמַהֵר וְנִבְהָל לְעוֹרֵר שְׂטִימָתְךָ לְאָחִיךָ. וְיֵשׁ לוֹעֲזִין לְשׁוֹן ״פַּלָּצוּת״ (ישעיה כא:ד); וְיֵשׁ לוֹעֲזִין לְשׁוֹן ״מִפְלֶצֶת״ (מלכים א טו:יג):",1,0],[49,16,"הִשִּׁיא אוֹתָךְ. לְהָרַע לָהֶם:",2,0],[49,16,"שׁוֹכְנִי. שׁוֹכֵן:",3,0],[49,16,"תּוֹפְשִׂי. כְּמוֹ ״תּוֹפֵשׂ״ (ירמיה נ:טז), וְהַיּוֹ״ד יְתֵרָה בּוֹ:",4,0],[49,19,"כְּאַרְיֵה יַעֲלֶה מִגְּאוֹן הַיַּרְדֵּן. שֶׁהוּא מְקוֹם אֲרָיוֹת, כְּתַרְגּוּמוֹ שֶׁל יוֹנָתָן, כֵּן יַעֲלֶה הָאוֹיֵב אֶל נְוֵה אֵיתָן:",1,0],[49,19,"אַרְגִּיעָה. אַקְרִיב אֶת הָרֶגַע:",2,0],[49,19,"אֲרִיצֶנּוּ מֵעָלֶיהָ. פִּתְאוֹם וּבְהַצְלָחָה יַחֲרִיבֶנָּה, וְיָשׁוּב לוֹ בְּרֶגַע קָטָן אֶל מְקוֹמוֹ. וַאֲנִי אוֹמֵר: אֲרִיצֶנּוּ מֵעָלֶיהָ מִמַּעַל לָהּ, שֶׁיְּהֵא מִתְגַּבֵּר עָלֶיהָ וְעֶלְיוֹן לָהּ; וְכֵן ״מִמַּעַל לָרָקִיעַ״ (יחזקאל א:כו); וְכֵן ״מִמַּעַל לוֹ״ (ישעיה ו:ב); ״מֵעַל לְמַדָּיו״ (שמואל א יז:לט):",3,0],[49,19,"וּמִי בָחוּר. אוֹתוֹ שֶׁבָּחַרְתִּי לִנְקוֹם נִקְמָתִי עָלֶיהָ אֶפְקֹד:",4,0],[49,19,"וּמִי יֹעִידֶנִּי. לַמִּלְחָמָה, לְהִלָּחֵם אִתִּי:",5,0],[49,19,"רוֹעֶה. מֶלֶךְ:",6,0],[49,20,"אִם לֹא. לְשׁוֹן בֶּאֱמֶת:",1,0],[49,20,"יִסְחָבוּם. יִגְרְרוּם:",2,0],[49,20,"צְעִירֵי הַצֹּאן. בְּזוּיֵי הָאֻמּוֹת. וְרַבּוֹתֵינוּ דָּרְשׁוּ (יומא י.): פָּרַס, שֶׁהוּא הַצָּעִיר בִּבְנֵי יֶפֶת (בראשית י:ב):",3,0],[49,20,"יַשִּׁים. לְשׁוֹן שְׁמָמָה:",4,0],[49,23,"בּוֹשָׁה חֲמָת וְאַרְפָּד. עָרֵי אֲרָם, כִּי שָׁמְעוּ שְׁמֻעָה רָעָה עַל דַּמֶּשֶׂק, שֶׁהִיא רֹאשׁ אֲרָם, כְּמָה שֶׁנֶּאֱמַר ״כִּי רֹאשׁ אֲרָם דַּמֶּשֶׂק״ (ישעיהו ז:ח); לְכָךְ נָמֹגוּ:",1,0],[49,23,"בְּיָם דְּאָגָה. דַּאֲגָתָהּ דּוֹמָה לְדַאֲגַת הַיָּם הַשְׁקֵט לֹא יוּכָל. כָּל דְּאָגָה לְשׁוֹן יִרְאָה הוּא:",2,0],[49,24,"רָפְתָה דַמֶּשֶׂק. רָפוּ יָדֶיהָ מֵהִלָּחֵם:",1,0],[49,24,"וְרֶטֶט. זִיעַ:",2,0],[49,25,"אֵיךְ לֹא עֻזְּבָה. לֹא נִתְמַלֵּאת עָפָר סְבִיב חוֹמָתָהּ לְחַזֵּק הַחוֹמָה, כְּמוֹ ״וַיַּעַזְבוּ אֶת יְרוּשָׁלַיִם עַד הַחוֹמָה״ (נחמיה ג:ח). וְיֵשׁ עוֹד לִפְתֹּר: לָמָּה לֹא נֶעֶזְבָה מִן הָרָעָה הַזֹּאת, שֶׁלֹּא תָבֹא הָרָעָה עָלֶיהָ?",1,0],[49,25,"קִרְיַת מְשׂוֹשִׂי. כָּךְ יִתְאַבֵּל מַלְכָּהּ עָלֶיהָ:",2,0],[49,26,"לָכֵן. לְשׁוֹן שְׁבוּעָה:",1,0],[49,26,"יִדַּמּוּ. יֶחֶרָבוּ, וְאֵינוֹ זָז מִלְּשׁוֹן דְּמָמָה, שֶׁכָּל עִיר חֲרֵבָה אֵין קוֹל נִשְׁמָע בָּהּ:",2,0],[49,28,"קֵדָר. שׁוֹכְנֵי מִדְבָּרוֹת בָּאֳהָלִים הֵם, אֵין חוֹמָה וְאֵין עִיר:",1,0],[49,29,"מָגוֹר. אֵימַאשְׁמְנְ״ט בְּלַעַ״ז. לָשׁוֹן אַחֵר: לְשׁוֹן יִרְאָה:",1,0],[49,30,"כִּי יָעַץ עֲלֵיכֶם וגו׳. וּמָה הִיא הָעֵצָה? קוּמוּ עֲלוּ אֶל גּוֹי שָׁלֵיו:",1,0],[49,31,"בָּדָד יִשְׁכֹּנוּ. בֶּטַח בִּיחִידוּת; אֵין צְרִיכִין לְהִתְאַסֵּף וְלֵישֵׁב בְּרֹב אָדָם, שֶׁאֵין יְרֵאִים שֶׁיָּבֹא אוֹיֵב עֲלֵיהֶם:",1,0],[49,32,"קְצוּצֵי פֵאָה. מוּקְצִים מִקָּצֶה אֶל קָצֶה הָרוּחוֹת:",1,0],[49,35,"אֶת קֶשֶׁת עֵילָם. אֶת תִּקְוַת עֵילָם (ס״א חָזְקַת עֵילָם):",1,0],[49,35,"רֵאשִׁית גְּבוּרָתָם. מֵיטַב גְּבוּרָתָם:",2,0],[49,38,"וְשַׂמְתִּי כִסְאִי. מָצוֹר שֶׁלִּי:",1,0],[50,2,"וּשְׂאוּ נֵס. פּוֹרְקָ״א בְּלַעַ״ז, סִימַן אֲסִיפָה הוּא:",1,0],[50,2,"בֵּל. וּמְרֹדָךְ – שְׁמוֹת עֲבוֹדָה זָרָה שֶׁל בָּבֶל:",2,0],[50,3,"גּוֹי מִצָּפוֹן. מָדַי וּפָרָס:",1,0],[50,5,"דֶּרֶךְ הֵנָּה. דֶּרֶךְ הַמָּקוֹם הַזֶּה, יְרוּשָׁלַיִם, יָסֵבּוּ פְנֵיהֶם, כְּשֶׁתֶּחֱרַב בָּבֶל וְיֵצְאוּ מִתּוֹכָהּ בִּרְשִׁיּוֹן כּוֹרֶשׁ מֶלֶךְ פָּרַס:",1,0],[50,6,"רוֹעֵיהֶם הִתְעוּם. גְּדוֹלֵיהֶם הִתְעוּם מֵעָלַי:",1,0],[50,6,"הָרִים שׁוֹבְבוּם. אֶל הֶהָרִים, אֶל עֲבוֹדַת כּוֹכָבִים שֶׁבֶּהָרִים. שׁוֹבְבוּם אַנְוִויזַאנְ״ץ בְּלַעַ״ז, שׁוֹבְבוּם מַלְכֵיהֶם. וְיוֹנָתָן תִּרְגֵּם הָרִים שׁוֹבְבוּם ״שַׁלְטוֹנִיָּא בְּזוֹנוּן״:",2,0],[50,7,"וּמִקְוֵה אֲבוֹתֵיהֶם. ״וְסִבּוּר אֲבָהָתְהוֹן״ (תרגום יונתן):",1,0],[50,8,"נֻדוּ מִתּוֹךְ בָּבֶל. מֵעַתָּה צְאוּ מִשָּׁם:",1,0],[50,8,"כְּעַתּוּדִים לִפְנֵי צֹאן. דֶּרֶךְ הָעַתּוּדִים לָלֶכֶת לִפְנֵי הָעֵדֶר בְּרֹאשׁ הָעִזִּים:",2,0],[50,9,"וְעָרְכוּ לָהּ. ״וִיסַדְּרוּן עֲלַהּ קְרָב״ (תרגום יונתן):",1,0],[50,11,"שׁוֹסֵי נַחֲלָתִי. בּוֹזְזֵי נַחֲלָתִי:",1,0],[50,11,"כִּי תָפוּשׁוּ. לְשׁוֹן שׁוּמָן:",2,0],[50,11,"כְּעֶגְלָה דָשָׁה. הַדָּשָׁה בַּתְּבוּאָה וְאוֹכֶלֶת תָּמִיד:",3,0],[50,12,"אִמְּכֶם. כְּנֵסִיַּתְכֶם:",1,0],[50,12,"אַחֲרִית. אַתֶּם, הַכַּשְׂדִּים, אִם רֵאשִׁיתְכֶם גָּדוֹל, אַחֲרִיתְכֶם יִהְיוּ מִדְבָּר:",2,0],[50,14,"יְדוּ אֵלֶיהָ. זִרְקוּ לָהּ אֲבָנִים, כְּמוֹ ״וַיַּדּוּ אֶבֶן בִּי״ (איכה ג:נג):",1,0],[50,15,"וְנָתְנָה יָדָהּ. כְּאָדָם שֶׁאֵין בּוֹ כֹּחַ וּמוֹשִׁיט יָד לְכָל מִי שֶׁרוֹאֶה, לְבַקֵּשׁ רַחֲמִים וְעֶזְרָה; וְכֵן ״מִצְרַיִם נָתְנוּ יָד״ (איכה ה:ו) – הוֹשַׁטְנוּ יָד לְמִצְרַיִם לְבַקֵּשׁ מֵהֶם עֶזְרָה:",1,0],[50,15,"אָשְׁיוֹתֶיהָ. חֹזֶק יְסוֹדוֹתֶיהָ, וְכֵן ״וְאֻשַּׁיָּא יְחִיטוּ״ (עזרא ד:יב). וּבִלְשׁוֹן מִשְׁנָה (בבא קמא נ.): כְּגוֹן אֵלּוּ הַחוֹפְרִים לְאוּשִׁין; וְכֵן ״וְהִתְאוֹשָׁשׁוּ״ (ישעיה מו:ח) – וְהִתְחַזְּקוּ:",2,0],[50,15,"כַּאֲשֶׁר עָשְׂתָה. לְעִיר ה׳:",3,0],[50,16,"כִּרְתוּ זוֹרֵעַ. ״שַׁיְצוּ מַלְכָּא מִבָּבֶל וַאֲחִידוּ חַרְבָּא בְּעִידָּן קְטוֹל״ (תרגום יונתן):",1,0],[50,17,"הָרִאשׁוֹן אֲכָלוֹ. שֶׁהִגְלָה עֲשֶׂרֶת הַשְּׁבָטִים:",1,0],[50,17,"עִצְּמוֹ. גֵּרְמוֹ, גִּירֵם עַצְמוֹתָיו, שֶׁגָּמַר הַשְּׁיָרִים: יְהוּדָה וּבִנְיָמִין. עִצְּמוֹ דִּישׁוֹשָׁ״ר בְּלַעַ״ז:",2,0],[50,19,"וְרָעָה הַכַּרְמֶל. לְשׁוֹן ״מִרְעֶה״ (בראשית מז:ד):",1,0],[50,21,"מְרָתַיִם. שֶׁהִמְרַתַּנִי וְהִרְגַּזְתַּנִי:",1,0],[50,21,"פְּקוֹד. שֵׁם מְדִינָה, וְכֵן ״פְּקוֹד וְשׁוֹעַ וְקוֹעַ״ (יחזקאל כג:כג) תִּרְגֵּם יוֹנָתָן שֵׁם מְדִינוֹת:",2,0],[50,21,"וַעֲשֵׂה כְּכֹל אֲשֶׁר צִוִּיתִיךָ. אַתָּה, כּוֹרֶשׁ, בְּיַד יְשַׁעְיָה הַנָּבִיא (ישעיה מה):",3,0],[50,23,"פַּטִּישׁ כָּל הָאָרֶץ. שֶׁהָיָה מְפוֹצֵץ וּמְכַתֵּת אֶת הַכֹּל:",1,0],[50,24,"יָקֹשְׁתִּי לָךְ. לְשׁוֹן ״מוֹקֵשׁ״ (דברים ז:טז):",1,0],[50,26,"בֹּאוּ לָהּ מִקֵּץ. מִסּוֹף הָעִיר הִתְחִילוּ בָהּ, שֶׁלֹּא תֵּדַע וְתִתָּפֵשׂ פִּתְאוֹם:",1,0],[50,26,"פִּתְחוּ מַאֲבֻסֶיהָ. תִּרְגֵּם יוֹנָתָן: ״אִבּוּלָהָא״ – שַׁעֲרֵיהָּ; וְאֵין לוֹ דִּמְיוֹן. וּמְנַחֵם חִבְּרוֹ לְשׁוֹן אֵבוּס:",2,0],[50,26,"סָלּוּהָ. דּוּשׁוּ אוֹתָהּ:",3,0],[50,26,"כְּמוֹ עֲרֵמִים. גְּרָנוֹת:",4,0],[50,27,"כָּל פָּרֶיהָ. שָׂרֶיהָ. כֵּן דֶּרֶךְ הַנְּבִיאִים לְהַמְשִׁיל הַשָּׂרִים לְפָרִים (ישעיה לד:ז), אַבִּירִים (ישעיה לד:ז), וְלַעֲתוּדִים (ישעיה יד:ט):",1,0],[50,29,"הַשְׁמִיעוּ אֶל בָּבֶל רַבִּים. לְשׁוֹן ״וַיַּשְׁמַע שָׁאוּל אֶת הָעָם״ (שמואל א טו:ד): הַזְעִיקוּ לְהֵאָסֵף אֶל בָּבֶל מוֹרִים בְּחִצִּים; כְּמוֹ ״יָסֹבּוּ עָלַי רַבָּיו״ (איוב טז:יג):",1,0],[50,30,"לָכֵן. לְשׁוֹן שְׁבוּעָה:",1,0],[50,34,"הִרְגִּיעַ אֶת הָאָרֶץ. כְּשֶׁתִּפּוֹל בָּבֶל יְהִי מַרְגּוֹעַ וְהַנָּחָה לַכֹּל:",1,0],[50,36,"אֶל הַבַּדִּים. אֶל הַקּוֹסְמִים שֶׁלָּהּ:",1,0],[50,36,"וְנֹאָלוּ. בְּקִסְמֵיהֶם. וְדוֹמֶה לוֹ: ״מֵפֵר אוֹתוֹת בַּדִּים״ (ישעיה מד:כה), וְכֵן תִּרְגְּמוֹ יוֹנָתָן; עַל שֵׁם שֶׁבּוֹדִים וְאוֹמְרִים דִּבְרֵי כָּזָב:",2,0],[50,37,"הָעֶרֶב. ״סוּמְכְוָותָא״ (תרגום יונתן); גְּרַנְטִיאָ״ה בְּלַעַ״ז:",1,0],[50,38,"וּבָאֵימִים יִתְהֹלָלוּ. יִשְׁתַּטּוּ. לָשׁוֹן אַחֵר: פורוונטרונט בְּלַעַ״ז, וְכֵן תִּרְגֵּם יוֹנָתָן: ״מִשְׁתַּבְּחִין״ – בֵּאלֹהֵי הָעֲנָקִים שֶׁהָיוּ לָהֶם:",1,0],[50,39,"צִיִּים אֶת אִיִּים. ״יְעָרְעוּן תַּמְוָן בַּחֲתוּלִין״ (תרגום יונתן), מִינֵי חַיּוֹת הַמְּצוּיִין בְּחוּרְבָּה:",1,0],[50,44,"הִנֵּה כְּאַרְיֵה. אֲשֶׁר יַעֲלֶה מִגְּאוֹן הַיַּרְדֵּן כֵּן יָבֹא הַשּׁוֹדֵד אֶל נְוֵה אֵיתָן. כָּךְ תִּרְגֵּם יוֹנָתָן: ״הָא מֶלֶךְ בְּמַשְׁרִיָּתֵיהּ יִיסַק עֲלֵיהוֹן כְּאַרְיָא דְּסָלִיק מֵרוּם יַרְדְּנָא״; לָמַדְנוּ, שֶׁגְּאוֹן הַיַּרְדֵּן מְקוֹם אֲרָיוֹת הוּא. וְאַף כָּךְ תִּרְגְּמוֹ יוֹנָתָן ״וְאֵיךְ תַּעֲשֶׂה בִּגְאוֹן הַיַּרְדֵּן״ (ירמיה יב:ה): ״לְקָבֵיל חֵיוָא בָּרָא בְּרוּם יַרְדְּנָא״:",1,0],[50,44,"כִּי אַרְגִּיעָה. כְּשֶׁאָבִיא הַשָּׁעָה:",2,0],[50,44,"מֵעָלֶיהָ. מִמַּעַל לָהּ:",3,0],[50,44,"וּמִי יֹעִידֶנִּי. לַמִּלְחָמָה:",4,0],[50,45,"צְעִירֵי הַצֹּאן. פָּרַס, צָעִיר לִבְנֵי יֶפֶת (בראשית י:ב; יומא י.):",1,0],[51,1,"לֵב קָמָי. כַּשְׂדִּים בְּגִימַטְרִיָּא דְּא״ת ב״ש, רוּחַ מַשְׁחִית אֶת רוּחַ מֶלֶךְ פָּרַס וּמָדַי שֶׁהוּא מַשְׁחִית. רוּחַ טַלְנְ״ט בְּלַעַ״ז:",1,0],[51,2,"וְזֵרוּהָ. וְנִפְּצוּהָ:",1,0],[51,2,"וִיבֹקְקוּ. וִירוֹקְנוּ:",2,0],[51,3,"אֶל יִדְרֹךְ הַדּרֵךְ. הֲרֵי זֶה מִקְרָא קָצָר: אֶל אֲשֶׁר אֲנִי אוֹמֵר, שָׁם יִדְרֹךְ הַדּרֵךְ קַשְׁתּוֹ:",1,0],[51,3,"וְאַל יִתְעַל בְּסִרְיוֹנוֹ. אַל יֵרָפֵא:",2,0],[51,5,"כִּי לֹא אַלְמָן. לֹא שְׁכָחוֹ מִלִּנְקוֹם נִקְמָתוֹ:",1,0],[51,5,"כִּי אַרְצָם. שֶׁל כַּשְׂדִּים:",2,0],[51,6,"נֻסוּ. יִשְׂרָאֵל מִתּוֹךְ בָּבֶל:",1,0],[51,7,"כּוֹס זָהָב. הָיְתָה בָּבֶל עַד הֵנָּה בְּיַד ה׳ לְשַׁכֵּר בָּהּ אֶת כָּל הָאָרֶץ יֵין הַחֵימָה (ירושלמי פסחים י:א):",1,0],[51,7,"עַל כֵּן יִתְהוֹלְלוּ גוֹיִם. נִשְׁתַּכְּרוּ וְנִשְׁתַּטּוּ:",2,0],[51,9,"נָגַע אֶל הַשָּׁמַיִם מִשְׁפָּטָהּ. גָּבַהּ פּוּרְעָנוּתָהּ עַד אֶל הַשָּׁמַיִם:",1,0],[51,10,"הוֹצִיא ה׳ אֶת צִדְקוֹתֵינוּ. נִזְכַּרְנוּ לְפָנָיו לִזְכוּת, וּבָאוּ צִדְקוֹת אֲבוֹתֵינוּ לְפָנָיו:",1,0],[51,11,"הָבֵרוּ. לְשׁוֹן נִקָּיוֹן:",1,0],[51,11,"הַשְּׁלָטִים. אַשְׁפּוֹת שֶׁהַחִצִּים נְתוּנִים בָּהֶם:",2,0],[51,12,"גַּם זָמַם ה׳. זֶה יָמִים רַבִּים:",1,0],[51,12,"גַּם עָשָׂה. אֶת מְזִמָּתוֹ. דֶּרֶךְ הַמִּקְרָא לְדַבֵּר שְׁנֵי גַמִּין זֶה אַחַר זֶה, וְעַל יְדֵי הָאַחֲרוֹן בָּא הָרִאשׁוֹן:",2,0],[51,13,"בָּא קִצֵּךְ. קֵץ שֶׁלָּךְ:",1,0],[51,13,"אַמַּת בִּצְעֵךְ. מִדַּת חֲמָסֵךְ. לָשׁוֹן אַחֵר: אַמַּת בִּצְעֵךְ. מִדַּת סוֹפֵךְ; כְּמוֹ ״כִּי יְבַצַּע״ (ישעיה י:יב):",2,0],[51,14,"בְּנַפְשׁוֹ. אִינְשִׁימִישִׁימוֹ״שׁ בְּלַעַ״ז:",1,0],[51,14,"כִּי אִם. לְשׁוֹן בֶּאֱמֶת:",2,0],[51,14,"מִלֵּאתִיךְ אָדָם. אֲמַלִּינָךְ מַשְׁרְיָת עַמְּמִין דְּסַגִּיאִין כְּזַחֲלָא״ (תרגום יונתן):",3,0],[51,14,"וְעָנוּ עָלַיִךְ הֵידָד. ״וִירִימוּן עֲלָךְ בְּקָלְהוֹן״ (תרגום יונתן):",4,0],[51,17,"נִבְעַר כָּל אָדָם. הָעוֹשֶׂה פֶּסֶל לֶאֱלוֹהַּ:",1,0],[51,17,"נִסְכּוֹ. לְשׁוֹן ״מַסֵּכָה״ (שמות לב:ד):",2,0],[51,18,"בְּעֵת פְּקֻדָּתָם. כְּשֶׁיִּפְקֹד הַקָּדוֹשׁ בָּרוּךְ הוּא עֲלֵיהֶם וְעַל עוֹבְדֵיהֶם:",1,0],[51,19,"וְשֵׁבֶט נַחֲלָתוֹ. יַעֲקוֹב הַנִּזְכָּר לְמַעְלָה בְּרֹאשׁ הַמִּקְרָא:",1,0],[51,20,"מַפֵּץ אַתָּה לִי. עַד הֵנָּה הֶעֱמַדְתִּיךָ לִי לְמַשְׁחִית וּלְמַפֵּץ אֶת הָאֻמּוֹת שֶׁגָּזַרְתִּי עֲלֵיהֶם גּוֹלָה:",1,0],[51,24,"וְשִׁלַּמְתִּי לְבָבֶל. אַחֲרֵי כָּל זֹאת, שֶׁאֶגְמֹר נִקְמָתִי עַל יָדוֹ בְּעוֹבְדֵי כּוֹכָבִים:",1,0],[51,27,"קַדְּשׁוּ. זַמְּנוּ:",1,0],[51,27,"טִפְסָר. לְשׁוֹן ״חַיִל״ (מלכים א כ:כה) (אוֹ לְשׁוֹן אָדוֹן):",2,0],[51,27,"סָמָר. הִירִיצִי״ר בְּלַעַ״ז, כְּמוֹ ״תְּסַמֵּר שַׂעֲרַת בְּשָׂרִי״ (איוב ד:טו):",3,0],[51,29,"וַתָּחֹל. לְשׁוֹן ״חַלְחָלָה״ (ישעיה כא:ג):",1,0],[51,30,"נָשְׁתָה. קָפְצָה; כְּמוֹ ״גִּיד הַנָּשֶׁה״ (בראשית לב:לג), שֶׁנָּשָׁה מִמְּקוֹמוֹ (חולין צא.):",1,0],[51,33,"כְּגֹרֶן עֵת הִדְרִיכָהּ. הֲרֵי הִיא עַתָּה מְלֵאָה כְּגֹרֶן בְּעֵת שֶׁדָּשׁוּ תְּבוּאָתָהּ, שֶׁהִיא מְלֵאָה חִטִּין:",1,0],[51,33,"עוֹד מְעַט. וְתִתְרוֹקֵן וְתִדְמֶה לְגֹרֶן בְּעֵת תְּחִלַּת הַקָּצִיר, שֶׁהִיא רֵיקָנִית:",2,0],[51,35,"חֲמָסִי וּשְׁאֵרִי. צַעֲקַת חֲמָסִי וּמְזוֹנוֹתַי, אֲשֶׁר אָכְלוּ שְׁאֵרִי:",1,0],[51,38,"נָעֲרוּ. לְשׁוֹן חֲמוֹר נוֹעֵר (ברכות ג.):",1,0],[51,39,"בְּחֻמָּם אָשִׁית אֶת מִשְׁתֵּיהֶם. אֲכַוֵּין שֶׁיְּהוּ מִשְׁתֵּיהֶן בְּעֵת הַחוֹם, כְּדֵי שֶׁיִּשְׁתַּכְּרוּ:",1,0],[51,39,"לְמַעַן יַעֲלֹזוּ וְיָשְׁנוּ. וְיִרְדְּמוּ:",2,0],[51,39,"שְׁנַת עוֹלָם. שֵׁנָה עוֹלָמִית. וְכֵן עָלְתָה בָּם: מִתּוֹךְ מִשְׁתֶּה וְשִׁכְרוּת נֶחְרְבוּ וְנֶהֶרְגוּ, וְנִלְכְּדָה הָעִיר; כְּמוֹ שֶׁנֶּאֱמַר בְּדָנִיֵּאל ״בֵּלְשַׁצַּר אָמַר בִּטְעֵם חַמְרָא וְגוֹ׳״ (דניאל ה:ב), ״אִשְׁתִּיו חַמְרָא וְגוֹ׳״ (דניאל ה:ד), ״בֵּיהּ בְּלֵילְיָא קְטִיל בֵּלְשַׁאצַּר מַלְכָּא וְגוֹ׳״ (דניאל ה:ל), ״וְדָרְיָוֶשׁ מָדָאָה קַבִּיל מַלְכוּתָא״ (דניאל ו:א):",3,0],[51,40,"כְּכָרִים. כְּבָשִׂים, (וְיוֹנָתָן תִּרְגֵּם) ״כְּתוֹרִין״:",1,0],[51,41,"שֵׁשַׁךְ. בָּבֶל בְּגִימַטְרִיָּא דְּא״ת ב״ש (תנחומא, קרח יב):",1,0],[51,42,"עָלָה עַל בָּבֶל הַיָּם. חַיִל גָּדוֹל כְּמוֹ הַיָּם:",1,0],[51,44,"עַל בֵּל. עַל עֲבוֹדַת כּוֹכָבִים שֶׁל בָּבֶל:",1,0],[51,44,"אֶת בִּלְעוֹ. שֶׁהוּשְׁפְּלוּ כָּל יוֹשְׁבֵי הָאָרֶץ תַּחְתָּיו:",2,0],[51,44,"וְלֹא יִנְהֲרוּ. וְלֹא יֵאָסְפוּ; וְכֵן ״וְנָהֲרוּ אֵלָיו כָּל הַגּוֹיִם״ (ישעיהו ב:ב) – כְּמֵימֵי נְהָרוֹת כֻּלָּם הַהוֹלְכִים אֶל הַיָּם (קהלת א:ז):",3,0],[51,46,"בַּשְּׁמוּעָה הַנִּשְׁמַעַת בָּאָרֶץ. הַשְּׁמוּעָה הַזֹּאת שֶׁל בֵּלְשַׁצַּר שֶׁנֶּהֱרַג:",1,0],[51,46,"וּבָא בַשָּׁנָה הַשְּׁמוּעָה. בְּאוֹתָהּ שָׁנָה עַצְמָהּ תָּבוֹא הַשְּׁמוּעָה שֶׁחָרְבָה בָּבֶל מֵאֵלֶיהָ מִן הַשָּׁמַיִם, שֶׁנֶּאֱמַר ״וְהָיְתָה בָבֶל צְבִי מַמְלָכוֹת תִּפְאֶרֶת גְּאוֹן כַּשְׂדִּים כְּמַהְפֵּכַת אֱלֹהִים אֶת סְדֹם וְאֶת עֲמֹרָה״ (ישעיה יג:יט):",2,0],[51,46,"וְאַחֲרָיו בַּשָּׁנָה. הַשְּׁנִיָּה:",3,0],[51,46,"הַשְּׁמוּעָה. הַטּוֹבָה לָכֶם: ״כֹּה אָמַר כּוֹרֶשׁ מֶלֶךְ פָּרַס״ (עזרא א:ב), ״מִי בָכֶם מִכָּל עַמּוֹ״ (עזרא א:ג):",4,0],[51,46,"וּמֹשֵׁל עַל מֹשֵׁל. דָּרְיָוֶשׁ הַמָּדִי מָלַךְ שָׁנָה אַחַת, וּבַשָּׁנָה הַשְּׁנִיָּה כּוֹרֶשׁ הַפַּרְסִי:",5,0],[51,49,"גַּם בָּבֶל. הָיְתָה לִנְפֹּל בָּהּ חַלְלֵי יִשְׂרָאֵל:",1,0],[51,49,"גַּם לְבָבֶל. יִפְּלוּ חַלְלֵי כָל אַרְצָהּ:",2,0],[51,50,"פְּלֵטִים מֵחֶרֶב. יִשְׂרָאֵל שֶׁגָּלוּ לְתוֹכָהּ, שֶׁפָּלְטוּ מֵחֶרֶב נְבוּזַרְאֲדָן (מלכים ב כה:ח-יב):",1,0],[51,51,"כִּי שָׁמַעְנוּ חֶרְפָּה. שֶׁהָיוּ כַשְׂדִּים אוֹמְרִים וּמְחָרְפִים אוֹתָנוּ לֵאמֹר: יַד אֱלֹהֵינוּ רָמָה, שֶׁהֶחֱרַבְנוּ אֶת בֵּיתוֹ:",1,0],[51,52,"יֶאֱנֹק חָלָל. יִצְעַק חָלָל; כְּשֶׁהוֹרְגִים אֶת הָאָדָם בְּחֵץ אוֹ בְרוֹמַח וְהוּא גּוֹנֵחַ כְּשֶׁמּוֹצִיא הָרוֹמַח, הִיא הָאֲנָקָה:",1,0],[51,53,"וְכִי תְבַצֵּר. לְשׁוֹן מִבְצָר, חוֹזֶק:",1,0],[51,53,"מֵאִתִּי יָבֹאוּ שׁוֹדְדִים לָהּ. מֵאִתִּי, מִן הַשָּׁמַיִם הַגְּבוֹהִים מִמֶּנָּה, יָבֹאוּ לָהּ הַשּׁוֹדְדִים:",2,0],[51,55,"נִתַּן שְׁאוֹן קוֹלָם. נִשְׁמַע קוֹל צַעֲקָתָם:",1,0],[51,58,"תִּתְעַרְעָר. לְשׁוֹן חֲפִירָה, לְשׁוֹן ״עָרוּ עָרוּ עַד הַיְסוֹד״ (תהלים קלז:ז):",1,0],[51,58,"בְּדֵי רִיק. בְּהַרְבֵּה רִיק שֶׁיָּבֹא עֲלֵיהֶם:",2,0],[51,59,"שַׂר מְנוּחָה. ״רַב תִּקְרוֹבְתָּא״ (תרגום יונתן); עַל יָדוֹ הָיוּ רוֹאִים אֶת פְּנֵי הַמֶּלֶךְ הַמְּבִיאִים לוֹ תְּשׁוּרָה:",1,0],[52,3,"כִּי עַל אַף ה׳ הָיְתָה. הִיא גָּרְמָה לוֹ, מֶרֶד צִדְקִיָּהוּ בְּמֶלֶךְ בָּבֶל, שֶׁהוּא תְּחִלַּת הַחֻרְבָּן:",1,0],[52,4,"דָּיֵק. ״כַּרְכּוֹם״ (תרגום יונתן):",1,0],[52,7,"יִבְרְחוּ. כְּמוֹ בָּרְחוּ:",1,0],[52,7,"דֶּרֶךְ שַׁעַר בֵּין הַחֹמֹתַיִם. מְעָרָה הָיְתָה לוֹ מִבֵּיתוֹ עַד עַרְבוֹת יְרִיחוֹ (פסיקתא רבתי כו); וּכְבָר פֵּרַשְׁתִּיהָ בַּסֵּפֶר הַזֶּה (לט:ד):",2,0],[52,9,"רִבְלָתָה. הִיא אַנְטוֹכְיָא (סנהדרין צו:):",1,0],[52,9,"וַיְדַבֵּר אִתּוֹ מִשְׁפָּטִים. עַל שֶׁעָבַר עַל הַשְּׁבוּעָה:",2,0],[52,10,"אֶת כָּל שָׂרֵי יְהוּדָה. סַנְהֶדְרִין, שֶׁאָמַר לָהֶם: אַתֶּם הִתַּרְתֶּם לוֹ אֶת שְׁבוּעָתוֹ (תנחומא, ואתחנן א). וְחֵטְא הָיָה בְּעֵינֵי הָאֱלֹהִים לְהַתִּיר הַשְּׁבוּעָה:",1,0],[52,11,"בֵּית הַפְּקֻדּוֹת. בְּבֵית הָאֲסִירִין:",1,0],[52,13,"בֵּית הַגָּדוֹל. בָּתֵּי כְנֵסִיּוֹת שֶׁמְּגַדְּלִין בָּהֶם תְּפִלָּה, וְיֵשׁ אוֹמְרִים: בָּתֵּי מִדְרָשׁוֹת שֶׁמְּגַדְּלִין בָּהֶם אֶת הַתּוֹרָה. מַחֲלֹקֶת הָאָמוֹרָאִים הִיא (מגילה כז.):",1,0],[52,15,"יֶתֶר הָאָמוֹן. כְּמוֹ ״הֶהָמוֹן״ (שמואל א ד:יד):",1,0],[52,16,"וּלְיֹגְבִים. חוֹפְרִין בָּאָרֶץ. רַבּוֹתֵינוּ אָמְרוּ (שבת כו.): צָדֵי חִלָּזוֹן:",1,0],[52,17,"וְאֶת הַמְּכֹנוֹת. שֶׁל כִּיּוֹרוֹת (מלכים א ז:מג):",1,0],[52,18,"הַמְזַמְּרוֹת. הֵם כְּלֵי זֶמֶר:",1,0],[52,19,"וְאֶת הַסִּפִּים. תִּרְגֵּם יוֹנָתָן: ״קוּלְיָא״, וְלֹא יָדַעְתִּי אִם מִמִּינֵי כְּלֵי זֶמֶר הוּא. וְאוֹמֵר אֲנִי שֶׁהֵן אַגָּנוֹת לְקַבֵּל דָּם, כְּמוֹ ״בַּדָּם אֲשֶׁר בַּסָּף״ (שמות יב:כב). וְיֵשׁ מְפָרְשִׁים הַסִּפִּים – לְשׁוֹן כַּדִּים, לְפִי תַּרְגּוּם שֶׁל יוֹנָתָן, שֶׁתִּרְגֵּם: ״קוּלְיָא״, כִּי כֵן תִּרְגֵּם אוּנְקְלוֹס ״וְכַדָּהּ עַל שִׁכְמָהּ״ (בראשית כד:טו): ״וְקוּלְתָהּ עַל כַּתְפָהָא״; וְלָשׁוֹן זֶה נִרְאֶה שֶׁהַסִּפִּים אֵינָם מִמִּין כְּלֵי זֶמֶר, אֶלָּא הֵם כַּדִּים:",1,0],[52,19,"הַמַּחְתּוֹת. שֶׁחוֹתִין בָּהֶם גֶּחָלִים מֵעַל הַמִּזְבֵּחַ:",2,0],[52,19,"הַמְּנַקִיּוֹת. סְנִיפֵי הַזָּהָב שֶׁבָּהֶם מַעֲמִידִין לֶחֶם הַפָּנִים, כְּמוֹ שֶׁשָּׁנִינוּ בִּמְנָחוֹת (מנחות צז.):",3,0],[52,20,"אֲשֶׁר תַּחַת הַמְּכֹנוֹת. לֹא יָדַעְתִּי הֵיאַךְ, שֶׁהֲרֵי תַּחַת הַיָּם הָיוּ (מלכים א ז:מד); וְדוֹמֶה לִי שֶׁאֵין זֶה אֶלָּא כְּמוֹ אֵצֶל הַמְּכֹנוֹת:",1,0],[52,21,"יְסֻבֶּנּוּ. יַקִּיפֶנּוּ עֹגֶל הֶקֵּפוֹ:",1,0],[52,21,"וְעָבְיוֹ אַרְבַּע אֶצְבָּעוֹת. סְבִיב חֲלָלוֹ:",2,0],[52,21,"נָבוּב. חָלוּל:",3,0],[52,22,"וּשְׂבָכָה וְרִמּוֹנִים עַל הַכּוֹתֶרֶת. עֲשׂוּיָה כִּשְׁתֵּי אֲגָנוֹת, אַחַת כְּדַרְכָּהּ וְאַחַת כְּפוּיָה עַל פִּי הַתַּחְתּוֹנָה, וְהָעֶלְיוֹנָה קְרוּיָה שְׂבָכָה; קוֹיְיפָ״א בְּלַעַ״ז. וְרִמּוֹנִים תְּחוּבִים הָיוּ בְּשַׁרְשְׁרוֹת, וְהַשַּׁרְשְׁרוֹת שְׁנֵי רָאשֶׁיהָ קְשׁוּרִין יַחַד, וּנְתוּנָה עַל הַשְּׂבָכָה, מָקוֹם שֶׁהַשְּׂבָכָה קְצָרָה, וְהִיא יוֹרֶדֶת עַד מְקוֹם דֶּבֶק הַשְּׂבָכָה וְכוֹתֶרֶת, שֶׁהִיא הַבֶּטֶן הָרָחָב שֶׁבַּכּוֹתֶרֶת, וְשָׁם עוֹמֶדֶת; וְהָרִמּוֹנִים מְכַסִּים אֶת מְקוֹם הִדָּבֵק שְׁתֵּי פִּיּוֹת הָאֲגָנוֹת הַמְּדֻבָּקִים יַחַד:",1,0],[52,23,"תִּשְׁעִים וְשִׁשָּׁה רוּחָה. וּבְסוֹף הַמִּקְרָא הוּא אוֹמֵר: כָּל הָרִמּוֹנִים מֵאָה עַל הַשְּׂבָכָה, וּבְסֵפֶר מְלָכִים הוּא אוֹמֵר ״וְהָרִמּוֹנִים מָאתַיִם טוּרִים״ (מלכים א ז:כ) – אַרְבַּע מֵאוֹת לִשְׁתֵּי הַשְּׂבָכוֹת! אֱמוֹר מֵעַתָּה: אַרְבַּע מֵאוֹת הָיוּ לִשְׁתֵּי הַשְּׂבָכוֹת עַל שְׁנֵי הָעַמּוּדִים, שְׁנֵי טוּרִים לְכָל שְׂבָכָה; וְהַטּוּר מֵאָה הוּא, שֶׁאָמַר כָּאן כָּל הָרִמּוֹנִים מֵאָה עַל הַשְּׂבָכָה – לַטּוּר הָאֶחָד, וּמָאתַיִם לִשְׁנֵי הַטּוּרִים, הוּא הָאוֹמֵר שָׁם ״הָרִמּוֹנִים מָאתַיִם טוּרִים סָבִיב״ – מָאתַיִם לִשְׁנֵי טוּרִים סָבִיב לָעַמּוּד הָאֶחָד, וְכֵן לַשֵּׁנִי, הֲרֵי אַרְבַּע מֵאוֹת. וְהָעַמּוּדִים הֶעֱמִידָם שְׁלֹמֹה בָּאוּלָם סָמוּךְ לְכוֹתֶל הַהֵיכָל, וְהַכּוֹתֶל מְכַסֶּה אַרְבַּע רִמּוֹנִים מִכָּל טוּר, שֶׁאֵין נִרְאִים מִבַּחוּץ; הוּא שֶׁאָמוּר כָּאן: וַיִּהְיוּ הָרִמֹּנִים תִּשְׁעִים וְשִׁשָּׁה רוּחָה:",1,0],[52,23,"רוּחָה. כְּמוֹ לָרוּחַ; כָּל תֵּיבָה שֶׁצְּרִיכָה לָמֶ״ד בִּתְחִלָּתָהּ, הִטִּיל לָהּ הֵ״א בְּסוֹפָהּ (יבמות יג:), וּלְכָךְ הַטַּעַם מִלְמַעְלָה תַּחַת הָרֵי״שׁ; כְּלוֹמַר: תִּשְׁעִים וְשִׁשָּׁה מֵהֶם נִרְאִים לְרוּחוֹת הָעַמּוּד. זוֹ לָמַדְתִּי בְּפִרְקֵי שְׁלֹשִׁים וּשְׁתַּיִם מִדּוֹת שֶׁאָמַר רַבִּי אֱלִיעֶזֶר בְּנוֹ שֶׁל רַבִּי יוֹסֵי הַגְּלִילִי (מידה יט):",2,0],[52,24,"כֹּהֵן הַמִּשְׁנֶה. סְגַן הַכֹּהֲנִים, הַמְמֻנֶּה תַּחַת כֹּהֵן גָּדוֹל לְשַׁמֵּשׁ תַּחְתָּיו, אִם יֶאֱרַע בּוֹ פְּסוּל:",1,0],[52,24,"שׁוֹמְרֵי הַסַּף. ״אֲמַרְכְּלִין״ (תרגום יונתן), שֶׁמַּפְתְּחוֹת הָעֲזָרָה מְסוּרוֹת לָהֶן:",2,0],[52,25,"וְשִׁבְעָה אֲנָשִׁים מֵרֹאֵי פְנֵי הַמֶּלֶךְ. וּבְסֵפֶר מְלָכִים (מלכים ב כה:יט) אָמַר ״וַחֲמִשָּׁה אֲנָשִׁים״. הַשְּׁנַיִם חֲשׁוּבִים וְלֹא חֲשׁוּבִים כָּל כָּךְ (שיר השירים רבה ג:יג):",1,0],[52,25,"הַמַּצְבִּא אֶת עַם הָאָרֶץ. יוֹדֵעַ מִנְיָן שֶׁל כָּל עִיר וָעִיר, כַּמָּה אֲנָשִׁים מוֹצִיאָה לַצָּבָא:",2,0],[52,28,"בִּשְׁנַת שֶׁבַע. הִיא גָּלוּת יְכָנְיָה; וּבְסֵפֶר מְלָכִים אָמַר ״בִּשְׁנַת שְׁמוֹנֶה״ (מלכים ב כד:יב), הָא כֵּיצַד? שְׁנַת שְׁמוֹנֶה שֶׁמָּלַךְ נְבוּכַדְנֶצַּר, שְׁנַת שֶׁבַע – שֶׁכִּבֵּשׁ אֶת יְהוֹיָקִים לְעֶבֶד; דְּאָמַר מַר (מגילה יא:): שָׁנָה רִאשׁוֹנָה כִּבֵּשׁ נִינְוֵה, שְׁנִיָּה עָלָה וְכִבֵּשׁ יְהוֹיָקִים:",1,0],[52,28,"יְהוּדִים שְׁלֹשֶׁת אֲלָפִים. וּמִשְּׁאָר שְׁבָטִים שִׁבְעַת אֲלָפִים, הֲרֵי עֲשֶׂרֶת אֲלָפִים. הַכָּתוּב הַזֶּה, שֶׁפֵּירֵשׁ יְהוּדִים שְׁלֹשֶׁת אֲלָפִים, הִכְרִיעַ בֵּין שְׁנֵי מִקְרָאוֹת שֶׁבְּסוֹף סֵפֶר מְלָכִים: פָּסוּק אֶחָד אוֹמֵר ״עֲשֶׂרֶת אֲלָפִים״ (מלכים ב כד:יד) וְאֶחָד אוֹמֵר ״שִׁבְעַת אֲלָפִים״ (מלכים ב כד:טז), בָּא זֶה וּפֵירֵשׁ: יְהוּדִים שְׁלֹשֶׁת אֲלָפִים וּמִשְּׁאָר שְׁבָטִים שִׁבְעַת אֲלָפִים, הֲרֵי עֲשֶׂרֶת אֲלָפִים:",2,0],[52,29,"בִּשְׁנַת שְׁמֹנֶה עֶשְׂרֵה. הִיא גָּלוּת צִדְקִיָּהוּ. וּלְמַעְלָה הוּא אוֹמֵר שְׁנַת תְּשַׁע עֶשְׂרֵה לַמֶּלֶךְ נְבוּכַדְנֶצַּר! – תְּשַׁע עֶשְׂרֵה שֶׁמָּלַךְ, שְׁמֹנֶה עֶשְׂרֵה שֶׁכִּבֵּשׁ אֶת יְהוֹיָקִים (סדר עולם רבה כז):",1,0],[52,30,"בִּשְׁנַת שָׁלֹשׁ וְעֶשְׂרִים. נִתְּנָה צוֹר בְּיָדוֹ, וְשָׁטַף יְהוּדִים שֶׁבִּסְבִיבוֹת עַמּוֹן וּמוֹאָב שְׁבַע מֵאוֹת וְאַרְבָּעִים וַחֲמִשָּׁה; כָּךְ מְפֹרָשׁ בְּסֵדֶר עוֹלָם (סדר עולם רבה כו):",1,0],[52,31,"בְּעֶשְׂרִים וַחֲמִשָּׁה לַחֹדֶשׁ. וּבְמָקוֹם אַחֵר הוּא אוֹמֵר ״בְּעֶשְׂרִים וְשִׁבְעָה לַחֹדֶשׁ״ (מלכים ב כה:כז)! בְּעֶשְׂרִים וַחֲמִשָּׁה לַחֹדֶשׁ מֵת שִׂטְנוֹ נְבוּכַדְנֶאצַּר, וּבְעֶשְׂרִים וְשִׁשָּׁה נִקְבַּר וְהוֹצִיאוֹ אֱוִיל מְרֹדַךְ מִקִּבְרוֹ, וּבְעֶשְׂרִים וְשִׁבְעָה מָלַךְ וְנָשָׂא אֶת רֹאשׁ יְהוֹיָכִין:",1,0],[52,31,"נָשָׂא. נְשָׂאוֹ וְגִדְּלוֹ. לִישְׁנָא אַחֲרִינָא: מְנָאוֹ עִם שְׁאָר הַמְּלָכִים, כְּמוֹ ״שָׂא אֶת רֹאשׁ בְּנֵי יִשְׂרָאֵל״ (במדבר לא:כו; שמות ל:יב):",2,0],[52,34,"וַאֲרֻחָתוֹ. נוֹטֵל פְּרָס מִבֵּית הַמֶּלֶךְ לְכָל צְרָכָיו (תנחומא, מסעי יב):",1,0]]);
